/* ÇEVİRİ sq · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("sq","olay",{
"OLAYLAR:1299-01:0":{"b": ["Themelimi i Bejlikut Osman", "9f0b7c0a"], "d": ["Fillimi i veprimit të pavarur të Osman Gaziut nga fisi Kaji në rrethinat e Sëgyt-Domaniçit pranohet si fillimi tradicional i themelimit të Shtetit Osman; disa historianë si kthesën e vërtetë konsiderojnë fitoren e Bafeut të vitit 1302. Bejliku, falë pozitës së tij në kufirin me Bizantin, u forcua shpejt me anë të sulmeve të gazasë. Në këtë mjedis, ku po shpërbëhej trashëgimia selxhuke, Osman Gaziu mblodhi rreth vetes ahitë, gazitë dhe turkmenët nomadë; lidhja që krijoi me Shejh Edebalinë konsiderohet themeli i legjitimitetit shpirtëror të bejlikut. Vende të tjera që u bashkuan në të njëjtën datë: Inegël, Jarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Pushtimi i Bursës", "98c727fa"], "d": ["Bursa, e mbajtur nën bllokadë për vite me radhë, iu dorëzua Orhan Gaziut, i cili drejtoi fazën e fundit të rrethimit; qyteti u bë kryeqyteti i parë i madh i bejlikut. Rrëfehet se lajmi i pushtimit iu çua Osman Gaziut në shtratin e vdekjes; sipas amanetit të tij, Osman Gaziu u varros në Bursë. Brenda një kohe të shkurtër qyteti u pajis me xhami, imarete dhe medrese, duke u bërë model i urbanistikës së hershme osmane.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Pushtimi i Iznikut", "a846a811"], "d": ["Izniku (Nikea), një nga qendrat më të rëndësishme të Bizantit në Anadoll, pasi humbi shpresën për të qëndruar pas fitores së Pelekanonit të vitit 1329, iu dorëzua Orhan Gaziut. Këtu u themelua medreseja e parë osmane dhe dijetarë si Davud Kajseriu filluan të jepnin mësim; qyteti u bë qendra e dijes së periudhës së hershme. Kisha e Shën Sofisë u shndërrua në xhami, duke dhënë një shembull të hershëm të traditës së pushtimit.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Pushtimi i Izmitit", "06a35035"], "d": ["Me rënien e Izmitit (Nikomedia), edhe kalaja e fundit e rëndësishme e Bizantit në anën anadollake hyri nën sundimin osman; i gjithë gadishulli i Koxhaelit, deri në bregun përballë Stambollit, u bë tokë osmane. Kështu bejliku, duke zotëruar të gjitha brigjet jugore dhe lindore të Marmarasë, përgatiti infrastrukturën për kalimin në Rumeli.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Kalaja e Çimpes — kalimi në Rumeli", "c2f0a07d"], "d": ["Sulejman Pasha, i biri i Orhan Gaziut, e kishte bërë bazë në vitin 1352 Kalanë e Çimpes, të dhënë gjatë luftës civile bizantine; pas tërmetit të madh që shkatërroi Galipolin në mars 1354, kalatë e zbrazura u fortifikuan me shpejtësi dhe gadishulli u shndërrua në një krye-urë të përhershme osmane. Ky hap, i mbështetur me vendosjen e popullsisë turkmene të sjellë nga Anadolli, është fillimi i pranisë së osmanëve në kontinentin evropian, e cila do të zgjaste më shumë se 550 vjet.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Pushtimi i Edrenesë", "2f54ebb0"], "d": ["Marrja e Edrenesë (Adrianopolit), qytetit kyç të Trakës, përcaktoi bazën kryesore dhe drejtimin e pushtimeve ballkanike; data e pushtimit diskutohet në burime midis viteve 1361 dhe 1369. Pak më vonë qyteti u bë kryeqytet, duke shpallur se qendra e rëndesës së shtetit ishte zhvendosur në Rumeli; deri në pushtimin e Stambollit mbeti seli e fronit për rreth 90 vjet.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Muradi I hipi në fron", "f8d48a26"], "d": ["Muradi I (Hydavendigari), që hipi në fron pas vdekjes së Orhan Gaziut, gjatë sundimit të tij 27-vjeçar e ngriti shtetin nga një bejlik kufitar në skeletin e një perandorie. Me sistemin e penxhikut u hodhën themelet e Korpusit të Jeniçerëve, u përhap rendi i timarit, u themelua Bejlerbejllëku i Rumelisë dhe u forcua institucioni i vezirit. Pushtimet ballkanike në kohën e tij u bënë politikë shtetërore sistematike.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Beteja e Parë e Kosovës — rënia shehid e Muradit I", "10b8ddc9"], "d": ["Aleanca ballkanike nën udhëheqjen e Knjaz Llazarit u mund përfundimisht në Fushën e Kosovës; Serbia hyri nën sovranitetin e lartë osman. Muradi I, ndërsa po vizitonte fushën e betejës, u godit me kamë nga fisniku serb Millosh Obiliq dhe ra shehid — është i vetmi padishah osman që vdiq në fushën e luftës. Në vend të tij, në ushtri u vendos në fron Bajazidi Jëlldërëm; vëllai i tij, Jakup Çelebiu, u mbyt me litar dhe ky u bë një nga shembujt e parë të njohur të praktikës së vëllavrasjes.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Fitorja e Nikopojës", "75716e96"], "d": ["Ushtria e madhe kryqtare, e mbledhur me thirrjen e mbretit hungarez Sigismund dhe në të cilën morën pjesë edhe kalorës francezë dhe burgundas, pësoi një disfatë të rëndë nga Bajazidi Jëlldërëm përpara Nikopojës, në bregun e Danubit. Fitorja e përforcoi përfundimisht sundimin osman mbi Bullgarinë; në Evropë për një brez nuk mund të organizohej një fushatë e madhe kryqtare.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Beteja e Ankarasë — filloi Periudha e Interregnumit", "b4a99d96"], "d": ["Në disfatën e rëndë përballë ushtrisë së Timurit në Fushën e Çubukut, Bajazidi Jëlldërëm u zu rob dhe vdiq në robëri pas disa muajsh. Timuri i ringjalli bejliqet e Anadollit; tokat osmane u copëtuan midis bijve të Bajazidit dhe filloi lufta për fron që do të zgjaste 11 vjet (Periudha e Interregnumit). Kjo periudhë, kriza më e rëndë që shteti kishte përjetuar që nga themelimi, e ngulit në kujtesën osmane rëndësinë e strukturës centraliste. Vendbanime të tjera që u humbën në të njëjtën datë: Datça, Marmaris, Fethije (Makri), Sëke, Kytahja, Afjon, Isparta, Manisa, Ajdën, Denizli, Mugla, Antalia, Konja, Karaman, Kajseri, Kastamonu, Bartën, Safranbolu, Samsun, Sivas, Malatja, Bejshehir, Sivrihisar, Kërshehir, Çorum, Çankëri, Jenishehir (Bursë), Inegël, Kalaja e Ajdosit, Gejve, Këprühisar (Jenishehir), Marmaraxhëk, Akhisar (Pamukova), Mekexhe, Kestel, Ulubat, Harmankaja, Akjazë, Ishulli Imrali, Kandëra, Mudanja, Jallova, Karamürsel, Armutlu, Gemlik (Kios), Sëgyt, Bilexhik, Eskishehir, Bursa, Izniku, Izmiti, Balëkesir, Çanakkala, Bergama, Amasja, Tokat, Çorlu, Lüleburgaz, Malkara, Keshan, Ipsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zagra), Tatarpazarxhik, Ihtiman, Qystendil, Petriç, Nevrokop (Goce Dellçev), Drama, Galipoli, Çimpe, Edrene, Dimotika, Kërklareli, Tekirdag, Filipopojë, Sofje, Nish, Vidin, Tërnovë, Varnë, Shumen, Silistra, Nikopojë, Ruse, Selanik, Serez, Kavallë, Shkup, Manastir, Ohër, Jenishehir (Larisë), Trikalla, Izdin (Lamia), Plevna, Gjymylxhinë, Biga, Domaniç, Kulaxhahisar, Karaxhahisar, Jarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebixhihisar, Karaçepüsh, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandëra, Kirmasti (M.Kemalpasha), Mihaliç (Karaxhabej), Konstancë, Gëljazë (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Mehmet Çelebiu e rivendosi bashkimin", "03413dfd"], "d": ["Mehmeti I, i cili në përballjen e fundit midis vëllezërve e mundi Musa Çelebiun në Çamurlu, i bashkoi tokat e vendit nën një administrim të vetëm; prandaj konsiderohet 'themeluesi i dytë i shtetit'. Gjatë sundimit të tij u riparua struktura e dëmtuar shtetërore, u balancuan marrëdhëniet me bejliqet e Anadollit dhe në Rumeli u ndoq një politikë e kujdesshme paqeje. Vendbanime të tjera që në të njëjtën datë, në hartë, kalojnë nga periudha e ndërmjetme e Interregnumit nën administrimin osman: Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Kryengritja e Shejh Bedredinit", "e0a072ca"], "d": ["Lëvizja fetaro-shoqërore që u zhvillua rreth Shejh Bedredinit, juristit të madh islam dhe mistikut që kishte shërbyer si kadiasker gjatë Interregnumit, shpërtheu njëkohësisht me kryengritjet e Bërklyxhe Mustafait në Karaburun dhe të Torllak Kemalit në Manisa. Kryengritjet u shtypën me gjakderdhje; Bedredini u kap në Deliorman dhe u ekzekutua në Serez. Ngjarja la gjurmë të thella në letërsi dhe në historiografi si kryengritja e parë e madhe shoqërore-mehdiste në historinë osmane.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Fitorja e Varnës", "f739eedc"], "d": ["Ushtria kryqtare hungaro-polake, që e prishi traktatin e Segedinit dhe zbriti drejt jugut, u asgjësua në Varnë nga Muradi II, i cili, ndonëse kishte hequr dorë nga froni, u kthye në krye të ushtrisë; mbreti i ri Vladislavi III vdiq në fushën e betejës. Fitorja i dha fund mundësisë së fundit të madhe për një ndërhyrje të jashtme që synonte zhdukjen e pranisë osmane në Ballkan dhe e siguroi rrugën drejt pushtimit të Stambollit.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Beteja e Dytë e Kosovës", "ebe0b662"], "d": ["Ushtria e Janosh Huniadit, që donte të merrte hakun për Varnën, u mund përfundimisht nga Muradi II në një betejë të ashpër që zgjati tre ditë. Kjo është beteja e fundit e madhe fushore që kryqtarët ndërmorën kundër osmanëve në Ballkan; me këtë fitore sundimi osman në jug të Danubit u vendos tashmë në mënyrë të pakthyeshme.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Pushtimi i Stambollit", "583d5e3e"], "d": ["Pas rrethimit që zgjati pesëdhjetë e katër ditë (6 prill–29 maj 1453), ushtria osmane i kaloi muret në mëngjesin e 29 majit dhe hyri në qytet; perandori i fundit Konstandini XI vdiq në përleshje dhe Perandoria Romake e Lindjes, 1100-vjeçare, hyri në histori. Padishahu i ri mori titullin 'Fatih' (Pushtuesi), e bëri qytetin kryeqytet dhe e shndërroi Shën Sofinë në xhami; qyteti u rigjallërua shpejt me ngulime dhe ndërtime. Sipas TDV-së, Silivria dhe Vizeja u pushtuan përfundimisht vetëm në vitin 1453; sipas artikullit të TDV-së për Lemnosin, ishulli hyri nën administrimin osman menjëherë pas pushtimit dhe iu la familjes Gattilusio me kusht pagimin e haraçit. Në atlas Silivria, Vizeja dhe Lemnosi shënohen që nga kjo ditë si kaluar nga Bizanti te Osmanët (Lemnosi si haraçpagues). Derdhja e topave gjigantë, tërheqja e anijeve në tokë dhe rendi i rrethimit përpara mureve konsiderohen kulmi i inxhinierisë ushtarake të asaj kohe. Në historiografinë evropiane, pushtimi numërohet ndër datat simbolike të përfundimit të Mesjetës.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Pushtimi i Trapezundës", "15f52403"], "d": ["Në fund të fushatës së vështirë në Detin e Zi, që Fatihu e zhvilloi njëkohësisht me ushtri dhe flotë, Perandoria Greke e Trapezundës u dorëzua; me likuidimin e kësaj mbetjeje të fundit të botës bizantine në Anadoll, bregu jugor i Detit të Zi hyri tërësisht nën sundimin osman. Dhënia fund dinastisë Komnene e përforcoi pretendimin e Fatihut si 'sundimtar i dy deteve dhe i dy tokave'. Vende të tjera që u bashkuan në të njëjtën datë: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Pushtimi përfundimtar i Silifkes — thyerja e rezistencës së fundit të Karamanëve", "d988bee4"], "d": ["Kalaja e Silifkes i ishte dorëzuar një herë Gedik Ahmed Pashës në vitin 1472, por po atë vit Kasim Beu Karamanoglu e kishte rimarrë kalanë me ndihmën e flotës kryqtare në Mesdhe. Pas fitores së Otllukbelit, Fatihu ngarkoi të birin dhe Gedik Ahmed Pashën me marrjen përfundimtare të krahinës; me ndihmën e topçinjve të vjetër osmanë iu vu zjarri depos së barutit dhe kalaja u mor shpejt. Kështu u thye rezistenca e fundit e Karamanëve në malet Tasheli-Içel; likuidimi i bejlikut do të përfundonte në vitin 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Beteja e Otllukbelit", "42c7194e"], "d": ["Uzun Hasani, sundimtari akkojunlu, që ishte bërë një fuqi e madhe në Lindje dhe kishte lidhur aleancë me Venedikun, pësoi në Otllukbeli një disfatë të rëndë përballë ushtrisë së Fatihut të pajisur me armë zjarri. Fitorja e përforcoi përfundimisht epërsinë osmane në Anadoll; ajo ishte gjithashtu një dëshmi e hershme e epërsisë së ushtrisë qendrore që përdorte topa dhe pushkë ndaj ushtrisë klasike. Sipas artikullit të TDV-së për Gümüshanenë, qyteti ishte që nga viti 1467 nën sundimin akkojunlu; ky sundim përfundoi me disfatën e Otllukbelit dhe Gümüshaneja kaloi përfundimisht nën sundimin osman.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Hyrja e Krimesë nën mbrojtjen osmane", "44e3f7c8"], "d": ["Flota nën komandën e Gedik Ahmed Pashës pushtoi qytetet e bregut jugor të Krimesë, në radhë të parë Kafën, që ishte në duart e Gjenovës; këto brigje u bënë drejtpërdrejt sanxhak osman. Ndërsa Hanati i Krimesë, me Mengli Girajin, u bë një shtet vasal i privilegjuar që njihte sovranitetin e lartë osman dhe për tre shekuj mbeti guri themelor i politikës veriore; Deti i Zi tashmë u shndërrua de fakto në një det të brendshëm osman. Vende të tjera që u bashkuan në të njëjtën datë: Bahçesaraj, Kerç, Azov.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Vdekja e Fatihut — çështja e Xhem Sulltanit", "190ecf01"], "d": ["Pas vdekjes së papritur të Fatihut gjatë një fushate, në fron hipi Bajazidi II; vëllai i tij, Xhem Sulltani, duke pretenduar sulltanatin, bëri që në Bursë të lexohej hytbeja në emrin e tij dhe preu monedha. Pasi u mund, u strehua fillimisht te memlukët e më pas te kalorësit e Rodosit; Xhemi, i shndërruar në duart e kalorësve dhe të papatit në mjet pazari të diplomacisë evropiane, vdiq në Napoli në vitin 1495. Kjo ngjarje e detyroi politikën e jashtme osmane të vepronte me kujdes për pesëmbëdhjetë vjet.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Fitorja e Çalldiranit", "fea64ebb"], "d": ["Sulltan Selimi Javuz, që donte ta zgjidhte me rrënjë kërcënimin e krijuar nga propaganda safavide në Anadoll, i shkaktoi ushtrisë së Shah Ismailit në Fushën e Çalldiranit një disfatë të rëndë falë epërsisë në topa dhe pushkë. U hy në Tebriz; Anadolli Lindor dhe Juglindor, si dhe vija Mosul-Dijarbekir, iu bashkuan administrimit osman. Lidhja e bejlerëve kurdë me Osmanët, me përpjekjet e Idris Bitlisiut, krijoi kornizën e kufirit lindor që do të zgjaste me shekuj.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Fitorja e Mexh Dabikut", "07d254d3"], "d": ["Ushtria memluke u shpartallua brenda pak orësh në Mexh Dabik, në veri të Halepit; sulltani i moshuar Kansu Gavri vdiq gjatë betejës. Me fitoren që hapi krejt dyert e Halepit dhe të Damaskut, Siria, Libani dhe Palestina kaluan nën administrimin osman; u hap rruga për fushatën e Egjiptit, që do t'i jepte fund Shtetit Memluk.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridanija — pushtimi i Egjiptit dhe halifati", "caf378d6"], "d": ["Ushtria osmane, që e kaloi shpejt shkretëtirën e Sinait, e çau vijën mbrojtëse të Tomanbeut në Ridanije dhe hyri në Kajro; Tomanbeu, që vazhdonte rezistencën, u kap dhe u ekzekutua, dhe Shteti Memluk hyri në histori. Egjipti, Hixhazi dhe qytetet e shenjta kaluan nën administrimin osman; halifi abasid dhe amanetet e shenjta u dërguan në Stamboll. Me kalimin e halifatit te dinastia osmane, padishahët morën përsipër pretendimin e udhëheqjes së botës islame; kontrolli i Rrugës së Erëzave i siguroi gjithashtu perandorisë të ardhura të mëdha. Vende të tjera që u bashkuan në të njëjtën datë: Akka, Maan, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Sulltan Sulejmani Kanuni hipi në fron", "f6512269"], "d": ["Sundimi 46-vjeçar i Sulejmanit I, që hipi në fron pas vdekjes së Javuzit si djali i vetëm mashkull, konsiderohet kulmi politik, ushtarak, juridik dhe kulturor i perandorisë. Kanunamet që sistemuan të drejtën zakonore i sollën titullin 'Kanuni' (Ligjvënësi); në Perëndim u njoh si 'i Madhërishmi' (Magnificent). Veprat e Mimar Sinanit, epoka e artë e letërsisë së divanit dhe epërsia e flotës në Mesdhe janë simbolet e kësaj periudhe.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Pushtimi i Beogradit", "59ef5cec"], "d": ["Beogradi, që Fatihu nuk arriti ta merrte në vitin 1456 dhe që konsiderohej 'kyçi i Evropës Qendrore', ra në fushatën e parë të Kanuniut me një rrethim në bashkimin e Danubit me Savën. Kështu u shemb vija mbrojtëse jugore e Hungarisë; me këtë pushtim u hap dera e operacioneve në Evropën Qendrore, që çuan pas pesë vjetësh në Mohaç e pas njëzet vjetësh në aneksimin e Budës.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Pushtimi i Rodosit", "807bbb1e"], "d": ["Rodosi, baza e kalorësve të Shën Gjonit që kërcënonin rrugët detare të Mesdheut Lindor dhe itinerarin e haxhit, pas një rrethimi të përgjakshëm që zgjati me muaj, u dorëzua me marrëveshje; kalorësve iu lejua të largoheshin lirisht nga ishulli (më vonë u vendosën në Maltë). U sigurua siguria e brigjeve të Anadollit dhe linja detare Stamboll-Egjipt hyri pa ndërprerje nën kontrollin osman.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Beteja Fushore e Mohaçit", "f3418b0d"], "d": ["Ushtria hungareze u asgjësua në Fushën e Mohaçit për rreth dy orë falë zjarrit të topave dhe epërsisë në manovrim; mbreti Lajoshi II vdiq në një moçal duke ikur. Mohaçi, një nga betejat e mëdha fushore të fituara më shpejt në historinë osmane, i dha fund de fakto mbretërisë së pavarur hungareze dhe hapi epokën e rivalitetit osmano-habsburg në Evropën Qendrore.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Rrethimi i Parë i Vjenës", "dc49ea4f"], "d": ["Në fushatën e organizuar kundër shtrirjes së dorës së Habsburgëve mbi fronin hungarez, ushtria osmane e rrethoi Vjenën; për shkak të lënies së topave të rëndë në rrugë, dimrit që nisi herët dhe vështirësive të furnizimit, rrethimi u hoq pas tri javësh. Megjithëse qyteti nuk u mor, ndikimi osman mbi Hungarinë u ruajt; rrethinat e Vjenës shënuan kufirin e arritjes logjistike të perandorisë në Evropën Qendrore.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Pushtimi i Bagdadit — Fushata e Dy Irakëve", "897092c3"], "d": ["Në fushatën e organizuar mbi 'Dy Irakët' (Iraku Arab dhe Iraku Persian) u hy fillimisht në Tebriz e më pas, pa luftë, në Bagdad; marrja e kryeqytetit të dikurshëm të abasidëve i solli sundimtarit osman prestigj të madh në botën islame. Tyrbja e Imam Adham Ebu Hanifes u rimëkëmb; me bashkimin e Bagdadit dhe të Basrës, tokat osmane arritën deri në Gjirin e Basrës. Vende të tjera që u bashkuan në të njëjtën datë: Kirkuk, Qerbela.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Fitorja Detare e Prevezës", "30dc0f97"], "d": ["Flota kryqtare, e krijuar me nismën e Papës, megjithëse epërore në numër, u shpartallua në ujërat e Prevezës nga taktika e Barbarosës, që e përdori me mjeshtëri erën dhe bregun; Andrea Doria u largua nga fusha e betejës. Fitorja vendosi në Mesdhe një epërsi detare të padiskutueshme osmane që do të zgjaste rreth 33 vjet; në traditën detare turke është data simbol e ditës së flotës. Vende të tjera që u bashkuan në të njëjtën datë: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Aneksimi i Budës — Hungaria ejalet osman", "db53b244"], "d": ["Kanuniu, që doli në fushatë pas rrethimit të Budës nga Habsburgët, pasi e shpëtoi qytetin, e mori Hungarinë Qendrore drejtpërdrejt nën administrimin osman dhe themeloi Bejlerbejllëkun e Budës; ndërsa Transilvania u bë principatë autonome vartëse e Osmanëve. Ky rend i Hungarisë i ndarë në tri pjesë zgjati rreth 150 vjet dhe formoi skeletin e përhershëm të administrimit osman në Evropën Qendrore.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Traktati i Amasjas", "a5afe0d1"], "d": ["Është traktati i parë zyrtar i paqes që u dha fund luftërave osmano-safavide që zgjatën me vite. Bagdadi dhe Iraku mbetën te Osmanët, kufiri i Anadollit Lindor u njoh për herë të parë nga të dyja palët; safavidët morën përsipër ta ndalnin propagandën shiite në vendin osman, kurse osmanët të garantonin sigurinë e kalimit të haxhinjve iranianë. Traktati u bë shembulli i parë i kornizës juridike të marrëdhënieve midis dy shteteve.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Sigetvari — vdekja e Kanuniut", "e2917ed2"], "d": ["Kanuniu 72-vjeçar vdiq në çadrën e tij, disa orë para rënies së Kalasë së Sigetvarit, të cilën e kishte rrethuar në fushatën e tij të trembëdhjetë; Sokollu Mehmed Pasha e fshehu vdekjen për javë të tëra që ushtria të mos shpërbëhej. Kalaja u mor, por shteti kishte humbur padishahun me sundimin më të gjatë dhe më të shkëlqyer; në fron hipi i biri, Selimi II, dhe pesha e vezirëve të mëdhenj në administrimin e shtetit filloi të rritej.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Pushtimi i Qipros", "e364a2b3"], "d": ["Në vitin 1570 u bë zbarkimi në Qipron nën administrimin venedikas; Nikosia ra shpejt, kurse Famagusta u dorëzua vetëm në gusht 1571, pas një rrethimi njëmbëdhjetëmujor. Ishulli, me rëndësi jetike për sigurinë e rrugëve të tregtisë dhe të haxhit në Mesdheun Lindor, u organizua si bejlerbejllëk dhe aty u vendos popullsi e sjellë nga Anadolli; pushtimi u bë edhe shkak i aleancës së madhe kryqtare që do të çonte në Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Disfata e Lepantos (İnebahtı)", "6a1d44a9"], "d": ["Flota kryqtare, e bashkuar pas pushtimit të Qipros, e zuri flotën osmane në gjirin e Lepantos dhe asgjësoi pjesën më të madhe të saj; kapudan pashai Myezinzade Ali Pasha ra shehid dhe shpëtoi vetëm flotilja e Uluç Aliut. Pas katastrofës, veziri i madh Sokollu Mehmed Pasha e emëroi Uluç Ali Pashën kapudan pasha, e ngarkoi të mblidhte flotën e shpërndarë dhe nisi ndërtimin e një flote të re në të gjitha arsenalet, nga Stambolli deri në Alanja; megjithatë, epërsia absolute në Mesdhe ishte tronditur psikologjikisht.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Beteja Fushore e Haçovës", "da308ec5"], "d": ["Në betejën më të madhe fushore të Luftës së Gjatë (1593–1606), ushtria me Mehmetin III vetë në krye, në çastin kur kishte arritur në pikën e shpërbërjes, e mblodhi veten me nxitjen e Hoxha Sadedin Efendiut dhe e shpartalloi ushtrinë habsburge. Konsiderohet beteja e fundit e madhe klasike fushore e fituar nga osmanët; megjithatë, mosndryshimi i rrjedhës së përgjithshme të luftës u pa edhe si shenjë e konsumimit të sistemit ushtarak.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Traktati i Zsitvatorokut", "39c01142"], "d": ["Me traktatin që i dha fund luftës rraskapitëse trembëdhjetëvjeçare, sundimtari habsburg për herë të parë u konsiderua i barabartë me padishahun në cilësinë e 'Perandorit Romak' dhe haraçi vjetor u hoq. Humbja territoriale ishte pothuajse e papërfillshme; por ky ndryshim i gjuhës diplomatike lexohet si simbol i përfundimit të pretendimit osman për epërsi absolute ndaj Evropës.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Traktati i Kasr-i Shirinit", "c1acf3af"], "d": ["Traktati, i nënshkruar pasi Murati IV rimori Bagdadin (1638), u dha fund luftërave osmano-safavide që kishin zgjatur më shumë se njëqind vjet. Bagdadi dhe Iraku mbetën përfundimisht te Osmanët, Jerevani iu la safavidëve; vija e caktuar, me ndryshime të vogla, u bë themeli i kufirit të sotëm Turqi-Iran dhe konsiderohet një nga kufijtë më jetëgjatë në botë. Traktati ua la Osmanëve Bedren, Xhesanin, Mendelinë, Dertengun dhe Dernen; Kalaja Zenxhir në kufi do të shkatërrohej, fshatrat në perëndim të saj do t'u mbeteshin Osmanëve, ata në lindje Iranit. Rrethinat e Kalasë Zalim pranë Shehrizorit dhe Kalaja Këzëlxha mbetën te Osmanët, Avromani dhe Mihribani te Irani; kështjellat Kotur, Maku dhe Magazberd do të shkatërroheshin nga të dyja palët.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Pushtimi i Kretës përfundoi", "e0d85604"], "d": ["Rrethimi i Kandisë, akti i fundit i luftës së Kretës që filloi në vitin 1645, përfundoi me operacionin e vendosur trevjeçar të Fazil Ahmed Pashës; komandanti venedikas Morosini e dorëzoi qytetin me marrëveshje. Lufta që zgjati rreth një çerek shekulli u regjistrua si rrethimi më i gjatë në historinë osmane; edhe kështjella e fundit e madhe latine e Mesdheut Lindor hyri nën administrimin osman. Tri kështjellat e vogla shkëmbore në bregun verior të ishullit — Suda, Spinalonga dhe Gramvusa — mbetën ende te Venediku; meqë janë ndërtuar mbi ishuj të veçantë, në hartë nuk mund të paraqiten të ndara nga pjesa tjetër e Kretës.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Traktati i Buçaçit — kufijtë më të gjerë", "b17b6e5a"], "d": ["Me Traktatin e Buçaçit, të nënshkruar pas pushtimit të Kamenecit në fushatën e Polonisë, Podolia iu bashkua Osmanëve dhe një pjesë e Ukrainës u mor nën mbrojtje. Kështu perandoria arriti kufijtë e saj më të gjerë në Evropë; kjo pikë konsiderohet kulmi i epokës së zgjerimit dhe njëkohësisht hallka e saj e fundit.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Disfata e Rrethimit të Dytë të Vjenës", "7d889252"], "d": ["Rrethimi dymujor i Vjenës nga Merzifonlu Kara Mustafa Pasha u shndërrua në disfatë me goditjen e befasishme që mbreti i Polonisë, Jan Sobieski, lëshoi nga kodrat e Kahlenbergut; ushtria u tërhoq duke lënë pas plaçkat e rënda, kurse Merzifonlu u ekzekutua në Beograd. Lufta me Lidhjen e Shenjtë, të krijuar pas kësaj fitoreje, zgjati 16 vjet; kjo disfatë tregohet si çasti i fillimit të rënies së madhe në historinë osmane.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Pushtimi i Kalasë së Gramvusës — një nga kështjellat shkëmbore që mbetën te Venediku në Kretë", "3ddf9eeb"], "d": ["Megjithëse pushtimi i Kretës konsiderohet kryesisht i përfunduar me dorëzimin e Kandisë në vitin 1669, ishulli-kala shkëmbor i Gramvusës, në skajin veriperëndimor të ishullit, mbeti edhe njëzet e tre vjet në duart e Venedikut. Me marrjen e tij në vitin 1692 u pastrua një nga tri mbetjet venedikase në Kretë; kurse Suda dhe Spinalonga do të prisnin fushatën e Moresë të vitit 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Traktati i Karlovcit — humbja e parë e madhe territoriale", "8f7e2546"], "d": ["Me Karlovcin, që u dha fund luftërave gjashtëmbëdhjetëvjeçare të Lidhjes së Shenjtë, Hungaria dhe Transilvania iu lanë Austrisë, Podolia Polonisë, kurse Moreja dhe brigjet e Dalmacisë Venedikut. Për herë të parë në historinë osmane, tokë në këtë përmasë dilte nga duart në tryezën e bisedimeve dhe përgjithmonë; traktati konsiderohet dokumenti fillestar i epokës së re, në të cilën perandoria kaloi në mbrojtje ndaj Evropës, dhe është gjithashtu një kthesë në historinë e diplomacisë osmane. Vendbanime që në atlas ndërrojnë dorë të njëjtën ditë: Kostajnica dhe Jasenovaci (nga Osmanët te Habsburgët; teksti i traktatit e lë Castanovizin në duart e perandorit, dita e dorëzimit të Jasenovacit mungon te burimi, u shënua dita e traktatit) dhe Preveza (nga Venediku te Osmanët; TDV karlofca: sipas dispozitës së nënshkruar më 24 rexheb 1110 / 26 janar 1699, u kthyen vendet e pushtuara nga Venediku në veri të gjirit të Lepantos). Atlasi gjithashtu shënon Kostajnicën dhe Jasenovacin në anën habsburge, Umanin dhe Vinicën në Ukrainën e bregut të djathtë si kaluar nga Osmanët te Polonia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: sundim turk 1672-99) dhe Nadinin në Dalmaci si kaluar te Venediku (dita e dorëzimit specifike për vendbanimin mungon te burimi, u shënua dita e traktatit; skajet e periudhës së Nadinit nuk janë vërtetuar me burim — përafërsi e deklaruar). Edhe Vonica në veri të gjirit të Lepantos u kthehet Osmanëve nga Venediku (TDV karlofca); në Dalmaci, Vrana (Urana) është ndër vendet që mbetën te Venediku (skaji i periudhës nuk është vërtetuar — i deklaruar).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Fitorja e Prutit", "2583572f"], "d": ["Në luftën që shpërtheu për shkak të çështjes së mbretit suedez, i cili pas disfatës së Poltavës ishte strehuar te Osmanët, ushtria e Carit Pjetri I u rrethua në bregun e Prutit dhe u detyrua të dorëzohej. Me traktatin e nënshkruar u rimor Azovi; kurse moszhdukja e ushtrisë dhe lirimi i carit kaluan në histori si një vendim që diskutohet deri në ditët e sotme.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Pushtimi i kështjellave të Sudës dhe të Spinalongës — fshirja e gjurmës së fundit venedikase në Kretë", "7261f7ba"], "d": ["Njëzet e tre vjet pas rënies së Gramvusës në vitin 1692, në kuadër të një degëzimi të fushatës së Moresë u pushtuan edhe dy mbështetjet e fundit të Venedikut në Kretë, kështjellat e Sudës dhe të Spinalongës. Kështu, pushtimi i Kretës që filloi në vitin 1645 u përfundua, pas dyzet e gjashtë vjetësh, deri në centimetrin e fundit të ishullit.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Kryengritja e Patrona Halilit", "100941a4"], "d": ["Zemërimi për dështimin në frontin e Iranit, për taksat dhe për luksin e rrethit të sarajit u shndërrua në një kryengritje të madhe nën udhëheqjen e Patrona Halilit, shërbëtor hamami. Veziri i madh Ibrahim Pasha u vra, Ahmeti III u rrëzua nga froni dhe Epoka e Tulipanëve mori fund; sundimi i kryengritësve mbi qytetin për muaj të tërë tregoi në mënyrë të bujshme brishtësinë e autoritetit qendror.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Traktati i Beogradit — rimarrja e Beogradit, Smederevës dhe Serbisë veriore", "ba7f8e46"], "d": ["Në fund të luftës së zhvilluar në dy fronte kundër Austrisë dhe Rusisë (1736–1739), u rimorën Beogradi dhe Serbia Veriore; Rusia pranoi ta çarmatoste Azovin dhe të mos mbante flotë në Detin e Zi. Traktati, që konsiderohet suksesi i fundit i madh i diplomacisë dhe i ushtrisë osmane të shekullit XVIII, i solli perandorisë një periudhë paqeje prej një çerek shekulli. Vendbanime të tjera që në atlas të njëjtën ditë kthehen nga Austria te Osmanët: Hisarxhëk (Grocka) (zinciri i qendrës kryesore të lidhur me Beogradin; TDV belgrad), Krajova (Craiova), Rimniku (Râmnicu Vâlcea) dhe Turnu Severin (kthimi i Oltenisë te Osmanët, në vasalitetin e Vllahisë). Kurse Brodi i Bosnjës (Bosanski Brod) dhe Dubica e Bosnjës (Bosanska Dubica), në brezin e Savës, në atlas u kthehen Osmanëve më 28 shtator 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 shtator 1739). Edhe Tărgu Jiu në Oltenisë u kthehet Osmanëve të njëjtën ditë.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Sulmi i Çeshmes", "840b30bd"], "d": ["Flota ruse, që doli në Mesdhe me mbështetjen e anglezëve, e sulmoi me anije zjarri flotën osmane në limanin e Çeshmes, ku ishte strehuar, dhe e dogji pothuajse tërësisht. Rusia u shfaq për herë të parë si fuqi e madhe detare në Mesdhe; katastrofa u bë një nga goditjet që vendosën fatin e luftës që çoi në Kyçyk Kajnarxha të vitit 1774 dhe nxori në pah nevojën për një reformë rrënjësore të flotës.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Traktati i Kyçyk Kajnarxhasë", "2776dcdb"], "d": ["Me Kyçyk Kajnarxhanë, që i dha fund luftës 1768–1774 dhe konsiderohet një nga traktatet më të rënda të historisë osmane, Hanatit të Krimesë iu dha 'pavarësia' — në fakt u krijua një zonë ndikimi ruse. Rusia u vendos në bregun e Detit të Zi, fitoi për anijet e saj tregtare të drejtën e kalimit nëpër Ngushtica dhe një ambasadë të përhershme në Stamboll; klauzola e paqartë e mbrojtjes mbi nënshtetasit ortodoksë hapi derën për pretekstet e ndërhyrjeve të shekullit pasues. Për herë të parë një tokë me popullsi myslimane po dilte nga sovraniteti osman.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Aneksimi i Krimesë nga Rusia", "bdf6faa8"], "d": ["Krimea 'e pavarur', e krijuar nga Kyçyk Kajnarxhaja, u aneksua nga Rusia me manifestin e Katerinës II, duke marrë si pretekst trazirat në kohën e hanit të fundit, Shahin Girajit. Partneriteti treshekullor osmano-krimeas mori fund; humbja e stepave veriore e zhduku thellësinë mbrojtëse të Stambollit dhe nisi valën e parë të madhe të shpërnguljes së dhjetëra mijëra tatarëve të Krimesë drejt tokave osmane. Atë ditë gadishulli i Krimesë (Alushta, Kafa, Sudaku, Jalta, Ballaklava, Inkermani, Mankupi, Arabati) iu bashkua Rusisë; edhe Tamani dhe Kubani kaluan te Rusia me të njëjtin aneksim (TDV Kırım: 8 prill 1783 julian = 19 prill gregorian).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selimi III dhe Nizam-i Xhedid", "d53aec21"], "d": ["Selimi III, që hipi në fron në mes të luftës, duke kuptuar se disfatat ishin strukturore, nisi një program të gjerë reformash me emrin 'Nizam-i Xhedid' (Rendi i Ri): një ushtri të re të stërvitur sipas mënyrës evropiane, një thesar të veçantë që e financonte atë (Irad-i Xhedid), forcimin e shkollave të inxhinierisë dhe ambasadat e para të përhershme në kryeqytetet evropiane. Programi konsiderohet fillimi i traditës moderne turke të reformave; por, për shkak të rezistencës së odxhaqeve dhe të ajanëve, do të shembej në vitin 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Likuidimi i kalorësve të Maltës — ndalesa e flotës franceze gjatë rrugës", "d62f901d"], "d": ["Flota franceze, që po shkonte në Egjipt, u ndal gjatë rrugës në Maltë; kalorësit e Shën Gjonit (të Maltës) e dorëzuan ishullin pa rezistuar shumë. Kështu mori fund kalaja e fundit e urdhrit kalorësiak, i cili, i dëbuar nga Rodosi në vitin 1522, ishte vendosur këtu. Malta dy vjet më vonë do të binte në duart e Anglisë, kurse Napoleoni nga ishulli do të drejtohej drejt e në Aleksandri.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Pushtimi i Egjiptit nga Napoleoni", "93fede5f"], "d": ["Ushtria e gjeneralit Bonapart zbarkoi në Aleksandri dhe pushtoi Egjiptin; kjo fushatë, që synonte rrugën e Anglisë drejt Indisë, ishte sulmi i parë i drejtpërdrejtë i një fuqie evropiane ndaj tokave qendrore osmane. Sulmi i Nelsonit në Abukir dhe mbrojtja e Akkës nga Xhezzar Ahmed Pasha e thyen përparimin francez; pushtimi përfundoi në vitin 1801, por në boshllëkun që la filluan ngritja e Mehmet Ali Pashës nga Kavalla dhe epoka e 'Çështjes së Lindjes'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i Ittifak (Dokumenti i Aleancës)", "cce49ef5"], "d": ["Dokument i nënshkruar midis sarajit dhe familjeve të fuqishme të ajanëve të provincës, me nismën e Alemdar Mustafa Pashës, ajanit të Rusçukut, që e kishte hipur në fron Mahmudin II; ajanët zotoheshin për besnikëri ndaj padishahut dhe për mbështetje me ushtarë, kurse shteti njihte ekzistencën dhe të drejtat e tyre. Meqë është shembulli i parë në historinë osmane i kufizimit të autoritetit të padishahut me një dokument, disa historianë e konsiderojnë fillim të largët të traditës kushtetuese; në praktikë mbeti pa efekt brenda pak muajsh.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Filloi Kryengritja Greke", "a7293715"], "d": ["Kryengritja e përgatitur nga organizata Filiki Eteria shpërtheu fillimisht në Vllahi e më pas, me forcën e saj kryesore, në More; shteti, i zënë me telashet e Ali Pashë Tepelenës, u vonua në ndërhyrjen e parë. Falë simpatisë së madhe për grekët në opinionin evropian (filhelenizmit), kryengritja u shndërrua shpejt në një çështje ndërkombëtare; kështu u ndez fitili i lëvizjes së parë të suksesshme për pavarësi të epokës së nacionalizmit në tokat osmane. Vendbanime të tjera që u humbën në të njëjtën datë: Athinë, Patra, Tebë, Livadhja, Eleusina (Atikë), Misolongji.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Kryengritja e parë e armatosur në More", "77e6250f"], "d": ["Pas kalimit të Prutit, kryengritja u përhap në More: veprimin e armatosur që filloi në Kallavrita (21 mars julian) e pasuan lëvizjet në Patra, Kalamata dhe Mani; Moreja shpejt u shndërrua në një kryengritje të përgjithshme dhe administrimi osman humbi pjesën më të madhe të gadishullit. Vendbanime të tjera që u humbën në të njëjtën datë: Athinë, Patra, Tebë, Livadhja, Eleusina (Atikë), Misolongji.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vaka-i Hajrije — u shfuqizua Korpusi i Jeniçerëve", "08c9372a"], "d": ["Jeniçerët, që u ngritën në rebelim kundër stërvitjeve të Odxhakut Eshkinxhi të sapokrijuar, u asgjësuan në kazermat e tyre në Sheshin e Mishit (Etmejdan) nga zjarri i topave të njësive besnike që Mahmudi II kishte përgatitur paraprakisht; korpusi u shfuqizua së bashku me të gjitha degët dhe teqetë bektashiane të lidhura me të. Ky operacion, që kaloi në histori me emrin që do të thotë 'ngjarja e mbarë', likuidoi një institucion katërshekullor dhe i hapi rrugën ushtrisë Asakir-i Mansure-i Muhammedije dhe të gjitha reformave pasuese të centralizimit.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Sulmi i Navarinit", "ee579e7f"], "d": ["Flota osmano-egjiptiane, që po shtypte kryengritjen greke, u dogj në Navarin nga flota e bashkuar anglo-franko-ruse, e cila hyri në liman pa shpallje lufte; humbën afro gjashtëdhjetë anije dhe mijëra detarë. Sulmi, që në diplomacinë evropiane u kalua si 'ngjarje fatkeqe', e garantoi de fakto pavarësinë greke dhe hapi rrugën për luftën osmano-ruse të viteve 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Fermani i Tanzimatit", "5042ce7b"], "d": ["Me Hatt-i Humajunin e lexuar në Gylhane, siguria e jetës, e pasurisë dhe e nderit të të gjithë nënshtetasve, pa dallim feje, u vu nën garancinë e shtetit; u shpallën parimet e drejtësisë në taksa, të rregullit në shërbimin ushtarak dhe të mosdhënies së dënimit pa gjykim. Fermani, vepër e Mustafa Reshid Pashës, konsiderohet dokumenti i parë i madh me karakter kushtetues i modernizimit osman dhe i ka dhënë emrin epokës së reformave, 'Periudhës së Tanzimatit' (1839–1876); brenda kësaj kornize u krye riorganizimi rrënjësor i administratës, drejtësisë, arsimit dhe financave.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Filloi Lufta e Krimesë", "3b9ca3c8"], "d": ["Kriza që nisi me çështjen e vendeve të shenjta dhe me pretendimin e Rusisë për mbrojtje mbi nënshtetasit ortodoksë u shndërrua në përplasje të hapur me shpalljen e luftës nga Osmanët; pas sulmit të Sinopit, Anglia dhe Franca (më pas edhe Piemonti) hynë në luftë në anën osmane. Me zbarkimin e ushtrive aleate në Krime dhe marrjen e Sevastopolit, lufta u fitua me Traktatin e Parisit të vitit 1856; por huaja e parë e jashtme e marrë gjatë viteve të luftës (1854) e futi perandorinë në spiralen e varësisë financiare që do të zgjaste gjysmë shekulli.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Fermani i Reformave (Islahat)", "78ff234d"], "d": ["Fermani i shpallur para bisedimeve të paqes së Parisit, duke zgjeruar parimet e Tanzimatit, u njohu nënshtetasve jomyslimanë të drejta të gjera barazie, përfshirë nëpunësinë shtetërore, shërbimin ushtarak dhe hapjen e shkollave; organizimet e komuniteteve u rirregulluan. Me Traktatin e Parisit të nënshkruar më pas, Shteti Osman u pranua zyrtarisht në familjen e së drejtës publike evropiane dhe integriteti i tij territorial u vu nën garancinë e përbashkët të fuqive të mëdha — në praktikë kjo garanci do të bëhej dera e re e ndërhyrjeve.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanun-i Esasi — Mbretëria e Parë Kushtetuese", "0fe052c1"], "d": ["Ditën kur u hap konferenca ndërkombëtare e mbledhur në Stamboll për të diskutuar krizën ballkanike, kushtetuta e parë osmane u shpall me të shtëna topash; me Kanun-i Esasi, vepër e lëvizjes së 'Osmanlinjve të Rinj' nën udhëheqjen e Mit'hat Pashës, u krijua parlamenti me dy dhoma. Kuvendi i Deputetëve (Mexhlis-i Meb'usan) u hap në mars 1877; por Abdylhamidi II, duke marrë si arsye Luftën e 93-shit, në shkurt 1878 e pezulloi parlamentin pa afat dhe kushtetuta mbeti e pezulluar për tridhjetë vjet.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Lufta e 93-shit (Lufta osmano-ruse 1877–78)", "5bd96af7"], "d": ["Në luftën që quhet 'Lufta e 93-shit' sepse përkon me vitin rumi 1293, ushtritë ruse sulmuan nga dy fronte; ndonëse mbrojtja e Plevnës nga Gazi Osman Pasha dhe betejat kaukaziane të Ahmed Muhtar Pashës u bënë legjendare, fronti u shemb dhe rusët përparuan deri në Jeshilkëj (Shën Stefan). Lufta nisi valët e mëdha të shpërnguljes myslimane nga Ballkani dhe Kaukazi drejt Stambollit, pasojat e të cilave zgjaten deri sot; struktura demografike dhe financiare e perandorisë nuk mundi të kthehej më në gjendjen e mëparshme.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Traktati i Berlinit", "47f76a49"], "d": ["Kongresi i Berlinit, që në emër të ekuilibrit të fuqive të mëdha e rishikoi 'Bullgarinë e Madhe' të krijuar nga Shën Stefani, la megjithatë një pamje të rëndë: Serbia, Mali i Zi dhe Rumania u bënë të pavarura; u krijua Principata autonome e Bullgarisë; Bosnjë-Hercegovina iu la pushtimit austriak, Qipro administrimit anglez, kurse Karsi, Ardahani dhe Batumi Rusisë. Rendi pesëqindvjeçar osman në Rumeli u shpërbë në masë të madhe; 'çështja e Lindjes' u bë temë e përhershme e diplomacisë evropiane. Vendbanime të tjera që u humbën në të njëjtën datë: Filipopojë, Vidin, Tërnovë, Varnë, Shumen, Silistra, Ruse, Bukuresht, Jash, Konstancë. Rumania, në këmbim të dorëzimit të Besarabisë Rusisë, mori Tulçen (Tulcea) dhe Dobruxhën: në Dobruxhën e Veriut, Tulça, Babadagu (Babadag), Maçini, Isakça (Isaccea), Hërshova (Hârșova) dhe Mangalia (Mangalia) kaluan te Rumania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Pushtimi i Tunizisë dhe Dyjun-i Umumije", "c7e25598"], "d": ["Franca, duke marrë si pretekst ngjarjet në kufirin me Algjerinë, pushtoi Tunizinë dhe me Traktatin e Bardos e mori nën protektoratin e saj; prania osmane në Afrikën Veriore u reduktua në Tripoli. Me Dekretin e Muharremit të nxjerrë po atë vit, për administrimin e borxheve të jashtme të falimentuara u krijua Administrata e Dyjun-i Umumijes, ku përfaqësoheshin kreditorët: të ardhura themelore si kripa, duhani dhe mëndafshi iu lidhën drejtpërdrejt kësaj administrate të huaj dhe sovraniteti financiar u kufizua rëndë. Vendbanime të tjera që u humbën në të njëjtën datë: Kajruani, Gabesi, Sfaksi, Xherba (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Pushtimi anglez i Egjiptit", "f1269768"], "d": ["Lëvizja e Urabi Pashës, që u ngrit në Egjipt kundër falimentimit financiar dhe kontrollit të huaj, u shtyp me fitoren e Tel el-Kebirit nga ushtria angleze, e cila zbarkoi pas bombardimit të Aleksandrisë, dhe Kajro u pushtua. Megjithëse Egjipti vazhdoi të mbetej juridikisht i lidhur me Osmanët, de fakto hyri nën administrimin anglez; kontrolli i Kanalit të Suezit u vendos në qendër të strategjisë perandorake britanike.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Shpallja e Mbretërisë së Dytë Kushtetuese", "95ee2fd2"], "d": ["Përballë lëvizjes që u rrit me daljen në mal në Maqedoni të oficerëve të lidhur me Komitetin Bashkim e Përparim, Abdylhamidi II e rivuri në fuqi Kanun-i Esasi; 'shpallja e lirisë' u prit me entuziazëm dhe u shkua drejt zgjedhjeve. Por stabiliteti nuk erdhi: pasi u shtyp Ngjarja e 31 Martit (prill 1909), Abdylhamidi u rrëzua nga froni; pavarësia e Bullgarisë, aneksimi i Bosnjës dhe orientimi i Kretës nga Greqia ndodhën gjithashtu në këta muaj të trazuar.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Lufta e Tripolit (Libisë)", "ed441994"], "d": ["Italia, në kërkim të kolonive, i shpalli luftë Tripolit, toka e fundit osmane në Afrikën Veriore, dhe pushtoi brigjet; kur shteti, që nuk kishte flotë, nuk mundi të dërgonte ushtri të rregullt, oficerë të rinj si Mustafa Kemali dhe Enver Beu kaluan fshehurazi në krahinë dhe organizuan me fiset senuse një rezistencë efektive. Me Traktatin e Ushit (18 tetor 1912), të nënshkruar pas shpërthimit të Luftës Ballkanike, Libia iu la Italisë; Italia gjithashtu pushtoi Rodosin dhe Dodekanezin.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Traktati i Londrës — humbja e Rumelisë", "f3f976df"], "d": ["Me Traktatin e Londrës, që i dha fund Luftës së Parë Ballkanike, u humbën të gjitha tokat në perëndim të vijës Midja-Enos dhe ishujt e Egjeut; Shqipëria u bë e pavarur. Nga Rumelia, që për më shumë se pesëqind vjet kishte qenë qendra e rëndesës demografike, ekonomike dhe kulturore e perandorisë, do të mbetej vetëm Traka Lindore (Edrenea u rimor në Luftën e Dytë Ballkanike); humbja e ashpërsoi rrënjësisht politikën e luftës dhe të ngulimeve të qeverisë ittihadiste. Këto vende që mbetën në perëndim të vijës Midja-Enos dolën nga duart: Shkup, Veles (Këprülü), Shtip (Štip), Strumicë, Dojran, Gjevgjeli (Gevgelija), Manastir, Ohër, Dibër (Dibra), Prizren, Prishtinë, Pejë (Peć), Novi Pazar (Yenipazar), Fusha e Kosovës (Kosovo Polje); Serez, Drama, Kavalla, Petriç, Nevrokop, Ksanthi, Gjymylxhinë, Aleksandrupoli (Dedeagaç), Dimotika, Çirmen, Feres (Ferexhik), Sufli (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); në Kretë Hania, Kandia, Rethimno (Resmo), Sitia (Sitiye) dhe Sfakia (İsfakiye).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Hyrja në Luftën e Parë Botërore", "05a0252e"], "d": ["Pranimi në Ngushticë i kryqëzorëve Goeben dhe Breslau, që po iknin nga anglezët, duke i paraqitur si të blerë, e tërhoqi shtetin hap pas hapi në anën e Gjermanisë; me bombardimin e porteve ruse nga flota nën komandën e admiralit Souchon (29 tetor), lufta filloi de fakto, kurse shpalljet e ndërsjella erdhën në fillim të nëntorit. Megjithë shpalljen e Xhihadit të Madh, efekti i pritur nuk u arrit; perandoria hyri për katër vjet në një luftë për ekzistencë në pesë fronte të ndryshme, nga Kaukazi në Palestinë.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Fitorja e Çanakkalasë", "95d888e8"], "d": ["Armada aleate, që synonte të merrte Stambollin dhe të arrinte te Rusia, më 18 mars u zmbraps nga Ngushtica nga vijat e minave dhe zjarri i fortifikatave; vija e shtruar nga anija minahedhëse Nusret përcaktoi fatin e luftës. Edhe operacioni tokësor i Galipolit, që filloi në prill, u ndal në Anafartalar dhe Çonkbajër; në janar 1916 aleatët e braktisën plotësisht gadishullin. Emri i nënkolonelit Mustafa Kemal u bë i njohur në këtë front; fitorja, e fituar me rreth një çerek milioni shehidë dhe humbje, konsiderohet vendi ku lindën kuadrot dhe shpirti i Luftës Nacionale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Kryengritja e Sherif Huseinit", "75f7c58c"], "d": ["Emiri i Mekës, Sherif Huseini, pas korrespondencës së fshehtë me anglezët, u ngrit në kryengritje me premtimin për një mbretëri të pavarur arabe; hekurudha e Hixhazit u bë shënjestër e sulmeve. Ndonëse mbrojtja legjendare e Medinës nga Fahredin Pasha, që zgjati deri pas armëpushimit, mbeti simbol i rezistencës, kryengritja, duke u bashkuar me përparimin anglez në frontin e Palestinës, përshpejtoi shpërbërjen e sundimit osman në vilajetet arabe. Vendbanime të tjera që u humbën në të njëjtën datë: Hurma, Turaba.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armëpushimi i Mudrosit", "9e87c767"], "d": ["Shteti Osman, frontet e të cilit u këputën nga njëri-tjetri me shembjen e Bullgarisë, doli nga lufta me armëpushimin e nënshkruar në kryqëzorin Agamemnon. Hapja e Ngushticave dhe sidomos neni 7, që mundësonte pushtimin e vendeve ku kërcënohej siguria, u bënë shpejt mbulesa juridike e ndarjes de fakto: u pushtuan Mosuli, Iskenderuni, pastaj Izmiri dhe Stambolli. Armëpushimi konsiderohet dokumenti i fundit de fakto të perandorisë. Vendbanime të tjera që u humbën në të njëjtën datë: Hama, Damask, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemali në Samsun — Lufta Nacionale", "09a8f784"], "d": ["Në atmosferën e indinjatës që shkaktoi pushtimi i Izmirit, Mustafa Kemal Pasha, që zbarkoi në Samsun si inspektor i Armatës së 9-të, e ktheu detyrën e tij zyrtare në organizimin e rezistencës në Anadoll. Qarkorja e Amasjas dhe kongreset e Erzurumit e të Sivasit janë vazhdimi i këtij hapi; parimi 'pavarësinë e kombit do ta shpëtojnë përsëri vendosmëria dhe vullneti i kombit' u bë bërthama e programit politik të Luftës Nacionale.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Hapja e Asamblesë së Madhe Kombëtare dhe Sevri", "2008feec"], "d": ["Pas pushtimit zyrtar të Stambollit dhe shpërndarjes së Kuvendit të Deputetëve, më 23 prill 1920 në Ankara u hap Asambleja e Madhe Kombëtare; asambleja, që mblodhi në vete kompetenca të jashtëzakonshme, u bë bërthama e shtetit të ri të mbështetur mbi vullnetin kombëtar. Traktati i Sevrit, i nënshkruar në gusht nga qeveria e Stambollit, e ndante Anadollin; Asambleja e Madhe Kombëtare e Turqisë i shpalli tradhtarë të atdheut nënshkruesit e traktatit dhe Sevri nuk u zbatua kurrë.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Beteja Fushore e Sakarjas", "f2f970a6"], "d": ["Ofensiva greke, që u afrua deri në 50 kilometra nga Ankaraja, u thye në betejën 22 ditë e 22 netë, të zhvilluar me urdhrin e Mustafa Kemal Pashës, që mori kompetencat e komandantit të përgjithshëm: 'nuk ka vijë mbrojtjeje, ka sipërfaqe mbrojtjeje'. Ushtria greke kaloi për herë të parë në mbrojtje strategjike; fitorja i solli Mustafa Kemalit titullin gazi dhe gradën e mareshalit dhe hapi derën për Marrëveshjen e Ankarasë me Francën dhe për njohjen e jashtme.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Ofensiva e Madhe dhe çlirimi i Izmirit", "172a50c4"], "d": ["Ofensiva e nisur në mëngjesin e 26 gushtit nga Koxhatepe arriti më 30 gusht, me Betejën Fushore të Komandantit të Përgjithshëm në Dumllupënar, në asgjësimin e forcave kryesore greke; me ndjekjen që vazhdoi me urdhrin 'Ushtri, objektivi juaj i parë është Mesdheu, përpara!', më 9 shtator u çlirua Izmiri. Me Armëpushimin e Mudanjas (11 tetor) Traka Lindore u rimor pa luftë; fitorja ushtarake përcaktoi fuqinë në tryezën e bisedimeve të shtetit të ri që do të themelohej në Lozanë.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Shfuqizimi i sulltanatit", "9f36a9f6"], "d": ["Pasi në bisedimet e Lozanës u ftua edhe qeveria e Stambollit, Asambleja e Madhe Kombëtare, më 1 nëntor 1922, duke ndarë sulltanatin nga halifati, e shfuqizoi sulltanatin; sundimi 623-vjeçar i dinastisë osmane mori fund juridikisht. Mehmeti VI Vahideddin u largua nga vendi më 17 nëntor me një kryqëzor anglez; në postin e halifatit, me vendim të Asamblesë, u vu Abdylmexhid Efendiu dhe edhe ky post do të shfuqizohej më 3 mars 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Traktati i Lozanës", "38c27f7d"], "d": ["Me Traktatin e Paqes së Lozanës, të nënshkruar pas negociatave të vështira që zgjatën tetë muaj, u njohën ndërkombëtarisht kufijtë, pavarësia e plotë dhe sovraniteti i shtetit të ri turk; kapitulacionet u shfuqizuan, Dyjun-i Umumije hyri në procesin e likuidimit dhe u rregullua shkëmbimi i popullsive. Lozana, që de fakto e bëri të pavlefshëm Sevrin, konsiderohet fitorja diplomatike e Luftës Nacionale dhe dokumenti i jashtëm themelues i Republikës.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Shpallja e Republikës", "d5bfcdfb"], "d": ["Republika u shpall kur Asambleja e Madhe Kombëtare, me ndryshimin e kushtetutës, miratoi dispozitën 'forma e qeverisjes së Shtetit Turk është republika'; Mustafa Kemal Pasha u zgjodh presidenti i parë. Kështu u mbyll aventura 624-vjeçare osmane, që nisi në vitin 1299 si bejlik kufitar, dhe mbi trashëgiminë e perandorisë u themelua shteti i ri, ku sovraniteti i takon pa kushte dhe pa kufizime kombit.", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Qendra e senusive në shkretëtirë, Xhagbubi, lidhet me rendin osman — fermani i përjashtimit nga taksat i Abdylmexhidit", "039fce6d"], "d": ["Muhamed b. Ali es-Senusi, që kishte qëndruar prej vitesh në Mekë, pas kthimit në Tripoli (Libi) u vendos në oazën e Xhagbubit në kufi me Egjiptin dhe urdhëroi ndërtimin e një zavieje të madhe mbi shkëmbin dominues; vendi, që përbëhej nga disa barraka, brenda një kohe të shkurtër u shndërrua në qytet. Më 1856, me ferman të sulltan Abdylmexhidit, pronat e anëtarëve të tarikatit u përjashtuan nga taksat dhe muridëve iu dha e drejta të mblidhnin zekat. Ky ferman e bëri oazën, mbi rrugën e karvaneve që lidhte Afrikën Perëndimore dhe Sudanin me Kajron, pjesë të rendit financiar e administrativ osman dhe e forcoi Xhagbubin si qendër tregtare. Besnikëria e popullsisë së rajonit ndaj halifit vërtetohet edhe nga udhëpërshkrimi i kolonelit Sadik el-Muejjed, që e vizitoi vendin më 1884 dhe 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Fillimi i gërmimit të Kanalit të Suezit dhe themelimi i Port Saidit", "cef0be8d"], "d": ["Punimet e gërmimit për projektin e Lesseps-it, që Babialia e miratoi më 5 janar 1856, filluan më 25 prill 1859; kanali do të përfundonte dhjetë vjet më vonë, më 16 nëntor 1869. Në skajin mesdhetar të gërmimit, në rripin bregdetar mes liqenit të Menzilesë dhe detit, fshati me pesë shtëpi-barraka i ngritur për punëtorët përbënte bërthamën e Port Saidit. Këtë emër, me kuptimin 'porti i Saidit', ia dhanë qytetit më 1860 zyrtarët e kompanisë së kanalit, për nder të Said Pashës, guvernatorit të atëhershëm të Egjiptit. Kështu në hartën osmane lindi një port i ri në një rrip bregdetar ku më parë nuk kishte asnjë vendbanim.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Vizita e sulltan Abdylazizit në Egjipt dhe themelimi i Ismailijes në istmin e Suezit", "bcfacf38"], "d": ["Sulltan Abdylazizi, me nxitjen e vezirit të madh Jusuf Kamil Pashës, më 3 prill 1863 shkoi në Egjipt dhe u prit me brohoritje të mëdha; qëllimi ishte të forcohej lidhja me qendrën e vilajetit, që që nga kryengritja e Mehmed Ali Pashës së Kavallës kishte filluar të merrte faktikisht formën e një shteti të veçantë. Po atë vit në istëm, mbi kodrat Tilal el-Xhisr në bregun e liqenit Timsah, u themelua qendra administrative e kompanisë së kanalit: fillimisht u ngrit fshati Karjetutimsah për inxhinierët, pastaj Karjetularab për punëtorët. Kur hidivi Ismail Pasha u interesua nga afër për kanalin e ujit të ëmbël dhe ndërtoi për vete një vilë në këtë kodër, vendbanimi u quajt me emrin e tij Ismailije. Themelimi i qytetit datohet në vitin 1863; dita e saktë nuk dihet.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Guvernatorllëku i Mit'hat Pashës në Bagdad dhe ngulimi i fiseve — themelimi i Ramadit dhe Nasirijes", "0fa98f06"], "d": ["Mit'hat Pasha, i hequr nga kryesia e Shura-i Devletit dhe i larguar nga Stambolli, e qeverisi vilajetin e Bagdadit, që përfshinte edhe Mosulin dhe Basrën, ndërmjet viteve 1869-1872 me kompetenca të gjera, duke pasur edhe komandën e Ushtrisë së Gjashtë. Atje zbatoi Ligjin e Tokës dhe ligjin e ri të vilajetit, i shpërndau tokat me tapi dhe i lidhi fiset nomade me jetën e ngulur dhe me autoritetin shtetëror. Si fryt i kësaj politike ngulimi, më 1869 u themeluan Ramadi në brigjet e Eufratit për fisin Dulejm, dhe në jug Nasirija nga mutasarrifi i Muntefikut, Nasir Pasha es-Sadun; të dy lindën në vende ku deri atëherë nuk kishte vendbanim dhe u shfaqën për herë të parë në hartë në këtë datë.", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Pas disfatës së Ankarasë, vojvoda i Vllahisë Mircea rimori Dobruxhën — Silistrën, Konstancën, Babadaghin, Isakçin", "5eaefc68"], "d": ["Disfata e Bajazitit I Jilldërëm nga Timuri në Ankara tronditi sundimin osman përgjatë Danubit. Vojvoda i Vllahisë, Mircea, duke përfituar nga ky boshllëk, hyri sërish në Dobruxhë; Silistra, Konstanca, rrethinat e Babadaghit dhe Isakçi në brigjet e Danubit mbetën gjatë viteve të Interregnumit në duart e tij. Mircea e përkrahu Musa Çelebiun kundër Mehmet Çelebiut. Silistrën e mbajti deri në vdekjen e tij më 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Babadaghi dhe rrethinat kalojnë te osmanët — Mircea dhe i biri Mihail u mundën", "bfda2c60"], "d": ["Mehmet Çelebiu, pasi mundi vojvodën e Vllahisë Mircea dhe të birin Mihail, e vuri nën sundimin osman Babadaghin në Dobruxhën Veriore dhe rrethinat e tij. Babadaghi ishte një qytezë që mban emrin e Salltuk Babait dhe që u themelua me ngulimin turkmen të shekullit XIII. Silistra, Konstanca dhe kështjellat e tjera të Dobruxhës përreth mbetën deri më 1419 në duart e Vllahisë; pra Babadaghi shfaqet për tre vjet si ishull i shkëputur nga toka osmane (eksklavë).", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Rimarrja e Silistrës dhe Dobruxhës — pas vdekjes së Mirceas", "73eb6ae9"], "d": ["Trazirat që shpërthyen në Vllahi pas vdekjes së vojvodës Mircea më 1418 i dhanë Sulltan Mehmet Çelebiut rastin për të rimarrë Silistrën dhe Dobruxhën. Në pranverën e vitit 1419 Silistra, Konstanca dhe pjesa më e madhe e Dobruxhës hynë sërish nën administrimin osman; kështjellat e Enisalës (Jenisale) dhe Isakçit u riparuan dhe u bënë kështjella kufitare (serhat); pas kësaj Dobruxha mbeti në duart osmane deri më 1878.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Mbyllja e Danubit të Poshtëm — aneksimi i Giurgiut, Turnut dhe Orshovës", "331a0b68"], "d": ["Pas mbylljes së periudhës së Interregnumit, hapi i Mehmet Çelebiut për të vënë në rregull vijën e Danubit dha fryt më 1420. Kështjella e Giurgiut, që vojvoda i Vllahisë Mircea i Vjetër e kishte ndërtuar në tokën e vet, duke i mbuluar shpenzimet me shitjen e kripës, kaloi këtë vit në duart osmane (Dobruxha ishte rimarrë një vit më parë, në pranverë 1419 — TDV silistre) dhe u aneksuan Turnu (Kulla/Holovnik) në bregun e djathtë të Danubit dhe Orshova — me emrin e mëvonshëm Fetislam. Kështu u vunë nën kontroll përnjëherë të dy brigjet e lumit. Rëndësia e Giurgiut vjen nga gjeografia: është një kështjellë osmane e ngritur në bregun e majtë, pra vllah, të Danubit dhe bashkë me Rusenë në bregun përballë mban dy skajet e të njëjtit kalim. Dokumentet osmane e shkruajnë hapur këtë dyzim — për Rusenë thuhet 'Giurgiu i bregut këtej', për Giurgiun 'Giurgiu i bregut përtej'. Kështjella do të rimerrej nga vllahët më 1427, do të hynte sërish nën kontrollin osman më 1449 dhe, me lidhjen e kazasë së Giurgiut me sanxhakun e Nikopojës, do të bëhej një ishull i administruar drejtpërdrejt brenda vojvodisë. Përgjigja se pse bregu i Danubit i Vllahisë është me ngjyrë të errët në hartë fillon këtu.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Rajoni i Toplicës (Kurshumlija, Prokuplja) hyri nën sundimin osman", "e22e690d"], "d": ["Gjatë fejesës së Muratit II me Mara Brankoviqin, vlerësohet e mundshme që rajoni i Dubočicës dhe Toplicës (rrethinat e Leskovcit, Kurshumlisë dhe Prokupljes) të ketë kaluar nën sundimin osman; regjistrimi tahrir i viteve 1445-1447 tregon se rajoni iu dha spahinjve osmanë si timar. Në hartë, Kurshumlija dhe Prokuplja janë nën administrimin osman që nga ky vit.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Aneksimi i fushës së Sarajit — krijimi i skajit kufitar osman brenda Bosnjës", "be5c0f00"], "d": ["Pasi mbretërit e Bosnjës u detyruan të paguanin haraç në 1428-1429, osmanët filluan të vendoseshin në mënyrë të qëndrueshme brenda mbretërisë. Ndërmjet viteve 1428-1435 u mor qyteza Hodidjed; më 852 (1448) vilajeti i Hodidjedit, bashkë me fushën e Sarajit, hyri tërësisht nën administrimin osman. Kjo është një zonë kufitare e krijuar në mes të mbretërisë pesëmbëdhjetë vjet para pushtimit të Bosnjës dhe e qeverisur nga beu i Shkupit Isa Beu, me titullin vojvodë — meqë rreth saj kishte ende bejlerë boshnjakë vartës të osmanëve, rajoni ishte nën kontroll të dyanshëm. Edhe vetë qyteti lindi në këtë periudhë: para vitit 1462 Is'hak Beu ose i biri, Isa Beu, ngriti lagjen e parë myslimane, më 862 (1458) në emër të Fatihut u ndërtua Xhamia e Hunqarit, dhe me ndërtimin mbi arat e fshatit Brodec doli në dritë qyteza Saraj. Pushtimi i vitit 1463 e zhduku Mbretërinë e Bosnjës; ndërsa fusha e Sarajit, në atë datë, kishte qenë tashmë tokë osmane për pesëmbëdhjetë vjet.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Podgorica u bashkohet tokave osmane — fusha e Zetës vihet nën kontroll", "46e401c5"], "d": ["Qyteza, e ngritur në fushën ku bashkohen ujërat e Moraçës dhe Ribnicës, njëzet kilometra në veri të liqenit të Shkodrës, përmendet në burime për herë të parë më 1216 me emrin Ribnica dhe më 1326 me emrin Podgorica. Më 1457 iu bashkua tokave osmane, dhe kështu kontrolli mbi fushën e Zetës doli nga duart e dinastive Balsha-Cërnojeviq. Sulltan Mehmeti II Fatih, ndërmjet viteve 1474-1478, urdhëroi ndërtimin e një kështjelle dhe një xhamie mbi shkëmbinjtë e thepisur në bashkimin e dy lumenjve; pas pushtimit të Shkodrës më 1479, rajoni u lidh me sanxhakun e sapokrijuar të Shkodrës. Podgorica, që në regjistrimin e vitit 1485 ishte një qytezë e krishterë me dyzet shtëpi, arriti më 1529-30 në 800 vetë dhe në një garnizon prej tridhjetë e dy vetësh nën një dizdar brenda kështjellës, dhe më 1582 në 322 shtëpi. Evlija Çelebiu më 1662 numëroi në Kështjellën e Fatihut treqind shtëpi, depo, armaturë dhe shtatëqind roja. Këto shënime tregojnë edhe dallimin mes fushës dhe malit të Zetës: fusha është një kaza osmane e regjistruar, e taksuar dhe me garnizon — por në shekullin XVIII qyteti do të detyrohet të fortifikohet me gjashtë bastione dhe mure me tri porta për të penguar sulmet e fiseve nga malet e Malit të Zi. Podgorica kaloi në duart e Malit të Zi në fund të luftës së viteve 1876-1878 dhe mbeti atje me Traktatin e Berlinit.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Marrja e Foçës — hapet hyrja e parë në Dukatin e Hercegovinës", "f098a9e6"], "d": ["Pasi më 1463 u zhduk Mbretëria e Bosnjës, erdhi radha e tokave të Stjepan Vukçiq-Kosaças, i cili ishte shkëputur nga mbretëria dhe kishte krijuar dukatin e vet. Foça, në luginën e Drinës, në udhëkryqin e rrugës tregtare që lidhte Stambollin me Dubrovnikun, hyri nën administrimin osman më 1465. Rëndësia e qytetit u kuptua menjëherë: më 1470 u bë qendër e sanxhakut të sapoorganizuar të Hercegovinës — pra bërthama administrative e Hercegovinës u ngrit në Foça para se vetë dukati të rrëzohej. Aneksimi i plotë i dukatit do të zgjaste deri më 1483. Pas kësaj Foça, falë klimës së favorshme dhe pozitës në udhëkryq, u zhvillua si qendër tregtare e administrative. Në hartë kjo datë është dita kur, pas pushtimit të Bosnjës, filloi vala e dytë drejt jugut.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Aneksimi përfundimtar i Livnos dhe Bosnjës Perëndimore — vendosja e kufirit me Venedikun", "c14d4283"], "d": ["Kështjella mbi pllajën që dominon fushën e Livnos ishte ndërmjet viteve 1448-1454 në duart e Stjepan Vukçiq-Kosaças, themeluesit të Dukatit të Hercegovinës. Gjatë fushatës së Bosnjës më 1463 u pushtua për pak kohë nga forcat osmane, por po atë vit u mor sërish; më 1466 zot i qytetit është Ivanish Vlatkoviq. Sipas shprehjes së TDV-së, sundimi përfundimtar osman ka shumë gjasa të jetë realizuar në vitet 1468-1469, dhe regjistrimi i vitit 1485 e shënon Livnon tashmë si tokë osmane. Kjo është mbyllja e skajit perëndimor të pushtimit të Bosnjës: Livno u bë qytezë kufitare e rrezikshme, fqinje me tokat venedikase vetëm tridhjetë e gjashtë kilometra larg përgjatë fushës së rrafshët, dhe e ruajti këtë pozitë derisa në vitet 1521-1522 guvernatori i Bosnjës Gazi Husrev Beu mori kështjellat venedikase.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Humbja e Šabacit (Bëgyrdelen) në favor të hungarezëve — çarja e parë në vijën e Savës", "129fe8f2"], "d": ["Në vendin që kishte kaluar në duart osmane në kohën e Sulltan Mehmetit II Fatih dhe që më parë quhej Zaslon, më 1471 ishte ndërtuar një fortifikim prej druri e dheu. Meqë ndodhej në një pikë që kërcënonte Beogradin dhe prej andej mund të bëheshin lehtë sulme në viset jugore të Hungarisë dhe Austrisë, edhe emrin kështjella e merrte nga ky funksion — Bëgyrdelen (turqisht Böğürdelen) do të thotë \"fortifikim që godet anash\". Mbreti hungarez Mátyás Corvin e rrethoi kështjellën nga fundi i vitit 1475 dhe e shtiu në dorë në shkurt 1476. Epika hungareze me titull Szabács viadala, që tregon rrethimin, është ndër shembujt më të gjatë të poezive historike hungareze të shekullit XV teksti i të cilave ka arritur deri sot. Hungarezët krijuan në rajon një banat dhe, duke e fortifikuar sërish kështjellën me gur, e bënë hallkë të zinxhirit të fortifikimeve kufitare. Osmanët u përpoqën ta rimerrnin më 1492 dhe nuk ia dolën; kështjella mbeti dyzet e pesë vjet në duart hungareze.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Pushtimi i ishujve Jonianë — fundi i dukatit Tocco: Ajamavra, Qefalonia, Zakintos, Itaka", "07b27251"], "d": ["Traktati i Stambollit, i nënshkruar me Venedikun në janar të po atij viti, ua kishte lënë osmanëve Shkodrën dhe bregdetin shqiptar; ishujt Jonianë nuk ishin nën administrimin e Venedikut, por të familjes Tocco, që mbante kontenë Qefaloni-Zakintos, dhe u morën me një operacion të veçantë. Sipas zërit për Ajamavrën (Lefkadën) të TDV-së, duka i fundit, Leonardo Tocco, fillimisht e kishte ruajtur besnikërinë duke u martuar me Milica Brankoviqin, të afërme të Fatihut, por kur gruaja i vdiq më 1464, më 1477 u martua me Francesca Marzanon nga dinastia e Napolit dhe e zemëroi padishahun. Dy vjet më vonë flota nën komandën e beut të Vlorës, Gedik Ahmed Pashës, shtiu në dorë Lefkadën bashkë me Qefalonin në jug; Leonardo dhe Francesca ikën në Itali. Zëri për Gedik Ahmed Pashën shënon se në të njëjtin operacion u mor edhe Zakintosi (Zante); me këtë dorëzim hyri nën administrimin osman edhe Itaka, e varur nga kontea e Qefalonisë. Kështu rruga detare nga hyrja e Adriatikut deri në More u vu tërësisht nën kontroll. Nga ishujt, Zakintosi do t'i lihej Venedikut tre vjet më vonë, Qefalonia dhe Itaka do të humbeshin më 1500, dhe vetëm Lefkada do të mbetej dyqind vjet në duart osmane.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Nënshtrimi i Zetës së Cërnojeviqëve dhe kthimi i Cetinjës në qendër", "59d20267"], "d": ["Kur Shkodra mbeti më 1479 në duart osmane, krahina malore e Zetës në prapavijën e saj hyri gjithashtu brenda kufijve të perandorisë. Familja Cërnojeviq, që e mbante rajonin, e njohu sundimin e Bajazitit II, i cili hipi në fron pas vdekjes së Fatihut, u detyrua të paguante haraç dhe mbeti e lirë në punët e brendshme; Ivan Cërnojeviqi e tërhoqi qendrën nga fusha në Cetinje, rrëzë malit Lovçen, dhe themeloi qytetin. Manastiri që ndërtoi aty dy vjet më vonë u bë qendra fetare e rajonit. Kështu Mali i Zi shfaqet në hartë jo si tokë e drejtpërdrejtë osmane, por si zonë vartëse me ngjyrë të çelët. Zëri për Malin e Zi i TDV-së përmend dinastinë dhe peshkopatën e Cetinjës dhe shkruan se sundimi u shndërrua në sanxhak të veçantë më 1514 me anë të Skender Beut (nga fisi Cërnojeviq, i rritur në pallatin osman); viti 1482 nuk përmendet te TDV-ja, është data që jep historiografia malazeze. Për shkak të ashpërsisë së terrenit, administrimi këtu nuk funksionoi kurrë aq rreptë sa në fusha.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Pushtimi i kështjellës së Kilias — çelësi i grykëderdhjes së Danubit", "ef4eca73"], "d": ["Që prej shtatorit 1455 Moldavia ishte vojvodë vartëse që paguante haraç vjetor prej dy mijë florinjsh ari, por dy portet e saj që hapeshin në Detin e Zi ishin ende në duart e vojvodës dhe tregtia që vinte nga Danubi kalonte andej. Bajaziti II e bëri fushatën e parë të madhe të sundimit të tij kundër këtyre dy porteve. Komandanti i kështjellës së Kilias, e cila u bombardua dhjetë ditë rresht ditë e natë, u detyrua të dorëzohej. Kështjella u vu drejtpërdrejt nën administrimin osman dhe u bë sanxhakbejllëk; në gjysmën e dytë të shekullit XVI, për shkak të rrezikut kozak, u bë kaza dhe u lidh me sanxhakun e Akermanit të bejlerbellëkut të Rumelisë. Pas kësaj Moldavia shfaqet në hartë me dy shkallë: në brendësi vojvodë qëndron si tokë vartëse me ngjyrë të çelët, ndërsa dy portet bregdetare janë sanxhak i drejtpërdrejtë osman me ngjyrë të errët. Zëri për Moldavinë i TDV-së i përmend këto të dyja si 'çelësat dhe dyert e Moldavisë' dhe shkruan se rajoni iu lidh përfundimisht osmanëve në kohën e Bajazitit II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Pushtimi i Akermanit — grykëderdhja e Dnjestrit dhe mbyllja e portës së Moldavisë drejt Detit të Zi", "7cb20feb"], "d": ["Njëzet ditë pas dorëzimit të Kilias, ushtria arriti para Akermanit në grykëderdhjen e Dnjestrit dhe kështjella u mor më 4 gusht. Qyteti ishte porti më i gjallë i Moldavisë; në kohën e Fatihut, kur vojvoda Pjetri III më 1455 njohu sundimin osman, tregtarëve të Akermanit u ishte dhënë leja për tregti, tani porti u bë drejtpërdrejt i shtetit. Pas pushtimit Akermani, i bërë sanxhak i varur nga bejlerbellëku i Rumelisë, më 1593 iu aneksua ejaletit të sapokrijuar të Özüsë. Kështu lëvozhga e jashtme e Moldavisë, e rrethuar nga Hotini në veri dhe nga Kilia dhe Akermani në jug, filloi të hynte nën kontrollin e drejtpërdrejtë osman; vojvodë mbeti e lirë në punët e brendshme, por pa dalje në det. Në hartë nuk ka zonë boshe në mes — sanxhaqet portuale me ngjyrë të errët dhe toka e vojvodës me ngjyrë të çelët preken me njëra-tjetrën; stepa e Buxhakut mes tyre mbeti ende pjesë e vojvodës deri më 1538.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Dorëzimi i Lepantos — hyrja e gjirit të Korintit merret nga Venediku", "2cfe0777"], "d": ["Lepanto ishte në duart e Venedikut që nga viti 1407 dhe mbante hyrjen e gjirit të Korintit; i gjithë bregdeti brenda gjirit vareshi nga rrezja e kësaj kështjelle. Në fushatën e vitit 1499 kështjella u rrethua nga toka, ndërsa flota osmane, që u përlesh me flotën venedikase në ujërat para Lepantos, i ndihmoi nga deti forcat rrethuese. Venedikasit në kështjellë ua dorëzuan qytezën osmanëve më 26 gusht. Pas kësaj qyteti mbeti njëqind e tetëdhjetë e tetë vjet nën osmanët, më 1687, me humbjen e Moresë, kaloi sërish te Venediku dhe u rimor më 1715. Beteja detare e asaj vere dhe ky dorëzim janë dy ngjarje të veçanta: përleshja e flotave ndodhi në skajin perëndimor të Moresë, në ujërat e Sapienza-Zonchios; ndërsa Lepanto ra me një rrethim tokësor në hyrje të gjirit të Korintit.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Aneksimi i banatit të Srebrenikut — çarja e parë e vijës hungareze në Bosnjën veriore", "6d98c725"], "d": ["Pasi Mbretëria e Bosnjës u rrëzua më 1463, Mátyás Corvin kaloi në kundërsulm dhe në veri të mbretërisë krijoi dy banate që ndaluan përparimin osman: Jajcën në perëndim dhe Srebrenikun në verilindje. Këto ishin vija e përparme mbrojtëse e Hungarisë në Bosnjë dhe mbyllnin korridorin mes Savës dhe Bosnjës. Banati i Srebrenikut u shti në dorë më 1512; kështu krahu lindor i vijës u shemb dhe sanxhaku i Zvornikut mundi të zgjerohej drejt veriut. Jajca, në krahun perëndimor, do të qëndronte edhe gjashtëmbëdhjetë vjet dhe mundi të merrej vetëm pas Mohaçit, më 1528.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Pushtimi i Šabacit — kështjella e parë që mori Sulejmani Kanuni dhe vendi ku u mor vendimi për Beogradin", "85177a90"], "d": ["Gjatë fushatës së parë të Sulltan Sulejman Kanuniut në Hungari, forcat e bejlerbeut të Rumelisë, Ahmed Pashës, të dërguara në rajon, pas një rrethimi të ashpër e morën kështjellën më 7 korrik 1521. Šabaci është kështjella e parë e pushtuar në sundimin e Kanuniut. Pas pushtimit padishahu hyri vetë në kështjellë dhe urdhëroi rindërtimin e qytetit; edhe vendimet për pushtimin e Beogradit u morën këtu — pra plani për Beogradin, që do të binte më 29 gusht 1521, u hartua në Šabac. Pas kësaj kështjella mbeti afro dyqind vjet në duart osmane; fillimisht u lidh me ejaletin e Rumelisë, nga viti 1580 me ejaletin e Bosnjës, pastaj për pak kohë me sanxhakun e Smederevës dhe, më në fund, me sanxhakun e Zvornikut. Në hartë kjo datë është dita kur vija e Savës u mbyll në favor të osmanëve.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Fillon kryengritja e tri vojvodive — Transilvania kaloi në Lidhjen e Shenjtë, bejlerët proosmanë u arrestuan", "68a33800"], "d": ["Në vitin e dytë të Luftës së Gjatë, brezi vasal osman në Evropën Qendrore u shpërbë përnjëherë. Lidhjes së Shenjtë, të krijuar nën patronazhin e papës Klementi VIII, në fund të verës iu bashkuan Moldavia dhe Transilvania: vojvoda i Moldavisë Aron Vodă më 16 gusht 1594 e zyrtarizoi me një dokument kalimin në anën e krishterë, ndërsa princi i Transilvanisë Zsigmond Báthory më 28 gusht 1594 i likuidoi bejlerët proosmanë që kundërshtonin luftën dhe e theu opozitën e brendshme. Vojvoda i Vllahisë, Mihai Trimi, iu bashkua lidhjes në vjeshtën e po atij viti. Kështu tri principatat vartëse osmane në veri të Danubit — tri vojvodi që kishin paguar haraç për njëqind e pesëdhjetë vjet dhe vojvodët e të cilave miratoheshin nga Stambolli — kaluan brenda së njëjtës vjeshtë në anën kundërshtare. Vendimi u zyrtarizua me traktatin e nënshkruar në Pragë më 28 janar 1595. Kjo ishte goditja më e rëndë që pësoi rendi osman i sundimit të tërthortë në veri të Ballkanit; kryengritja do të shtypej, por besnikëria e tri principatave nuk do të ishte më kurrë aq e fortë sa në vitet 1526-1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Kryengritja e Bukureshtit dhe sulmi mbi kështjellat e Danubit", "18971100"], "d": ["Vendimi i Lidhjes së Shenjtë u zbatua me gjak një muaj më vonë: Mihai Trimi në Bukuresht kaloi në shpatë njësinë e gardës osmane dhe huadhënësit levantinë të qytetit. Po atë dimër kryengritja u përhap në vijën e Danubit; forcat e Vllahisë sulmuan Giurgiun, Brailën, Hirsovën dhe Silistrën, ndërsa nga ana e Moldavisë Aron Vodă bëri të njëjtin sulm mbi garnizonin osman në Bender. Zgjedhja e vendeve të goditura nuk është e rastit: asnjë prej tyre nuk ishte tokë e vojvodive, por kështjella dhe kaza përgjatë Danubit të varura drejtpërdrejt nga administrimi osman — kazaja e Giurgiut varej nga sanxhakbejllëku i Nikopojës, Braila që nga viti 1538 drejtpërdrejt nga shteti, Benderi po që nga viti 1538 nga sanxhaku i Buxhakut. Pra, kryengritja nuk kishte goditur brendësinë vasale, por lëvozhgën e drejtpërdrejtë osmane që e rrethonte atë. Pa shpuar këtë lëvozhgë, trekëndëshi Transilvani-Vllahi-Moldavi nuk mund të lidhej me frontin habsburg.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Beteja e Călugărenit — fushata e Koxha Sinan Pashës në Vllahi", "201210a1"], "d": ["Pasi humbën përnjëherë tri vojvoditë, veziri i madh Koxha Sinan Pasha kaloi Danubin me një ushtri të madhe dhe marshoi për ta vënë sërish Vllahinë nën bindje. Mihai Trimi, duke e ditur se nuk mund t'i rezistonte në betejë të hapur, e priti ushtrinë në kalimin moçalor të Neajlovit, në Călugăreni, dhe i sulmoi befas forcat e ngujuara në terrenin e ngushtë. Pas sulmit, i paaftë t'i bënte ballë ushtrisë osmane më të madhe në numër, u tërhoq në veri, në male; Sinan Pasha pushtoi Bukureshtin dhe Târgoviștenë dhe u përpoq ta vinte Vllahinë nën administrim të drejtpërdrejtë. Prandaj Călugăreni nuk ishte disfatë për osmanët, por një sulm i befasishëm që e vonoi përfundimin e fushatës; por fakti që Mihai arriti ta ruante ushtrinë i mundësoi, pas disa javësh, të kalonte në kundërsulm me ndihmën që erdhi nga Transilvania.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Tërheqja nga Vllahia dhe sulmi në Giurgiu — fushata e shtypjes mbetet pa rezultat", "118806e1"], "d": ["Përballë kundërsulmit të Mihait Trim, të bashkuar me forcat e princit të Transilvanisë, Sinan Pasha liroi Târgoviștenë dhe Bukureshtin dhe u tërhoq drejt Danubit. Çasti më i kushtueshëm i tërheqjes u përjetua pranë kalimit: në tetor 1595 akinxhinjtë që ndiqnin ushtrinë që kthehej nga Vllahia ranë në Giurgiu në sulmin e befasishëm të Mihait. Kështu fushata përfundoi pa arritur synimin për ta vënë Vllahinë nën administrim të drejtpërdrejtë, dhe vojvodia mbeti faktikisht e humbur. Autoriteti osman në këtë trekëndësh mundi të riparohej vetëm me vite dhe pjesë-pjesë; kthimi i Transilvanisë në bindje do të priste kryengritjen e Bocskait në 1604, ndërsa mbyllja e plotë e frontit Traktatin e Zsitvatorokut të vitit 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Shkëputja e Hotinit nga Moldavia — sanxhak i drejtpërdrejtë osman në mes të vojvodisë", "947517cb"], "d": ["Kalimi i vojvodës së Moldavisë Dimitrie Cantemir në anën ruse gjatë fushatës së Prutit tregoi se kufiri verior i vojvodisë nuk mund t'i lihej më vojvodës. Prandaj pas vitit 1711 Hotini u shkëput nga Moldavia dhe u vu nën administrimin e drejtpërdrejtë osman; fillimisht iu dha statusi i nahijes, pastaj i sanxhakut. Pas pushtimit të përkohshëm rus në 1713, kështjella u riparua dhe u zgjerua nën mbikëqyrjen e një delegacioni teknik osman e francez të dërguar nga Stambolli dhe u bë fortifikimi osman më i fortë në veri të Danubit. Fakti që pas kësaj date Hotini në hartë del nga toni i vojvodisë vartëse e kthehet në ngjyrën e drejtpërdrejtë osmane, dhe qëndron si ishull i vetëm në mes të Moldavisë vartëse, është pikërisht pasqyrimi i kësaj ndarjeje administrative — jo gabim vizatimi. E njëjta strukturë ekzistonte tashmë në Buxhak që nga viti 1538 dhe në Kili e Akerman që nga viti 1484: vojvodia e lirë në punët e brendshme, kështjellat kufitare të shtetit.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Pushtimi i dytë austriak i Šabacit — hapja e frontit të Savës", "063b3ad0"], "d": ["Pasi Austria hyri në luftë në krah të Rusisë më 9 shkurt 1788, vija e Savës u bë sërish front dhe Šabaci kaloi nën sundimin austriak më 24 prill 1788. Kështjella ishte lëshuar edhe më parë, më 17 gusht 1717, pa luftë në favor të Austrisë dhe u mbajt deri në Traktatin e Beogradit (1739); në atë periudhë popullsia ishte pakësuar aq shumë, sa në qytet kishin mbetur tridhjetë e katër shtëpi të krishtera dhe asnjë mysliman. Gjatë periudhës osmane 1739-1788 popullsia ishte rritur sërish në 1500-2000 vetë. Pushtimi i dytë do të merrte fund me Traktatin e Svishtovit (4 gusht 1791) dhe kështjella do t'u kthehej osmanëve.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Dorëzimi i Šabacit te Karagjorgje — kështjella e parë në Kryengritjen e Parë Serbe", "5c913eb4"], "d": ["Gjatë revolucionit të parë serb, që filloi më 1804 si reagim ndaj shtypjes së dajive dhe jamakëve në Beograd dhe më pas mori karakter nacionalist, kështjella e Šabacit iu dorëzua Karagjorgjes më 26 janar 1806. Kjo kështjellë mbi Savë është fortifikimi i parë i madh osman që kryengritësit shtinë në dorë dhe paralajmëron rënien e Beogradit. Kur kryengritja u shtyp më 1813 dhe Beogradi u rimor, edhe kështjella u kthye nën administrimin osman; por me kushtin e garnizonit të fermanit të vitit 1830, Šabaci u përcaktua, bashkë me Beogradin, Smederevën dhe Fetislamin, si një nga katër kështjellat në Serbinë autonome ku mbeti ushtri osmane, dhe e mbajti këtë status derisa më 1867 iu tërhoq garnizoni.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Lamia (Izdin) mbeti brenda kufijve të Greqisë — vija Arta-Volos", "930f63b8"], "d": ["Kufiri verior i shtetit të pavarur grek u vizatua më 1832 në vijën nga gjiri i Artës te gjiri i Volosit. Lamia (Izdin), që në periudhën osmane (1424-1832) ishte qendër kazaje e varur nga sanxhaku i Eubesë, meqë mbeti në jug të kësaj vije, i kaloi Greqisë; pjesa tjetër e Thesalisë (Larisa, Trikalla) mbeti në duart osmane deri më 1881.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Shpallja e luftës nga Rusia — fillimi i Luftës Nëntëdhjetetrishe", "ac548ab8"], "d": ["Shtypja e kryengritjes bullgare të vitit 1876 kishte shkaktuar indinjatë të madhe në opinionin evropian, dhe Rusia e shfrytëzoi atë deri në fund për ta izoluar Babialinë. Kur Shteti Osman refuzoi propozimin e Konferencës së Stambollit (Tersane) për ndarjen e Bullgarisë në dy provinca autonome dhe pastaj Protokollin e Londrës të 31 marsit 1877, Rusia shpalli luftë më 24 prill 1877 dhe ushtria e saj hyri në tokat e principatës së Rumanisë, të cilën e kishte tërhequr në anën e vet (harta e tregon Vllahinë dhe Moldavinë, nga ky çast deri në Armëpushimin e Edrenesë, me mbulesën me vija të përparimit rus). Meqë përkonte me vitin 1293 të kalendarit rumi, lufta njihet me emrin Lufta Nëntëdhjetetrishe. Operacionet u zhvilluan në dy fronte, në Danub dhe në Anadollin Lindor: në Danub ushtria osmane prej 180.000 vetësh e kishte konsideruar bregun e majtë të lumit vijën e parë të mbrojtjes dhe malet e Ballkanit vijën e dytë; në lindje 55.000 ushtarët e Ahmed Muhtar Pashës ishin vendosur mes Ardahanit dhe Doghubajazitit. Në hartë kjo luftë është ngjarja që nis shembjen e Rumelisë osmane — të gjithë kufijtë e sotëm të Bullgarisë, Serbisë, Malit të Zi dhe Rumanisë janë produkt i këtyre pesëmbëdhjetë muajve.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Rumania shpall pavarësinë — fundi i vasalitetit të Vllahisë dhe Moldavisë", "bdd164b3"], "d": ["Dy javë pas shpalljes së Luftës së 93-ës, principata e Rumanisë shpalli pavarësinë dhe hyri në luftë në krah të Rusisë; pjesa e saj në rrethimin e Plevnës qe vendimtare në disfatën osmane. Kështu mori fund de facto vasaliteti mbi katërqindvjeçar i Vllahisë dhe Moldavisë; pavarësia fitoi njohje ndërkombëtare në Kongresin e Berlinit (1878). Harta e tregon Rumaninë që nga kjo datë jo si vartëse, por si shtet të pavarur me ngjyrën e vet. Me shpalljen e pavarësisë, e gjithë Vllahia dhe Moldavia (Jashi, Galaci, Braila, Giurgiu, Calafati, Botoshani etj.) u bënë Rumani e pavarur.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Ushtria ruse kalon Danubin — bien Svishtovi dhe Tërnova", "811367b1"], "d": ["Rusët, që me fillimin e luftës hynë në tokat rumune dhe e tërhoqën këtë principatë në anën e vet, përparuan me dy krahë, njërin drejt Dobruxhës dhe tjetrin drejt Bukureshtit. Danubi u kalua mes Rusesë dhe Nikopojës, dhe më 27 qershor u pushtua Svishtovi, më 1 korrik kryeqyteti i vjetër bullgar, Tërnova. Edhe pse ishte urdhëruar evakuimi, meqë nuk iu kushtua kujdes kësaj, edhe Nikopoja u dorëzua pasi rezistoi për një farë kohe. Çarja e vijës së parë mbrojtëse brenda një jave shkaktoi panik të madh në Stamboll; madje u përhapën lajme se qendra e sulltanatit do të zhvendosej në Bursë, dhe drejtimi i luftës iu dorëzua një këshilli ushtarak të krijuar në kryeqytet.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Evakuimi i qafës së Shipkës — çahet vija e Ballkanit", "1f45e50a"], "d": ["Forcat osmane në Shipkë, më strategjikja e qafave që kapërcenin malet e Ballkanit, i rezistuan me forcë sulmeve ruse; por kur u bindën se do të munden, më 19 korrik e liruan fshehurazi qafën. Kështu u hap edhe vija e dytë e mbrojtjes dhe gjenerali Gurko më 22 korrik shtiu në dorë Stara Zagorën. Sulejman Pasha, që erdhi nga ana e Malit të Zi, megjithëse e mundi Gurkon dhe rimori vendet e pushtuara në jug të Ballkanit, nuk arriti ta rimerrte Shipkën pavarësisht sulmeve që zgjatën me muaj nga 21 gushti. Në hartë, kjo shënon se uniteti mbrojtës mes veriut dhe jugut të vargmalit të Ballkanit nuk mundi të rivendosej më: lufta në frontin e Danubit tani do të nyjëzohet në Plevnë.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Lovçi u pushtua nga ushtria ruse", "70e54611"], "d": ["Në Luftën e 93-ës, Lovçi u pushtua nga rusët më 5 qershor 1877; forcat osmane nën komandën e Rifat Pashës i shtynë rusët më 15 qershor; më 23 gusht qyteti u lirua nga osmanët dhe u pushtua sërish nga rusët. Harta e tregon Lovçin nga kjo ditë deri në Traktatin e Berlinit nën pushtim rus (me vija); juridikisht vazhdon të jetë tokë osmane.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Rënia e Karsit — shpërbërja e frontit lindor dhe fortifikimet e Azizijes", "53fc3bf5"], "d": ["Rusët, që përparonin në Anadollin Lindor me tri kolona drejt Karsit, Doghubajazitit dhe Ardahanit, kishin marrë Doghubajazitin më 30 prill dhe kishin hyrë në Ardahan, por, duke marshuar mbi Erzurum, më 15 korrik u mundën dhe u dëbuan jashtë kufirit. Ky sukses, që i solli Ahmed Muhtar Pashës titullin \"Gazi\", u përmbys kur në gusht gjenerali Lazarev kaloi sërish në sulm, dhe më 18 nëntor ra Karsi. Forcat osmane, të tërhequra në Erzurum për një mbrojtje më të përshtatshme, bënë rezistencë të madhe në fortifikimet e Azizijes, me nxitjen që Nene Hatuni i bëri popullsisë. Karsi, Ardahani dhe Batumi do t'i liheshin Rusisë tetë muaj më vonë në Berlin si pjesë e dëmshpërblimit të luftës.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Fillimi i Luftës së Parë Ballkanike — Mali i Zi shpall luftë", "c0c2697e"], "d": ["Shtetet ballkanike, pasi Itihad ve Terakki me ligjin e 3 korrikut 1911 zgjidhi çështjen e kishave dhe kështu u hoq pengesa më e madhe mes tyre, me nxitjen e Rusisë nënshkruan gjatë vitit 1912 traktate aleance me njëra-tjetrën (13 mars Serbi-Bullgari, 29 maj Bullgari-Greqi, në gusht Mal i Zi-Bullgari, 6 tetor Mal i Zi-Serbi). Babiali nuk e vuri re këtë; madje, duke u mbështetur te garancia e Rusisë, çmobilizoi 120 batalione të stërvitura në Rumeli. Katër shtetet më 3 tetor dorëzuan një notë të përbashkët dhe kërkuan autonomi për Maqedoninë, Shqipërinë dhe Kretën; meqë nuk morën përgjigje, më 8 tetor 1912 operacionet filluan me shpalljen e luftës nga Mali i Zi. Më 13 tetor ambasadorëve të Serbisë dhe Bullgarisë u dorëzuan pasaportat, të nesërmen këto dy shtete dhe pastaj Greqia shpallën luftë. Gjatë luftës mosmarrëveshjet politike brenda ushtrisë luajtën rol të madh në disfatë.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Në Rodope u shpartallua reparti i Kërxhalit, ra Kërxhali", "8cf59b7f"], "d": ["Pas shpalljes së luftës nga bullgarët, forcat bullgare që zbritën nga Rodopet e mundën repartin e Kërxhalit të Mehmed Javer Pashës dhe hynë në Kërxhali. Reparti i shpartalluar u tërhoq drejt Gjymylxhinës; pjesa lindore e Rodopeve u humb në javën e parë të luftës.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Shpartallimi i Ushtrisë Lindore dhe tërheqja në vijën e Çatalxhasë — humbja e Kumanovës dhe Selanikut", "cf95591a"], "d": ["Ushtria Lindore osmane më 23 tetor 1912 u mund nga ushtria bullgare tri herë më e madhe dhe u tërhoq deri te vija e Çatalxhasë, tridhjetë kilometra në perëndim të Stambollit; kryeqyteti u vu nën kërcënim të drejtpërdrejtë që në muajin e parë të luftës. Në të njëjtat ditë Ushtria Perëndimore u mund nga serbët në Kumanovë më 23-24 tetor dhe Tahsin Pasha me ushtrinë e tij prej 35.000 vetësh iu dorëzua grekëve në Selanik. Pas këtyre disfatave, më 29 tetor kabineti i Gazi Ahmed Muhtar Pashës dha dorëheqjen; Abdylhamidi II, që jetonte në internim në Selanik, më 1 nëntor u transferua në Stamboll. Vija e Çatalxhasë u mbajt deri në fund të luftës — gjeografia osmane pesëqindvjeçare e Rumelisë u reduktua brenda pak javësh në këtë rrip të ngushtë.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Princi Aleksandar hyri në qendrën e sanxhakut të Novi Pazarit", "326d0616"], "d": ["Forcat serbe e morën Novi Pazarin në javën e parë të luftës dhe u bashkuan me forcat malazeze që vinin nga perëndimi. Kështu sanxhaku i Novi Pazarit, që për njëqind vjet kishte ndarë Serbinë nga Mali i Zi, u shndërrua në urë mes dy aleatëve.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Pas betejës së Kërkklisesë u humb Kërklarelia", "eda4c759"], "d": ["Kur në Trakën Lindore Ushtria Lindore u mund në betejën e Kërkklisesë, qyteti që mbrohej nga Këlemen Abdullah Pasha iu la forcave bullgare. Qyteti u çlirua nga pushtimi nëntëmujor vetëm gjatë Luftës së Dytë Ballkanike, më 21 korrik 1913.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Shkupi, qendra e vilajetit të Kosovës, u lëshua pa rezistencë", "455d9b71"], "d": ["Pas disfatës së Kumanovës (23-24 tetor), Shkupi, qendra e vilajetit të Kosovës, mbeti pa mbrojtje. Meqë populli nuk dëshironte përleshje rreth qytetit, forcat serbe nën komandën e princit Aleksandar, të ftuara përmes konsujve, hynë në qytet pa rezistencë në mbrëmjen e 26 tetorit.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["U humb Velesi (Köprülü) përgjatë Vardarit", "73d20b7d"], "d": ["Dy ditë pas rënies së Shkupit, ushtria serbe, që zbriste drejt jugut përgjatë Vardarit, mori Velesin. Kështu porta e luginës së Vardarit që hapet drejt Selanikut kaloi në duart serbe.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Pellgu i Bregalnicës: gjenerali Stefanoviq hyri në Shtip", "70a84256"], "d": ["Njësitë serbe nën komandën e gjeneralit Stefanoviq e morën Shtipin pa hasur rezistencë; së pari hynë në qytet çetat e parregullta. Pas Kumanovës, pellgu i Bregalnicës në Maqedoninë lindore kaloi nën kontrollin serb.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Pas qafës së Sarantaporit, Verria kaloi nën sundimin grek", "02a68e02"], "d": ["Ushtria greke, që përparonte nga Thesalia drejt veriut, pasi kapërceu qafën e Sarantaporit (Kërkgeçit), vendosi sundimin mbi Verrian. Në atë kohë një pjesë e popullsisë myslimane të qytetit e braktisi rajonin.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["U humb Vodena në hekurudhën Selanik-Manastir", "fc15b917"], "d": ["Vodena në hekurudhën Selanik-Manastir kaloi në duart e ushtrisë greke. Me largimin me dhunë të popullsisë sllave dhe turke, popullsia e qytetit ra ndjeshëm brenda një kohe të shkurtër.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Beteja e Jenixhesë — Jenixhe Vardari kalon te grekët", "8f6cb76e"], "d": ["Korpusi i 8-të i përbërë i Hasan Tahsin Pashës u mund nga ushtria greke në Jenixhe, në perëndim të Selanikut, dhe u tërhoq në rajonin e Selanikut. Gjatë betejës u dogj pjesa më e madhe e qytezës; rruga për në Selanik iu hap ushtrisë greke.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizreni në jugperëndim të Kosovës u dorëzua", "bae6b1b9"], "d": ["Prizreni në jugperëndim të Kosovës iu dorëzua forcave serbe. Sjellja e njësive që hynë në qytet ndaj popullsisë myslimane u shënua si një nga faqet më të rënda të luftës në Kosovë.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Koloneli Mitov shpalli gjendje të jashtëzakonshme në Strumicë", "bcad75cc"], "d": ["Koloneli bullgar Mitov hyri në Strumicë dhe shpalli gjendje të jashtëzakonshme; kur u largua të nesërmen, ia la qytezën një kajmakami bullgar dhe një komandanti serb. Strumica ndërroi duar mes aleatëve gjatë gjithë luftës dhe më 1913 iu bashkua Bullgarisë.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Pasha ua la Selanikun grekëve", "1738933c"], "d": ["Hasan Tahsin Pasha, i tërhequr në Selanik pas disfatës së Jenixhesë, ndërsa ushtria bullgare afrohej nga veriu, ua la qytetin grekëve; ushtria greke hyri në qytet rreth mesditës së 8 nëntorit. Kështu humbi qyteti-port më i madh i Rumelisë osmane dhe Selaniku, vendlindja e Itihad ve Terakkit.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Gjymylxhina, qendra e Trakës Perëndimore, u hapet bullgarëve", "96eec25f"], "d": ["Kur reparti i Javer Pashës, i tërhequr nga Kërxhali, u tërhoq prapa drejt Feresë, Gjymylxhina iu dorëzua forcave bullgare. Qendra e Trakës Perëndimore ishte ndër tokat e para që në fund të luftës do t'i liheshin Bullgarisë.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Serbët që arritën në Elbasan hynë po atë ditë në Dibër", "16720246"], "d": ["Forcat serbe që përparonin nga Manastiri drejt perëndimit, ditën që arritën në Elbasan hynë edhe në Dibër dhe zbritën drejt Adriatikut. Po atë ditë në Vlorë shpallej pavarësia e Shqipërisë.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Timuri pushtoi Bagdadin për herë të dytë — u shkatërruan lagjet abaside të qytetit", "04b68a24"], "d": ["Timuri e mori Bagdadin dy herë me tetë vjet diferencë. Gjatë pushtimit të parë më 1393 qyteti nuk ishte dëmtuar shumë; i dyti, më 1401, konsiderohet goditja e dytë e rëndë ndaj jetës kulturore të Bagdadit — populli u kalua në shpatë dhe u shkatërrua pjesa më e madhe e lagjeve dhe ndërtesave të mbetura nga periudha abaside. Sundimtari xhelajirid Ahmedi u kthye në qytet më 1405 dhe u përpoq të riparonte muret e rrënuara dhe tregjet, por nuk pati kohë; Bagdadi kaloi më 1410 në duart e turkmenëve karakojunlu. Këto dy pushtime janë ndër hapat më konkretë që tregojnë sa shumë iu afrua Timuri kufijve osmanë e memlukë në rrugën drejt Betejës së Ankarasë.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Xhunejd Beu u kthye në krye të Ajdin-ilit — Ajdinidët sërish të pavarur", "63281658"], "d": ["Mehmet Çelebiu, duke marrë Izmirin në vitet 1414-15 dhe duke e dërguar Xhunejd Beun në sanxhakbejllëkun e Nikopojës, e kishte lidhur Ajdin-ilin me administrimin osman. Pas vdekjes së Mehmet Çelebiut, Xhunejdi u rishfaq në skenë përkrah Mustafa Çelebiut, që Bizanti e nxori si pretendent për fron, dhe madje i shërbeu si vezir. Murati II e shkëputi nga kjo aleancë me premtimin se do t'ia kthente bejlikun e vjetër; Xhunejdi u kthye në Izmir, shtiu në dorë Ajasulukun dhe, duke vrarë Ajdinoglu Mustafa Beun, u vu në krye të bejlikut. Kështu Ajdin-ili lindi nga kriza e Mustafait të Rremë (Düzmece) si i dalë nga administrimi osman.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Ekzekutimi i Xhunejd Beut dhe familjes së tij — fundi i bejlikut Ajdinid", "efa684ba"], "d": ["Kur Xhunejd Beu, që kishte rivendosur sundimin mbi Ajdin-ilin, nxiti bejlerët e Anadollit dhe kërkoi kontakt me Venedikun, Murati II dërgoi kundër tij bejlerbeun e Anadollit, Hamza Beun. Pasi i biri, Kurd Hasani, u mund afër Akhisarit dhe u zu rob, Xhunejdi, i tërhequr në Ipsili përballë ishullit të Samos, kur nuk i erdhi ndihma që priste nga karamanoglu dhe kur gjenovezët që vepronin bashkë me osmanët e bllokuan nga deti, u detyrua të dorëzohej; u zhduk bashkë me tërë farën e tij. Kështu tokat e Ajdinidëve hynë tërësisht nën administrimin osman.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurumi dhe pellgu i Vanit kalojnë te safavidët — shembet krahu verior i akkojunlunjve", "b418875f"], "d": ["Shah Ismaili, i cili mundi Elvend Beun në Sharur dhe hyri në Tabriz në verën e vitit 1501, vitin pasues përparoi në drejtim veriperëndimor dhe vuri nën sundim vijën nga Erzurumi deri në pellgun e liqenit të Vanit. Shteti Akkojunlu pas vdekjes së Uzun Hasanit ishte ndarë tashmë në dysh nga luftërat për fron: Elvend Beu mbante Azerbajxhanin dhe Dijarbekirin, ndërsa kushëriri i tij Murati Irakun Axhem dhe Farsin. Kjo ndarje e lehtësoi përparimin safavid; rajoni ndërroi duar brenda një viti në formën e dhjetë regjistrimeve. Pas kësaj Erzurumi mbeti gjashtëmbëdhjetë vjet në duart safavide dhe hyri nën sundimin osman vetëm pas Çalldiranit, në 1518-19. Këtë vit (1502) Ashkale dhe Pasinler (Hasankale), bashkë me rajonin e Erzurumit, kaluan nga akkojunlutë te safavidët (dita e pakonfirmuar).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Disfata e Murad Beut në Hamadan: Iraku Axhem dhe Farsi u kalojnë safavidëve", "8de07a31"], "d": ["Pretendenti i dytë për fronin akkojunlu, sulltan Murati, pësoi një disfatë të rëndë në betejën kundër Shah Ismailit afër Hamadanit dhe iku në Bagdad. Me këtë betejë të vetme rajonet e Irakut Axhem, Farsit dhe Kermanit hynë nën administrimin safavid; në hartë këto rajone ndërrojnë duar njëkohësisht. Ky është hapi më i madh i vetëm i shpërbërjes së Shtetit Akkojunlu — humbja e Tabrizit e kishte lënë dinastinë pa kryeqytet, ndërsa disfata e Hamadanit e la pa toka.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Shah Ismaili hyri në Jazd: bie bastioni i fundit i mbetjes akkojunlu në Iranin qendror", "6f9835df"], "d": ["Edhe pse pas disfatës së Hamadanit të vitit 1503 Iraku Axhem dhe Farsi u kaluan safavidëve, Jazdi kishte mbetur veçmas në duart e Bajindirli Murad Beut nga dinastia akkojunlu. Qyteti ra pas një rrethimi njëmujor dhe u mbyll ishulli i fundit akkojunlu në Iranin qendror. Shënimi i TDV-së: \"Shah Ismaili hyri në qytet pas një rrethimi njëmujor më 28 xhemaziulahir 910 (6 dhjetor 1504).\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Fushata e Shah Ismailit në Dijarbekir: bien qendrat e fundit të akkojunlunjve", "b6d8504e"], "d": ["Shah Ismaili, që shtiu në dorë Azerbajxhanin dhe pllajën e Iranit, më 1507 u drejtua nga perëndimi, drejt rajonit të Dijarbekirit, ku lindi dinastia akkojunlu. Vija nga Amidi te Mardini, nga Urfa te Harputi hyri me dy hapa nën administrimin safavid dhe akkojunlutë u zhdukën faktikisht. Kjo fushatë njëkohësisht e solli për herë të parë kufirin safavid ngjitur me kufijtë osmanë dhe memlukë; kështu u krijua terreni gjeografik i tensionit që çoi në Çalldiran.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Bagdadi u kalon safavidëve — Iraku Arab ndërron duar", "39730186"], "d": ["Pas sulltan Muratit akkojunlu, i cili pas disfatës së Hamadanit ishte strehuar në Bagdad, Shah Ismaili hyri më 1508 në Irakun Arab dhe e mori Bagdadin. Kalimi i tyrbeve të Qerbelasë dhe Nexhefit nën administrimin safavid ishte aq i rëndësishëm për pretendimin fetar të lëvizjes sa marrja e Tabrizit. Në hartë Iraku Arab ndërron duar po atë ditë; ky është hapi i fundit dhe gjeografikisht më i gjerë i shpërbërjes. Bagdadi mbeti në duart safavide deri në Fushatën e dy Irakëve (Irakejn) të Sulejmanit Kanuni më 1534.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Beteja e Mervit: uzbekët pësuan disfatë të rëndë, u morën Mervi dhe Herati", "f8e45aaf"], "d": ["Shah Ismaili, që plotësoi trashëgiminë akkojunlu në perëndim, marshoi drejt lindjes, në Horasan, dhe para Mervit u shkaktoi uzbekëve një disfatë të rëndë; Shejbani Hani vdiq në fushën e betejës. Mervi dhe Herati hynë nën sundimin safavid dhe Shteti Safavid arriti kufijtë që shtriheshin nga Eufrati deri te Amu Darja (Xhejhuni). Kështu procesi që filloi me hyrjen në Tabriz në verën e vitit 1501 u plotësua për nëntë vjet: e gjithë trashëgimia akkojunlu kaloi nën administrimin safavid dhe Shteti Osman u bë fqinj në lindje me një shtet të dytë po aq të madh sa ai vetë.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Hyrja përfundimtare e Zebidit nën sundimin osman", "ddd971c7"], "d": ["Flota që hoqi rrethimin e Diut më 5 nëntor 1538, në rrugën e kthimit u ndal në bregdetin e Jemenit dhe Zebidi u lidh përfundimisht me administrimin osman; Hadëm Sulejman Pasha u largua nga qyteti më 10 mars 1539 dhe arriti në Xhidë më 1 prill. Që nga viti 1517 qyteti qeverisej në emër të osmanëve nga ish-bejlerë memlukë; me këtë datë kaloi në administrim të drejtpërdrejtë.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Bashkimi Iberik: kurora portugeze i kalon mbretit të Spanjës", "1cc6dfdc"], "d": ["Lufta për trashëgimi, që u hap me vdekjen pa trashëgimtar të mbretit kardinal Henrique, u mbyll në favor të Spanjës në Betejën e Alcântarës (25 gusht 1580), dhe Cortes-i portugez i mbledhur në Tomar më 16 prill 1581 e njohu Filipin II si mbret të Portugalisë. Sipas kushteve të Tomarit, Portugalia do të ruante institucionet, monedhën dhe gjuhën e vet, në qeverisje do të emëroheshin vetëm portugezë, dhe në Madrid do të kishte një këshill të veçantë portugez — pra bashkimi ishte bashkim personal, jo aneksim.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: Portugalia rifitoi pavarësinë", "64ec0738"], "d": ["Në ditët kur kryengritja e Katalonjës e mbante të zënë Spanjën, një grup fisnikësh në Lisbonë sulmoi befas pallatin, rrëzoi administrimin spanjoll dhe shpalli dukën e Braganzës mbret me emrin João IV. Kështu mori fund Bashkimi Iberik gjashtëdhjetëvjeçar; por Ceuta zgjodhi të mbetej te Spanja dhe kjo u njoh me Traktatin e Lisbonës të vitit 1668. Kjo dritare, kur Portugalia u shkëput nga përfshirja në luftërat habsburge, është edhe korniza e humbjeve të saj në Azi: Hormuzi doli nga dora më 1622, Malaka më 1641, Kolombo më 1656; ndërsa Tanxheri dhe Bombei iu dhanë Anglisë si çmim i pavarësisë. Burimi: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tanxheri iu dorëzua Anglisë", "1f7cad6d"], "d": ["Neni i dytë i traktatit të martesës (23 qershor 1661), i lidhur për të siguruar mbështetjen angleze në luftën e pavarësisë së Portugalisë, ia linte Tanxherin Anglisë si pajë të Catherine de Braganzës. Flota e kontit të Sandwich-it u ankorua më 29 janar 1662 dhe të nesërmen u bë dorëzimi zyrtar me ceremoninë e kontit të Peterborough-ut. Anglezët do ta braktisnin qytetin më 1684.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Vrasja e Nadir Shahut — shpërbërja e sundimit afshar", "19c218c0"], "d": ["Nadir Shahu, i cili i dha fund fronit safavid dhe më 1736 shpalli sundimin në emrin e vet, me fushatën e Indisë arriti deri në Delhi dhe, pas tri luftërave me osmanët, bëri paqe me Traktatin e Kerdenit të vitit 1746, u vra në çadrën e tij nga vetë rojet e tij. Pas kësaj Irani nuk mundi të qeverisej nga një dorë: për dyzet e nëntë vjet vendin e ndanë mbetjet afshare në Horasan, zendët në jug dhe kaxharët që ngriheshin në veri. Falë kësaj përçarjeje kufiri lindor osman mbeti i qetë për një kohë të gjatë. Nadir Shahu u vra më 20 qershor 1747; sipas TDV-së, Hanati i Revanit u themelua po atë vit (1747), dita e pakonfirmuar.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Dinastia kaxhare vendos sundimin mbi Iranin", "744b48c5"], "d": ["Kreu i fisit kaxhar, Aga Muhamed Hani, duke rrëzuar sundimin zend dhe duke thyer rezistencën e fundit afshare në Horasan, e bashkoi sërish Iranin në një dorë dhe e bëri Teheranin kryeqytet. Kështu u mbyll periudha dyzetenëntëvjeçare e copëtimit; pas kësaj fqinji lindor i osmanëve do të ishte deri më 1923 Irani kaxhar. Sipas Enciklopedisë Islame të TDV-së, Mashhadi më 1796 u prit para Aga Muhamed Shahut nga sundimtari afshar Shahrukh dhe hyri nën sundimin kaxhar (dita mungon te burimi).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdinandi shtiu në dorë Budinin — Szapolyai u dëbua nga kryeqyteti", "99f77c29"], "d": ["Pas Mohaçit në fronin hungarez dolën dy mbretër: një pjesë e fisnikëve zgjodhi János Szapolyain, një pjesë habsburgun Ferdinand. Ferdinandi më 1527 shtiu në dorë Budinin dhe e dëboi Szapolyain nga kryeqyteti; Szapolyai kërkoi ndihmë nga sulltan Sulejmani. Kjo është arsyeja pse objektivi i parë i fushatës së Vjenës të vitit 1529 ishte Budini.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Fushata e Barbarosës në ishujt e Egjeut — Dukati i Naksosit hyri nën kontrollin osman", "722b2fea"], "d": ["Dukati i Naksosit, që nga viti 1207 qeverisej nga dukë latinë nën kujdestarinë e Venedikut, me fushatën e Barbaros Hajredin Pashës në ishuj hyri nën kontrollin osman. Statusi i ishullit nuk u prek; dukati vazhdoi si vartës i osmanëve, dhe me traktatin osmano-venedikas të vitit 1540 e drejta e sundimit iu kalua zyrtarisht osmanëve.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Flota kryqtare pushtoi Xherbën — baza e Turgut Pashës doli nga dora", "f41b3f2a"], "d": ["Flota kryqtare, e përbërë nga anije të Spanjës, Papatit, Maltës, Gjenovës dhe Firences, shënjestroi Xherbën, që Turgut Reisi e përdorte si bazë sulmesh qysh nga viti 1551. Për shkak të stuhive dhe epidemisë, mundi të arrinte para ishullit vetëm në fillim të vitit 1560; më 12 mars 1560 e pushtoi ishullin dhe ndërtoi një kështjellë. Pijale Pasha, sapo mori lajmin, më 28 mars u nis nga Stambolli me flotën e tij prej 120 galerash. Pushtimi nuk zgjati: flota osmane në maj i mundi aleatët para Xherbës, dhe edhe kështjella u rimor në fund të korrikut. Kjo fushatë është fillimi i operacionit të dytë të madh detar që, pas Prevezës, e përforcoi epërsinë osmane në Mesdhe.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Rënia e kështjellës së Xherbës — ishulli kalon nën administrimin osman", "f1efc0df"], "d": ["Pas fitores detare të Pijale Pashës më 14 maj 1560, forcat kryqtare u mbyllën në kështjellën që kishin ndërtuar në ishull; forcat e bejlerbeut të Tripolit (Libi), Turgut Pashës, e rrethuan nga toka. Rrethimi dymujor përfundoi më 30 korrik 1560 me rënien e kështjellës dhe ishulli iu lidh bejlerbellëkut të Tripolit. Mes fitores detare dhe pushtimit të kështjellës kaluan shtatëdhjetë e shtatë ditë; ishulli ndërroi faktikisht duar jo më 14 maj, por më 30 korrik.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Në Danzig mori fund pushteti i dyfishtë ruso-prusian — qyteti i lirë i Napoleonit iu kthye Prusisë", "1ccda4d2"], "d": ["Danzigun, që me paqen e Tilsitit (9 korrik 1807) ishte shkëputur nga Prusia dhe ishte bërë qytet i lirë nën mbrojtjen franceze, forcat e Napoleonit e braktisën pas rrethimit të vitit 1813. Ndërmjet 2 janarit dhe 4 shkurtit 1814 në qytet vazhdoi pushteti i dyfishtë ruso-prusian; kur cari Aleksandër hoqi dorë nga plani për të marrë Danzigun dhe grykëderdhjen e Vistulës, qyteti kaloi nën administrimin prusian.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Në Vjenë Krakovi u shpall qytet i lirë, i pavarur dhe asnjanës", "19eea839"], "d": ["Në Kongresin e Vjenës, Rusia, Austria dhe Prusia e bënë qytetin e Krakovit me rrethinat e tij shtet të lirë nën mbrojtjen e tri shteteve; Akti Përfundimtar i Vjenës e regjistroi këtë rend.", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Bornuja hyri nën sundimin e Rabih bin Zubejrit", "8be4ca96"], "d": ["Komandanti sudanez Rabih bin Zubejr, që tronditi Bagirmin dhe Vadain, shtiu në dorë Bornunë; deri më 1896 mori të gjithë vendin dhe e bëri Dikeon qendër.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Rabih bin Zubejri u mund dhe u vra nga francezët — sundimi i tij në Bornu u shpërbë", "fb5a3ace"], "d": ["Rabihu, i mundur nga ushtria koloniale franceze, u vra; djali i tij, megjithëse deshi ta vazhdonte sundimin, nuk mundi të qëndronte, dhe Bornuja më 1902 u nda mes Francës, Anglisë dhe Gjermanisë.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["U shpall Qeveria e Përkohshme e Trakës Perëndimore me qendër në Gjymylxhinë", "974b2e28"], "d": ["Kur Traktati i Bukureshtit (10 gusht 1913) ia la Trakën Perëndimore Bullgarisë, populli turk i rajonit shpalli një qeveri të përkohshme me qendër në Gjymylxhinë; pasi u mor Dedeagaçi, qeveria shpalli pavarësinë me emrin 'Qeveria e Pavarur e Trakës Perëndimore'. Për shkak të ndërhyrjes së fuqive të mëdha, qeveria osmane nuk e përkrahu; Traktati i Stambollit i 29 shtatorit 1913 ua la Trakën Perëndimore bullgarëve, dhe qeveria jetoi deri më 25 tetor 1913 vetëm pesëdhjetë e shtatë ditë.", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Vdekja e Orhan Gaziut — fundi i dyzet viteve të kalimit nga bejliku në shtet", "62c59cfd"], "d": ["Orhan Gaziu, që pas vdekjes së Osman Gaziut më 1324 u vu në krye të bejlikut, gjatë sundimit tridhjetë e tetëvjeçar e shndërroi shtetin osman nga një bejlik kufitar në një shtet të vendosur në të dy brigjet e Marmarasë: u morën Bursa (1326), Izniku (1331) dhe Izmiti (1337), u aneksua bejliku Karesi, u pre akçeja e parë (1327), u themelua medreseja e parë në Iznik (1331) dhe kalimi në Rumeli u bë i qëndrueshëm përmes Çimpesë (1352) dhe Galipolit (1354). Djalin e madh, Sulejman Pashën, që drejtonte pushtimet në Rumeli, e humbi më 1357 në një aksident gjatë gjuetisë; ai vetë vdiq në Bursë në mars 1362 dhe në vendin e tij erdhi i biri, Murati I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Ishujt e Bahrejnit kalojnë në duart e xhebridëve", "6a242b16"], "d": ["Zëri për Bahrejnin i TDV-së shënon se ishulli \"mbeti me radhë nën administrimin e ujunidëve, salgurlinjve, tabive dhe xhebridëve, dhe në kohën e xhebridëve shumica kaloi nga shiitë te sunitë\"; për asnjërin nuk jep datë. Në literaturën e përgjithshme, dinastia xhebride u themelua në fillim të shekullit XV duke rrëzuar sundimtarin e fundit xhervanid në Katif dhe, në kohën e saj më të shkëlqyer (Axhvad b. Zamil, v. 1496), kontrolloi të gjithë bregun arab të Gjirit Persik, Lahsanë, Katifin dhe ishujt e Bahrejnit. Pas Axhvadit, ishujt Eval i kaluan Mukrin b. Zamilit — sundimtarit që do të mundej nga portugezët më 1521.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Portugalia merr Arzilën — koka e dytë e urës në bregdetin marokenas", "83444a11"], "d": ["Afonsoja V me një forcë prej 30.000 vetësh dhe një flotë prej 400 anijesh zbarkoi vetë në bregdetin marokenas dhe më 24 gusht 1471 mori Arzilën, nën administrimin vattasid. Rënia e qytetit e theu rezistencën e Tanxherit; Tanxheri u dorëzua pa luftë katër ditë më vonë, më 28 gusht. Kështu Portugalia, pas Ceutës (1415) dhe Kasr es-Sagirit (1458), krijoi pozicionin e tretë dhe të katërt në bregdetin atlantik të Marokut; pas kësaj fushate mbreti ia shtoi titullit të vet shprehjen \"zot i Afrikës\".", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Safi hyn nën ndikimin portugez", "765e703e"], "d": ["Safi, porti më i gjallë i drithit dhe peshkimit në bregdetin atlantik, hyri nën ndikimin portugez më 1488; për një kohë qyteti u qeveris nën protektoratin portugez nga qeveritarë vendas dhe më 1508 u pushtua drejtpërdrejt. Meqë burimet u japin peshë të ndryshme këtyre dy fazave, data e fillimit ndryshon mes 1488 dhe 1508; të dyja janë skajet e të njëjtit proces. Safi mbeti pesëdhjetë e tre vjet në duart portugeze dhe u lirua më 1541, pas rënies së Agadirit.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Themelimi i Santa Cruz do Cabo de Gué — kështjellë portugeze në Agadir", "cc22c433"], "d": ["Kështjella Santa Cruz do Cabo de Gué, e themeluar me nismë private në bregdetin e Susit, në një pikë ku portugezët s'kishin arritur deri atëherë, u ndërtua më 1505 dhe më 1513 iu dorëzua kurorës portugeze. Kështjella, duke kontrolluar tregtinë e sheqerit dhe arit të luginës së Susit, mbyllte daljen jugperëndimore të Marrakeshit; prandaj u bë objektivi i parë i madh i lëvizjes saadite. Rrethimi i vitit 1533 u zmbraps, ai i vitit 1541 pati sukses dhe nisi rënien e Portugalisë në Marok.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Marrja e Azemmurit — kontrolli i grykëderdhjes së Um er-Rbias", "232acd4b"], "d": ["Ushtria portugeze nën komandën e dukës së Braganzës, Jaimes, më 3 shtator 1513 hyri pa hasur rezistencë në Azemmur, në grykëderdhjen e lumit Um er-Rbia. Marrja e qytetit dha kontrollin si mbi grykëderdhjen, ashtu edhe mbi rrugën e drithit që hapej drejt brendësisë, dhe vitin pasues hapi rrugën për ngritjen e kështjellës së Mazaganit 12 km në jugperëndim. Azemmuri mbeti njëzet e tetë vjet në duart portugeze.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Ngritja e kështjellës së Mazaganit — pozicioni portugez që do të qëndronte më gjatë në Marok", "786cdb40"], "d": ["Vitin pas marrjes së Azemmurit, në verën e vitit 1514, në bregdet u ndërtua fortifikimi i Mazaganit. Pas shembjes së përgjithshme të vitit 1541, Portugalia, ndërsa braktisi të gjitha pozicionet në Marok, Mazaganin nuk e braktisi; përkundrazi, e rindërtoi kështjellën me bastione sipas stilit italian dhe qyteti u mbajt dyqind e pesëdhjetë e pesë vjet. Edhe rrethimi i madh i vitit 1562 u zmbraps. Mazagani, si pozicioni i fundit portugez në Marok, do të lirohej më 1769.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Dorëzimi i kështjellës së Mardinit — fundi i rezistencës safavide në jug të Dijarbekirit", "e6226de5"], "d": ["Kur Bëjëklë Mehmed Pasha, që marshoi pas Çalldiranit në rajonin e Dijarbekirit, rrethoi Mardinin, forcat safavide në tetor 1515 u tërhoqën në kështjellë; megjithëse qyteti kaloi në duart osmane, kështjella rezistoi. Kalimi në kundërsulm me përforcime i guvernatorit safavid Kara Han përfundoi me Betejën e Koçhisarit (Këzëltepe) në maj 1516 — në betejën që zgjati gjithë ditën në fushën e Dede Garkënit, Kara Hanit iu pre koka dhe ushtria e tij u shpërnda. Kështjella, sipas shprehjes së TDV-së, u dorëzua \"vetëm pas nëntë muajsh\".", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Portugalia merr Bahrejnin — fundi i sundimit xhebrid", "315a435a"], "d": ["Kur sundimtari xhebrid Mukrin b. Zamil refuzoi t'i paguante taksë Hormuzit, flota portugeze dhe forcat e Mbretërisë së Hormuzit, vartëse e Portugalisë, zbarkuan në ishull; Mukrini u mund në luftë dhe Bahrejni më 1521 kaloi nën administrimin portugez. Pas kësaj ishulli u qeveris për tetëdhjetë vjet nëpërmjet Hormuzit, kryesisht nga guvernatorë sunitë iranianë. Perlat dhe pozita strategjike e Bahrejnit do ta bënin ishullin objektiv të drejtpërdrejtë të rivalitetit osmano-portugez në Gji.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Rënia e Agadirit — fillon shkulja e Portugalisë nga Maroku prej saadëve", "bb1568f6"], "d": ["Sulltani saad Muhamed esh-Shejh rrethoi kështjellën Santa Cruz më 16 shkurt 1541 dhe e pushtoi më 12 mars; rreth gjashtëqind portugezë, përfshirë guvernatorin Guterre de Monroy, ranë robër.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Lirimi i Safit dhe Azemmurit — Portugalia tërhiqet nga bregdeti atlantik", "4cb6099a"], "d": ["Meqë Agadiri ra më 12 mars 1541 dhe nuk mundi të krijohej aleanca që pritej me sulltanin marokenas, João III urdhëroi lirimin e dy pozicioneve të mëdha në bregdetin atlantik; evakuimi i Safit dhe Azemmurit përfundoi në vjeshtën e vitit 1541, në muajt shtator-tetor. Kështu brenda një viti të vetëm dolën nga duart tri pozicione dhe zgjerimi pesëdhjetëvjeçar portugez në bregdetin marokenas u kthye mbrapsht; mbetën Ceuta, Tanxheri, Arzila, Kasr es-Sagiri dhe Mazagani i fortifikuar rishtas.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Lirimi i Arzilës — Portugalia ngushton bregdetin verior", "b5d18373"], "d": ["Me bashkimin e krizës financiare dhe presionit saad, João III e liroi Arzilën, që mbahej që nga viti 1471. Kështu prania portugeze në Marok u reduktua në Ceuta, Tanxher dhe Mazagan. Arzila do të pushtohej sërish për pak kohë më 1577 dhe do të braktisej përfundimisht më 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Fushata osmane në Bahrejn — hapi i fundit i madh kundër Portugalisë në Gji", "14501df3"], "d": ["Shteti Osman, që me aneksimin e Basrës më 1546 dhe me krijimin e ejaletit të Lahsasë u vendos në bregun arab të Gjirit, duke synuar tregtinë e perlave të ishullit dhe vijën e Hormuzit të Portugalisë, marshoi mbi Bahrejn nën komandën e bejlerbeut të Lahsasë, Mustafa Pashës. Rezultati i fushatës ndryshon në burime: Enciklopedia Islame e TDV-së shkruan se osmanët \"në vitin 1559 shtinë në dorë Bahrejnin dhe ngritën atje një bazë\" dhe se ishujt \"më vonë kaluan sërish nën administrimin portugez\"; ndërsa literatura perëndimore shënon se rrethimi dështoi, se përforcimet portugeze që erdhën me det nga Hormuzi i zmbrapsën forcat osmane dhe se, pas një epidemie murtaje që goditi të dyja palët, osmanët kërkuan kushte dorëzimi. Dy tregimet ndahen pikërisht te rezultati; e përbashkëta është se Bahrejni nuk mbeti përgjithmonë në duart osmane.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Uluç Ali Pasha merr Tunisin — fundi i rendit hafsido-spanjoll", "d4498698"], "d": ["Kur Karli V e mori Tunisin më 1535, nuk e qeverisi vetë qytetin, por e riktheu në fron sulltanin hafsid Mulej Hasan; sipas shprehjes së TDV-së, qyteti i Tunisit mbeti \"nën protektoratin e spanjollëve dhe nën administrimin e Mulej Ahmedit III deri në ndërhyrjen e dytë të osmanëve në 1569\". Uluç Aliu, i emëruar më 27 qershor 1568 bejlerbe i Algjerisë, marshoi nga toka mbi Tunis dhe, duke mundur sulltanin hafsid në Beja, hyri në qytet; Mulej Ahmedi u strehua në presidion spanjolle të La Goulettes (Halkulvadi). Kështu gjiri u nda në dy pjesë — qyteti osman, kështjella e portit spanjolle — dhe kjo ndarje zgjati katër vjet.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Don Juan de Austria rimerr Tunisin — e vetmja përgjigje tokësore e Lepantos", "a6f044ee"], "d": ["Edhe pse Lidhja e Shenjtë u shpërbë pas Lepantos (1571), Spanja e vetme iu vërsul Afrikës së Veriut: sipas shprehjes së TDV-së, \"më 10 tetor 1573 spanjollët ndërmorën një operacion të ri me qëllim për të marrë kontrollin në Tunis. Morën Tunisin dhe lanë aty 8000 ushtarë.\" Ky operacion nën komandën e Don Juan de Austrias është i vetmi vend ku fitorja e Lepantos pati pasqyrim në tokë; por nuk qe i qëndrueshëm dhe qyteti u rimor njëmbëdhjetë muaj më vonë. Ajo që rrëzoi pushtimi ishte një administrim osman i vendosur: më 2 dhulhixhe 980 (5 prill 1573) komandant i Tunisit ishte Kylyç Ali Pasha, kajmakam Ramazan Pasha, bejlerbe Hajdar Pasha.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Safavidët ia marrin Bahrejnin Portugalisë", "c37d982c"], "d": ["Forcat që dërgoi Shah Abasi I u bashkuan me kryengritësit në ishull dhe e dëbuan garnizonin portugez nga kështjella; sipas shprehjes së TDV-së, ishujt iu morën portugezëve \"më 1602 nga forcat vartëse të Iranit\". Kështu Bahrejni doli nga administrimi portugez tetëdhjetë e njëvjeçar, hyri nën sundimin safavid dhe mbeti i varur nga Irani njëqind e pesëmbëdhjetë vjet. Kjo është hallka e parë e shpërbërjes portugeze në Gji; njëzet vjet më vonë edhe vetë Hormuzi do të binte me një operacion të përbashkët anglo-iranian.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Pushtimi i Bahrejnit nga omanasit — fundi i sundimit safavid", "c9be5820"], "d": ["Gjatë shpërbërjes së viteve të fundit të Shtetit Safavid, flota omane nën administrimin e dinastisë jarubide pushtoi ishullin dhe sundimi safavid mori fund. Tridhjetë e pesë vjet që pasuan janë periudha më e trazuar e Gjirit: ishulli ndërroi disa herë duar mes Omanit, Iranit dhe forcave vendase arabe.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Bahrejni kalon nën administrimin e Al Medhkurit nga Bushehri", "610e2f9d"], "d": ["Familja Al Medhkur, me origjinë nga Omani, e vendosur në Bushehr dhe e konsideruar huvela, më 1753, duke u nisur nga bazat e veta në Bushehr, vuri Bahrejnin nën administrimin e vet. Familja drejtonte komunitetet arabe në bregun iranian të Gjirit dhe e qeveriste ishullin në emër të Iranit; përfaqësuesi i fundit i saj, Nasr Al Medhkuri, ishte emëruar guvernator i Bahrejnit nga administrata zende. Ky është administrimi i fundit i ishullit para Al Halifës.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Lirimi i Mazaganit — bie pozicioni i fundit portugez në Marok", "f9e9749d"], "d": ["Garnizoni prej 592 vetësh nuk mundi të qëndronte përballë rrethimit që sulltani alavit Muhamed III bin Abdullah nisi në fillim të vitit 1769; flota e evakuimit, që u nis nga Lisbona më 1 shkurt, më 11 mars 1769 i mori ushtarët e fundit në anije, dhe i fundit që e braktisi qytetin qe guvernatori Dinis Gregório. Kështu prania portugeze në Marok, që filloi me marrjen e Ceutës më 1415, mori fund pas tre shekujsh e gjysmë. Mazagani ishte i vetmi pozicion në bregdetin atlantik i mbajtur pas shembjes së përgjithshme të vitit 1541 dhe, me dyqind e pesëdhjetë e pesë vjet, u bë vendi që Portugalia mbajti më gjatë në Marok.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Al Halifa pushton Bahrejnin — themelimi i dinastisë që vazhdon deri sot", "8773b011"], "d": ["Guvernatori i Bahrejnit i administratës zende, Nasr Al Medhkur, rrethoi Zubaran në gadishullin e Katarit; forcat utub nën komandën e Ahmed b. Muhamed b. Halifës e thyen rrethimin dhe, duke kaluar në kundërsulm, po atë vit morën Bahrejnin. Shënimi i TDV-së është i shkurtër: \"Bahrejni më 1783 hyri nën sundimin e Al Halifës nga fisi utub.\" Pas kësaj fitoreje Ahmed b. Muhamedi u përmend me nofkën \"el-Fatih\" dhe dinastia që themeloi sundon në ishull deri sot.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Traktati i Bahrejnit me Anglinë — hyrja në rendin e protektoratit në Gji", "576796b2"], "d": ["Sipas shënimit të TDV-së, \"më 21 maj 1861 Anglia dhe Aliu, vëllai i shejh Muhamedit, si përfaqësues i Bahrejnit, nënshkruan një marrëveshje që ndalonte tregtinë e skllevërve dhe piraterinë në rajon\"; në dokumentet angleze i njëjti traktat (Perpetual Truce of Friendship and Peace) mban datën 31 maj 1861. Traktati është hallka e parë e rendit të protektoratit që i lidhte marrëdhëniet e jashtme të Bahrejnit me Anglinë, dhe ishulli mbeti jashtë rendit osman edhe pasi osmanët u rivendosën më 1871 në Lahsa e Katif.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahi Evrani — piri themelues i organizatës së ahive", "3392e100"], "d": ["Ahi Evrani konsiderohet një nga themeluesit e organizatës së ahive në Anadoll dhe piri i regjësve (dabbagëve). Zavieja e tij në Këshehir vazhdoi në periudhën osmane, deri në fillim të shekullit XX, si qendra shpirtërore e organizatës së zejtarëve/esnafeve; shteti e konfirmoi zyrtarisht këtë pozitë më 1780, 1782, 1822-23 dhe 1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Shejh Edebaliu — lidhja themeluese mes ahive dhe dinastisë osmane", "c1186059"], "d": ["Edebaliu, që themeloi një zavie në Bilexhik dhe ishte edhe shejh i organizatës së ahive, sipas gojëdhënës e shpjegoi ëndrrën e famshme të Osman Gaziut; pastaj Osman Gaziu u martua me vajzën e Edebaliut, Mal Hatunin. Edebaliu konsiderohet gjithashtu kadiu dhe myftiu i parë osman.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Orhan Gaziu pas pushtimit të Bursës lë si vakëf një fushë për lojërat e xhiritit", "da1becbd"], "d": ["Sipas zërit për xhiritin të TDV-së, Orhan Gaziu, pas pushtimit të Bursës, la si vakëf një sipërfaqe në rrethinat për garat me kuaj dhe lojërat e xhiritit — një nga shembujt e parë të dokumentuar të institucionalizimit të lojës së xhiritit tek osmanët.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Fillimi i mundjes së Kërkpënarit sipas gojëdhënës", "2d93fa65"], "d": ["Sipas gojëdhënës, tradita e mundjes së Kërkpënarit ka filluar me ndeshjet e mundjes mes dyzet gazive që kaluan bashkë me pushtuesin e Rumelisë, Sulejman Pashën. Zërat e TDV-së për mundjen dhe për Kërkpënarin e transmetojnë këtë gojëdhënë, por nuk japin ndonjë datë të saktë themelimi.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Themelimi i Ocakut të Jeniçerëve", "f4206dce"], "d": ["Sistemi që filloi me edukimin e të rinjve jomyslimanë të marrë nga robërit e luftës në bazë të ligjit penxhik, me udhëzimin e Çandarlli Kara Halilit dhe mulla Rustemit, përmes Ocakut të Axhemive të themeluar në Galipoli fitoi karakter institucional në kohën e Muratit I.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Fillon ndërtimi i Xhamisë së Vjetër (Ulu Xhamisë) në Edrene", "da7a22ac"], "d": ["Ndërtimi i Xhamisë së Vjetër, e njohur në popull edhe me emrin Ulu Xhami (Xhami-i Atik), u fillua më 1402-1403 nga emir Sulejman Çelebiu.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Fillon ndërtimi i kompleksit të Xhamisë së Gjelbër në Bursë", "280b8a21"], "d": ["Mehmeti I, që pas periudhës së Interregnumit e bashkoi sërish fronin, më 1414 nisi ndërtimin e kompleksit dhe e vendosi në një pikë qendrore të Bursës, në mënyrë që të dallohej nga komplekset e gjyshit dhe të atit. Kryearkitekti i tij është Haxhi Ivaz Pasha.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Përfundimi i kompleksit të Xhamisë së Gjelbër në Bursë", "bc82821f"], "d": ["Kompleksi i Xhamisë së Gjelbër, i njohur për programin e pllakave dhe zbukurimeve ku kontribuuan edhe mjeshtra nga Tabrizi, përfundoi në dhjetor 1419. Kompleksi përbëhet nga xhamia, tyrbja (Tyrbja e Gjelbër), medreseja, imareti dhe hamami; është një nga shembujt më të pasur të arkitekturës së hershme osmane.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Fillon zbatimi de facto i sistemit të devshirmes", "fa835172"], "d": ["Metoda e devshirmes, që nuk haset në shtetet islame të mëparshme, filloi fillimisht si shfrytëzim i të rinjve jomyslimanë të zënë rob lufte në bazë të ligjit penxhik. Sipas TDV-së, \"kuptohet se u zbatua në kohën e Mehmet Çelebiut, por u bë ligj në kohën e të birit, Muratit II.\"", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Krijimi i postit të shejhulislamit — mulla Fenariu myfti i Bursës", "2a8ee2b9"], "d": ["Emërimi më 1425 myfti i Bursës i dijetarit mulla Fenari, që për vite të gjata kishte qenë kadi i Bursës, sipas shprehjes së TDV-së konsiderohet \"fillimi i myftillëkut dhe i shejhulislamllëkut te osmanët\". Megjithatë, TDV vë në dukje se kjo nuk është identike me postin plotësisht të institucionalizuar të shejhulislamit, që në shekullin XVI përfaqësonte tërë organizatën e ilmijes.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Institucionalizimi i sistemit të timarit", "dc267780"], "d": ["Përmendjet e para të timarit të bazuara në dokumente shkojnë deri në kohën e Orhan Beut; kodifikimi sistematik u bë në kohën e Muratit II. Defterët përmbledhës (ixhmal) të timarit të përgatitur në këtë periudhë tregojnë se të gjitha parimet themelore të sistemit u formuan atëherë; dokumentet e rreth vitit 1432 provojnë se ligjet ishin plotësisht në fuqi.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Përfundimi i Xhamisë Üç Şerefeli dhe kompleksit të saj", "cde6993e"], "d": ["Xhamia Üç Şerefeli (me tri sherefe), që Murati II urdhëroi t'ia ndërtonin mjeshtrat Muslihudin dhe Shehabedin për një periudhë dhjetëvjeçare (1437-1447), konsiderohet shembulli i parë i xhamive me plan qendror në arkitekturën osmane dhe është një nga pikat kthese të arkitekturës kalimtare para periudhës klasike.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Institucionalizimi i Divan-i Humajunit me ligjin e Fatihut", "e8443e77"], "d": ["Divani, në kohën e Muratit II, duke u lidhur në Edrene me rregulla të rregullta, filloi të merrte karakterin e \"Divan-i Humajun\". Shndërrimi i vërtetë erdhi me ligjin e Sulltan Mehmetit II Fatih: risia më e madhe ishte heqja e plotë e kryesisë së divanit nga padishahu dhe kalimi i saj te veziri i madh.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Sulltan Mehmeti II Fatih ua cakton Okmejdanin harkëtarëve", "342a9fd5"], "d": ["Sulltan Mehmeti II Fatih, që gjatë pushtimit të Stambollit e kishte ngritur selinë në shpatet e Kasëmpashës, e kishte përdorur këtë vend njëkohësisht si fushë stërvitjeje për harkëtarët; pasi mori qytetin, ua caktoi përgjithmonë këtë sipërfaqe harkëtarëve. Ky caktim është fillimi i Okmejdanit si qendër e traditës osmane të harkëtarisë, që do të vazhdonte me shekuj.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Bursa arrin kulmin në tregtinë e mëndafshit iranian", "f1324cdf"], "d": ["Karvanet nga Tabrizi sillnin në Bursë mëndafshet e Gilanit, Astarabadit dhe Sarit, të cilat atje i blinin me konkurrencë tregtarë gjenovezë, venedikas, fiorentinë dhe çifutë. Më 1479 vlera e mëndafshit të importuar nga Irani arriti në 150.000 florinj venedikas; më 1502 në qytet punonin më shumë se 1000 vegja endëse.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Bajaziti II u jep shpërblim të madh mundësve të Kërkpënarit", "d745b882"], "d": ["Sipas zërit për mundjen të TDV-së, Bajaziti II në vitin 1504 u dha mundësve shpërblime prej 3.000 dhe 1.500 kurushësh; është një nga shembujt e hershëm të dokumentuar të përkrahjes që pallati osman i jepte sportit të mundjes.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Përfundimi i Xhamisë së Bajazitit dhe kompleksit të saj", "eb9ab65b"], "d": ["Ndërtimi i Xhamisë së Bajazitit dhe kompleksit të saj, ndërtuar për Bajazitin II, sipas një dokumenti arkivor filloi në vitin 906 (1500) dhe përfundoi më 14 xhemaziulevel 911 (13 tetor 1505). Arkitekti i saj është i diskutueshëm: duke u mbështetur në shënimin e Ajvansarajiut, për një kohë të gjatë u konsiderua vepër e Mimar Hajredinit, pastaj iu atribua Mimar Kemaledinit, ndërsa sipas disave punuan të dy bashkë; i njëjti dokument tregon se mjeshtri ishte Jakub Shah b. Sulltan Shah. Xhamia konsiderohet një nga monumentet e rëndësishme të kalimit nga arkitektura para-klasike osmane te periudha klasike.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Tersane-i Amire (arsenali perandorak) zhvendoset në Stamboll (Kasëmpashë/Briri i Artë)", "f36e3675"], "d": ["Në kohën e sulltan Selimit Javuz, arsenali i ri, ndërtimi i të cilit filloi në gjirin në perëndim të mureve të Gallatës, përfundoi më 1515 me 160 hapësira (dok); kështu veprimtaritë e arsenalit me qendër në Galipoli u zhvendosën në Stamboll. Institucioni më vonë, në kohën e Barbaros Hajredin Pashës, mori zyrtarisht emrin \"Tersane-i Amire\".", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Vdekja e shejh Hamdullahut dhe trashëgimia e shkollës së tij të kaligrafisë", "f5ed4d09"], "d": ["Shejh Hamdullahu nga Amasja, si mësues i kaligrafisë i Bajazitit II, e çoi shkollën e aklam-i sittes (gjashtë llojeve të shkrimit) në moshën e pjekurisë dhe u bë themeluesi i një stili osman kaligrafie që do të mbizotëronte në tërë botën islame. Kur vdiq më 1520, la pas një rreth të gjerë nxënësish.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Piri Reisi përfundon versionin e parë të Kitab-i Bahrije", "fd6cc1ff"], "d": ["Piri Reisi përfundoi më 1521 versionin e parë (në prozë) të Kitab-i Bahrije, që përmbledh bregdetet e Mesdheut, portet dhe njohuritë e lundrimit. Ky version i parë ende nuk i ishte paraqitur padishahut dhe kishte karakter drafti që do të zgjerohej në vitet pasuese.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Piri Reisi e zgjeron Kitab-i Bahrijen dhe ia paraqet sulltan Sulejman Kanuniut", "d4abf0b7"], "d": ["Piri Reisi e zgjeroi Kitab-i Bahrijen pjesërisht në vargje dhe më 1526 ia paraqiti sulltan Sulejman Kanuniut. Në këtë formë vepra u përhap si udhëzuesi më gjithëpërfshirës i lundrimit i detarisë osmane.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçi Nasuhu pikturon itinerarin e fushatës së dy Irakëve te Bejan-i Menazil", "aa012278"], "d": ["Matrakçi Nasuhu, që mori pjesë në fushatën e parë iraniane (të dy Irakëve) të sulltan Sulejman Kanuniut më 1534, pikturoi me teknikën miniaturë-hartë çdo stacion ndalese në itinerarin e ushtrisë nga Stambolli në Tabriz e prej andej në Bagdad. Ky punim u mblodh në veprën Bejan-i Menazil-i Sefer-i Irakejn dhe është shembulli më origjinal i gjinisë së menzilnamesë tek osmanët.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Fuzuli i paraqet Kanuniut kaside pas pushtimit të Bagdadit", "1ef0653f"], "d": ["Pasi sulltan Sulejman Kanuni pushtoi Bagdadin më 1534, Fuzuli i paraqiti sulltanit osman pesë kaside, përfshirë kasiden e tij të famshme që fillon me vargun \"Geldi burc-ı evliyâya pâdişâh-ı nâmdâr\"; kështu, duke dalë nga mbrojtja safavide, kërkoi patronazhin e burrave të shtetit osman.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Fuzuli përfundon mesnevinë Lejla dhe Mexhnuni", "e3ef4085"], "d": ["Lejla dhe Mexhnuni, e konsideruar një nga mesnevitë më të bukura të letërsisë klasike turke, u shkrua dhe u përfundua nga Fuzuli më 1535, me kërkesën e poetëve nga Stambolli që morën pjesë në fushatën e Kanuniut në Bagdad.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Emërimi i Mimar Sinanit kryearkitekt i oborrit", "7a753f0e"], "d": ["Sipas zërit për Sinanin në Enciklopedinë Islame të TDV-së, pas vdekjes më 1537 të kryearkitektit të oborrit Axhem Alisi, Sinani, që kishte tërhequr vëmendjen me urën që ndërtoi mbi lumin Prut gjatë fushatës së Moldavisë, u emërua në këtë detyrë me vlerësimin e vezirit të madh Lutfi Pasha. Kështu filloi periudha e kryearkitekturës së Sinanit që do të zgjaste mbi pesëdhjetë vjet.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Fillon ndërtimi i Xhamisë dhe kompleksit të Shehzades", "1a70ddfd"], "d": ["Sulltan Sulejman Kanuni urdhëroi ndërtimin e kompleksit në emër të të birit, shehzade Mehmetit, të cilin e humbi më 1543 nga epidemia e murtajës; ndërtimi filloi në qershor 1543, fillimisht u përfundua tyrbja dhe pastaj nisi ndërtimi i xhamisë. Kjo ndërtesë, sipas vetë shprehjes së Mimar Sinanit, është \"vepra ime e çirakllëkut\".", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Përfundimi i kompleksit të Skelës së Yskydarit (Mihrimah Sulltan)", "3769007f"], "d": ["Ndërtimi i kompleksit në sheshin e Skelës së Yskydarit filloi në vitet e para të dekadës 1540 dhe përfundoi më 1547. Nga dy xhamitë e mëdha që Mihrimah Sulltana ia porositi Mimar Sinanit, kjo është kronologjikisht e para; e dyta (Edirnekapë) do të përfundonte rreth njëzet vjet më vonë.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Venediku hap konsullatë në Alep", "3aad8b9e"], "d": ["Në shekullin XVI qendra e rëndesës tregtare të evropianëve u zhvendos nga Damasku në Alep. Si shenjë konkrete e këtij ndryshimi, Venediku hapi konsullatë në Alep më 1548; pas tij erdhi Franca më 1557 dhe Anglia më 1586. Qyteti u bë tregu kryesor ku shkëmbeheshin pëlhurat e leshit dhe argjendi i Evropës me erëzat indiane, dhe në fund të shekullit me mëndafshin iranian.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Xhamia e Shehzades hapet për adhurim", "2bb3f4b2"], "d": ["Pas një ndërtimi që zgjati rreth pesë vjet, Xhamia e Shehzades u hap për adhurim në gusht 1548. Me planin me dy minare dhe kube qendrore, konsiderohet lajmëtare e veprave të mëvonshme të mëdha të Mimar Sinanit; kompleksi përbëhet nga xhamia, tyrbja, medreseja, imareti, tabhaneja dhe karvansaraji.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Fillon ndërtimi i ujësjellësit të ujërave të Kërkçeshmesë", "14124b59"], "d": ["Mimar Sinani, me urdhër të Kanuniut, shqyrtoi sjelljen e ujit në Stamboll nga pyjet e Beogradit dhe njoftoi se ishte e mundur; ndërtimi i veprës së madhe ujore filloi më 1554 dhe përfundoi para vitit 1563. TDV e përshkruan këtë ndërtesë si \"veprën më të rëndësishme të Sinanit nga pikëpamja inxhinierike dhe më të madhen për nga vëllimi\".", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Hapja e kafeneve të para në Stamboll", "85c12f9f"], "d": ["Hyrja e kafesë në jetën qytetare osmane filloi me kafenetë që hapën në Tahtakale tregtari nga Alepi Hakem dhe një person nga Damasku me emrin Shems. Brenda pak kohe lindi një hapësirë e re publike ku mblidheshin njerëz nga çdo shtresë e shoqërisë; në periudhën e fundit të Kanuniut në Stamboll kishte pesëdhjetë kafene.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ebussuud Efendiu shqyrton juridikisht çështjen e gedikut (e drejtës monopol të esnafit)", "5d4e2930"], "d": ["Çështja e \"gedikut\", e drejtë monopoli dhe privilegji që u njihej një numri të caktuar personash në zejtari, u ngrit sërish në rend të ditës në kohën e Kanuniut; shejhulislami Ebussuud Efendi, më 1555-56, e shqyrtoi thellë çështjen dhe ia paraqiti padishahut legjitimitetin e zbatimit.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Sejdi Ali Reisi përfundon në Stamboll Mir'atul-Memalik", "ee8640e1"], "d": ["Veprën udhëpërshkruese Mir'atul-Memalik, që e shkroi gjatë udhëtimit të kthimit duke filluar nga Bagdadi, Sejdi Ali Reisi e përfundoi në Stamboll në janar 1557. Vepra është një burim i dorës së parë që tregon kthimin e një detari osman në atdhe me rrugë tokësore, nga Oqeani Indian nëpër Azinë Qendrore.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Ndërtimi i kompleksit (xhamisë) të Rustem Pashës", "02e30725"], "d": ["Kompleksi që Rustem Pasha, dhëndri dhe veziri i madh i Kanuniut, ia porositi Mimar Sinanit u ndërtua ndërmjet viteve 1555-1561. Ndërtesa njihet për arkitekturën origjinale, të ngritur mbi një platformë të lartë me dyqane të harkuara poshtë, dhe për pllakat e pasura të Iznikut.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Përfundimi i Urës së Mostarit", "e7f434af"], "d": ["Ura e famshme e Mostarit mbi lumin Neretva u ndërtua rreth viteve 1566-67 nga Mimar Hajredini; përmendja e urës në një dokument zyrtar të vitit 1568 vërteton se ajo ishte përfunduar. Ndërtesa është një nga shembujt më të njohur të arkitekturës klasike osmane të urave me një hark të mprehtë.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Përfundimi i Xhamisë së Edirnekapësë (Mihrimah Sulltan)", "f2d21a82"], "d": ["Ndërtimi i xhamisë, që filloi pas lejes së konfirmuar më 1563 për Mihrimah Sulltanen, vajzën e Kanuniut, përfundoi më 1566; vakëfnameja e kompleksit u përpilua në vitet 1570-71. Ndërtesa është një nga veprat e mëdha të Mimar Sinanit më afër mureve të Stambollit.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Baki shkruan elegji për sulltan Sulejman Kanuniun", "7aa6665f"], "d": ["Kur erdhi lajmi i vdekjes së sulltan Sulejman Kanuniut nga Sigetvari, Baki, \"sulltani i poetëve\" i epokës, shkroi një nga elegjitë (mersije) më të famshme të letërsisë osmane.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Baki i paraqet Selimit II poezinë e hipjes në fron", "6027f034"], "d": ["Menjëherë pas hipjes në fron të Selimit II, Baki i paraqiti padishahut të ri një \"xhylusije\" (poezi për ardhjen në fron) — sipas TDV-së, menjëherë pas elegjisë që shkroi për vdekjen e Kanuniut.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Përfundimi i urës së Büyükçekmecesë", "5f49b3c5"], "d": ["Ura e nisur me urdhër të sulltan Sulejman Kanuniut, për shkak të vdekjes së padishahut gjatë fushatës së Sigetvarit, u përfundua me porosi të të birit, Selimit II, në vitet 1567-68. Mimar Sinani e riparoi vetë edhe pjesët e urës, të ndërtuar në pikën ku liqeni i Büyükçekmecesë bashkohet me detin, që u dëmtuan nga përmbytja.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Fillon ndërtimi i Xhamisë Selimije (Edrene)", "07e18c9e"], "d": ["Ndërtimi i Selimijes, që Mimar Sinani e quajti \"vepra ime e mjeshtërisë\", filloi më 1568 në emër të Selimit II dhe, pas gjashtë vjetësh, përfundoi më 1574 (përfundimi është shënuar tashmë në kronologji). Dyqanet perëndimore të arastasë dhe mektebi i fëmijëve u përfunduan pas vdekjes së Selimit II, në kohën e Muratit III, nga Davud Aga.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Vdekja e Kënalëzade Ali Çelebiut — autorit të Ahlak-i Alai, tekstit klasik të filozofisë morale osmane", "dd921873"], "d": ["Autori i Ahlak-i Alai, tekstit klasik më të njohur të filozofisë morale osmane, Kënalëzade Ali Çelebiu, vdiq si kazasker i Anadollit më 22 janar 1572. Nga vepra e tij në bibliotekat e Stambollit ruhen mbi shtatëdhjetë kopje.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Ndërtimi i kompleksit të Pijale Pashës", "75411278"], "d": ["Kapudan-i derja Pijale Pasha, njëri nga dhëndurët e Selimit II, e bleu truallin e kompleksit më 1573 dhe ia porositi Mimar Sinanit. Kompleksi u projektua si një tërësi e gjerë e përbërë nga xhamia, medreseja, teqeja, tyrbja, varrezat, mektebi i fëmijëve, çezma, tregu dhe hamami.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Përfundimi i urës mbi Drinë (Mehmet Pashë Sokoli)", "1d668c73"], "d": ["Ura, e ndërtuar nga Mimar Sinani nën patronazhin e vezirit të madh Mehmet Pashë Sokoli, sipas datës në mbishkrim përfundoi në vitet 1577-78; disa studiues pretendojnë se ndërtimi filloi në 1571-72. Ura është simbol i lidhjes së Sokolit me vendlindjen e tij, Vishegradin.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Ndërtimi i Xhamisë së Azapkapësë (Mehmet Pashë Sokoli)", "f7b57feb"], "d": ["Xhaminë, që ndodhet pranë këmbës së urës së Unkapanit nga ana e Shishhanes, veziri i madh Mehmet Pashë Sokoli ia porositi Mimar Sinanit. Ndërtesa është një nga dy xhamitë e Sinanit të ndërtuara në emër të Sokolit (tjetra është xhamia në Kadërga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Murati III lëshon ferman për hartimin e Hunernames", "b125710d"], "d": ["Murati III me fermanin e datës 2 janar 1578 urdhëroi Sejid Lokmanin të shkruante Hunernamen, që trajton jetët e padishahëve nga Osman Gaziu deri në kohën e vet; miniaturat e veprës u përgatitën nga Nakash Osmani dhe ekipi i tij.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Përfundimi i Xhamisë së Zal Mahmud Pashës", "732f75bc"], "d": ["Në ndërtimin e kompleksit, që filloi pas martesës së Zal Mahmud Pashës me Shah Sulltanen më 1574, ndërtimi i xhamisë përfundoi më 1580; medresetë vazhduan deri më 1582, kurse çezma deri më 1590. Kompleksi tërheq vëmendjen në shpatet e Ejupit me planin origjinal me dy minare simetrike.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Përfundimi i vëllimit II të Hunernames", "70a1e741"], "d": ["Vëllimi i dytë i Hunernames përfundoi në janar 1588; me 65 miniaturat u bë një nga veprat më të vlefshme dokumentare të historiografisë osmane. Të dy vëllimet u ilustruan në punishten e Nakash Osmanit.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Davud Aga bëhet kryearkitekt i oborrit", "8cdc7f53"], "d": ["Pas një ndërprerjeje të shkurtër pas vdekjes së Mimar Sinanit më 1588, Davud Aga, që nga viti 1592, filloi të përmendej në dokumentet zyrtare si kryearkitekt i oborrit. Davud Aga, që mori përsipër disa elemente plotësuese të kompleksit Selimije dhe ndërtimin e parë të Xhamisë së Re, është një nga arkitektët më të rëndësishëm të periudhës.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Vihet themeli i Xhamisë së Re (Eminönü)", "d3cddc01"], "d": ["Me patronazhin e Safije Sulltanes, nënës së Mehmetit III, themeli i xhamisë u hodh me blloqe guri pasi toka u forcua me hunj. Dy zëra të ndryshëm të TDV-së japin data të ndryshme për këtë ngjarje (zëri për kompleksin e Jeni Xhamisë 9 prill 1598, zëri për Davud Agën 23 gusht 1597); këtu është marrë si bazë data në zërin e veçantë të ndërtesës.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Vdekja e Davud Agës nga murtaja dhe mbetja përgjysmë e ndërtimit të Xhamisë së Re", "81f2cd04"], "d": ["Në vend të Davud Agës, që vdiq në epideminë e murtajës në shtator 1598 kur e kishte ngritur Xhaminë e Re vetëm një zira mbi tokë, kryearkitekt u emërua Dallgëç Ahmed Çaushi. TDV vëren se data e vdekjes në një gojëdhënë alternative, e bazuar në një kronogram në vargje, përmendet edhe si 1599-1600, dhe se data e saktë nuk është përcaktuar.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Eksport i madh i sofit të Ankarasë në Evropë", "3f37018d"], "d": ["Sofi dhe shali i endur në Ankara, përveç tregjeve të brendshme si Stambolli, Bursa, Damasku e Alepi, eksportohej në Venedik, Poloni, Angli dhe Francë. Në shembullin që jep TDV-ja, më 1599 tetëmbëdhjetë tregtarë blenë 162 ngarkesa sofi me vlerë 5.700.000 akçe dhe i dërguan në Alep dhe Venedik.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Ndalet ndërtimi i Xhamisë së Re për shkak të vdekjes së Mehmetit III", "5acef053"], "d": ["Pas vdekjes më 1603 të Mehmetit III, djalit të patrones Safije Sulltane, Safije Sulltana u dërgua në Pallatin e Vjetër dhe ndërtimi i Xhamisë së Re mbeti përgjysmë; ndërtesa në këtë gjendje priti e papërfunduar rreth gjashtëdhjetë vjet.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Qatib Çelebiu fillon kërkimet në Alep për Keshfuz-Zunun", "094e6870"], "d": ["Qatib Çelebiu filloi më 1633 në Alep të mblidhte materialin për Keshfuz-Zunun, që më vonë do të bëhej kryevepra e tij bibliografike. Gjatë kësaj pune njëzetvjeçare ai shqyrtoi një nga një bibliotekat dhe librashitësit e qyteteve ku shkonte.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Nefiu ekzekutohet për shkak të satirave", "5e459c60"], "d": ["Poeti i divanit Nefi, i njohur për satirat, më 1635 u ekzekutua me urdhër të Muratit IV për shkak të përmbledhjes satirike të tij Siham-i Kaza. Veziri i madh Bajram Pasha e dorëzoi; Nefiu u mbyt në drunjtoren e pallatit dhe kufoma e tij u hodh në det.", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Hartimi i defterit gjithëpërfshirës të narkut", "6c1e231b"], "d": ["Edhe pse zbatimi i narkut (çmimit maksimal) tek osmanët është shumë i vjetër, defteri më gjithëpërfshirës i narkut që ka arritur deri në ditët tona mban datën 1640; ky defter, që përfshinte ushqimin, veshjen, shërbimet, standardet dhe kushtet e higjienës, sipas shprehjes së TDV-së \"funksionoi si një ligj i plotë për rregullimin e tregut\".", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Qatib Çelebiu fillon për herë të parë të shkruajë Xhihannumanë", "554c6734"], "d": ["Qatib Çelebiu, me qëllim që të mbushte boshllëkun e njohurive gjeografike osmane përballë zbulimeve gjeografike të Perëndimit, filloi më 1648 hartimin e parë të Xhihannumasë. Ky version i parë mbeti përgjysmë, sepse për disa vende evropiane nuk gjeti burime të mjaftueshme.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Sistemi i iltizamit piqet duke u kthyer në monopol të shtresës ushtarake", "2c587934"], "d": ["Metoda e iltizamit (dhënia me ankand e mbledhjes së taksave personave privatë kundrejt një pagese) zbatohej që nga gjysma e dytë e shekullit XV, por nga fillimi i shekullit XVI po përhapej me shpejtësi. Sipas TDV-së, procesi me të cilin sektori u bë tërësisht monopol i anëtarëve të shtresës ushtarake përfundoi më 1650; kështu iltizami u bë metoda kryesore financiare që zuri vendin e sistemit të timarit.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Qatib Çelebiu fillon ta shkruajë Xhihannumanë nga e para", "e9c68110"], "d": ["Qatib Çelebiu, që e kishte lënë përgjysmë hartimin e parë, në fund të vitit 1654 filloi ta shkruante Xhihannumanë nga e para. Edhe ky version i dytë nuk u përfundua; kur vepra kishte arritur te Vani, ajo mbeti përgjysmë me vdekjen e autorit më 1657 dhe vetëm më 1732 u botua në këtë formë nga Ibrahim Myteferika.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Xhamia e Re përfundon dhe hapet për adhurim", "d6d86c82"], "d": ["Ndërtimi i Xhamisë së Re, që kishte mbetur përgjysmë për mbi gjashtëdhjetë vjet, u përfundua nën drejtimin e kryearkitektit Meremetxhi Mustafa Aga, që Valide Sulltane Hatixhe Turhan e emëroi më 1661, dhe u hap për adhurim me namazin e xhumasë të falur më 30 tetor 1665.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Mehmeti IV organizon me ditë të tëra gara xhiriti në dasmën e synetisë në Edrene", "3638a5b6"], "d": ["Mehmeti IV, në dasmën e synetisë së shehzadeve që organizoi më 1675 në Edrene, caktoi gara xhiriti që zgjatën me ditë; kjo përmendet veçanërisht në zërin për xhiritin të TDV-së si një nga shembujt më madhështorë të përkrahjes që pallati osman i dha sportit të xhiritit.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hafiz Osmani zhvillon stilin e vet kaligrafik", "93081cb3"], "d": ["Hafiz Osmani, që vinte nga linja e shejh Hamdullahut, më 1679 zhvilloi në aklam-i sitte një stil të ri të veçantin, që më vonë do të njihej si \"shkolla e Hafiz Osmanit\". Ky stil ka vazhduar deri në ditët tona në dy degë të veçanta.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Hafiz Osmani emërohet mësues kaligrafie i Mustafait II", "d976cda4"], "d": ["Hafiz Osmani, i konsideruar kaligrafi më mjeshtër i epokës, më 1695 u emërua mësues kaligrafie i Mustafait II, i sapoardhur në fron. Gjatë jetës formoi rreth pesëdhjetë kaligrafë dhe kopjoi 25 Kuranë.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Vdekja e Itriut", "62750526"], "d": ["Njëri nga kompozitorët më të mëdhenj të muzikës turke, Buhurizade Mustafa Itri Efendi, sipas burimeve afër asaj kohe vdiq më 1711. Me vepra si tekbiri në makamin segah dhe nati në makamin rast la kryevepra të muzikës së xhamive dhe teqeve.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedimi del në pah si pararendës i poezisë së Epokës së Tulipanëve", "d3c40dbb"], "d": ["Gjatë Epokës së Tulipanëve të viteve 1718-1730, Nedimi zhvilloi një stil të ri poezie që dallohej për përsosmërinë e shprehjes, kërkimin e thjeshtësisë dhe stilin plot mendjehollësi. Ky stil, i zhvilluar në rrethin e Nevshehirli Damad Ibrahim Pashës, konsiderohet përfaqësuesi më i madh i rrymës së vendëzimit në poezinë e divanit.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levni ilustron Surnamen e Vehbiut (Surname-i Vehbî)", "8c127866"], "d": ["Piktori i pallatit Levni ilustroi me 137 miniatura Surname-i Vehbî-në, që tregon dasmën e synetisë së shehzadeve të Ahmetit III më 1720. Ndryshe nga shembujt e mëparshëm, ai nuk i kufizoi festimet vetëm në Atmejdan, por i paraqiti në skaje të ndryshme të qytetit dhe kështu nisi një kuptim të ri në artin osman të miniaturës.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Sistemi i gedikut vendoset zyrtarisht si rend zejtarie monopolist", "cd0f79a7"], "d": ["Sipas TDV-së, shndërrimi sistematik me të cilin e drejta e gedikut mori kuptimin e \"monopolit, privilegjit dhe një lloj patente\" ndiqet që nga viti 1727; ky rend, që u njihte një numri të caktuar personash të drejtën për të punuar në zejtari, u vendos nën emrin \"e drejta e gedikut\" kryesisht në dyqane që ishin pronë vakëfi.", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Shkatërrimi i Sadabadit në kryengritjen e Patrona Halilit", "8a30f9a0"], "d": ["Gjatë kryengritjes së Patrona Halilit, që shpërtheu më 25 shtator 1730, u shkatërruan qindra kioska e ndërtesa në Sadabad; ky kompleks, simbol i Epokës së Tulipanëve, nuk e rifitoi më kurrë shkëlqimin e vjetër.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Vdekja e Nedimit gjatë kryengritjes së Patrona Halilit", "06bf909e"], "d": ["Nedimi, që kur shpërtheu Kryengritja e Patrona Halilit ishte myderriz në medresenë e Sekban Ali Pashës, vdiq në ditët pas kryengritjes. Dita e vdekjes nuk dihet; por, meqë dokumenti i kasamit për trashëgiminë e tij u përpilua më 15 rebiulahir 1143 (28 tetor 1730), ai ka vdekur para kësaj date. Për shkakun e vdekjes ka gojëdhëna të ndryshme: një pjesë e burimeve shkruan se vdiq nga sëmundja e frikës (illet-i vehime) ose nga sëmundja e dridhjes që e kishte zënë për shkak të pijes dhe opiumit, ndërsa Mustakimzade shkruan se gjatë trazirave, nga frika, doli në çatinë e shtëpisë dhe vdiq duke rënë prej andej. Me vdekjen e tij mori fund de facto edhe shkëlqimi kulturor i Epokës së Tulipanëve.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Vdekja e Levniut", "dd48b56e"], "d": ["Levni, i konsideruar përfaqësuesi i fundit i madh i artit osman të miniaturës, vdiq më 1732. Pjesa më e madhe e veprave të tij ndodhet sot në Muzeun e Pallatit Topkapi.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Vihet themeli i Xhamisë Nuruosmanije dhe kompleksit të saj", "397ec798"], "d": ["Themelin e kompleksit Nuruosmanije e vuri Mahmudi I më 19 janar 1749. Kjo ndërtesë konsiderohet zbatimi i parë i madh i stilit barok evropian në arkitekturën osmane dhe dallohet qartë nga skema klasike e kompleksit.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Hapja e Xhamisë Nuruosmanije dhe kompleksit të saj", "15d83731"], "d": ["Hapja e kompleksit, që Mahmudi I e nisi, por nuk e pa të përfunduar, u bë në kohën e vëllait të tij, Osmanit III, më 5 dhjetor 1755. Xhamia e mori emrin në kuptimin \"Drita e Osmanit\", për nder të Osmanit III, që e kreu hapjen.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Hapja e Shkollës Perandorake të Inxhinierisë Detare (Mühendishâne-i Bahrî-i Hümâyun)", "a2fab1cd"], "d": ["Shkolla e parë moderne osmane e inxhinierisë detare, Mühendishâne-i Bahrî-i Hümâyun, sipas dokumenteve arkivore franceze u hap më 29 prill 1775 në kohën e Abdulhamidit I, gjatë vezirllëkut të madh të Dervish Mehmed Pashës.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Krijimi i sistemit të eshamit", "eabd8ece"], "d": ["Përballë barrës së dëmshpërblimit prej 7,5 milionë kurushësh që solli Traktati i Küçük Kajnarxhës, më 1775 u krijua sistemi i eshamit. Në këtë metodë, e projektuar për të tejkaluar kufijtë e malikanes, të ardhurat e mukatasë ndaheshin në aksione dhe, ndryshe nga malikaneja, aksionarë mund të bëheshin edhe gratë, jomyslimanët dhe populli i thjeshtë.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Lindja e Hamamizade Ismail Dede Efendiut", "c033f039"], "d": ["Njëri nga kompozitorët më prodhimtarë të muzikës turke, Hamamizade Ismail Dede Efendiu, lindi më 9 janar 1778 në lagjen Shehzadebashi të Stambollit. Gjatë jetës kompozoi mbi 500 vepra, nga të cilat rreth 294 kanë arritur deri në ditët tona.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Fillon ndërtimi i Shkollës Perandorake të Inxhinierisë Tokësore (Mühendishâne-i Berrî-i Hümâyun)", "4f5d521a"], "d": ["Ndërtimi i Mühendishâne-i Berrî-i Hümâyun, një nga institucionet më të rëndësishme të reformave Nizam-i Xhedid të Selimit III, filloi më 14 korrik 1793. Ndërtesa përfundoi në shtator 1795 dhe u hap për mësim; institucioni ishte shkolla e dytë osmane e inxhinierisë ushtarake, sipas modelit të akademive ushtarake evropiane.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Selimi III fillon të heqë monopolin e disa esnafeve", "008f4a7d"], "d": ["Sipas zërit për esnafet të TDV-së, në rendin osman të esnafeve, që nga themelimi ishte i ndërthurur me organizatën e ahive, funksionarë si \"ahi baba\" dhe \"shejhu\" ushtruan udhëheqjen e esnafeve deri në fillim të shekullit XIX; kur në shekullin XVIII, me monopol, esnafet i ngritën çmimet mbi narkun (çmimin e caktuar) dhe krijuan presion ekonomik, Selimi III që nga viti 1794 filloi të hiqte monopolin e esnafeve të ushqimeve bazë.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendiu pranohet në pallat si musahib-i shehrijari", "0cb99ac3"], "d": ["Dede Efendiu, që në kohën e Selimit III tërhoqi vëmendjen e padishahut me një kompozim në makamin buselik, më 1812 u pranua nga Mahmudi II ndër \"musahib-i shehrijari\" (shokët e ngushtë të bisedave të padishahut) dhe pak më vonë u ngrit në postin e kryemuezinit.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Kryhet regjistrimi i parë i rregullt i popullsisë tek osmanët", "4f004c6c"], "d": ["Mahmudi II, me qëllim të përcaktimit të popullsisë që do të merrej ushtar, urdhëroi për herë të parë, në fund të vitit 1830, një regjistrim të rregullt; u regjistrua vetëm popullsia mashkullore dhe në Anadoll e Rumeli u përcaktuan rreth 7,5 milionë vetë. Në disa zona si Erzurumi dhe Vani regjistrimi mundi të përfundonte vetëm më 1836.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Themelimi i Feshanes Perandorake (Feshâne-i Âmire)", "971ab85a"], "d": ["Për të plotësuar nevojën për fese të ushtrisë Asakir-i Mansure-i Muhammedije, të krijuar pas shfuqizimit të Ocakut të Jeniçerëve më 1826, me një kapital prej 1,5 milionë kurushësh, më 1833 filloi prodhimi i feseve në Sheshin Xhyndi në Kadërga. Instalimet u transferuan më 1839 në Pallatin e Hatixhe Sulltanes në Ejup; Feshanja përbëri bazën e industrisë osmane të tekstilit.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Shkolla e mjekësisë merr emrin Mekteb-i Tibbije-i Adlije-i Shahane", "187d60f3"], "d": ["Shkolla e mjekësisë, e transferuar në ndërtesën e Shkollës së Agallarëve të Enderunit në Gallatasaraj, me vizitën e Mahmudit II më 14 maj 1839 mori emrin \"Mekteb-i Tibbije-i Adlije-i Shahane\"; kështu institucioni u regjistrua zyrtarisht me identitetin e një shkolle ushtarako-administrative.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Vdekja e Dede Efendiut në Mina gjatë haxhit", "c3e613a2"], "d": ["Hamamizade Ismail Dede Efendiu, që shkoi për të kryer detyrimin e haxhit, u prek nga kolera në Mina dhe vdiq më 29 nëntor 1846. Me vdekjen e artistit, që ndërmjet viteve 1824-1839 kishte kompozuar shtatë ajine (ceremoni) mevlevije, u mbyll një epokë e muzikës klasike osmane.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Miratimi i Kodit Tregtar të vitit 1850", "8ac085fd"], "d": ["Në kuadër të reformave juridike të periudhës së Tanzimatit, nga shtetet perëndimore u morën me përkthim dhe huazim ligje të reja: kodi penal hyri në fuqi më 1840, kodi tregtar më 1850 dhe ligji i tokës më 1857. Kodi Tregtar ishte kodifikimi i parë modern i së drejtës tregtare osmane.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Fillimi i valës së madhe të migrimit të tatarëve të Krimesë dhe popujve të Kaukazit në tokat osmane", "8832c06d"], "d": ["Pasi shejh Shamili ra rob i rusëve më 1859, bashkë me tatarët e Krimesë, shumë muhaxhirë çerkezë dhe nogaj nga Kaukazi filluan të shpërnguleshin në tokat osmane. Kjo valë migrimi vazhdoi me intensitet të ndryshëm deri pas luftës osmano-ruse të viteve 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Themelimi i Komisionit të Muhaxhirëve", "9717e77e"], "d": ["Për të administruar valën gjithnjë e më të madhe të migrimit nga Kaukazi, qeveria osmane më 16 janar 1860 themeloi Komisionin e Muhaxhirëve. Komisioni koordinoi punimet e ngulimit në Anadoll, Ballkan dhe Siri dhe veproi deri më 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Riorganizimi i Bank-i Osmanisë si Bank-i Osmani-i Shahane (Banka Osmane)", "c3530456"], "d": ["Më 1856, pas Luftës së Krimesë, për të administruar shlyerjet e borxhit të jashtëm ishte themeluar Banka Osmane (Bank-i Osmani) me qendër në Londër dhe me kapital anglez. Më 1863 një grupi të përbashkët franko-anglez iu dha leja për të themeluar një bankë të re me emrin Bank-i Osmani-i Shahane (Banka Osmane); institucioni më vonë mori edhe të drejtën të nxirrte kartëmonedha.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Themelimi i Shoqërisë Islame të Arsimit (Cem'iyyet-i Tedrîsiyye-i İslâmiyye)", "77ad553a"], "d": ["Për të marrë përsipër arsimimin e çirakëve të varfër myslimanë, më 30 mars 1864 u themelua Cem'iyyet-i Tedrîsiyye-i İslâmiyye; kjo nismë shoqate civile është shembull pararojë i shndërrimit të traditës së institucioneve të bamirësisë në projekt të shkollës moderne. Nëntë vjet më vonë shoqata do të hapte Darushafakanë.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Rregullimi i sistemit të kryepleqve dhe këshillit të pleqve me Rregulloren e Vilajetit të vitit 1864", "1a2e8cf2"], "d": ["Me Rregulloren e Vilajetit të vitit 1864 u riorganizua administrimi i fshatit; u pranua që në fshatrat ku jetonin bashkë myslimanë e jomyslimanë çdo bashkësi të zgjidhte kryeplakun dhe këshillin e vet të pleqve. Kështu këshilli i pleqve zuri për herë të parë një vend zyrtar në administrimin e fshatit/lagjes.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Kulmi i Internimit të Madh të Çerkezëve", "b2ab1874"], "d": ["Me pushtimin rus të Kaukazit ndërmjet viteve 1858-1878, me intensitetin më të lartë në 1861-1864, 1,2-1,5 milionë çerkezë u detyruan të shpërnguleshin me dhunë në tokat osmane. Sipas TDV-së, shumë studiues e cilësojnë këtë ngjarje si \"lëvizjen e parë të spastrimit etnik të historisë moderne\".", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Shpallja e Rregullores së Arsimit të Përgjithshëm të vitit 1869", "787f6022"], "d": ["Rregullorja e Arsimit të Përgjithshëm (Maarif-i Umumije Nizamnamesi), e shpallur më 1 shtator 1869, qe teksti i parë gjithëpërfshirës që rregulloi arsimin e përgjithshëm në provinca dhe në qendër. Me rregulloren u themelua Këshilli i Madh i Arsimit (Mexhlis-i Kebir-i Maarif); me këtë rregullim filloi edhe riorganizimi i mektebeve të fëmijëve, që nga një fazë thjesht e arsimit fetar u drejtuan nga mësimi i leximit e shkrimit.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Shkolla Darushafaka fillon mësimin", "525c457c"], "d": ["Darushafaka, e themeluar nga Cem'iyyet-i Tedrîsiyye-i İslâmiyye, filloi efektivisht mësimin më 28 qershor 1873 për të arsimuar falas, me konvikt, fëmijët jetimë dhe të varfër myslimanë; mosha maksimale e pranimit u caktua dhjetë vjeç.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Tërmeti i Stambollit i vitit 1894", "7ae7f648"], "d": ["Tërmeti që ndodhi më 10 korrik 1894 në ujërat përballë gjirit të Izmitit goditi rëndë Stambollin; u dëmtuan shumë xhami dhe ndërtesa historike, përfshirë muret e Stambollit. Zëri për tërmetin i TDV-së e numëron këtë tërmet, bashkë me tërmetet e viteve 1509, 1719 dhe 1766, ndër tërmetet që shkaktuan humbje të mëdha jetësh e pasurie në rajonin e Marmarasë.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Hapja e Darulaxhezes", "a30baf31"], "d": ["Darulaxhezeja, e përgatitur sipas urdhrave që Abdylhamidi II dha që nga viti 1890, u hap më 2 shkurt 1896 nga veziri i madh Halil Rifat Pasha. Institucioni, që strehonte fëmijë të pastrehë, të moshuar dhe nevojtarë, me spitalin me 200 shtretër, punishtet dhe faltoret e veçanta si xhami, kishë e sinagogë, ishte kompleksi më i madh i ndihmës sociale të kohës së vet.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Darylfunun-i Shahane rithemelohet si institucion i qëndrueshëm", "7d6d8fc4"], "d": ["Darylfynuni, pas dy përpjekjeve të mëparshme të pasuksesshme (1863 dhe 1870), më 31 gusht 1900 u rithemelua si institucion i qëndrueshëm me emrin Darylfunun-i Shahane; TDV e cilëson këtë datë si bazën e drejtpërdrejtë të sistemit të sotëm universitar turk.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Serbedarët morën Sebzevarin — shteti i parë pas-ilhanid në Horasan", "af997fec"], "d": ["Kur me vdekjen e Ebu Saidit (30 nëntor 1335) u shemb autoriteti qendror ilhanid, indinjata e grumbulluar në Horasan kundër mbledhësve të taksave shpërtheu në Bashtin: Abdurrezaku u ngrit më 13 mars 1337 dhe më 9 shtator 1337 (12 safer 738) shtiu në dorë Sebzevarin. Emri \"serbedar\" — \"kokën në litar\" — është fjala e tyre që tregon se, po të munden, ishin gati të vareshin.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Sejidët Marashi morën Amulin — sundimi i sejidëve në Mazanderan", "c0e03266"], "d": ["Sejid Kivamudin Marashi, duke ndjekur rrugën që serbedarët kishin hapur në Horasan, në vitin 760 (1359) shtiu në dorë Amulin dhe në bregun jugor të Detit Kaspik themeloi një shtet sejidësh. Dinastia u përhap në Sari, Barfurush dhe rrethina; u trondit nga fushatat e Timurit dhe u shpërbë në kohën e safavidit Shah Abas I.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Dinastia Karkija u themelua në Gilan — zotërit e fundit të pavarur të bregut të Kaspikut", "6e5f9db7"], "d": ["Ali Kija, duke u kthyer me familjen në Gilan, në vitin 773 (1371-72) vendosi sundimin Karkija me qendër në Lahixhan; dinastia e mbajti bregun jugperëndimor të Detit Kaspik për më shumë se dy shekuj dhe vazhdoi deri kur safavidi Shah Abas I e aneksoi rajonin më 1592.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Sundimi në Darfur kalon nga daxhutë te tunxhurët", "6eb22a2a"], "d": ["Sipas zërit për Darfurin në Enciklopedinë Islame të TDV-së, të parët që u vendosën në rajon dhe krijuan shtetin e parë janë fisi daxhu; daxhutë, që sunduan këtu gjatë shekujve XIII dhe XIV, ua humbën sundimin tregtar tunxhurëve, dhe në shekullin XV situata, veçanërisht në zonën qendrore, u kthye tërësisht në favor të tunxhurëve.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Spanja rimerr shkëmbin e Badisit (Peñón de Vélez)", "0dc52728"], "d": ["Zëri për saadët i TDV-së shënon se marrja e Badisit nga spanjollët ishte goditje e rëndë për detarinë e Magrebit (1564). Ky pozicion shkëmbor në bregdetin verior të Marokut shërbente si mbështetje për piraterinë në Mesdheun Perëndimor dhe për rivalitetin osmano-spanjoll.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["el-Arajshi (Larache) i lëshohet Spanjës", "7b8f6e27"], "d": ["Gjatë viteve të luftës civile, kur dinastia saade u copëtua, porti i el-Arajshit në bregdetin atlantik iu la Spanjës. Zëri për saadët i TDV-së shënon se në këtë periudhë vendi u nda në dysh si emiratet e Marrakeshit (jug) dhe Fesit (veri) dhe se palët në luftën për fron kërkonin ndihmë nga jashtë. Porti do të mbetej afro tetëdhjetë vjet në duart spanjolle dhe më 1689 do ta rimerrte Mulej Ismaili.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Mamora (Mehdia) kalon në duart e spanjollëve", "c8fd494e"], "d": ["Porti i Mamorës (Ma'mure / Mehdia) në grykëderdhjen e lumit Sebu u mor nga spanjollët më 1614 dhe u fortifikua me emrin San Miguel de Ultramar. Zëri për Mulej Ismailin i TDV-së shënon se porti iu rimor spanjollëve me një sulm të befasishëm në vitin 1092 (1681) — pra sundimi spanjoll zgjati gjashtëdhjetë e shtatë vjet.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Fundi i dinastisë saade — fillimi i periudhës alavite (filali) në Marok", "b1afa579"], "d": ["Enciklopedia Islame e TDV-së e përkufizon zërin për saadët si \"një dinasti islame që sundoi në Marok (1511-1659)\". Dinastia, që më 1549 i dha fund sundimit vattasid dhe bashkoi tërë Marokun, që më 1578 në Vadi es-Sejl asgjësoi ushtrinë portugeze dhe që në asnjë periudhë nuk iu nënshtrua osmanëve, mori fund më 1659 pas luftërave të gjata për fron. Vendin e saj e zunë sherifët alavitë (filali) që vinin nga Tafilalti; Mulej Reshidi, duke hyrë në qytetin e Fesit më 1666, e përforcoi dinastinë e re, dhe vëllai i tij Mulej Ismaili pastroi pozicionet evropiane në bregdetin atlantik.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Spanja pushton ishujt el-Husejma (Alhucemas)", "954ca998"], "d": ["Ishujt e el-Husejmas në bregdetin mesdhetar u pushtuan nga flota spanjolle më 1673. Bashkë me Badisin dhe Ceutën, janë ndër pozicionet që Spanja mbajti në bregdetin verior marokenas dhe që i kanë mbetur deri sot. Po atë vit vëllai i madh i Mulej Ismailit, Mulej Reshidi, kishte hyrë në Marrakesh dhe kishte marrë betimin e besnikërisë nga populli, dhe sundimi filali ishte përforcuar në jug — kjo humbje në bregdet tregon se bashkimi i brendshëm ende s'kishte pasqyrim në frontin e jashtëm.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Mulej Ismaili ia rimerr el-Arajshin spanjollëve", "a54bc6ee"], "d": ["Zëri për Mulej Ismailin i TDV-së është i qartë: \"Në vitin 1100 (1689), duke ua rimarrë spanjollëve Arajshin, shtinë në dorë 200 topa, dhe dy vjet më pas rimorën edhe Asilën.\" Kjo është një nga hallkat e zinxhirit të pastrimit të bregdetit nga sulltani filali — Tanxheri u rimor më 1678 nga anglezët, Mamora më 1681, el-Arajshi më 1689, Asila më 1691. Porti i braktisur tetëdhjetë vjet më parë gjatë luftës civile saade, kështu i kthehej Marokut.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Themelimi i Sulltanatit të Darfurit — dinastia Keira dhe Sulejman Solong", "0fc1c112"], "d": ["Sipas TDV-së, themelimi i Sulltanatit të Darfurit përkon me kohën pas trazirave që pasuan pushtimin e rajonit nga Bumu el-Kasiri në fund të shekullit XVII. Furët, nën udhëheqjen e fisit Kira (Keira) me Sulejman Solongun në krye, ua morën sundimin daxhuve dhe tunxhurëve dhe krijuan një administratë të fortë. Sulejman Solongu sundoi ndërmjet viteve 1695-1715. Në shekujt pasues sulltanët e Darfurit mbajtën letërkëmbim me Babialinë; Abdylmexhidi dhe Abdylazizi ua konfirmuan sundimin.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Shpallja e Republikës së Parë në Francë — fundi i mbretërisë", "d53d49b0"], "d": ["Në mbledhjen e parë të Konventës Kombëtare u shfuqizua mbretëria dhe të nesërmen u shpall Republika e Parë; nga kjo ditë filloi viti i parë i kalendarit të ri. Për osmanët bashkëbiseduesi nuk ndryshoi, por ndryshoi lloji i tij: në vitet e Nizam-i Xhedidit të Selimit III, Franca nuk ishte më dinasti, por regjim, dhe edhe ushtria që do të zbarkonte në Egjipt më 1798 ishte ushtria e atij regjimi.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Rënia e Kabilisë së Madhe — robëria e Lalla Fatma N'Soumer", "0f61ff08"], "d": ["Zëri për Algjerinë i TDV-së shënon se me pushtimin e rajonit malor të Kabilisë (Bilad el-Kabail) pas fushatave të viteve 1853, 1854 dhe 1857, procesi i pushtimit francez të Algjerisë u përfundua në masë të madhe. Fushata e vitit 1857 theu vijën Tizi Ouzou-Akbou; Lalla Fatma N'Soumer, simbol i rezistencës, u zu robinjë. Kështu u shua vatra e fundit e madhe e rezistencës që kishte mbetur në këmbë pas dorëzimit të emir Abdylkadirit më 1847.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Francezët pushtojnë In Salah (Tidikelt)", "1e28d1d0"], "d": ["In Salahu, qendra e grupit të oazave të Tidikeltit në mes të Saharasë, u mor nga forcat franceze më 29 dhjetor 1899. Ky është hapi i parë i madh i zgjerimit francez që zbriste nga bregdeti algjerian drejt jugut e derdhej në shkretëtirë; brenda dy vjetëve edhe Tuati dhe Gurara do të ndiqnin të njëjtën rrugë.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Aneksimi i oazave Tuat · Gurara · Tidikelt nga Franca", "d412838b"], "d": ["Brezi i oazave Tuat, Gurara dhe Tidikelt në jugperëndim të Algjerisë iu lidh zyrtarisht Francës më 21 shkurt 1901. Kështu kjo nyje e rrugëve të karvaneve, mbi të cilën sulltani i Marokut pretendonte të drejtë nominale — përfshirë Adrarin, Timimunin, Reganin dhe Beni Abbesin — iu bashkua Algjerisë; ky është fillimi i mosmarrëveshjes kufitare mes Marokut dhe Algjerisë franceze.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Ngritja e karakollit francez në Béchar (Colomb-Béchar)", "4d44d252"], "d": ["Oaza e Bécharit në kufi me Marokun u mor nga forcat franceze më 11 nëntor 1903 dhe u shndërrua në post të përparuar me emrin Colomb-Béchar. Ky hap, që erdhi dy vjet pas aneksimit të brezit të Tuatit, është ndër hallkat e fundit të përparimit francez nga Algjeria drejt Marokut; ai hap rrugën që çoi në vënien e Marokut nën protektorat më 1912.", "bd1a7ae2"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Themelimi i bejliqeve Karesi dhe Hamidi", "3905da93"], "d": ["Sipas zërit për Karesinjtë të TDV-së, Karesi Beu, duke shpallur pavarësinë në organizatën kufitare selxhuke që u shpërbë me vdekjen e të atit, Kalem Beut, që nga viti 696 (1296-97) e bëri Balëkesirin qendër dhe brenda pak kohe ia mori Bizantit të tërë Misinë, përfshirë Erdekun, Bigan, Edremitin dhe Bergamën. Po atë vit (1297) Hamid Beu, duke e bërë Uluborlunë qendër qeveritare, themeloi bejlikun Hamidi; Isparta, Burduri, Egirdiri dhe Jalvaçi u bashkuan nga zona kufitare selxhuke në shpërbërje me kufijtë e parë të bejlikut. Të dy bejliqet janë produkt i së njëjtës shembje në Anadollin Perëndimor — shpërbërjes së autoritetit qendror selxhuk.", "7d297343"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Themelimi i bejlikut Ajdinid — marrja e Izmirit, Ajasulukut dhe Tires", "69a021ae"], "d": ["Sipas zërit për Ajdinidët të TDV-së, Mubarizudin Gazi Mehmed Beu, duke ia marrë këtë rajon beut kufitar të Germijanit, Sasa Beut, më 1308 vendosi sundimin në Ajdin-ili; pushtoi pjesën myslimane të Izmirit bashkë me Ajasulukun (Selçuk), Tiren dhe Bodemjan. Ajasulukun e bëri bazë flote dhe tokat që shtiu në dorë i ndau mes pesë djemve të tij — bejliku, në dhjetëvjeçarët pasues, veçanërisht në kohën e të birit, Umur Beut, do të bëhej forcë vendimtare në detarinë e Egjeut.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Fundi de facto i Shtetit Selxhuk të Anadollit — administrimi i drejtpërdrejtë ilhanid", "00f85ecb"], "d": ["Sipas zërit për Mesudin II të TDV-së, Gijasedin Mesudi II, që vdiq në Kajseri më 708 (1308) pas një sëmundjeje të gjatë, sipas mendimit të pranuar përgjithësisht është sundimtari i fundit i Shtetit Selxhuk të Anadollit — kandidatët e hipur në fron pas vdekjes së tij nuk fituan as njohjen e institucioneve të brendshme, as atë të ilhanidëve. Rajoni tashmë gjatë gjithë sundimit të Mesudit qeverisej faktikisht nga nëpunësit ilhanidë; me vdekjen e tij ky administrim i drejtpërdrejtë humbi edhe mbulesën formale në qendra si Konja, Nigde dhe Aksaraji.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Zgjerimi i bejlikut Xhandarid në Kastamonu, Çankëri, Bartën dhe Safranbolu", "64e39ad0"], "d": ["Sipas zërit për Xhandaridët të TDV-së, bejliku u themelua në fillim të shekullit XIV në rrethinat e Kastamonu-Sinopit nga Shemsedin Jaman Xhandari, të cilit sundimtari ilhanid Gajhatu i kishte dhënë si ikta Eflanin dhe rrethinat; për shkak të pamjaftueshmërisë së burimeve, data e saktë e themelimit nuk dihet. Pasardhësi i Xhandarit, Sulejman Beu, përmendet si sundimtar që zuri vendin e bejlikut Çobanid — pra rrethinat e Kastamonusë dhe Çankërisë kaluan nga Çobanidët te Xhandaridët, ndërsa vija Bartën-Safranbolu-Eflani nga administrimi i drejtpërdrejtë ilhanid.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Pushtimi i Rodosit dhe Dodekanezit nga kalorësit e Shën Gjonit (hospitalierët)", "67885b4b"], "d": ["Zëri për Rodosin i TDV-së shënon se ishulli më 1309 kaloi në duart e kalorësve të Shën Gjonit (hospitalierëve/isbitarijje); historia standarde e hospitalierëve (shih J. Riley-Smith, The Knights Hospitaller) hollëson se rrethimi filloi në verën e vitit 1306, ndërsa qyteti i Rodosit, që rezistoi gjatë me përforcime bizantine, ra para forcave të mjeshtrit të madh Foulques de Villaret vetëm më 15 gusht 1310. Nga kjo datë deri te pushtimi osman më 1522, ishulli do të ishte qendra e kalorësve, dhe edhe Dodekanezi përreth kaloi në të njëjtin proces nga Bizanti nën sundimin hospitalier.", "c1422e2c"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Marrja e Kosit (İstanköy) nga kalorësit e Shën Gjonit", "445666f7"], "d": ["Sipas zërit për Kosin të TDV-së, kalorësit e Shën Gjonit, pasi u vendosën në Rodos, morën edhe Kosin (1315) dhe ndërtuan kështjella të reja. Kështu ishulli hyri nën sundimin e kalorësve që vazhdoi deri më 1523; se nën cilin administrim ishte Kosi pas rënies së qytetit të Rodosit më 1310, TDV nuk e hollëson.", "145d1bad"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Themelimi i bejlikut Eretna — Anadolli Qendror pas ilhanidëve", "a67bacd9"], "d": ["Sipas zërit për Eretnaogllarët të TDV-së, Alaedin Eretna, një nëpunës ilhanid me origjinë ujgure, pas vdekjes më 1335 të sundimtarit ilhanid Ebu Said Bahadur Hanit, e shndërroi faktikisht në administratë të pavarur përfaqësimin ilhanid në Anadoll; fillimisht u shfaq si naib i sulltanit memluk, më 1340 e hoqi emrin e memlukut nga hutbeja dhe rreth vitit 1341 shpalli pavarësinë e plotë. Bejliku, me qendër fillimisht në Sivas, pastaj në Kajseri, deri në vdekjen e tij (1352) vendosi një sundim të gjerë në Anadollin Qendror, që përfshinte Amasjan, Tokatin, Çorumin, Nigden, Aksarajin dhe Erzinxhanin, dhe iu dha fund më 1381 nga Kadi Burhanedini.", "04978a80"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Themelimi i Shtetit Xhelajirid — Azerbajxhani pas ilhanidëve", "a13ada90"], "d": ["Sipas zërit për Xhelajiridët të TDV-së, Hasan-i Buzurg, nipi i emirit ilhanid Nojan, duke përfituar nga luftërat për fron që shpërthyen me vdekjen e sundimtarit ilhanid Ebu Said Bahadur Hanit, më 1340 themeloi një shtet të pavarur me qendër në Tabriz. Kështu xhelajiridët u bënë dinastia e parë e madhe që mbushi boshllëkun pas-ilhanid në Azerbajxhan dhe rrethina; në kohën e pasardhësit të tij Uvejsit (1356-1374) tokat do të zgjeroheshin deri në Mosul dhe Dijarbekir.", "224cbb81"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Kalimi i Bagdadit në duart karakojunlu — disfata e xhelajiridit sulltan Ahmed", "a42ebe92"], "d": ["Sipas zërit për Karakojunlunjtë të TDV-së, Kara Jusufi më 28 rebiulahir 813 (30 gusht 1410) i shkaktoi xhelajiridit sulltan Ahmed një disfatë të rëndë afër Tabrizit; pas vdekjes së sulltan Ahmedit, në vitin 814 (1411) e shpalli në Tabriz të birin, Pir Budakun, sulltan, dhe po atë vit djali i tij i madh, Shah Mehmedi, pushtoi Bagdadin. Kështu Bagdadi, kryeqytet xhelajirid për afro një shekull, bashkë me vijën Basra-Mosul-Kirkuk përreth, hyri nën sundimin karakojunlu.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Erzinxhani dhe Kemahu u kaluan akkojunlunjve — Kara Yülük Osman Beu", "122460d4"], "d": ["Pas vdekjes së Kara Jusufit, me kërkesën e popullit të Erzinxhanit, nipi i Mutahhartenit, Jar Aliu, u bë guvernator i qytetit. Në kohën e tij beu akkojunlu Kara Yülük Osmani mori Erzinxhanin dhe ia bashkoi tokave akkojunlu. Pas kësaj date Erzinxhani u bë vend që ndërronte duar herë mes akkojunlunjve e karakojunlunjve, herë mes shehzadeve akkojunlu.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Themelimi i Hanatit të Kazanit — shkëputja e Ulug Muhamed Hanit nga Orda e Artë", "335a7408"], "d": ["Sipas zërit për Hanatin e Kazanit të TDV-së, Ulug Muhamed Hani, që humbi fronin në Saraj, kryeqytetin e Ordës së Artë, me familjen dhe rreth 3000 ushtarë u tërhoq fillimisht në Belev, më 1437-1438 luftoi me princin rus Vasili II dhe pastaj u vendos në qytetin e Kazanit; me mbështetjen e popullsisë vendase hodhi atje themelet e një hanati të ri. TDV vëren se procesi i themelimit përfundoi ndërmjet viteve 1437-1445 dhe se hanati fitoi status plotësisht të pavarur që nga viti 1445 — harta merr si bazë fillimin e këtij procesi, vitin 1438, kur Ulug Muhamedi u vendos në Kazan.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Themelimi i Hanatit të Krimesë — pavarësimi i Haxhi Girajit nga Orda e Artë", "5728223e"], "d": ["Sipas zërit për Krimenë të TDV-së, Hanati i Krimesë doli si produkt i copëtimit të Ordës së Artë nga luftërat për fron në gjysmën e dytë të shekullit XIV; monedha më e vjetër që preu themeluesi i vërtetë i hanatit, Haxhi Giraj, mban datën 845 (1441-42), dhe kjo konsiderohet data zyrtare e themelimit të hanatit. Po atë vit Haxhi Giraj e përforcoi pozitën e vet në Krime duke lidhur miqësi me Moskën, dhe familjet vendase të bejlerëve, në radhë të parë fisi Shirin, kaluan në anën e tij.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Xhihan Shahu mori Erzinxhanin — sundimi karakojunlu", "0c928cc4"], "d": ["Sundimtari karakojunlu Xhihan Shahu në vitin 854 (1450) dërgoi ushtri në Erzinxhan dhe ua mori qytetin akkojunlunjve. Kjo humbje çoi në përçarjen mes beut akkojunlu Xhihangir Mirza dhe vëllait të tij Hasan Beut (Uzun Hasanit).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Karakojunluja Xhihan Shah shtie në dorë Iranin timurid (Rej, Isfahan, Fars, Kerman)", "c6fbb3f5"], "d": ["Sipas zërit për Karakojunlunjtë të TDV-së, sundimtari karakojunlu Xhihan Shahu, duke përfituar nga luftërat për fron mes shehzadeve timurid, në vitet 856-857 (1452-1453) vuri nën administrimin e vet vilajetet Rej, Isfahan, Fars dhe Kerman; kjo është pika kulmore e procesit të zgjerimit që filloi pas vdekjes së Shahruh Mirzës më 1447 dhe u hap me aneksimin e Sulltanijes-Kazvinit. Kështu tokat timurid në Iranin jugor e qendror u kaluan karakojunlunjve; sundimi i Xhihan Shahut më 1466 do të arrinte një shtrirje që përfshinte Azerbajxhanin, Arranin, Irakun Axhem, Irakun Arab, Farsin, Kermanin dhe Anadollin Lindor.", "3f6a6c37"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Uzun Hasani rimori Erzinxhanin — sërish akkojunlu", "550d010a"], "d": ["Uzun Hasani, duke mundur karakojunlunjtë, e vuri sërish Erzinxhanin nën sundimin akkojunlu. Qyteti mbeti brenda kufijve akkojunlu edhe pas Betejës së Otllukbelit të vitit 1473.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Traktati i Dytë i Thornit — Danzigu (Gdańsk) dhe Prusia Perëndimore iu lidhën Polonisë", "e2152dae"], "d": ["Traktati i Dytë i Thornit (Toruń), që u dha fund Luftërave Trembëdhjetëvjeçare, të filluara më 1454 me kryengritjen e Konfederatës Prusiane kundër sundimit të Kalorësve Teutonë (Teutonic Order), u nënshkrua më 19 tetor 1466; Kalorësit ia lanë Mbretërisë së Polonisë Pomeraninë Lindore me Danzigun (Gdansk), grykëderdhjen e Vistulës me Elbingun (Elbląg) dhe rajonin e Kulmit — këto toka morën emrin 'Prusia Mbretërore'. Ndërsa Prusia Lindore do t'u mbetej Kalorësve deri më 1525.", "831685a9"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["Mbretëresha Katerina Cornaro ia dorëzon Qipron Venedikut — fundi i shtetit kryqtar", "e24d3f3a"], "d": ["Venedikasja Katerina Cornaro, që pas vdekjes së të shoqit, mbretit Jak II, më 1473, e qeverisi Qipron si regjente-mbretëreshë, meqë nuk kishte trashëgimtar, nën presionin e qeverisë venedikase më 26 shkurt 1489 hoqi dorë nga froni dhe ia kaloi doxhit dhe Republikës së Venedikut të drejtat sunduese mbi ishull; si kundërvlerë ruajti titullin e mbretëreshës dhe mori kontenë e Asolos në Terraferma. Me këtë dorëzim mori fund sundimi i dinastisë Lusignan, që vazhdonte që nga viti 1192, dhe shteti i fundit kryqtar, dhe ishulli mbeti nën administrimin venedikas deri në pushtimin osman të viteve 1570-71.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Rënia e Granadës — fundi i shtetit të fundit mysliman në Gadishullin Iberik", "46e5201b"], "d": ["Sundimtari i fundit i Emiratit Nasrid të Granadës, i dobësuar nga një rrethim dhjetëvjeçar me faza dhe nga përçarjet e brendshme, Ebu Abdullahu (Boabdili), sipas kushteve bujare të dorëzimit të nënshkruara në nëntor 1491 (Kapitulacionet e Granadës), më 2 janar 1492 ua dorëzoi çelësat e qytetit mbretërve katolikë Ferdinand dhe Izabelë; pas largimit të Boabdilit nga Alhambra mori fund shteti i fundit mysliman në Gadishullin Iberik dhe u përfundua Reconquista. Po atë vit do të pasonin dëbimi i çifutëve (mars) dhe udhëtimi i Kristofor Kolombit (gusht).", "5dc28ef8"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Shejbani Hani ua merr timuridëve Heratin dhe Horasanin", "a81d8575"], "d": ["Sipas zërit për Shejbani Hanin të TDV-së, sundimtari uzbek Shejbani Hani, pasi ndërmjet viteve 1503-1505 mori Andixhanin, Ferganën, Hisarin, Kunduzin dhe Belhun, në vitin 913 (1507) pushtoi edhe kryeqytetin timurid, Heratin; zëri për Horasanin i Encyclopaedia Iranica jep datën e plotë të këtij pushtimi — qyteti ra më 8 muharrem 913 (20 maj 1507), një javë më vonë, më 15 muharrem (27 maj), hutbeja u lexua në emër të Shejbani Hanit dhe pushtimi u zyrtarizua. I gjithë Horasani, përfshirë Mashhadin, po atë vit kaloi nga timuridët te shejbanidët; kjo nënkuptonte se dinastia timurid, pas Maveraunnehrit, humbi edhe bastionin e fundit të madh në Iran.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Oran bie në duart e Spanjës — fushata e kardinalit Cisneros në Afrikën e Veriut", "86ed8ac1"], "d": ["Orani (Vehran), që kontrollonte rrugën detare të Mesdheut Perëndimor dhe ishte porti i Tlemcenit, ishte rritur me strehimin e myslimanëve dhe çifutëve andaluzianë që ikën nga Granada më 1492. Mbretëria e Kastiljës, që në fillim të shekullit XVI i mori një nga një qytetet portuale të bregdetit të Magrebit, më 17 maj 1509 pushtoi Oranin; pjesa më e madhe e popullit u masakrua, të tjerët u zunë robër dhe në qytet nuk mbeti popullsi myslimane e çifute. Spanjollët i zgjeruan muret dhe kështjellat; Orani mbeti në duart e Spanjës deri më 1708.", "be7b3b1b"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Vendet e Ulëta i lidhen kurorës spanjolle — vdekja e Ferdinandit, hipja në fron e Karlit V", "fbe0dbd2"], "d": ["Me vdekjen e mbretit të Aragonës Ferdinandit II më 23 janar 1516, nipi i tij Karli V, që qysh nga viti 1506 i qeveriste Vendet e Ulëta (Belgjika, Holanda, Luksemburgu i sotëm dhe një pjesë e Francës veriore) si dukë i Burgonjës, u bë trashëgimtar edhe i froneve të Kastiljës dhe Aragonës dhe më 14 mars 1516 u shpall në Bruksel mbret i Spanjës. Kështu këto toka, me anë të bashkimit personal, filluan të konsideroheshin të varura jo nga dega gjermano-austriake e dinastisë habsburge, por drejtpërdrejt nga kurora spanjolle — me zgjedhjen e Karlit V perandor i Perandorisë së Shenjtë Romake më 1519, këto dy identitete (mbret i Spanjës dhe perandor gjermano-romak) do të bashkoheshin në të njëjtin person, ndërsa lidhja e rajonit me Spanjën do të vazhdonte derisa më 1556 Karli V u tërhoq nga froni dhe trashëgiminë ia la të birit, Filipit II.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Sulltanati i Demakut rrëzon Majapahitin dhe sundon bregdetin e Javës", "7da602b5"], "d": ["Sipas zërit për Demakun të TDV-së, Sulltanati i Demakut, shteti i parë i pavarur mysliman i Javës, u themelua në çerekun e fundit të shekullit XV nga Raden Patah; sipas burimeve javaneze, Mbretëria hindu-budiste Majapahit, që po shembej, u zhduk nga sulmet e Demakut. Më 1527 Demaku pushtoi Tubanin, të cilin burimet kineze që nga shekulli XI e përmendin si port të rëndësishëm për sundimtarët e Majapahitit — ky është viti kur edhe mbetjet e fundit të Majapahitit iu lidhën Demakut dhe është pika kthese e procesit të islamizimit të pjesës më të madhe të Javës.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Norvegjia reduktohet në provincë të varur nga kurora daneze", "8e2f274e"], "d": ["Mbreti i Danimarkës Christian III, në kartën e kurorëzimit (håndfæstning) të vitit 1536, shpalli se Norvegjia nuk do të konsiderohej më mbretëri e veçantë, se do të qeverisej si provincë e Danimarkës dhe se Këshilli Shtetëror Norvegjez (riksråd) shfuqizohej; ky vendim u bë i zbatueshëm faktikisht më 1537, kur Rregullorja Kishtare Daneze u shtri edhe në Norvegji, dhe u thye rezistenca e peshkopit norvegjez Olav Engelbriktsson. Edhe pse Norvegjia në praktikë i ruajti për ca kohë ligjet dhe institucionet e veta, statusi i saj politik tani nuk ishte ai i një mbretërie të pavarur, por i një province të varur nga kurora daneze — gjendje që do të vazhdonte deri më 1814.", "a8c9dee7"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Traktati i Vilniusit — u shpërbë Konfederata e Livonisë, Kurlanda dhe Livonia iu lidhën Poloni-Lituanisë (përveç qytetit të Rigës)", "d1ceaad5"], "d": ["Mjeshtri i fundit i madh i Konfederatës së Livonisë, e cila u shpërbë nën presionin rus gjatë Luftës së Livonisë, Gotthard Kettler, me traktatin e nënshkruar në Vilnius më 28 nëntor 1561 (Pacta Subiectionis) hyri nën mbrojtjen e Dukës së Madh të Lituanisë dhe mbretit të Polonisë Zygmunt II August; pjesa më e madhe e Livonisë, përveç qytetit të Rigës, iu lidh Poloni-Lituanisë, ndërsa Kettleri u bë duka i parë i Dukatit të Kurlandës. Ky ishte akti i fundit i Urdhrit të Kalorësve të Livonisë në kalimin nga Mesjeta te Koha e Re.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Akti i Heqjes Dorë (Plakkaat van Verlatinghe) — Holanda shpalli pavarësinë nga Spanja", "a632aaee"], "d": ["Ndërsa vazhdonin Luftërat Tetëdhjetëvjeçare, Kuvendi i Përgjithshëm (Staten-Generaal) i provincave holandeze të Bashkimit të Utrehtit, me Aktin e Heqjes Dorë të miratuar më 26 korrik 1581, e shpalli mbretin e Spanjës Filipin II 'tiran' dhe refuzoi besnikërinë ndaj tij; ky dokument konsiderohet faktikisht deklarata themeluese e Provincave të Bashkuara të pavarura (Republikës Holandeze). Njohja përfundimtare nga Spanja do të priste Vestfalinë e vitit 1648, por shkëputja faktike është kjo ditë.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Smolensku bie në duart e Poloni-Lituanisë — fundi i rrethimit 20-mujor", "4e9678e3"], "d": ["Gjatë Kohës së Trazirave (Smuta), ushtria e mbretit të Polonisë Zygmunt III, më 13 qershor 1611, duke shpërthyer një minë, hapi çarje në muret e Smolenskut, që e rrethonte që nga shtatori 1609, dhe e shtiu në dorë qytetin; rezistenca 20-mujore mori fund. Smolensku mbeti te Poloni-Lituania deri më 1654, dhe kjo rënie përgatiti terrenin për Armëpushimin e Deulinos (1618), që do të nënshkruhej shtatë vjet më vonë.", "25d6488d"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Traktati i Stolbovës — Rusia humbi bregdetin baltik (Ingrinë) në favor të Suedisë", "175dc175"], "d": ["Traktati i Stolbovës, që i dha fund Luftës së Ingrisë, u nënshkrua më 27 shkurt 1617 në fshatin Stolbova në jug të liqenit Ladoga; Rusia rimori Novgorodin dhe toka të tjera në veri, ndërsa Suedia mbajti Karelinë dhe Ingrinë (mes Estonisë dhe Finlandës, përfshirë kështjellat Ivangorod-Jam-Koporje-Oreshek), dhe Rusisë iu pre dalja e drejtpërdrejtë në Baltik. Kjo ndërprerje do të zgjaste deri kur Pjetri i Madh më 1703 themeloi Shën Petersburgun në të njëjtin rajon.", "7e70e3e6"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Armëpushimi i Deulinos — Smolensku, Çernigovi dhe Novgorod-Severski iu lanë Polonisë", "6880d2c1"], "d": ["Armëpushimi i Deulinos, që i dha fund luftës polako-ruse 1609-1618, u nënshkrua më 11 dhjetor 1618 dhe siguroi një armëpushim 14,5-vjeçar; Rusia u detyrua t'i linte Bashkimit Poloni-Lituani Smolenskun (përveç Vjazmës) dhe 29 qytete në rajonet e Çernigovit dhe Novgorod-Severskit — kjo ishte humbja territoriale më e rëndë e Kohës së Trazirave (Smuta). Rajoni do të mbetej te Polonia deri në Armëpushimin e Andrusovos të vitit 1667.", "5c52de5a"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Rada e Perejasllavit — kozakët e Zaporozhjes i bënë betimin e besnikërisë carit rus", "bcd8f8ef"], "d": ["Hetmani i kozakëve të Zaporozhjes, Bohdan Hmelnicki, që nga viti 1648 në kryengritje kundër Poloni-Lituanisë, në Radën e Perejasllavit të 18 janarit 1654 (8 janar julian), ku mori pjesë delegacioni nga Moska i kryesuar nga Vasili Buturlin, i bëri betimin e besnikërisë carit Aleksej Mihajloviç I; kjo konsiderohet fillimi i hyrjes së Hetmanatit Kozak të Ukrainës nën mbrojtjen ruse dhe e zhvendosi kontrollin faktik të rajonit Çernigov-Seversk nga Polonia te Rusia — ndërsa kufiri zyrtar do të vizatohej me Armëpushimin e Andrusovos të vitit 1667.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Rimarrja e Smolenskut nga Rusia", "bf0eca92"], "d": ["Gjatë luftës polako-ruse që filloi më 1654, ushtria ruse e rimori më 3 tetor 1654 Smolenskun, që e rrethonte që nga korriku, me dorëzimin e garnizonit polak; qyteti i humbur në favor të Polonisë më 1611 iu kthye Rusisë 43 vjet më vonë. Ky ishte një nga hapat më të rëndësishëm të procesit të përmbysjes së humbjeve të Kohës së Trazirave të Rusisë dhe u bë i qëndrueshëm me Armëpushimin e Andrusovos të vitit 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Armëpushimi i Andrusovos — Kievi dhe Ukraina e bregut të majtë i kaluan Rusisë", "799be067"], "d": ["Armëpushimi i Andrusovos, që i dha fund luftës polako-ruse 1654-1667, siguroi një armëpushim 13,5-vjeçar; Rusia fitoi Smolenskun, rajonin Çernigov-Seversk dhe Ukrainën në bregun e majtë të Dnieprit, si edhe — fillimisht për dy vjet, faktikisht përgjithmonë — qytetin e Kievit. Ky traktat vuri bazën juridike të ndarjes së tokave ukrainase përgjatë Dnieprit mes Polonisë dhe Rusisë (dhe të mbetjes së Kievit te Rusia).", "94445e3a"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Themelimi i Shën Petersburgut — dritarja e Rusisë drejt Perëndimit", "ba196be0"], "d": ["Në Ishullin e Lepurit në deltën e Nevës, të sapormarrë nga Suedia gjatë Luftës së Madhe Veriore, Pjetri i Madh më 16/27 maj 1703 hodhi themelet e kështjellës Petropavllovsk (Kështjella Pjetër-Pal); kjo ditë pranohet si data e themelimit të qytetit të Shën Petersburgut. Pjetri e projektoi deltën moçalore si 'dritare' drejt Perëndimit, dhe më 1712 qyteti u bë kryeqyteti i ri i Rusisë — rajoni do t'i lidhej zyrtarisht Rusisë me Traktatin e Nystadit të vitit 1721.", "24c24aaf"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Traktati i Rastattit — mori fund Lufta për Trashëgiminë Spanjolle, Holanda Spanjolle dhe Milano i kaluan Austrisë", "3c0e086f"], "d": ["Traktati i Rastattit, që i dha fund Luftës për Trashëgiminë Spanjolle mes Francës dhe Austrisë, u nënshkrua më 7 mars 1714 (Utrehti më 1713 kishte rregulluar marrëdhëniet mes Anglisë dhe Francës); me traktat, Habsburgët e Austrisë morën Holandën Spanjolle (Belgjikën e sotme) dhe në Itali Napolin, Milanon dhe Sardenjën. Ky ishte zgjerimi territorial më i gjerë në historinë e Austrisë dhe i shtoi peshës së dinastisë habsburge në Evropën Qendrore një front të ri në Evropën Perëndimore dhe Jugore.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Traktati i Nystadit — mori fund Lufta e Madhe Veriore, brigjet baltike i kaluan Rusisë", "068ffd06"], "d": ["Traktati i Nystadit, që i dha fund Luftës së Madhe Veriore 21-vjeçare, u nënshkrua në Finlandë më 10 shtator 1721 (30 gusht julian); Suedia ia la Rusisë Estoninë, Livoninë (përfshirë Rigën), Ingermanlandin dhe një pjesë të Finlandës juglindore (Karelisë), ndërsa si kundërvlerë mori mbrapsht pjesën tjetër të Finlandës dhe u pagua dëmshpërblim. Traktati konsiderohet regjistrimi zyrtar i fundit të statusit të Suedisë si fuqi e madhe dhe i ngritjes së Rusisë si perandori evropiane — Pjetri I pas kësaj fitoreje mori titullin 'Perandor'.", "f0c4fc4a"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Ndarja e Dytë e Polonisë — humbje tokash në favor të Rusisë dhe Prusisë", "31750484"], "d": ["Meqë reformat kushtetuese të vitit 1791 shqetësuan Rusinë dhe Prusinë, të dy shtetet, me traktatin e nënshkruar më 23 janar 1793 në Shën Petersburg, e ndanë sërish Poloninë: Rusia mori pjesën më të madhe të Lituanisë-Bjellorusisë dhe Ukrainën Perëndimore (përfshirë Kamenicën, Barin, Minskun), ndërsa Prusia aneksoi Poloninë e Madhe me Gdanskun dhe Poznanin — gjithsej 307.000 km². Sejmi polak nën presion u detyrua ta ratifikonte traktatin po atë vit; ishte një ndarje jetëshkurtër që e shtyu për dy vjet aneksimin e plotë të Polonisë. Në këtë ditë (23 janar 1793), me Ndarjen e Dytë të Polonisë, Ukraina e bregut të djathtë, përfshirë Berdiçevin, Fastovin, Zhitomirin, Kanivin, Kostantinovin, Umanin dhe Çerkasin, i kaloi Rusisë.", "656e71c2"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Traktati i Campo Formios — ndarja e Venedikut mes Austrisë dhe Francës", "9f29678c"], "d": ["Traktati i Campo Formios, i nënshkruar më 17 tetor 1797 mes Napoleon Bonapartit dhe përfaqësuesit austriak kontit Cobenzl, e zhduku zyrtarisht Republikën mijëvjeçare të Venedikut dhe ndau tokat e saj: viset në lindje të lumit Adige, bregdeti i Istrisë dhe Dalmacisë (përfshirë Splitin, Zarën, Shibenikun, Kotorrin) iu lanë Austrisë, ndërsa Ishujt Jonianë (përfshirë Korfuzin, Qefalonin, Zakintosin, Lefkadën, Prevezën dhe Pargën, bazat venedikase në bregdetin shqiptaro-peloponezian) i kaluan Francës. Austria gjithashtu ia la Francës tokat e veta në Vendet e Ulëta (Belgjika e sotme).", "296ee82f"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Traktati i Amiensit — Menorka iu kthye Spanjës", "f341e4b8"], "d": ["Traktati i Amiensit (25 mars 1802), i nënshkruar mes Francës, Spanjës, Holandës dhe Anglisë, i dha fund përkohësisht Luftës së Koalicionit të Dytë; Anglia ktheu pothuajse të gjitha tokat që kishte shtënë në dorë gjatë luftës (përveç Ceylonit dhe Trinidadit) — njëra prej tyre ishte Menorka, marrë nga Spanja më 1798. Paqja zgjati vetëm një vit, lufta shpërtheu sërish në maj 1803, por pas këtij traktati Menorka nuk kaloi më kurrë në duart angleze.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Traktati i Fredrikshamnit (Haminës) — Suedia ia lë Finlandën Rusisë", "c0d407bc"], "d": ["Traktati i Fredrikshamnit (Hamina e sotme), që i dha fund luftës ruso-suedeze 1808-1809, u nënshkrua më 17 shtator 1809; Suedia ia la Rusisë të gjithë Finlandën, përfshirë Ishujt Åland. Finlanda fitoi statusin e Dukatit të Madh me autonomi të gjerë brenda Perandorisë Ruse dhe e ruajti besimin luteran e të drejtën suedeze. Kjo nënkuptonte fundin de facto të statusit të Suedisë si fuqi e madhe në Baltik. Me këtë traktat, gjashtë provincat e Finlandës dhe Västerbotteni deri te lumi Torne (Kokkola, Joensuu, Savonlinna, Tornio, Rovaniemi, Inari etj.) i kaluan Dukatit të Madh të Finlandës të varur nga Rusia.", "fb46c9a1"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Traktati i Kielit — Danimarka ia lë Norvegjinë Suedisë", "59ab1601"], "d": ["Pas disfatës së Napoleonit në Leipzig, Suedia, që sulmoi Danimarkën nga jugu, me Traktatin e Kielit të nënshkruar më 14 janar 1814 mori Norvegjinë (përveç Islandës, Ishujve Faroe dhe Grenlandës) — kështu mori fund zyrtarisht bashkimi dano-norvegjez që vazhdonte që nga viti 1380. Si kompensim, Suedia ia la Danimarkës tokat e veta në Pomerani; Danimarka gjithashtu ia kaloi Helgolandin Anglisë. Norvegjia i rezistoi traktatit me armë dhe shpalli kushtetutën e vet, dhe Suedia u detyrua ta njihte — rezultati ishte një bashkim personal (real union) që do të zgjaste deri më 1905. Suedia nuk mundi ta merrte faktikisht Norvegjinë: traktati nuk u pranua në Norvegji dhe administrimi mbeti te Christian Frederik; ushtria suedeze hyri në Norvegji vetëm më 26 korrik 1814.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Akti Përfundimtar i Kongresit të Vjenës — harta e Evropës pas Napoleonit u vizatua rishtas", "fca1c676"], "d": ["Akti Përfundimtar i Kongresit të Vjenës, i nënshkruar mes fuqive të mëdha (Austri, Rusi, Prusi, Angli, Francë) që i dhanë fund Luftërave Napoleonike, u miratua më 9 qershor 1815 (9 ditë para Waterloos) dhe e rivizatoi njëherësh hartën e kontinentit: ish-Holanda Spanjolle/Austriake dhe Provincat e Bashkuara u bashkuan nën 'Mbretërinë e Bashkuar të Holandës', Republika e Gjenovës iu bashkua Mbretërisë së Sardenjë-Piemontit, pjesa më e madhe e Dukatit të Varshavës me emrin 'Polonia e Kongresit' iu lidh Rusisë dhe Pomerania Suedeze (Stralsundi) i kaloi Prusisë. Kjo ditë e vetme konsiderohet fillimi zyrtar i ekuilibrit evropian të pasluftës (Concert of Europe). Me këtë akt, Łódź, Częstochowa, Kielce, Radom, Lublin, Chełm dhe Zamość (Dukati i Varshavës) i kaluan Mbretërisë së Polonisë të varur nga Rusia, Poznani (Dukati i Madh i Posenit) Prusisë, ndërsa Mastrihti dhe Roermondi Mbretërisë së Holandës.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Traktati i Përgjithshëm Detar — Kavasimi dhe sheikatet e tjera të Gjirit u lidhën me traktat me Anglinë", "fc499e19"], "d": ["Anglia, pasi më 1819 bombardoi Ras el-Hajmën dhe shpërndau flotën 'pirate' të Kavasimit, imponoi Traktatin e Përgjithshëm Detar, që filloi më 8 janar 1820, u nënshkrua veçmas me sheikatet e rajonit dhe u plotësua deri në mars; traktati ndaloi piraterinë dhe skllavërinë dhe i detyroi anijet të mbanin një flamur kuq e bardhë të ngjashëm me atë anglez. Me këtë traktat, 'Bregdeti i Piratëve' me kohë u shndërrua në 'Bregdeti i Armëpushimit' (Trucial Coast); ishte fillimi i një marrëdhënieje të hegjemonisë angleze, të thelluar me armëpushimin e përhershëm detar të vitit 1853 dhe traktatet ekskluzive të vitit 1892, që do të zgjaste deri më 1971.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Fundi i rrethimit të Gaetës — shembja e Mbretërisë së Dy Siqelive", "121ae580"], "d": ["Pas shembjes që filloi me zbarkimin e Garibaldit në Siqeli në maj 1860, mbreti burbon Françesku II, që iku nga Napoli, u rrethua që nga 3 nëntori 1860 në kështjellën e tij të fundit, Gaetën; me tërheqjen e flotës franceze nga zona në janar 1861, bllokada detare italiane u shtrëngua dhe më 13 shkurt 1861 Gaeta u dorëzua. Françesku II la fronin dhe shkoi në mërgim; pika e fundit e rezistencës së Mbretërisë së Dy Siqelive, Civitella del Tronto, do të binte vetëm më 20 mars 1861. Me shembjen e mbretërisë, tokat në Siqeli (Palermo, Mesina, Sirakuza, Trapani, Misilmeri) dhe në Kampani (përfshirë Nolën) nuk ishin më nën administrimin burbon.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Shpallja e Mbretërisë së Italisë — bashkimi i Sardenjës, Toskanës dhe Italisë jugore", "12e52f70"], "d": ["Në mbledhjen e parë të parlamentit italian në Torino, më 17 mars 1861, u shpall zyrtarisht Mbretëria e Italisë dhe mbreti i Sardenjë-Piemontit, Viktor Emanueli II, u bë mbreti i parë i Italisë së bashkuar. Mbretëria e re bashkonte me Mbretërinë e Sardenjës tokat e Toskanës, Emilia-Romanjës, Napolit dhe Siqelisë (Dy Siqelitë), që u bashkuan me plebishcite vitin e mëparshëm; Roma (Shteti Papnor) dhe Venediku (Austria) ende mbeteshin jashtë — ata do të bashkoheshin përkatësisht më 1870 dhe 1866.", "d044a9c0"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Britania vendos protektorat në bregdetin verior somalez — fillimi i Somalilandit", "f301ea94"], "d": ["Sipas zërit për Somalinë të TDV-së, Zejla, Berbera dhe Taxhura më 1884 u kolonizuan nga anglezët me emrin Somaliland; sipas burimit standard akademik, ky proces filloi në Berbera me traktatin e nënshkruar me fisin Habar Avel, që përkon me 21 ramazan 1301 (14 korrik 1884), dhe u zgjerua ndërmjet viteve 1884-1886 me traktate të ngjashme të nënshkruara me fiset Gadabursi, Habar Tolcaala, Habar Gerhacis, Ise dhe Warsangeli; si kundërvlerë, Anglia premtoi mbrojtje ushtarake. Ky zinxhir traktatesh përgatiti terrenin për shpalljen zyrtare të Protektoratit Britanik të Somalilandit më 1887.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Beteja e Mulejdasë — fundi i Shtetit të Dytë Saudit, Nexhdi u kalon rashididëve", "1cd3b213"], "d": ["Pas përkeqësimit të marrëdhënieve për shkak të mosmarrëveshjes për zekatin dhe arrestimit të një të dërguari rashidid, ushtria e emirit të Xhebel Shammarit, Muhamed bin Reshid, më 21 janar 1891 në Mulejda, në rajonin e Kasimit, u shkaktoi një disfatë të rëndë forcave saudite të udhëhequra nga Abdurrahman bin Fejsal dhe aleatëve të tyre; kjo ishte fundi faktik i Shtetit të Dytë Saudit, familja Al Saud shkoi në internim në Kuvajt dhe i gjithë Nexhdi hyri nën sundimin rashidid; në të përfshiheshin edhe viset e Dilemit (Harc), Haves (Havtat Beni Temim) dhe Lejlës (Aflaxh) në jug. Sundimi do të vazhdonte deri kur Abdylazizi i ri bin Saud rimori Riadin më 1902 (Sulmi i Riadit, 16 janar 1902).", "b77d8161"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Somalia Italiane kalon në administrim të drejtpërdrejtë shtetëror — likuidimi i Kompanisë së Benadirit", "8c7d085b"], "d": ["Sipas zërit për Somalinë të TDV-së, Italia e kishte vendosur sundimin në bregdetin jugor somalez (Benadir) me marrëveshjet e viteve 1889-1891 me Sulltanatin e Zanzibarit dhe Anglinë, ndërsa administrimin fillimisht ia kishte lënë një kompanie tregtare me privilegj (Benadir Company); sipas burimit standard akademik, privilegji i kësaj kompanie mori fund më 24 janar 1905 dhe shteti italian, duke blerë sovranitetin e drejtpërdrejtë mbi bregdetin e Benadirit (përfshirë Mogadishun, Merkan, Baraven), vendosi administratën zyrtare koloniale. Zgjerimi faktik i kolonisë drejt brendësisë (Bardera, Baidoa) do të përfundonte me dekretin themelues të vitit 1908 dhe në vitet pasuese.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Shpërbërja e Bashkimit Norvegji-Suedi — shpallja e njëanshme e pavarësisë nga Storting-u", "aaba2935"], "d": ["Kur mbreti Oskar II vuri veton ndaj kërkesës së qeverisë norvegjeze për të themeluar konsullata të veçanta dhe deklaroi se nuk mund të formonte qeveri të re, Storting-u (parlamenti) norvegjez më 7 qershor 1905 vendosi njëzëri se mbreti faktikisht nuk e ushtronte më detyrën si mbret i Norvegjisë dhe se bashkimi që vazhdonte që nga Traktati i Kielit i vitit 1814 ishte i shpërbërë. Në plebishcitin e 13 gushtit 1905 pothuajse të gjithë zgjedhësit (184 vota kundër 371.000-ve) e miratuan shpërbërjen; Suedia, pas bisedimeve të Karlstadit, më 26 tetor 1905 e njohu zyrtarisht pavarësinë.", "94eda38c"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Prerja e akçes së parë osmane", "38d2d638"], "d": ["Akçeja e parë prej argjendi, e prerë në emër të Orhan Gaziut, është shpallja monetare e sovranitetit të pavarur të bejlikut; akçeja mbeti për pesë shekuj njësia themelore e parasë.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["U krijua Bejlerbejllëku i Rumelisë", "ffa16089"], "d": ["Pushtimet në anën evropiane u mblodhën nën një çati të vetme ushtarako-administrative; sistemi i bejlerbejllëkut u bë shtylla kurrizore e organizimit provincial të perandorisë.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Martesa Bajazidi Jëlldërëm – Despina Hatun", "4b10dc6c"], "d": ["Vasaliteti i vendosur me despotatin serb pas Kosovës u vulos me martesën e Oliverës, së bijës së Llazarit, me Bajazidin — shembull tipik i diplomacisë martesore të periudhës së hershme.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["U krijua Bejlerbejllëku i Anadollit", "5ef8d3a7"], "d": ["Për administrimin e tokave të bejliqeve të aneksuara u organizua Bejlerbejllëku i Anadollit; u plotësua sistemi dykrahësh Rumeli-Anadoll i administrimit.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["U përfundua Xhamia e Madhe (Ulu) e Bursës", "27bcc4a5"], "d": ["Xhamia e madhe me njëzet kupola, e ndërtuar me plaçkën e Nikopojës, është shembulli monumental i arkitekturës së hershme osmane dhe muze i hapur i artit të kaligrafisë.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Shkarkimi dhe ekzekutimi i Çandarli Halil Pashës", "5e19438f"], "d": ["Pas pushtimit, veziri i madh nga familja e vjetër Çandarli, që kishte qëndruar me rezervë ndaj rrethimit, u ekzekutua; për herë të parë një vezir i madh vritej me urdhër të padishahut dhe hapej epoka e vezirëve me origjinë devshirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Moldavia bëhet haraçpaguese", "25bd3693"], "d": ["Vojvodati i Moldavisë pranoi të paguante haraç; së bashku me Vllahinë dhe Transilvaninë, brezi i trefishtë vasal në veri të Danubit u bë zona tampon veriore e perandorisë. Vende të tjera që u bashkuan në të njëjtën datë: Jashi.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Haraçi i Dubrovnikut (Raguzës)", "d127c78a"], "d": ["Republika tregtare e Raguzës, në këmbim të haraçit, siguroi autonominë dhe privilegjet tregtare; si dritare osmane në Adriatik u pasurua. Ishulli Mljet (Mliyet), tokë e republikës, e ndau gjithashtu këtë status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Fushata në Vllahi: Vojvoda Shpuesi (Kazıklı)", "fd4530bb"], "d": ["Me fushatën kundër Vlad Tepeshit, i cili refuzoi të paguante haraç dhe vrau ambasadorët, Vllahia u kthye në vasalitet; skenat e sulmit të natës dhe të tmerrit të hunjve u bënë legjendë në Evropë. Vende të tjera që u bashkuan në të njëjtën datë: Bukureshti.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["U hap Kompleksi i Fatihut", "a150ea55"], "d": ["Me tetë medresetë e tij (Sahn-i Seman), kompleksi ishte hapi i parë i madh i programit për ta shndërruar Stambollin në qendër të dijes së botës islame.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kushçiu në Stamboll", "8508229d"], "d": ["Ali Kushçiu, përfaqësuesi i fundit i madh i observatorit të Samarkandit, me ftesë të Fatihut u bë profesor (myderriz) në Medresenë e Ajasofjes; krijoi në Stamboll traditën e matematikës dhe të astronomisë.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunameja e Fatihut", "b08944c9"], "d": ["Kanunameja e parë gjithëpërfshirëse e së drejtës zakonore, që mblodhi organizimin shtetëror, protokollin dhe dënimet; diskutohet ende për nenin e njohur që lejonte vëllavrasjen 'për rendin e botës'.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["U pre ari i parë osman (sulltani)", "2fd5c0dd"], "d": ["U pre monedha e parë e artë osmane, e barasvlershme me dukatin venedikas; financat e perandorisë u bashkuan me rendin monetar ndërkombëtar.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Kalimi në Sarajin Topkapë", "b9cd6a5e"], "d": ["Me përfundimin e Sarajit të Ri (Topkapë), qendra e qeverisjes së shtetit u zhvendos këtu; saraji mbeti për katër shekuj truri i perandorisë.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Republika e Firences u shndërrua në dukat — Alessandro de' Medici", "c08764e1"], "d": ["Nën presionin e Papës Klement VII, komisioni drejtues i Firences (Balìa) miratoi një kushtetutë të re; regjimi republikan pesëshekullor u hoq, Alessandro de' Medici u shpall duk i trashëgueshëm dhe më 1 maj hipi de fakto në fron. Kështu Firenzja nga republikë qytetare e pavarur u shndërrua në dukat të trashëgueshëm të dinastisë Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Kurora Kanuni – Hyrrem Sulltan", "abc05f26"], "d": ["Lidhja zyrtare e kurorës së Kanuniut me Hyrremin e ndryshoi rrënjësisht traditën e sarajit; lindi institucioni i 'Haseki Sulltanes' dhe u hap dera e epokës së grave në politikën dinastike.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Kapitulacionet e para gjithëpërfshirëse për Francën", "e2264e48"], "d": ["Si pjesë e aleancës me Francën kundër darës habsburge, midis Jean de la Forest-it dhe Makbul Ibrahim Pashës u nënshkruan privilegje tregtare; kapitulacionet, atëherë mjet diplomatik, brenda shekujsh do të bëheshin dera e varësisë financiare.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Fushata në Oqeanin Indian: rrethimi i Diut", "fcd1217a"], "d": ["Flota që u nis nga Suezi kaloi Detin e Kuq dhe rrethoi Diun në Gujarat; ndonëse kalaja nuk u mor, fuqia osmane për herë të parë u shtri në Oqeanin Indian dhe monopoli portugez u trondit.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Udhëtimi indian i Sejdi Ali Reisit", "e5da3b2c"], "d": ["Sejdi Ali Reisi, i ngarkuar të sillte në Egjipt flotën në Basra, u shty nga stuhitë drejt Indisë; Mirat el-Memalik, ku tregon aventurën e kthimit, është nga librat e parë osmanë të udhëtimeve.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Ekzekutimi i Piri Reisit", "63026444"], "d": ["Detari dhe hartografi i madh, i cili u kthye nga fushata e Hormuzit duke e lënë flotën në Basra, u ekzekutua në moshën 84 vjeç — një nga vendimet më të diskutuara në historinë tonë të shkencës.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["U hap Kompleksi Sulejmanije", "1c6458b2"], "d": ["Kompleksi që Mimar Sinani e quajti 'vepra e kalfës sime'; me medresetë, spitalin (darushifa) dhe bibliotekën e tij u bë kompleksi më i madh arsimor-bamirës i periudhës klasike.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Rrethimi i Maltës", "f57f6a85"], "d": ["Malta, kyçi i Mesdheut, u rrethua për katër muaj; Turgut Reisi ra shehid dhe rrethimi u hoq. Ishte hapi i parë i madh prapa i detarisë së periudhës së Kanuniut.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["U përfundua Xhamia Selimije", "3b0484e1"], "d": ["Selimija, që Sinani e quajti 'vepra e mjeshtërisë sime' dhe ku një kupolë e vetme sundon hapësirën, konsiderohet kulmi i arkitekturës klasike osmane (Trashëgimi Botërore e UNESCO-s).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["U themelua Observatori i Stambollit", "169bdf5d"], "d": ["Observatori i Takijyddinit, një nga observatorët më të pajisur të kohës, u shemb në vitin 1580 për shkak të debateve që lindën pas kometës së vitit 1577; astronomia institucionale u vonua tre shekuj.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Fitorja e Çëlldërit — filloi lufta lindore", "13125a54"], "d": ["Me disfatën e ushtrisë safavide në Çëlldër u hapën dyert e Kaukazit; u mor Tbilisi dhe Gjeorgjia hyri nën sundimin osman.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Beteja e Pishtarëve — Shirvani përfundimisht te Osmanët", "3bbc23bc"], "d": ["Në betejën që njihet me këtë emër sepse vazhdoi edhe natën në dritën e pishtarëve, safavidët u mundën përfundimisht; sundimi osman në Shirvan dhe Baku u përforcua.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Zhvlerësimi i madh i monedhës — kriza e akçes", "9205c3d4"], "d": ["Nën presionin e luftërave të gjata dhe të argjendit amerikan, përmbajtja e argjendit në akçe u përgjysmua; revolucioni i çmimeve ushqeu shpërbërjen e rendit të spahinjve dhe trazirat xhelali.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Pushtimi i Tebrizit", "6506bdb9"], "d": ["Serdari Ozdemiroglu Osman Pasha hyri në Tebriz; kryeqyteti i dikurshëm i safavidëve u mor nën administrimin osman. Osman Pasha vdiq pas pak javësh në kamp.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Traktati i Ferhad Pashës — kufijtë më të gjerë në lindje", "c429972f"], "d": ["Me traktatin e lidhur pas ardhjes së ambasadorit të Shah Abasit, Hajdar Mirzës, në Stamboll (18 janar 1590), me kushtin që vendet e pushtuara t'u mbeteshin Osmanëve, dhe që i dha fund luftës 12-vjeçare, Tebrizi, Karabaku, Shirvani, Gjeorgjia dhe Lorestani mbetën te Osmanët; perandoria arriti në lindje kufijtë më të gjerë të historisë së saj.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Filloi lufta osmano-safavide (1603-1612) — kundërofensiva e Shah Abasit, humbja e Tebrizit", "abf27dd8"], "d": ["Shah Abasi, që e riorganizoi ushtrinë e tij, përfitoi nga trazirat xhelali dhe kaloi në ofensivë; ra Tebrizi, kurse fitimet në Kaukaz u humbën brenda pak vjetësh. Vendbanime të tjera që u humbën në të njëjtën fushatë dhe më pas: Nahçevan, Hoj, Marand, Salmas; edhe bejlerët e Karaxhadagut (Ahar) dhe të Mukrive kaluan në anën safavide.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Lindi Evlija Çelebiu", "2b6051ff"], "d": ["Evlija Çelebiu, që udhëtimet e tij më shumë se pesëdhjetëvjeçare i mblodhi në Sejahatname me dhjetë vëllime, la një panoramë të paparë të botës osmane të shekullit XVII.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Traktati i Nasuh Pashës", "bb69e388"], "d": ["Me traktatin që i dha fund luftës që vazhdonte nga viti 1603, u hoq dorë nga fitimet e vitit 1590 dhe u kthye te kufiri i Amasjas i vitit 1555; ekuilibri në frontin lindor u rivendos.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["U hap Xhamia Sulltan Ahmed", "e39dfd43"], "d": ["'Xhamia Blu', me gjashtë minaret dhe pllakat blu të Iznikut, është kompleksi i fundit i madh sulltanor i periudhës klasike.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Vrasja e Sulltan Ibrahimit", "bc4eb452"], "d": ["Aleanca odxhak-ulema, me arsyetimin e shpërdorimit dhe të krizës së qeverisjes, e rrëzoi Ibrahimin nga froni; dhjetë ditë më vonë, me fetva, u mbyt me litar. Në fron hipi shtatëvjeçari Mehmeti IV; pushteti de fakto kaloi në duart e nënës së madhe të sulltanit, Kosem Sulltan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Vdekja e Qatib Çelebiut", "e167e89d"], "d": ["Me bibliografinë Keshf el-Zunun dhe gjeografinë Xhihannyma, ai është një nga emrat më të shquar të historisë së dijes osmane; njihet për qasjen pioniere që përdorte burime evropiane.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Ngjarja e Edrenesë — rrëzimi i Mustafait II", "0291c1cd"], "d": ["Zemërimi për qëndrimin e padishahut në Edrene dhe për ndikimin e Fejzullah Efendiut u shndërrua në një kryengritje të madhe të ushtrisë dhe të esnafëve; shejhulislami u linçua, padishahu u rrëzua nga froni dhe saraji u kthye në Stamboll.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambasador në Paris: Jirmisekiz Mehmed Çelebiu", "26312a3f"], "d": ["Ambasada e madhe e dërguar në Francë u bë vëzhgimi i parë sistematik që studioi Perëndimin në vend; Sefaretnameja e tij frymëzoi ripërtëritjen e Epokës së Tulipanëve.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["U themelua shtypshkronja e parë osmane", "4943f7e5"], "d": ["U dha leja për shtypjen e librave turqisht; vepra e parë, Fjalori i Vankulut, u botua në vitin 1729. Shtypshkronja është trashëgimia më e qëndrueshme e ripërtëritjes së Epokës së Tulipanëve.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitulacionet u bënë të përhershme", "d044a79e"], "d": ["Privilegjet e dhëna Francës pushuan së qeni të kufizuara me jetën e padishahut dhe u lidhën me një traktat të përhershëm; regjimi i kapitulacioneve, i shndërruar në diçka që nuk mund të prishej në mënyrë të njëanshme, mundi të hiqej vetëm në Lozanë.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["U themelua Shkolla e Inxhinierisë Detare Perandorake", "9bf3f439"], "d": ["Shkolla e inxhinierisë, e themeluar pas katastrofës së Çeshmes për të përgatitur oficerë modernë të marinës, është institucioni i parë i përhershëm i arsimit teknik të stilit perëndimor; shkolla e inxhinierisë tokësore pasoi në vitin 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Ambasada e parë e përhershme në Londër", "6b5630eb"], "d": ["Si pjesë e programit Nizam-i Xhedid, në kryeqytetet evropiane u hapën ambasada të përhershme; diplomacia osmane kaloi te parimi i reciprocitetit.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Vdekja e Alemdar Mustafa Pashës", "4426534e"], "d": ["Veziri i madh reformator, i rrethuar në Portën e Lartë gjatë kryengritjes së jeniçerëve që filloi natën e 15 nëntorit 1808, kur nuk i erdhi ndihma e pritur, të nesërmen i vuri flakën depos së municionit dhe vdiq së bashku me qindra sulmues; bashkë me të u varrosën rendi i Sened-i Ittifakut dhe përpjekja e parë reformuese.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Gazeta e parë zyrtare: Takvim-i Vekai", "c637f623"], "d": ["Filloi të botohej gazeta zyrtare e shtetit; është fillimi i opinionit publik modern dhe i traditës së njoftimit zyrtar.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Traktati Tregtar i Balta Limanit", "e790b383"], "d": ["Anglisë iu njoh pozita më e privilegjuar edhe në tregtinë e brendshme, u hoq sistemi i monopolit (yed-i vahit); prodhimi vendas mbeti pa mbrojtje, ndërsa traktati u bë dokumenti i hapjes së plotë të tregut osman ndaj tregtisë së lirë.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fundi i Emiratit të Libanit — shkarkimi i Bashirit III Shihab", "f85ae454"], "d": ["Emiri Bashir II (III), që nuk arriti të kontrollonte grindjen kristiano-druze dhe ekuilibrat e brendshëm të krahinës së Shufit, u shkarkua në janar 1842; rendi i emiratit vendor që vazhdonte nga viti 1516 (përmes Ma'nogllutëve e më pas Shihabogllutëve) mori fund dhe krahina kaloi nën administrimin e drejtpërdrejtë osman, më pas në sistemin e dy kajmekamëve.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Korrigjimi i monedhës: sistemi i Mexhidijes", "c77be809"], "d": ["Me reformën monetare, monedhat me titër të prishur u tërhoqën nga qarkullimi; u vendos një sistem i qëndrueshëm bimetalik i mbështetur te lira e artë (Mexhidije).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fundi i sundimit vendor të familjes Harfush në Baalbek", "8438f4ae"], "d": ["Ndikimi i familjes Harfush, që nga viti 1521 (pas kryengritjes së Xhanbirdi Gazaliut) sundonte si dinasti e vogël vendore në Baalbek, mori fund me rregullimin e ri administrativ të Portës së Lartë; qyteti u bë një qendër e zakonshme kazaje në varësi të vilajetit të Damaskut.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["U themelua Shirket-i Hajrije", "462830e7"], "d": ["Kompania e krijuar për të shfrytëzuar vaporë në Bosfor konsiderohet shoqëria e parë aksionare osmane; skelat e vaporëve i vunë vulën jetës së qytetit.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Kontrata e parë e huasë së jashtme", "9017c579"], "d": ["Për financimin e Luftës së Krimesë, nga tregu i Londrës u mor huaja e parë e jashtme; pas 15 huamarrjesh në 21 vjet, pika ku u arrit ishte moratoriumi i vitit 1875 dhe Dyjun-i Umumije.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Linja telegrafike në Stamboll", "d320f39f"], "d": ["Linja e parë telegrafike, e ndërtuar për nevojat e Luftës së Krimesë, u vu në shfrytëzim; brenda pak dekadash perandoria fitoi një nga rrjetet telegrafike më të gjera në botë.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunameja e Tokës", "6bae243a"], "d": ["Kanunameja që modernizoi të drejtën agrare e lidhi me tapi posedimin de fakto mbi tokat shtetërore (miri); është një nga dokumentet themelore të rendit të sotëm të pronësisë në Lindjen e Mesme.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Leksionet e para në Darulfunun", "08f74066"], "d": ["Darulfununi, që do të jepte arsim të nivelit universitar, filloi punën me leksione të hapura për publikun; institucioni, që vazhdoi me ndërprerje, u hap përfundimisht në vitin 1900 dhe u bë bërthama e Universitetit të Stambollit.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Rregullorja e Vilajeteve", "ad20853b"], "d": ["Në vend të sistemit të ejaleteve u krijua organizimi i vilajeteve sipas modelit francez; duke marrë si shembull zbatimin e Mit'hat Pashës në Vilajetin e Danubit, u shtri në gjithë vendin.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Udhëtimi i Abdylazizit në Evropë", "9ff0fa1e"], "d": ["Udhëtimi i parë paqësor i një padishahu osman në Evropë; vizitat në ekspozitën e Parisit dhe në Londër shërbyen si vitrinë edhe e diplomacisë, edhe e modernizimit.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["U hap Liceu Perandorak i Galatasarajit (Mekteb-i Sultani)", "f9688524"], "d": ["Liceu me mësim në frëngjisht, me nxënës pa dallim feje dhe kombi, u bë simboli i idealit të Tanzimatit për barazi në arsim.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Hyn në fuqi libri i parë i Mexhelesë", "6475461c"], "d": ["Mexheleja, që përmblodhi me teknikën moderne të ligjit fushën e detyrimeve dhe të pasurive të së drejtës islame, konsiderohet kodi i parë civil islam; komisioni nën kryesinë e Xhevdet Pashës i përfundoi 16 librat në vitin 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Rrëzimi i Abdylazizit", "eb7397ea"], "d": ["Burrështetasit mbështetës të kushtetutës dhe krerët ushtarakë e rrëzuan Abdylazizin me një grusht shteti të heshtur; vdekja e tij e dyshimtë pesë ditë më vonë dhe ngjarjet e Çiraganit që pasuan lindën përballje që do të zgjasnin me vite.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Sulmi i Çiraganit (ngjarja e Ali Suaviut)", "d2a9ac87"], "d": ["Gazetari Ali Suavi sulmoi Çiraganin për ta rikthyer në fron Muratin V; sulmi u shtyp me gjakderdhje dhe regjimi i Abdylhamidit e shtrëngoi përgjithmonë unazën e sigurisë.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["U krijua Administrata Rezhi (monopoli i duhanit)", "bad9b030"], "d": ["Të ardhurat e duhanit iu kaluan kompanisë Rezhi me kapital të huaj në kuadër të Dyjun-i Umumijes; përplasjet midis fshatarëve dhe rojtarëve, 'kontrabanda e Rezhisë', zgjatën me dekada. Vendbanime të tjera që u humbën në të njëjtën datë: Zejla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Vizita e Kajzerit Vilhelm II në Stamboll dhe Jerusalem", "2988cd06"], "d": ["Vizita e dytë e perandorit gjerman e përforcoi afrimin osmano-gjerman; u hap rruga për koncesionin e hekurudhës së Bagdadit dhe në Damask u mbajt fjalimi ku ai u shpall 'mik i treqind milionë myslimanëve'.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hekurudha e Hixhazit në Medinë", "95009b9c"], "d": ["Linja prej 1464 km, e ndërtuar vetëm me dhurime të myslimanëve dhe me inxhinieri vendase, arriti në Medinë; udhëtimi i haxhit u shkurtua nga javë në ditë. Është vepra më e madhe infrastrukturore e periudhës së Abdylhamidit II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Ngjarja e 31 Martit", "1d7c2bb2"], "d": ["Kryengritja e madhe antikushtetuese e mori Stambollin; Ushtria e Veprimit që erdhi nga Selaniku e shtypi kryengritjen dhe Abdylhamidi II u rrëzua nga froni.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Filloi rrethimi i Edrenesë", "234d9b28"], "d": ["Mbrojtja pesëmujore e Shykri Pashës u bë epope e rezistencës brenda katastrofës ballkanike; qyteti ra nga uria dhe u rimor në korrik 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Sulmi mbi Portën e Lartë", "b304d02d"], "d": ["Qeveria, që po përgatitej të dorëzonte Edrenenë, u rrëzua me sulmin e armatosur të ittihadistëve; ministri i luftës, Nazim Pasha, u vra. Filloi periudha e pushtetit të plotë të Komitetit Bashkim e Përparim.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Shfuqizimi i Mutesarrifllëkut të Malit të Libanit", "b5639051"], "d": ["Rendi i mutesarrifllëkut autonom, i krijuar me Reglement Organique të vitit 1861 dhe i mbështetur te protokolli ndërkombëtar i rinovuar në vitin 1864, u shfuqizua në mënyrë të njëanshme nga Shteti Osman gjatë Luftës së Parë Botërore; Ministria e Brendshme filloi të emëronte drejtpërdrejt në krahinë mutesarrifë myslimanë. Kështu u mbyll periudha e autonomisë 1861-1915, gjatë së cilës shërbyen tetë mutesarrifë.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Ndarja e vendit midis shehzadeve", "82f26bfb"], "d": ["Pas disfatës së Ankarasë, Sulejman Çelebiu kaloi në Rumeli dhe u shpall sulltan në Edrene; Isa Çelebiu mbante Bursën, kurse Mehmet Çelebiu krahinën Amasja-Tokat-Sivas. Në hartë këto tri pjesë paraqiten me ngjyra të ndryshme.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Traktati i Galipolit: bregu i Detit të Zi deri në Mesemvri iu la Bizantit", "a4164eca"], "d": ["Emiri Sulejman, që pas disfatës së Ankarasë donte të qëndronte në Rumeli, nënshkroi në Galipoli një traktat me perandorin bizantin Manuel. Ia la Bizantit Kartalin, Pendikun, Gebzen dhe disa ishuj, në Rumeli Selanikun dhe Thesalinë, si dhe në Detin e Zi brezin bregdetar deri në Mesemvri; u hoq edhe taksa që Bizanti u paguante Osmanëve. Kështu Ahtopoli, Igneada dhe Rezve në bregun e Istranxhës mbetën njëzet e një vjet nën administrimin bizantin; Murati II, me paqen e vitit 1424, rimori shumicën e këtyre vendeve.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Vdekja e Bajazidit Jëlldërëm në robëri", "7e968d83"], "d": ["Padishahu, rob në duart e Timurit, vdiq në Akshehir; kufoma e tij u soll në Bursë dhe u varros. Vdekja e tij e bëri të pakthyeshme luftën për fron midis shehzadeve.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Traktati i Galipolit — lëshimet ndaj Bizantit", "dfacbd00"], "d": ["Sulejman Çelebiu, që donte të siguronte pozitën e vet në Rumeli, u mor vesh me Bizantin dhe me shtetet latine dhe ua ktheu Selanikun, brigjet e Marmarasë dhe disa ishuj; pranoi madje të paguante haraç.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Përplasja e Ulubatit — disfata e Isa Çelebiut", "500c5d24"], "d": ["Isa Çelebiu, që mbante Bursën, u mund në Ulubat nga i vëllai, Mehmeti; edhe disa përpjekje për t'u rimëkëmbur mbetën pa rezultat.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Zhdukja e Isa Çelebiut", "0effa11e"], "d": ["Isa Çelebiu, që me mbështetjen e Sulejman Çelebiut u kthye disa herë në Anadoll, pas disfatës së fundit u zhduk; pjesa e tij i kaloi Mehmet Çelebiut dhe në hartë zona e Mehmetit u zgjerua drejt perëndimit.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebiu kaloi në Vllahi", "8441267a"], "d": ["Mehmet Çelebiu, që përballë Sulejman Çelebiut humbi Bursën dhe Ankaranë dhe u tërhoq në Tokat-Amasja, e nxiti të vëllanë, Musanë, të shkonte në Rumeli. Musa pranoi ftesën e vojvodës së Vllahisë, Mirçea, dhe arriti në Vllahi me rrugë detare; prej aty do të niste luftën që do ta linte Sulejmanin midis dy fronteve.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Mehmet Çelebiu rimori Bursën dhe Ankaranë — pjesa e Anadollit doli nga duart e Sulejman Çelebiut", "bfb69f12"], "d": ["Pas sukseseve të Musa Çelebiut në Rumeli (Jamboll, 13 shkurt 1410), Emir Sulejman Çelebiu, që ndodhej në Anadoll, kaloi në Rumeli. Pas largimit të Sulejmanit nga Anadolli, Mehmet Çelebiu rimori krahinën e Bursës, përfshirë Ankaranë, dhe si shenjë e hipjes në fron preu monedhë me datën 813. Në hartë ana anadollake e Marmarasë kalon nga pjesa e Emir Sulejmanit në ngjyrën e Mehmet Çelebiut.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Beteja e Kosmidionit", "0efc2caa"], "d": ["Në betejën e zhvilluar përpara mureve të Stambollit me mbështetjen e Bizantit, Sulejman Çelebiu e mundi të vëllanë, Musanë; por mbështetja e tij në Rumeli kishte filluar të shkrihej me shpejtësi. Vendbanime të tjera që u humbën në të njëjtën datë: Elasona (Alasonya), Ajtosi (Aydos), Bolajir (vende në Rumeli që në hartë kalojnë nga Musa te Sulejmani).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Rrethimi i Stambollit nga Musa Çelebiu", "4932f586"], "d": ["Musa Çelebiu, që donte të ndëshkonte Bizantin për mbështetjen ndaj Sulejmanit, rrethoi Stambollin; ky rrethim e shtyu Bizantin në aleancë me Mehmet Çelebiun.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Vdekja e Emir Sulejmanit — Musa zot i Rumelisë", "325c1549"], "d": ["Sulejman Çelebiu, i kapur ndërsa po ikte nga Edrenea, u vra; e gjithë Rumelia kaloi në duart e Musa Çelebiut. Në hartë Rumelia kalon nga ngjyra blu në ngjyrën vjollcë.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Beteja e Çamurlusë — rivendosja e bashkimit", "0b23173e"], "d": ["Mehmet Çelebiu, me mbështetjen e Bizantit, të despotatit serb dhe të bejlerëve të Rumelisë, i shkaktoi të vëllait, Musait, një disfatë vendimtare në Çamurlu; Musa u vra ndërsa po ikte. Rumelia në duart e Musait, së bashku me Edrenenë, i kaloi Mehmetit dhe Mehmet Çelebiu u shpall në Edrene sundimtari i vetëm i Shtetit Osman. Periudha njëmbëdhjetëvjeçare e Interregnumit mori fund dhe pjesët e shehzadeve në hartë u bashkuan në një trup të vetëm.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Vendimi për fushatën e Vjenës — paqja e Vasvárit nuk u ripërtëri, objektivi u ndryshua nga Janëkkalaja (Győr) në Vjenë", "1bf278f2"], "d": ["Perandori Leopold I kërkonte ripërtëritjen e Traktatit të Vasvárit, afati i të cilit ende nuk kishte skaduar, dhe edhe Mehmeti IV dukej në anën e paqes. Por veziri i madh Merzifonlu Kara Mustafa Pasha, duke marrë si arsye ankesat e Imre Thökölyt, të cilin e kishte shpallur mbret të Hungarisë së Mesme, nuk lejoi ripërtëritjen e paqes; duke vënë në lëvizje predikuesit, në radhë të parë Vani Mehmed Efendiun, e bindi padishahun për luftë. Në këshillin e mbajtur u vendos që padishahu të rrinte në Beograd dhe serdar-i ekremi të përparonte për të marrë Janëkkalanë; por në këshillin e Székesfehérvárit (İstolni Belgrad), megjithë kundërshtimin e hanit të Krimesë, Murad Girajit, dhe të valiut të Budës, Uzun Ibrahim Pashës, objektivi u ndryshua në rrethimin e Vjenës.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Filloi Rrethimi i Dytë i Vjenës — ushtria përpara Vjenës", "bb542e49"], "d": ["Ushtria osmane nën komandën e vezirit të madh Kara Mustafa Pashës arriti përpara Vjenës më 14 korrik 1683. Perandori Leopold I, duke ia lënë mbrojtjen e qytetit Starhembergut, u tërhoq në brendësi të Austrisë. Ndryshe nga i pari, ky rrethim i dytë, i përgatitur me Vjenën si objektiv të drejtpërdrejtë, do të zgjaste deri më 12 shtator.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Disfata e Párkányt dhe humbja e Estergomit", "a7366740"], "d": ["Ushtria që po tërhiqej nga Vjena u mund për herë të dytë në Párkány; më pas ra Estergomi, një nga kalatë kyçe të Hungarisë. Tërheqja filloi të shndërrohej në shembje.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Ekzekutimi i Merzifonlu Kara Mustafa Pashës", "ce8b10ac"], "d": ["Veziri i madh, i konsideruar përgjegjës për disfatën e Vjenës, u mbyt me litar në Beograd; por ekzekutimi i tij as e rregulloi frontin, as e riktheu prestigjin e tronditur të shtetit.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["U krijua Lidhja e Shenjtë", "060280d0"], "d": ["Me nismën e papatit, midis Austrisë, Polonisë dhe Venedikut u krijua kundër Osmanëve Lidhja e Shenjtë; në vitin 1686 iu bashkua edhe Rusia. Kështu perandoria hyri në një luftë shumëfrontëshe që do të zgjaste gjashtëmbëdhjetë vjet.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Mbrojtja e parë e Budës", "ccc43630"], "d": ["Rrethimi i parë i Budës nga ushtria e Lidhjes së Shenjtë u zmbraps me mbrojtjen këmbëngulëse katërmujore të kalasë; por kalatë në Hungari vazhdonin të binin njëra pas tjetrës.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Humbja e Ujvarit", "689ab78c"], "d": ["Ra Kalaja e Ujvarit, që kishte mbetur njëzet e dy vjet në duart osmane dhe ishte bërë proverbiale në Evropë; prania osmane në Hungarinë e Sipërme u shpërbë.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arrestimi i Thökölyt në Varad — Mbretëria e Hungarisë së Mesme u shpërbë, kalatë e Hungarisë së Sipërme u dorëzuan", "1741aaaf"], "d": ["Pas disfatës së Vjenës, osmanët kishin filluar ta shihnin edhe Thökölyn ndër ata që kishin çuar në luftë dhe në disfatë. Më 15 tetor 1685, me urdhër të serdarit Melek Ibrahim Pasha, bejlerbeu i Varadit Ahmed Pasha urdhëroi kapjen e Thökölyt, që kishte ardhur për ndihmë; shpresohej të fitoheshin kushte më të mira paqeje duke ua dorëzuar atë Habsburgëve. Kur u përhap lajmi i arrestimit, të gjitha kalatë dhe qytetet e Mbretërisë së Hungarisë së Mesme, përveç Munkácsit që mbronte gruaja e tij Ilona Zrínyi, u dorëzuan te Habsburgët; shumica e ushtarëve kuruc kaluan në ushtrinë habsburge. Kur Thököly u lirua në Beograd më 2 janar 1686, mbretëria ishte zhdukur tashmë.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Humbja e Budës — kryeqyteti hungarez 145-vjeçar", "70800e2b"], "d": ["Në fund të rrethimit shtatëdhjetë e tetëditor, ra Buda; bejlerbeu i fundit, Abdurrahman Abdi Pasha, ra shehid mbi muret. Humbja e qytetit, nën administrimin osman që nga viti 1541, konsiderohet simbol i daljes nga duart të Hungarisë. Vendbanime të tjera që u humbën në të njëjtën datë: Pesht.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Disfata e Mohaçit të Dytë (Harsány) — humbja e Transilvanisë dhe e Mohaçit", "a7922681"], "d": ["Në fushën ku në vitin 1526 ishte fituar fitorja e madhe, këtë herë u pësua një disfatë e rëndë; ushtria u shpërbë dhe ushtarët që u rebeluan arritën shkarkimin e vezirit të madh. Disfata çoi edhe në humbjen e Transilvanisë.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Humbja e Athinës dhe shpërthimi i Partenonit", "b6691730"], "d": ["Një predhë e hedhur nga artileria venedikase e hodhi në erë Partenonin, që osmanët e përdornin si depo municioni; tempulli dymijëvjeçar u shndërrua në rrënoja. Qyteti kaloi në duart e Venedikut (do të rimerrej në vitin 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Rrëzimi i Mehmetit IV dhe hipja në fron e Sulejmanit II", "9f53037c"], "d": ["Për shkak të katastrofave në front dhe të kryengritjes së ushtrisë, Mehmeti IV u rrëzua pas sundimit 39-vjeçar; në vend të tij u soll i vëllai, Sulejmani II, i mbajtur dyzet vjet në kafaz.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Humbja e parë e Beogradit — rrethimi i Lidhjes së Shenjtë", "c6b9b19a"], "d": ["Beogradi, në duart osmane që nga viti 1521, iu dorëzua ushtrisë së Lidhjes së Shenjtë; dyert e Serbisë u hapën për armikun dhe rreziku arriti te vija Nish-Sofje. Vendbanim tjetër që në atlas po në atë datë kalon nga Osmanët te Habsburgët: Hisarxhëk (Grocka) — ndjek zinxhirin e qendrës kryesore të lidhur me Beogradin (TDV belgrad; përafërsi e deklaruar).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Badeni kaloi Moravën përpara Pozharevcit — Pozharevci ra në duart e Austrisë", "bcf3fc59"], "d": ["Markgrafi Ludwig von Baden, në gusht 1689, kaloi Moravën në Pozharevac dhe përparoi drejt Nishit; qyteti mbeti në duart e Austrisë deri në verën e vitit 1690 (TDV suleyman-ii thotë se Pozharevci u rimor në vitin 1690). Dita dhe leximi i Röderit nuk u riverifikuan në këtë seancë.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Humbja e Nishit — përparimi habsburg (kurora e Mbretërisë së Hungarisë), viti më kritik", "c5e27b3f"], "d": ["Përparimi habsburg (kurora e Mbretërisë së Hungarisë) e hoqi edhe Nishin nga administrimi osman; sulmet arritën deri në Shkup dhe Prishtinë. Kurse Vidini ra më pas, në tetor 1689 (zë më vete). Në vitin më të errët të luftës, shteti ndiente se kërcënohej edhe kryeqyteti.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova dhe Fethylislami (Kladova) morën garnizon austriak", "ee8dd875"], "d": ["Pas marrjes pa luftë të Vidinit (tetor 1689, TDV vidin), Badeni më 25 tetor 1689 riparoi Orsovën dhe Fethylislamin dhe vendosi garnizone në to; Orsova mbeti në duart e Austrisë deri në vjeshtën e vitit 1690. Dita mbështetet te Bánlaky/Röder dhe nuk u riverifikua në këtë seancë.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Nishi sërish te Osmanët", "0c4f44eb"], "d": ["Fazil Mustafa Pasha doli në fushatë në korrik 1690; pasi u morën Piroti, Pozharevci dhe Golubaci (Güvercinlik), Nishi i rrethuar kaloi në duart osmane më 27 shtator 1690 (TDV semendire). Në të njëjtën kohë ishte rimarrë edhe Vidini. Vendbanime të tjera që në atlas po në atë datë kthehen nga Habsburgët te Osmanët: Jagodina (Yagodina) dhe Prokuplje (Ürküp) — meqë nuk u gjet ditë në nivel vendi, u mor dita e Nishit (TDV semendire; përafërsi e deklaruar; Röder 1842 shkruan se veziri kaloi nga Jagodina më 8-24 shtator, kundërthënia nuk u zgjidh).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Njësitë austriake në Smederevë u dorëzuan", "90da20c4"], "d": ["Pas marrjes së Nishit më 27 shtator 1690, me një rrethim katërditor u dorëzuan njësitë austriake në Smederevë (TDV semendire). Bánlaky/Röder thonë 24 shtator; burimet kundërshtohen, u mor për bazë TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Beogradi u rimor", "ab435838"], "d": ["Veziri i madh Kyprylyzade Fazil Mustafa Pasha më 8 tetor 1690 e rimori Beogradin nga Austria; kështu qyteti i humbur në vitin 1688 iu kthye Osmanëve (TDV suleyman-ii). Vendbanim tjetër që në atlas po në atë datë kthehet nga Habsburgët te Osmanët: Hisarxhëk (Grocka) — ndjek zinxhirin e qendrës kryesore të lidhur me Beogradin (TDV suleyman-ii; përafërsi e deklaruar).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Disfata e Salankamenit — Fazil Mustafa Pasha shehid", "10d626f1"], "d": ["Në një nga betejat fushore më të përgjakshme të shekullit, veziri i madh ra shehid i goditur në ballë; ushtria u shpërbë. Shpresa për rimëkëmbje u shua me këtë luftë.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Humbja e ishullit të Kiosit", "07c084f8"], "d": ["Flota venedikase pushtoi Kiosin; sundimi osman në Egje hyri nën kërcënim. Ishulli do të rimerrej vitin pasues.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Vendimi i Mustafait II për të dalë vetë në fushatë", "61c3ba9c"], "d": ["Padishahu i ri, duke ndjekur rrugën e stërgjyshërve, shpalli se do të dilte në fushatë në krye të ushtrisë; ky vendim ngriti moralin në ushtri dhe nisi periudhën dyvjeçare të fushatave personale.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Rimarrja e Kiosit", "6b496fca"], "d": ["Mezomorto Husein Pasha, që e mundi flotën venedikase në betejat detare të Ishujve Oinousses (Koyun Adaları), rimori Kiosin; u bë shenjë e një ringjalljeje të shkurtër të detarisë osmane.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Fitorja e Lugojit — fushata e parë e Mustafait II kundër Austrisë", "d5ee9b34"], "d": ["Në fushatën e parë ku padishahu mori pjesë personalisht, u rimor Lipova dhe forcat austriake u mundën në Lugoj; u bë thyerja e parë në vargun shumëvjeçar të disfatave. Atlasi e konsideron edhe Karánsebesin (Caransebeş) si të kthyer në këtë fushatë nga Habsburgët te Osmanët; burimi jep vetëm shtatorin 1695 (TDV mustafa-ii), dita në atlas u mor nga regjistrimi i Lugojit (përafërsi e deklaruar).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Humbja e Kalasë së Azovit", "2b78b5cd"], "d": ["Pjetri I, që synonte të dilte në Detin e Zi, me rrethimin e dytë mori Azovin; Rusia për herë të parë u vendos përgjithmonë në një kala osmane dhe hodhi hapin e parë drejt shndërrimit në fuqi detare.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Fitorja e Ulashit (Olasch)", "02ac9ca8"], "d": ["Fitorja e fituar në bregun e Danubit në fushatën e dytë të padishahut prishi planin austriak për të marrë Temeshvarin; por nuk e ndryshoi ekuilibrin e përgjithshëm të luftës.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Disfata e Zentës — u përcaktua fati i luftës", "475c4a7b"], "d": ["Ndërsa ushtria po kalonte lumin Tisa, pësoi sulmin e befasishëm të princit Eugjen; forcat e ndara në të dy brigjet e lumit u asgjësuan brenda pak orësh, vdiqën mijëra ushtarë dhe burrështetas, përfshirë vezirin e madh Elmas Mehmed Pashën. Zenta, një nga disfatat më të rënda të historisë osmane, e bëri të pashmangshme tryezën e paqes.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Filluan bisedimet e paqes së Karlovcit", "1f395cf3"], "d": ["Në bisedimet që filluan me ndërmjetësimin e Anglisë dhe të Holandës, delegacioni osman për herë të parë u detyrua të pranonte parimin 'uti possidetis' (secila palë mban atë që ka në dorë); negociatat prej shtatëdhjetë e dy seancash konsiderohen lindja e diplomacisë moderne osmane.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmet Ali nga Kavalla doli në Egjipt", "514c943f"], "d": ["Në ushtrinë osmane të dërguar për të rimarrë Egjiptin e pushtuar nga francezët ishte edhe njësia vullnetare e mbledhur nga Kavalla. Mehmet Aliu, në të tridhjetat, ishte komandanti i dytë i kësaj njësie; në Egjipt shkeli jo si vali, por si oficer kompanie.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Ushtarët shqiptarë rrëzuan valiun e Egjiptit", "c76a0ec2"], "d": ["Njësitë shqiptare, rrogat e të cilave nuk paguheshin, u ngritën në kryengritje dhe e detyruan valiun Hysrev Pasha të ikte nga kalaja. Në boshllëkun që lindi me tërheqjen e francezëve, bejlerët qylemenë (memlukë), odxhaku shqiptar dhe valinjtë e emëruar nga Porta e Lartë hynë në një luftë tripalëshe; Mehmet Aliu, duke krijuar ekuilibra në këtë trekëndësh, doli në plan të parë. Vendbanime të tjera që u humbën në të njëjtën datë: Taifi.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulemaja e Kajros e shpalli Mehmet Aliun vali", "a16752f2"], "d": ["Esnafët dhe ulemaja e Kajros, të rraskapitur nga presioni i taksave, nën udhëheqjen e nakib-ul-eshrafit Omer Mekrem, u ngritën, njoftuan se nuk e njihnin valiun Hurshid Pasha dhe e vendosën Mehmet Aliun në postin e valiut. Zgjedhja e një valiu nga populli është një ngjarje e rrallë në historinë osmane.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Porta e Lartë pranoi faktin e kryer: fermani për valiun e Egjiptit", "b86736a3"], "d": ["Porta e Lartë, që nuk kishte fuqi të mbante në Egjipt kandidatin e vet, i dërgoi Mehmet Aliut fermanin e valiut të Egjiptit me gradën e vezirit. Në hartë Egjipti që nga kjo datë kalon në shtresën vartëse (me ngjyrë të çelët): juridikisht tokë osmane, de fakto vendi i dinastisë së Mehmet Aliut nga Kavalla. Vendbanime të tjera që po në atë datë kalojnë në shtresën vartëse: Kajro, Aleksandria, Damieta, Asjuti, Asuani, Ibrimi, Suezi, Rashidi (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Ekspedita angleze e Fraserit zbarkoi në Aleksandri", "4d6c31be"], "d": ["Në përgjigje të afrimit të Osmanëve me Francën, Anglia dërgoi në Egjipt një forcë zbarkimi. Mehmet Aliu në atë kohë merrej me qylemenët në Egjiptin e Epërm; u kthye shpejt dhe organizoi mbrojtjen.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Disfata e Rashidit (Rosettës) — anglezët u zmbrapsën", "3636004c"], "d": ["Kolona angleze që hyri në qytezën e Rashidit pësoi humbje të rënda në përleshjet në rrugë; në shtator forcat e zbrazën plotësisht Egjiptin. Kjo fitore e përforcoi prestigjin e Mehmet Aliut si në Egjipt, ashtu edhe në Stamboll.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Ngjarja e Kalasë: likuidimi i bejlerëve qylemenë", "84030b97"], "d": ["Bejlerët qylemenë, të ftuar në kortezhin e ceremonisë së organizuar për fushatën e Hixhazit, u zhdukën pasi u zunë në kurth në kalimin e ngushtë të Kalasë së Kajros. Kështu mori fund ndikimi pesëqindvjeçar i qylemenëve dhe në Egjipt Mehmet Aliut nuk i mbeti asnjë rival.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Filloi fushata e Hixhazit — ushtria marshoi nga Suezi në Jenbo me det dhe nga rruga e haxhit me tokë", "1c05c159"], "d": ["Rimarrja e dy qyteteve të shenjta (Haremejn), nën administrimin saudito-vehabit që nga viti 1803, ishte çështja më e madhe e legjitimitetit të Mahmudit II; meqë Porta e Lartë nuk kishte fuqi, detyra iu dha valiut të Egjiptit. Mehmet Aliu dërgoi në krye të ushtrisë të birin gjashtëmbëdhjetëvjeçar, Tosunin.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["U mor Jenboja — baza e parë bregdetare e fushatës së Hixhazit", "179bc78d"], "d": ["Rreth dy mijë këmbësorë shqiptarë, të nisur nga Suezi me anije të sapondërtuara, zbarkuan pranë Jenbos në tetor 1811; qyteza u dorëzua pas një rezistence të dobët dyditore. Kalorësit nën komandën e Tosunit, që ndiqnin me tokë rrugën e haxhit, arritën në Jenbo përmes Akabasë dhe Vexhit vetëm dy javë më vonë. Jenboja u bë baza e parë në Hixhaz e ushtrisë egjiptiane që do të marshonte drejt Medinës dhe Mekës.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Disfata e parë në grykën Safra-Xhedide", "99ef804d"], "d": ["Pararoja egjiptiane, që ra në pritë në qafat e ngushta malore, u shpartallua. Disfata u bë mësimi taktik i fushatës: u kuptua se pa mbështetjen e fiseve beduine nuk ishte e mundur të ecej në Hixhaz.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["U rimor Medina", "6f6a5d55"], "d": ["Pas një rrethimi të gjatë, Medina u dorëzua. Rimarrja e qytetit të Profetit u festua në Stamboll me të shtëna topash; Mehmet Aliut, si shpërblim, iu dha edhe valiu i Xhidës.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["U rimor Meka — u hap rruga e haxhit", "3d6d66a0"], "d": ["Forcat egjiptiane që hynë në Mekë bënë që në Qabe të lexohej përsëri hytbeja në emër të padishahut osman. Karvanet e haxhit, të ndërprera prej dhjetë vjetësh, mundën të niseshin sërish. Në hartë Hixhazi kthehet nën sovranitetin osman, por, meqë administrimi ishte në Kajro, paraqitet me ngjyrë vartëse. Vend tjetër që po në atë datë kalon në administrim vartës: Xhida.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Rimarrja e Taifit — përfundimi i fushatës së Hixhazit", "6315fb31"], "d": ["Pas Medinës (dhjetor 1812) dhe Mekës (janar 1813), ushtria egjiptiane nën komandën e Tosun Pashës së fundi ua rimori vehabitëve Taifin. Sundimi saudit dhjetëvjeçar mori fund dhe të tri qendrat e shenjta të Hixhazit hynë përsëri nën kontrollin osmano-egjiptian.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmet Aliu kaloi vetë në Hixhaz", "fda0ea2d"], "d": ["Valiu, që pa se fushata po ecte ngadalë, e mori administrimin drejtpërdrejt në dorë; duke bërë pazar me krerët e fiseve, u përpoq ta shpërbënte frontin saudit nga brenda. Me këtë fushatë u rrit edhe pjesa e Egjiptit në tregtinë e Detit të Kuq.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Beteja e Bisalit: forcat saudite u shpartalluan", "9c9ab91f"], "d": ["Sauditët, që pësuan një disfatë të rëndë në betejën fushore, u tërhoqën në brendësi. Armëpushimi i bërë nuk qe i qëndrueshëm; dy vjet më vonë operacioni do të zhvendosej në zemër të Nexhdit. Atlasi konsideron se pas kësaj fitoreje Turaba dhe Hurma, në lindje të Taifit, dolën nga duart saudite (burimi i ngjarjes: Lorimer, Gazetteer; dëshmia specifike për vendbanimet dhe dita 13 janar janë përafërsi e deklaruar).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasha doli në fushatën e Nexhdit", "d5ed80d1"], "d": ["Ibrahim Pasha, që mori komandën pas vdekjes së të vëllait, Tosunit, nisi një marshim të rëndë në shkretëtirë që zgjati dy vjet. Ushtria, duke përparuar pus pas pusi dhe duke i mënjanuar fiset një nga një, arriti përpara kryeqytetit saudit.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Ra Dirija — mori fund Shteti i parë Saudit", "aa96206d"], "d": ["Pas rrethimit gjashtëmujor, Dirija u dorëzua dhe u shkatërrua. Emiri Abdullah bin Saud u dërgua në Stamboll dhe u ekzekutua. Flamuri osman për herë të parë arriti kaq thellë në brendësi të Arabisë; garnizoni i Nexhdit qëndroi deri në vitin 1824. Vende të tjera që u bashkuan në të njëjtën datë: Dirija (Nexhd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Filloi fushata e Sudanit", "b1fc6905"], "d": ["Synimi i Mehmet Aliut ishte i trefishtë: të mblidhte ushtarë për ushtrinë, të arrinte te ari i Senarit dhe të zhdukte mbetjet e qylemenëve të ikur. Forca nën komandën e të birit, Ismail Pashës, duke ndjekur Nilin, zbriti drejt jugut.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola i kaloi ushtrisë egjiptiane pa dhunë (memlukët e kishin braktisur në qershor 1820)", "bc5942c0"], "d": ["Dongola, në kthesën e madhe të Nilit, pasi memlukët e braktisën në qershor 1820, kaloi pa dhunë në duart e ushtrisë egjiptiane të Ismail Pashës. Në hartë Sudani që nga kjo datë shfaqet në shtresën vartëse: pushtuesi është Kajro dhe sundues do të jetë përsëri Kajro.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Beteja e Xhebel ed-Dajkës — konfederata Shajkija mundet përfundimisht nga ushtria egjiptiane", "befc9539"], "d": ["Ushtria e Ismail Pashës, të birit të Mehmet Ali Pashës, një muaj pas përplasjes së parë në Kurti, e mundi Shajkijan në betejën e dytë dhe vendimtare pranë Xhebel ed-Dajkës. Kreu i Shajkijas, Mak Subajri, u dorëzua; Mak Shavishi vazhdoi rezistencën. Pas kësaj sundimi egjiptian në kthesën e Nilit u bë i përhershëm.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Sulltanati i Senarit (Funxh) u dorëzua", "3cac7dd2"], "d": ["Dinastia treshekullore Funxh u dorëzua pa luftë. Po atë vit, kampi ushtarak i ngritur në pikën ku bashkohen dy degët e Nilit, për pak kohë u shndërrua në Hartum, qendrën administrative të Sudanit. Vende të tjera që u bashkuan në të njëjtën datë: Senar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["U mor Kordofani", "06440602"], "d": ["Kolona e dytë, e dërguar drejt perëndimit, duke mundur forcat e Darfurit në Bara, mori Kordofanin së bashku me rrethinat e Nuhudit. Kështu sundimi egjiptian në Sudan u zgjerua nga lugina e Nilit deri në stepat perëndimore.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Forcat egjiptiane zbarkuan në Kretë", "835aee90"], "d": ["Kur kryengritja greke u përhap në Kretë, Porta e Lartë kërkoi dërgimin e një force egjiptiane në ishull. Ndikimi i Mehmet Aliut në ishull filloi me këtë ndërhyrje dhe tetë vjet më vonë përfundoi me dhënien atij të valisë së Kretës.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Vrasja e Ismail Pashës në Shendi", "223860c9"], "d": ["Emiri vendor Nimri, i zemëruar nga kërkesa për taksa të rënda dhe ushtarë, i vuri flakën shtëpisë ku Ismail Pasha po bujtte dhe e dogji atë me shpurën e tij. Fushata hakmarrëse e ktheu krahinën në një liqen gjaku; administrimi i Sudanit pas kësaj u ndërtua mbi ashpërsinë.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmudi II i kërkoi ndihmë Mehmet Aliut për Morenë", "03594a42"], "d": ["Për kryengritjen e Moresë, që ushtria e jeniçerëve nuk arriti ta shtypte për tre vjet, padishahu iu drejtua ushtrisë egjiptiane të stërvitur sipas mënyrës evropiane. Në këmbim u premtuan valia e Moresë dhe Kreta. Kjo kërkesë ishte pranimi i parë i hapur se perandoria ishte bërë e varur nga vilajeti i vet.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasha zbarkoi në Modon", "9c993dba"], "d": ["Forca e zbarkimit, e mbrojtur nga flota egjiptiane, shkeli në skajin jugperëndimor të Moresë. Kjo ushtri, e pajisur me këmbësori të rregullt dhe me artileri fushore, brenda pak kohe fitoi epërsi ndaj çetave kryengritëse.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["U rimor Tripolica — ra qendra e Moresë", "8a478c11"], "d": ["Me rënien e Tripolicës, qendrës drejtuese të kryengritjes, pjesa më e madhe e Moresë u vu përsëri nën kontroll. Në hartë gadishulli, meqë ishte në duart e forcave egjiptiane, shfaqet me ngjyrë vartëse.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Ra Misolongji", "07257f87"], "d": ["Pas një rrethimi njëvjeçar qyteti u mor. Megjithatë, jehona që mbrojtja pati në shtypin evropian e çoi në kulm simpatinë për çështjen greke dhe përgatiti terrenin për ndërhyrjen e fuqive të mëdha.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["U mor Akropoli i Athinës", "3b19f946"], "d": ["Me rënien e Akropolit, kryengritja greke ushtarakisht pothuajse kishte marrë fund. Pikërisht në këtë pikë çështja pushoi së qeni kryengritje e brendshme dhe u bë temë e diplomacisë evropiane.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Traktati i Londrës: tri shtetet imponuan autonominë greke", "7ce46fd8"], "d": ["Anglia, Franca dhe Rusia vendosën të vepronin bashkë për t'i detyruar Osmanët dhe grekët të pranonin armëpushim dhe kushtin e autonomisë; u njoftua se, nëse refuzohej, flotat e tyre do të ndërhynin. Porta e Lartë e refuzoi propozimin.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Konventa e Aleksandrisë: vendimi për tërheqjen e Egjiptit nga Moreja", "cc978f37"], "d": ["Mehmet Aliu, që humbi flotën në Navarin, pa u këshilluar me Stambollin, u mor vesh drejtpërdrejt me admiralin anglez dhe pranoi t'i tërhiqte forcat e veta nga Moreja. Fakti që një vali lidhte marrëveshje të pavarur me fuqitë e mëdha paralajmëronte krizën e ardhshme.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Forcat egjiptiane zbrazën Morenë", "8fb742dd"], "d": ["Njësitë e fundit u hipën në anije; gadishulli de fakto doli nga duart dhe me Protokollin e Londrës të vitit 1830 u bë bërthama e Greqisë së pavarur. Kurse Mehmet Aliu nuk mundi të merrte valinë e premtuar të Moresë dhe në këmbim kishte humbur një flotë e ushtri të madhe. Vendbanime të tjera që u humbën në të njëjtën datë: Modoni, Koroni.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Administrimi i Kretës iu la Mehmet Aliut", "7f76396d"], "d": ["Si kompensim për humbjen e Moresë, Mehmet Aliut iu dha valia e Kretës. Ishulli për dhjetë vjet u qeveris nga Kajro; gjatë kësaj kohe në hartë paraqitet me ngjyrë vartëse. Vende të tjera që u bashkuan në të njëjtën datë: Kandia (Kretë).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasha hyri në Siri — filloi kriza e parë", "1a5cc386"], "d": ["Pretekst ishte valiu i Akkës, që nuk i kthente felahët e ikur nga Egjipti; arsyeja e vërtetë ishte nevoja e Mehmet Aliut për lëndën drusore, portet dhe burimet njerëzore të Sirisë. Ushtria kaloi Sinain dhe pushtoi shpejt bregun e Palestinës.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Filloi rrethimi i Akkës", "b211d96d"], "d": ["Kalaja që ndali Napoleonin në vitin 1799 rezistoi gjashtë muaj. Rrethimi ishte prova e parë e madhe e artilerisë moderne të ushtrisë egjiptiane.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Ra Akka", "0f47917b"], "d": ["Kur bateritë që goditnin muret hapën të çarë, kalaja u mor. Dera e Sirisë ishte hapur; Porta e Lartë po në ato ditë e shpalli Mehmet Aliun rebel dhe i hoqi valinë.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["U dorëzua Damasku", "48da3b62"], "d": ["Qyteti u dorëzua pa luftë. Ibrahim Pasha, duke shpallur rendin tatimor dhe barazinë e njohur jomyslimanëve, u përpoq të fitonte mbështetjen vendore; po këto politika pas pak vjetësh do të bëheshin edhe shkaku i kryengritjeve kundër tij. Vende të tjera që u bashkuan në po ato ditë: Bejruti, Tripoli i Sirisë (Trablusshami), Sidoni.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Beteja e Homsit", "867810ee"], "d": ["Ushtria osmane e dërguar për të shpëtuar Sirinë u shpartallua në fushë të hapur. U pa se ushtria e re, e krijuar gjashtë vjet pas shfuqizimit të korpusit të jeniçerëve, nuk ishte ende gati.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["U mor Halepi", "9c0ead76"], "d": ["Ra edhe qendra tregtare dhe administrative e Sirisë Veriore. Kështu ushtria egjiptiane arriti rrëzë maleve të Taurit dhe u drejtua për në qafat në derën e Anadollit.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Disfata e Qafës së Belenit (Beylan) — u hap Çukurova", "4bae872b"], "d": ["Në qafën e ngushtë të maleve Amanos u ça vija mbrojtëse. Antakia, Adana dhe Tarsi kaluan te forcat egjiptiane (pushtimi i Marashit, sipas TDV-së, është i vitit 1833, zë më vete); në hartë Çukurova kalon në ngjyrë vartëse. Rruga drejt brendësisë së Anadollit tashmë ishte e pambrojtur.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Ra Qafa e Gylekut — bregu i Içelit (Mersin, Silifke) hyri nën kontrollin egjiptian", "d9049b5b"], "d": ["Qafa e Gylekut, porta e Çukurovës në Tauri, kaloi në duart e ushtrisë egjiptiane. Ibrahim Pasha emëroi mytesellimin e vet në Sanxhakun e Içelit dhe të gjitha skelat bregdetare hynë nën kontrollin egjiptian. Në hartë Mersini dhe Silifkja paraqiten si të lidhura me Egjiptin që nga kjo ditë (kufiri i poshtëm; dita e emërimit mungon te burimi); meqë me vendimin e Kytahjas kaloi vetëm muhasillëku i Adanasë, ky kontroll merr fund me evakuimin e Anadollit.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereglia e Konjas nën pushtim egjiptian — gryka e Taurit në rrugën Konja–Adana", "fb908900"], "d": ["Ereglia, në rrugën për në Konja të ushtrisë egjiptiane që kaloi Qafën e Gylekut, hyri nën pushtimin e Ibrahim Pashës në vitin 1832 dhe, kur u zbraz me rregullimin e Kytahjas të vitit 1833, u lidh përsëri me vilajetin e Karamanit. Në hartë është pikë e ndërmjetme e mbështetur në burim e vijës së pushtimit midis Adanasë dhe Konjas; për Ulukëshlanë dhe Karapënarin nuk u gjet dëshmi në nivel qyteti.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Ushtria egjiptiane hyri në Konja", "13952a2d"], "d": ["Ushtria që kaloi Taurin arriti në Anadollin Qendror. Forcat e një valiu osman për herë të parë po përparonin në tokat bërthamë të perandorisë. Vende të tjera që u bashkuan në të njëjtën datë: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Beteja Fushore e Konjas: veziri i madh u zu rob", "ec82cc9a"], "d": ["Ushtria osmane, e shpërndarë në mjegull, pësoi një disfatë të rëndë dhe veziri i madh Reshid Mehmed Pasha u zu rob. Ushtria qendrore e shtetit nuk ekzistonte më; midis Stambollit dhe forcave egjiptiane nuk kishte mbetur asnjë fuqi që të qëndronte.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Marashi pësoi pushtimin egjiptian", "f558e383"], "d": ["Sipas TDV-së, Marashi në vitin 1833 pësoi pushtimin e Ibrahim Pashës së Kavallës dhe mbeti nën administrimin e tij afro nëntëmbëdhjetë muaj. Meqë Marashi mbetej jashtë kufijve të ejaletit të rregullimit të Kytahjas, ky administrim nuk ishte juridik, por de fakto.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisar-i Sahib (Afjon) pësoi pushtimin egjiptian — rruga Konja–Kytahja", "ae0c2c78"], "d": ["Karahisar-i Sahib, në rrugën e ushtrisë egjiptiane që pas Betejës Fushore të Konjas përparoi drejt Kytahjas, në vitin 1833 mbeti për ca kohë në duart e Ibrahim Pashës. Në hartë është pikë e ndërmjetme e mbështetur në burim e vijës së pushtimit midis Konjas dhe Kytahjas; për Akshehirin, Ilgënin dhe Ishaklinë nuk u gjet dëshmi në nivel qyteti, ato janë me ngjyrë osmane.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Ushtria egjiptiane arriti në Kytahja", "214f8df6"], "d": ["Ibrahim Pasha u ndal në Kytahja, tri etapa larg Stambollit. Mosvazhdimi përpara nuk ishte ushtarak, por politik: ishin marrë parasysh ndërhyrja ruse dhe reagimi i Evropës.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Flota ruse përpara Büyükderesë", "6f836d61"], "d": ["Mahmudi II, që nuk mundi të merrte ndihmë nga Anglia dhe Franca, iu drejtua armikut të djeshëm, Rusisë. Ky vendim, që përmendet me fjalën e padishahut \"kush bie në det kapet edhe pas gjarprit\", përfundoi me daljen e ushtarëve rusë në ngushtica dhe ngriti alarmin në Evropë.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Marrëveshja e Kytahjas (gojore) — Siria dhe Adana te Mehmet Aliu nga Kavalla", "25fe9985"], "d": ["Porta e Lartë, përveç Egjiptit, Kretës dhe Hixhazit, ia la Mehmet Aliut valinë e Damaskut, të Halepit, të Tripolit të Sirisë dhe të Sidonit; muhasillëkun e Adanasë ia la Ibrahim Pashës. Në këmbim, ushtria u tërhoq në jug të Taurit. Kjo nuk ishte traktat, por kishte formën e fermaneve që padishahu i dha një valiu — çështja nuk ishte zgjidhur, por shtyrë.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Tërheqja e ushtrisë egjiptiane nga Anadolli përfundoi përmes Gylekut", "a53ac2a3"], "d": ["Pas rregullimit të Kytahjas, forcat egjiptiane zbrazën Anadollin; rreth mesit të qershorit e gjithë ushtria kaloi nga Qafa e Gylekut në Çukurovë. Bregu i Içelit (Mersin, Silifke) kthehet përsëri nën administrimin osman; muhasillëku i Adanasë dhe Siria mbeten te Egjipti.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Traktati i Hünkâr İskelesit", "da741d5c"], "d": ["Me Rusinë u nënshkrua një aleancë e ndërsjellë mbrojtëse tetëvjeçare. Sipas nenit sekret, nëse Rusia sulmohej, Osmanët do t'i mbyllnin ngushticat për anijet luftarake. Ky u bë një nga vendimet më të diskutuara të diplomacisë osmane dhe e bëri Anglinë aktive në çështjen egjiptiane.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Kryengritja e Palestinë-Nablusit kundër administrimit egjiptian", "4fe43e27"], "d": ["Shërbimi ushtarak i detyrueshëm, mbledhja e armëve dhe taksat e reja shkaktuan një kryengritje të gjerë në Palestinë. Kryengritja u shtyp ashpër; mbështetja e popullsisë vendase për administrimin egjiptian u shkri shpejt.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fundi i administrimit egjiptian në Marash (përafërsisht)", "bb46ca42"], "d": ["Nëse fjalia e TDV-së për kohëzgjatjen 'afro nëntëmbëdhjetë muaj' llogaritet nga pushtimi i vitit 1833, administrimi egjiptian merr fund rreth verës së vitit 1834. Fakti që Mustafa Beu nga familja Kyçykalioglu, në vitin 1834, pa mundur t'i rezistonte ushtrisë egjiptiane, u tërhoq drejt Marashit tregon gjithashtu se Marashi në atë kohë ishte një strehë jashtë kontrollit egjiptian.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Kryengritja e Xhebel Druzit", "12e74626"], "d": ["Rezistenca që shpërtheu në krahinën druze zgjati dy vjet. Pakënaqësia e grumbulluar në Siri, kur në vitin 1840 flotat aleate dolën në breg, do t'ia zbrazte shpinën ushtrisë egjiptiane.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmet Aliu njoftoi synimin për pavarësi", "48633bbd"], "d": ["Valiu u deklaroi konsujve të fuqive të mëdha se po mendonte të shpallte pavarësinë e Egjiptit dhe të Sirisë. Anglia e kundërshtoi prerë: lindja në Mesdhe e një shteti të fortë dhe afër Francës do të kërcënonte rrugën e Indisë.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Ushtria osmane kaloi Eufratin", "9af1ea69"], "d": ["Mahmudi II, për të rimarrë atë që kishte humbur në Kytahja, e shtyu ushtrinë drejt kufirit sirian. Oficeri prusian Moltke, që ndodhej në ushtri si këshilltar, kundërshtoi zgjedhjen e pozicionit dhe ofensivën e parakohshme; kundërshtimet e tij nuk u dëgjuan.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Beteja e Nizipit — ushtria osmane u shpërbë", "156b3cdf"], "d": ["Ushtria osmane e vendosur keq u shpartallua brenda pak orësh. Padishahu vdiq para se lajmi i disfatës të arrinte në Stamboll; shteti, brenda pak ditësh, do të humbte ushtrinë, sundimtarin e më pas flotën.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Vdekja e Mahmudit II", "07eccfff"], "d": ["Padishahu që gjatë sundimit tridhjetë e një vjeçar shfuqizoi korpusin e jeniçerëve dhe rindërtoi administrimin qendror, vdiq pa mundur të mundte kundërshtarin më të madh. Sëmundjes së tij nuk iu bë diagnoza e saktë. Vdekja u mbajt e fshehtë deri më 30 qershor, derisa në qytet u morën masa ushtarake, nga frika se mentaliteti jeniçer do të vihej në lëvizje.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Hipja në fron e Abdylmexhidit dhe funerali i Mahmudit II", "d0f3d2cc"], "d": ["Pas vdekjes së të atit, Abdylmexhidi gjashtëmbëdhjetëvjeçar hipi në fron. Po atë ditë trupi i Mahmudit II u soll në Sarajin Topkapë; trazirat e frikshme nuk ndodhën dhe turma të gjera popullore, myslimane e jomyslimane, iu bashkuan kortezhit të varrimit.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Dorëzimi i flotës në Aleksandri", "a53e6103"], "d": ["Kapudan pashai Ahmed Fevzi Pasha, me dyshimin se veziri i madh Koxha Hysrev Pasha do t'ia jepte flotën Rusisë, e çoi flotën në Aleksandri dhe ia dorëzoi Mehmet Aliut. Brenda po atij muaji Shteti Osman mbeti pa ushtri, pa padishah dhe pa flotë.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota e përbashkët e fuqive të mëdha", "2a3b8316"], "d": ["Pesë shtete i dërguan Portës së Lartë një notë, duke kërkuar që në çështjen egjiptiane të mos bënte marrëveshje të veçantë. Kështu një çështje e brendshme u bë zyrtarisht \"çështje evropiane\"; shteti osman de fakto humbi kompetencën për të vendosur për vilajetin e vet.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Traktati i Londrës: katër shtete në anën e Osmanëve", "a517f775"], "d": ["Traktati, i nënshkruar duke lënë jashtë Francën, i dha Mehmet Aliut një ultimatum: nëse pranonte brenda dhjetë ditësh, valinë e trashëgueshme të Egjiptit dhe, me kusht përjetësie, Akkën; nëse pranonte brenda njëzet ditësh, vetëm Egjiptin; nëse refuzonte, asgjë. Valiu refuzoi.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardimi i Bejrutit dhe zbarkimi aleat", "0905ce92"], "d": ["Flota anglo-austriake e goditi me topa Bejrutin; popullit që u ngrit kundër administrimit egjiptian në malet e Libanit iu shpërndanë armë. Kontrolli i Ibrahim Pashës në Siri u shemb midis kryengritjes së brendshme dhe ndërhyrjes së jashtme.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Bejruti dhe qytetet bregdetare dolën nga duart", "09bdaf23"], "d": ["Pas përleshjeve në drejtim të Baalbekut, forcat egjiptiane u tërhoqën nga bregdeti. Në hartë bregu i Libanit del nga ngjyra vartëse dhe kthehet në administrimin e drejtpërdrejtë osman.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka ra brenda dy orësh", "5aec21f0"], "d": ["Gjatë bombardimit të flotës aleate shpërtheu depoja e municionit të kalasë dhe Akka u dorëzua brenda pak orësh. Kalaja që tetë vjet më parë Ibrahim Pasha mundi ta merrte vetëm për gjashtë muaj tregoi epërsinë e artilerisë detare.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konventa e Aleksandrisë", "85cb47b0"], "d": ["Mehmet Aliu pranoi të hiqte dorë nga Siria, Adana, Kreta dhe Hixhazi, të kthente flotën osmane dhe të njihte sovranitetin e padishahut; në këmbim iu sigurua valia e trashëgueshme e Egjiptit.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Ushtria egjiptiane zbrazi Sirinë dhe Çukurovën", "719a28dc"], "d": ["Pushtimi nëntëvjeçar mori fund; ushtria e Ibrahim Pashës u kthye në Egjipt përmes Sinait. Në hartë brezi i gjerë nga Halepi në Gazë, nga Adana në Kretë kalon përsëri në administrimin e drejtpërdrejtë osman. Vendbanime të tjera që u humbën në të njëjtën datë: Urfa, Marashi, Tarsi, Antakia, Kandia (Kretë), Hama, Damasku, Jerusalemi, Jafa, Nablusi.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Fermani: valia e Egjiptit iu la si e trashëgueshme familjes së Mehmet Aliut", "87b89ff8"], "d": ["Fermani i padishahut e njohu valinë si të trashëgueshme brenda dinastisë, nga ati te i biri; në këmbim, numri i ushtrisë u ul në tetëmbëdhjetë mijë, taksa u lidh me Stambollin, u hoqën kompetencat për të prerë monedhë dhe për të lidhur traktate. Egjipti mbeti vilajet, por tashmë ishte vendi i një dinastie më vete. Administrimi i Hixhazit dhe i Haremejnit iu kthye Portës së Lartë. Vendbanime të tjera që po në atë datë kthehen nga shtresa vartëse në atë të drejtpërdrejtë: Meka, Medina, Xhida, Jenboja.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konventa e Londrës për Ngushticat", "0e95a1ea"], "d": ["Konventa që zëvendësoi Hünkâr İskelesin përcaktoi që në kohë paqeje ngushticat të ishin të mbyllura për të gjitha anijet luftarake. Kështu privilegji që Rusia e kishte fituar vetë u shndërrua në garanci të përbashkët të Evropës; çështja e ngushticave fitoi status ndërkombëtar.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasha u bë de fakto vali i Egjiptit", "9e14f5d9"], "d": ["Në vend të Mehmet Aliut, që ishte plakur dhe kishte humbur aftësitë mendore, vali u bë i biri, Ibrahim Pasha. Por pas pak muajsh, në nëntor 1848, vdiq para të atit.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Vdekja e Mehmet Ali Pashës nga Kavalla", "871310e0"], "d": ["Valiu, i lindur në Kavallë, që krijoi dinasti në Egjipt dhe dy herë e çoi perandorinë në buzë të greminës, vdiq tetëdhjetë vjeç. Dinastia që themeloi sundoi në Egjipt deri në vitin 1953; shteti, duke parë se plagën që hapi ai mund ta mbyllte vetëm me ndërhyrjen evropiane, përparoi në rrugën e Tanzimatit.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Sulejman b. Kutallmëshi u mund dhe vdiq në Ajnusejlem; Antiokia doli nga selxhukët e Anadollit", "0412dfa1"], "d": ["Sulejman b. Kutallmëshi, që më 1084 ia mori Antiokinë Bizantit, vdiq në betejën e Ajnusejlemit kundër Tutushit, sundimtarit selxhuk të Sirisë; qyteti kaloi nën kontrollin e Melikshahut, sulltanit të selxhukëve të mëdhenj, dhe Jagisijani u emërua vali.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Vdiq Melikshahu; Antiokia bashkë me Jagisijanin iu lidh Tutushit, selxhukut të Sirisë", "c61da1b4"], "d": ["Pas vdekjes së Melikshahut, sulltanit të selxhukëve të mëdhenj, shteti u nda mes trashëgimtarëve; valiu i Antiokisë, Jagisijani, iu lidh Tutushit, zotit të Sirisë.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikea iu dorëzua kryqtarëve; qendra selxhuke u tërhoq në Konja, Bizanti filloi të rimerrte Anadollin perëndimor", "8a4e90fa"], "d": ["Pas rrethimit të Nikeas nga kryqtarët, qyteti më 19 qershor 1097 iu dorëzua Bizantit; sulltani selxhuk Këlëç Arslani I e tërhoqi qendrën në brendësi, në Konja, ndërsa Bizanti rimori vende si Efesi në brigjet e Anadollit perëndimor.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Këlëç Arslani II ia mori Bizantit Dorileumin (Eskishehirin) dhe Kutahjan", "3ddee6c2"], "d": ["Pas Miriokefalonit (1176), kështjellat bizantine të Dorileumit dhe Kutahjas në brendësi të Anadollit, në vitet e fundit të Manuelit/pas vdekjes së tij, më 576/1180 kaluan në duart e Këlëç Arslanit II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoglu Mehmet Beu u emërua subash i Ermenekut dhe mori nën administrim Iç Ilin", "6d62be11"], "d": ["Karamanoglu Mehmet Beu në vitin 675 (1276) u emërua subash i Ermenekut dhe vuri nën administrimin e vet Iç Ilin; Ermeneku u bë qendra e parë e Karamanogullëve, që vitin pasues do të marshonin mbi Konja.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Vdekja e Ertogrul Gaziut dhe kalimi i Osman Beut në krye të bejlikut — trashëgimia e Sëgytit dhe e Domaniçit", "395fb9fa"], "d": ["Sipas TDV-së, Ertogrul Gaziu vdiq në vitin 680 (1281-82); zëri shënon se jepen edhe datat 1288 dhe 1289. Osman Beu nga i ati nuk mori një qytet të pushtuar, por dy caktimet që sulltani selxhuk ia kishte dhënë Ertogrulit, të cilin e kishte vendosur në vijën më të përparuar të zonës kufitare: në Sëgyt një jurt (kullotë dimërore) dhe në Domaniç një verishte (kullotë verore). Pra bejliku e nisi punën jo me një trashëgimi pushtimi, por me dy caktime kullotash; në hartë këto dy vende paraqiten jo si 'pushtim', por si 'trashëgimi'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vesprat Siçiliane — dinastia Anzhu humbi ishullin e Siçilisë", "547db635"], "d": ["Kryengritja që shpërtheu në Palermo, të hënën e Pashkëve, në kohën e lutjes së mbrëmjes, kundër sundimit të Karlit I të Anzhuit, e shkëputi ishullin e Siçilisë nga dinastia Anzhu. Mbretëria e Siçilisë u nda në dy pjesë: ishulli u drejtua nga Aragona, kurse dinastia Anzhu u mbajt në mbretërinë kontinentale me qendër Napolin. Edhe zotërimet e jashtme të dinastisë në Adriatik dhe Mesdhe mbetën të lidhura me këtë mbretëri: Korfuzi, në duart e tyre që nga viti 1267, dhe Durrësi, që e mbanin nga vitet 1270, vazhduan si pjesë e Mbretërisë së Napolit; edhe kalatë e Vlorës, Kaninës dhe Himarës në bregun shqiptar mbetën në mbretërinë me qendër Napolin (komandanti i Vlorës, John of Taxis, rezistoi kundër bizantinëve gjatë gjithë vitit 1282; Durrësi, Vlora dhe Kanina me shumë gjasë i kaluan Bizantit në fillim të vitit 1285). Kurse Malta ra në duart e aragonezëve vetëm në vitin 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Sulmi i befasishëm mbi Kulaxhahisar — operacioni i parë ushtarak i Osman Beut", "79b00b14"], "d": ["Zëri Osman I i TDV-së: 'Ai plaçkiti dhe i vuri zjarrin kalasë së vogël Kulaxha pranë Inegëlit (684/1285).' Ky është veprimi i parë ushtarak i Osman Beut që mund të datohet në burime. Nuk u mor ndonjë vendbanim i përhershëm, kështjella u plaçkit dhe u dogj; prandaj, më shumë se pushtim, është një sulm tipik kufitar. Konsiderohet pikënisja e veprimtarisë ushtarake të bejlikut.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Pushtimi i Karaxhahisarit — fitimi i parë i qytetit dhe sundimi mbi Eskishehir", "178ae619"], "d": ["Zëri Osman I i TDV-së: Osman Beu në vitin 687 (1288) 'duke pushtuar Karaxhahisarin u bë zot i Eskishehirit'. Ky është fitimi i parë i vërtetë i një qyteti nga bejliku dhe, sipas rrëfimit, me këtë sukses Osman Beu u ngrit në gradën e sanxhakbeut në kufi; tregohet se hytbeja e parë e xhumasë në emrin e tij u lexua në Karaxhahisar dhe se aty u emërua kadiu i parë. Zëri i TDV-së për Eskishehirin vëren se tradita osmane jep datën 1291, por saktësia e saj është e dyshimtë.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Rënia e Akkës te memlukët — dëbimi i kryqtarëve nga bregu i Sirisë: Sidoni dhe Bejruti", "3ca7a464"], "d": ["Akkën, që për një kohë të gjatë ishte qendra e Mbretërisë Kryqtare të Jerusalemit, e pushtoi sulltani memluk al-Ashraf Halil dhe sundimi i kryqtarëve në Palestinë mori fund. Kalorësit templarë të tërhequr nga Akka u strehuan në Sidon; kur u afrua ushtria memluke, ata e lanë kështjellën detare, ikën në Qipro dhe qyteti po atë verë u kaloi memlukëve. Edhe Bejruti, në duart e kryqtarëve që nga viti 1197, në 1291 u mor nga valiu i Damaskut, Sanxhar ash-Shuxhai. Kështu prania kryqtare dyshekullore u fshi nga bregu Siri-Palestinë.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Pushtimi i Bilexhikut dhe i Jarhisarit me sulm nate", "f461b0af"], "d": ["Zëri Bilexhik i TDV-së: 'Edhe pse tekfurët e tjerë të krahinës, midis tyre tekfuri i Bilexhikut, përgatitën një atentat kundër Osman Gaziut, pasi u mor vesh ky komplot, forcat osmane me një sulm të befasishëm pushtuan Jarhisarin dhe Bilexhikun (1299).' Të dyja kalatë u morën në një operacion të vetëm, në të njëjtin sulm nate. Kjo datë është kthesa e pranuar si viti i themelimit të Shtetit Osman. Vende të tjera që u bashkuan në të njëjtën datë: Inegël.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Beteja e Kojunhisarit (Bafeut) — fitorja e parë e madhe kundër ushtrisë bizantine", "584a9512"], "d": ["Zëri Osman I i TDV-së: Osman Beu më 27 korrik 1302 luftoi në Bafe (Kojunhisar) me ushtrinë bizantine dhe e mundi. Kjo fitore është kthesa që e ngriti Osman Beun nga një bej kufitar krahinor në statusin e themeluesit të dinastisë. Pas betejës, fusha e Bursës hyri nën kontrollin osman dhe filloi bllokada e Iznikut.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Fitorja e Dimbosit dhe më pas marrja e Kites dhe e Ulubatit", "e168ab64"], "d": ["Zëri Osman I i TDV-së: në vitin 702 (1303), aleanca e krijuar nga tekfurët e Bursës, Kestelit, Kites dhe Adranosit u shpartallua në Grykën e Dimbosit; armiku, duke luftuar, u shty deri në grykën e ngushtë dhe tekfuri i Kestelit vdiq në fushën e betejës. Menjëherë pas fitores u morën kalatë e Kites dhe të Ulubatit, u pre lidhja tokësore e Bursës dhe u shtrëngua bllokada. Në këtë betejë mori pjesë edhe Orhani i ri.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Fushata e Sakarjas: marrja e Leblebixhihisarit, Lefkes, Mekexhes dhe Gejves", "a51ba4d3"], "d": ["Zëri Osman I i TDV-së jep radhën e fushatës së Sakarjas të vitit 704 (1304): 'Kur arriti në kalanë Leblebyxhi, tekfuri u nënshtrua... Arriti në Lefke... Arriti në Mekexhe... Shkoi në Gejve dhe mori kështjellën që e gjeti të braktisur.' Lefkja është porta e luginës së Sakarjas që hapet drejt Bilexhikut. Kjo fushatë e vetme, duke e kaluar nën kontrollin osman vargun e kalave përgjatë luginës, mbylli krahun lindor të pellgut të Iznikut.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Kiosi kaloi nën kontrollin e familjes gjenoveze Zaccaria", "9eebe4de"], "d": ["Përballë kërcënimit të Ajdënogullëve, perandori bizantin i kërkoi ndihmë gjenovezit Benedetto Zaccaria; ishulli kaloi nën kontrollin e tij (vasalitet nominal bizantin). Sundimi i Zaccarias zgjati deri më 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samosi hyri në pronësinë e gjenovezëve (Zaccaria) të Kiosit", "0e6f51e3"], "d": ["Familja gjenoveze Zaccaria, që vuri nën kontroll Kiosin, e bashkoi me pronat e saj edhe Samosin, pothuajse të zbrazur (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Pushtimi i kalave të Grykës së Gejves: Karaçepüsh, Karatigin dhe Absu", "76907c78"], "d": ["Zëri Orhan i TDV-së: Orhani, në fushatën e Sakarjas të vitit 705 (1305), 'pushtoi kalatë Karaçepüsh (Katoikia), Karatigin përpara Iznikut dhe Absu (Hypsu: në Grykën e Gejves)'. Këto tri kala, duke mbyllur kalimin midis luginës së Sakarjas dhe pellgut të Iznikut, ia prenë plotësisht Iznikut ndihmën tokësore. Në Karaçepüsh dhe Absu të grykës së Gejves u vendos Gazi Abdurrahmani; qyteti tashmë mund të rrëzohej vetëm me uri.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Fushata e Adranosit (Orhaneli) — fushata e fundit e Osman Beut", "4811546c"], "d": ["Zëri Orhan i TDV-së e shënon fushatën e Kalasë së Adranosit në vjeshtën e vitit 1323 si fushatën e fundit të Osman Beut. Tekfuri i Adranosit ishte anëtar i aleancës së tekfurëve të krijuar njëzet vjet më parë në Dimbos kundër Osmanëve; kjo fushatë do të thoshte mbyllje e asaj llogarie. Dita e saktë e pushtimit të kalasë nuk dihet; operacionin e vazhdoi Orhan Beu.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Vdekja e Osman Gaziut dhe kalimi i Orhan Beut në krye të bejlikut", "021487cd"], "d": ["Osman Gaziu, që i dha emrin bejlikut, vdiq në vitin 724 (1324), siç dëshmojnë vakëfnamet e Asporça Hatunit dhe të Mekexhes. I biri, Orhani, që që nga viti 1305 ishte në krye të ushtrisë në fushata, pas vdekjes së të atit u vendos në krye të bejlikut pa asnjë grindje për fron. Fakti që brezi themelues e dorëzoi flamurin pa tronditje tregon se dinastia e kaloi me qetësi provën e saj të parë të madhe në rrugën nga bejliku kufitar te shteti.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Marrja e Kiosit nga Zaccaria dhe lidhja me Bizantin", "f6741b26"], "d": ["Perandori Androniku III e largoi Zaccarian nga ishulli dhe e lidhi ishullin me Bizantin me Benedetton III si guvernator. Ishulli më 1346 do të pushtohej nga gjenovezi Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samosi u kthye nga Zaccaria te Bizanti (zinxhiri i Kiosit)", "08034974"], "d": ["Me shembjen e senjorisë së Zaccarias (lidhja e Kiosit me Bizantin më 1329) mori fund edhe pronësia gjenoveze në Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Beteja e Pelekanonit (Maltepe) dhe marrja e gjithë Koxhaelit", "389e7bd4"], "d": ["Zëri Orhan i TDV-së: ditën e parë të betejës Orhan Gaziu, për të tërhequr ushtrinë bizantine, dërgoi një forcë prej treqind vetash; ditën e dytë, me zbritjen në fushë të njësive nën komandën e Pazarlusë, beteja u zgjerua dhe, kur perandori u plagos me shigjetë, në ushtrinë bizantine ra paniku. Përfundimi është i prerë: 'Orhani mori gjithë Koxhaelin; pas fitores, banorëve të Iznikut nuk u mbeti asnjë shpresë.' Qytezat bregdetare nga Hereke deri në Yskydar hynë nën sundimin osman dhe Gebzeja u bë qendra e krahinës. Kjo ishte ushtria e fundit perandorake bizantine që erdhi për të shpëtuar Stambollin.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Themelimi i medresesë së parë osmane në Iznik", "c85fb625"], "d": ["Orhan Beu, menjëherë pas marrjes së Iznikut, emëroi aty kadi Çandarli Kara Halilin, shndërroi një bazilikë në xhami dhe, duke ndërtuar pranë saj një imaret dhe një medrese, nisi ndërtimin e qytetit. Sipas zërit Davud Kajseriu të TDV-së, ndërtimi i medresesë përfundoi në vitin 1336 dhe Orhan Gaziu caktoi si myderriz të saj Davud Kajseriun me 30 akçe në ditë. Kjo medrese është hapi i parë institucional i jetës shkencore osmane; bejliku i shtoi fuqisë së pushtimit edhe një traditë dijeje. Shndërrimi i një kryeqyteti bizantin të pushtuar në qendër të dijes islame ishte shenja e parë konkrete e pretendimit osman për t'u bërë shtet i ngulitur.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizanti bëhet haraçpagues — rrethimi i Izmitit dhe traktati", "0c1ec8d3"], "d": ["Zëri Orhan i TDV-së: Orhani, në verën e vitit 733 (1333), e rrethoi Izmitin me një ushtri të madhe dhe me katapulta, dhe perandori pranoi marrëveshje. Në këmbim të heqjes së rrethimit, Bizanti pranoi t'i paguante Orhanit 12.000 monedha ari (hyperper) në vit; 'kështu, në sytë e emirit osman, Bizanti ra në gjendjen e një vendi haraçpagues'. Në këmbim, Orhani do të bëhej mik i perandorit dhe nuk do të sulmonte qytetet vartëse të Bizantit. Fakti që një bejlik kufitar e lidhi me taksë Romën e Lindjes ishte shpallja se sa ishte përmbysur ekuilibri i forcave.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotraka kaloi nga venedikasit te familja gjenoveze Gattilusio", "c499ed5f"], "d": ["Venedikasit, që e mbanin ishullin që nga viti 1204, u nxorën nga ishulli nga familja gjenoveze Gattilusio.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksimi i Bejlikut të Karesit: Balikesiri, Bergama, Biga, Edremiti dhe Erdeku", "c7cb0511"], "d": ["Zëri Orhan i TDV-së (İnalcık) e vendos aneksimin në vitin 735 (1334-35): me vdekjen e Demirhan Beut, gazitë e Karesit dhe Haxhi Ilbeu e ftuan Dursun Beun në fron dhe i kërkuan ndihmë Orhanit. Orhani marshoi fillimisht mbi Balikesir; kur Dursun Beu, që po shkonte për bisedime paqeje, vdiq nga një shigjetë e hedhur nga kalaja e Bergamës, bejliku iu bashkua tërësisht vendit osman. Në të njëjtin operacion Kirmasti dhe Mihaliçi u nënshtruan, u mor Gëljaza dhe u pushtua përfundimisht Ulubati, i lënë më parë me garanci sigurie. Orhani emëroi Sulejman Pashën në sanxhakun e Karesit dhe e bëri Bigën qendër kufitare — kështu u fitua kuadri detar i kalimit në Rumeli. Shënim: zëri Karesiogllutë i TDV-së për të njëjtën ngjarje jep datën 746 (1345); enciklopedia bie në kundërshtim me veten. Vende të tjera që u bashkuan në të njëjtën datë: Çanakkala.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samosi hyri në pronësinë e Maonës së Kiosit", "01628b2f"], "d": ["Me marrjen e Kiosit nga gjenovezi Simone Vignosi dhe lënien e administrimit shoqërisë Maona, edhe Samosi hyri në pronësinë e gjenovezëve të Kiosit (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Kapitulacioni i parë i Orhan Gaziut me gjenovezët", "e64cb196"], "d": ["Orhan Gaziu, që gjatë luftës venedikaso-gjenoveze u mor vesh me gjenovezët, pas betejës së Bosforit në shkurt 1352 dërgoi 1000 harkëtarë për mbrojtjen e Perës dhe dha 60.000 monedha ari për transportin e ushtarëve; në këmbim u dhuroi gjenovezëve kapitulacionin e parë. Teksti i plotë i traktatit nuk ka mbërritur deri në ditët tona. Kjo është marrëveshja e parë zyrtare e Osmanëve me një fuqi detare evropiane dhe do të ripërtërihej tridhjetë e pesë vjet më vonë, në 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Marrja e Galipolit — krye-urë e përhershme në Rumeli", "ba51a160"], "d": ["Osmanët morën në vitin 1354 Galipolin, rrethinat e të cilit i njohën si aleatë të Kantakuzenit midis viteve 1349-1352; mundësinë e kishte krijuar tërmeti i madh që shembi muret e qytetit. Kështu krye-ura e ngushtë në Çimpe u shndërrua në një bazë të vërtetë në anën rumeliote të Bosforit dhe dera drejt Trakës u hap krejt. Galipoli do të dilte nga duart në vitin 1366 me Kryqëzatën e Savojës, por me pushtimin e dytë të vitit 1376 do të hynte përfundimisht nën sundimin osman. Vende të tjera që u bashkuan në të njëjtën datë: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Vdekja e Sulejman Pashës, pushtuesit të Rumelisë", "2dc98228"], "d": ["Sulejman Pasha, djali i madh i Orhan Beut dhe arkitekti i pushtimeve të Rumelisë, vdiq duke rënë nga kali gjatë një gjuetie në vjeshtën e vitit 1357, data më e pranuar ndër datat që burimet japin: 758 (1357), 759 dhe 760 (1359). Vdekja e shehzadesë, që me kalimet midis viteve 1352-1354 krijoi praninë e përhershme osmane në Rumeli, ia la radhën e trashëgimtarit të vëllait, Muratit. Tyrbja e Sulejman Pashës, të varrosur në Bolajir, mbeti monumenti më i vjetër dinastik osman në Evropë.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Ligji i Penxhikut — hedhja e themeleve të Korpusit të Jeniçerëve", "e5877c2d"], "d": ["Pas pushtimeve të Rumelisë, me këshillën e Kara Rustem Karamanliut nga ulemaja, hyri në fuqi sistemi i penxhikut, që parashikonte ndarjen për shtetin të një të pestës së robërve të luftës ose të vlerës së saj në para. Me përgatitjen e të përzgjedhurve nga këta robër pranë familjeve turke dhe marrjen në ushtri u formua bërthama e një force këmbësorie të përhershme, të lidhur drejtpërdrejt me padishahun — Korpusi i Jeniçerëve. Shndërrimi i një bejliku kufitar të mbështetur te kalorësia fisnore në një shtet me ushtri qendrore filloi me këtë rregullim.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Zbritja në Trakën Perëndimore: pushtimi i Gjymylxhinës", "9ef69221"], "d": ["Pas marrjes së Edrenesë, forcat kufitare që u drejtuan në perëndim të Maricës, nën komandën e Gazi Evrenos Beut, morën Gjymylxhinën, qendrën e Trakës Perëndimore. Qyteti u bë shtabi i përparuar prej nga Evrenos Beu do t'i shtrinte sulmet në Maqedoni. Kështu pjesa e Trakës që shtrihet deri në bregun e Egjeut hyri nën kontrollin osman dhe u hap rruga e Selanikut.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna i kaloi Principatës së Dobruxhës dhe u bë kryeqytet", "2bfe73f9"], "d": ["Në procesin e shpërbërjes së Caratit Bullgar, Varna, në bregun e Detit të Zi, iu bashkua Principatës së Dobruxhës së themeluar nga Dobrotiçi dhe u bë kryeqytet i këtij shteti të vogël.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Në perëndim të Filipopojës: bashkimi i Tatarpazarxhikut dhe i Ihtimanit", "1664d0e1"], "d": ["Pas marrjes së Filipopojës në vitin 1372, Tatarpazarxhiku, në skajin e sipërm të luginës së Maricës, dhe Ihtimani, që zinte qafën që hapet drejt Sofjes, u lidhën me administrimin osman. Kjo vijë, në duart e bejlerëve vendorë të vasalizuar pas Betejës së Çirmenit, u kalua në administrim të drejtpërdrejtë dhe itinerari Filipopojë-Sofje u bë i pandërprerë. Ky përparim është përgatitja e rrugës që dymbëdhjetë vjet më vonë do të çonte në pushtimin e Sofjes.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Kryengritja e Savxhë Beut — rebelim i përbashkët i shehzadesë dhe princit trashëgimtar bizantin", "75198c33"], "d": ["Savxhë Beu, i biri i Muratit I, dhe Androniku Paleolog, i biri i perandorit bizantin Joan V, në fillim të majit 1373, njëkohësisht në Bursë dhe në Stamboll u ngritën kundër etërve të tyre. Kjo aleancë që bashkonte trashëgimtarët e dy dinastive u shtyp shpejt; Savxhë Beu u kap, iu shuan sytë me hekur të nxehtë dhe u ekzekutua. Data 787 (1385) që rrëfimi osman jep për kryengritjen është e gabuar; ngjarja bie menjëherë pas viteve kur Bizanti hyri në vasalitetin osman dhe tregon sa shumë ishin ndërthurur dy sarajet.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Luginat e Strumës dhe të Mestës: bashkimi i Qystendilit, Petriçit, Nevrokopit dhe Dramës", "8c0980c4"], "d": ["Luginat e Strumës dhe të Mestës, në duart e bejlerëve vendorë serbë dhe bullgarë që pas fitores së Çirmenit filluan t'u paguanin haraç Osmanëve, me përparimin e bejlerëve kufitarë u morën nën administrimin e drejtpërdrejtë osman. Me bashkimin e Qystendilit, Petriçit, Nevrokopit dhe Dramës u hap gjysma lindore e Maqedonisë dhe Selaniku e Serezi hynë në unazën e rrethimit. Zgjerimi i Rumelisë drejt jugperëndimit në hartë është pasojë e këtij operacioni.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Fundi i Bejlikut të Eretnës dhe themelimi i Shtetit të Kadi Burhanedinit", "60dcaf57"], "d": ["Eretnaogllutë, që lindën nga valiu ilhanid në vitin 1335 dhe për dyzet e gjashtë vjet sunduan Anadollin Qendror me qendra Sivasin dhe Kajserinë, u shpërbënë nga grindjet brenda sarajit. Kadi Burhanedini, që u bë vezir në maj 1378, pasi eliminoi rivalët Këlëçarsllan dhe Haxhi Shadgeldi, në vjeshtën e vitit 1381, duke shpallur sulltanatin e vet, i dha fund bejlikut dhe themeloi shtetin që mban emrin e tij. Kështu ndërroi dorë fqinji lindor i Osmanëve; vija Sivas-Kajseri pas kësaj do të mbetej shtatëmbëdhjetë vjet në duart e Kadi Burhanedinit.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timuri mori Heratin: fundi i dinastisë Kert dhe kalimi i Horasanit te timuridët", "15f6019e"], "d": ["Horasani, në vitin 1380, ishte i copëtuar nga lufta midis Sarbedarëve, Kertëve dhe Muzaferidëve. Timuri, pasi e dërgoi të birin, Miran Shahun, në krahinë, vetë marshoi mbi Herat dhe, pas një rrethimi, e mori qytetin nga meliku Kert Gijasedin Pir Aliu. Kryengritja që shpërtheu pas largimit të tij u shtyp me gjak nga Miran Shahu dhe iu dha fund dinastisë Kert, që sundonte në Herat që nga viti 1255. I gjithë Horasani, nga Mashhadi në Nishapur, në këtë datë hyri nën administrimin timurid.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Përparimi në brendësi të Maqedonisë: pushtimi i Manastirit dhe i Ohrit", "63bb7838"], "d": ["Manastiri mbi Via Egnatia dhe Ohri në bregun e liqenit hynë nën administrimin osman gjatë sulmeve në drejtim të Shqipërisë. Të dy ishin pika kyçe të rrugës që shtrihet drejt Adriatikut; Ohri ishte gjithashtu një nga qendrat më të vjetra kryepeshkopale ortodokse të Ballkanit. TDV shënon se për datën e pushtimit të Ohrit nuk ka të dhëna të sakta dhe se janë propozuar datat 787 (1385) dhe 797 (1395), pas vdekjes së Kraliviç Markos; këtu u mor për bazë viti 1385. Manastiri në shekujt pasues do të bëhej një nga qendrat ushtarake më të rëndësishme të Rumelisë.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Beteja e Savrës — hapja e dyerve të Shqipërisë", "dda6671b"], "d": ["Me kërkesën për ndihmë të beut shqiptar Karlo Topia, i shtrënguar nga dinastia Balsha, forcat osmane shpartalluan në fushën e Savrës ushtrinë e Balshës II; Balsha humbi jetën në fushën e betejës. Kjo betejë, ku hynë me ftesën e një beu vendas, u siguroi Osmanëve për herë të parë ndikim të përhershëm në tokat shqiptare që shtriheshin deri në brigjet e Adriatikut. Kjo politikë, që e shfrytëzonte grindjen midis bejlerëve të krahinës, do të bëhej metoda e pandryshueshme e pushtimeve ballkanike gjatë shekullit pasues.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Fushata trevjeçare' e Timurit: marrja e Azerbajxhanit dhe e Iranit Verior", "2a98ec51"], "d": ["Timuri, që gjatë fushatave në Horasan pa nga afër gjendjen e shpërndarë të Iranit, në vitin 788 (1386) marshoi drejt perëndimit. Në operacionin 1386-1388, i njohur si 'fushata trevjeçare', përmes Mazanderanit, Lorestanit dhe Gjeorgjisë kaloi në Azerbajxhan dhe arriti në Karabak; Tebrizi, Ardebili, Urmia dhe Nahçevani hynë nën administrimin timurid. Marrja e Iranit Verior dhe e Azerbajxhanit, ashtu si dikur midis ulusit të Xhoxhit dhe ilhanidëve, u bë fillimi i një përplasjeje të gjatë me Hordhinë e Artë.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Beteja e Frenkjazësë dhe rrethimi i Konjës — fushata e parë kundër Karamanit", "af4e5d77"], "d": ["Kundër Karamanogllu Alaedin Ali Beut, i cili, ndonëse ishte dhëndri i tij, ishte i shqetësuar nga zgjerimi osman në Anadollin Perëndimor, Murati I doli vetë në fushatë; në betejën e zhvilluar në vendin e quajtur Frenk Jazësi, ushtria osmane e stërvitur dhe me përvojë i mundi forcat e Karamanit. Më pas u rrethua kalaja e Konjës, por me faljen e Alaedin Beut bejliku nuk u zhduk plotësisht. Kjo fushatë është akti hapës i llogarive të gjata midis Osmanëve dhe Karamanit, që do të zgjaste një shekull dhe do të përfundonte vetëm me aneksimin përfundimtar në 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Mushi kaloi nga administrimi karakojunlu nën administrimin e Timurit (789/1387)", "ed2e7a11"], "d": ["Mushi, që pas periudhës mongole kaloi nën administrimin karakojunlu, në vitin 789 (1387) hyri nën administrimin e Timurit, i cili zotëroi tokat karakojunlu. Në atlas, Mushi në këtë vit shënohet si kalim nga karakojunlutë te timuridët.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Themelimi i Arsenalit të Galipolit — lindja e flotës osmane", "47546241"], "d": ["Arsenali i parë i organizuar i Shtetit Osman u themelua në vitin 1390 nga Bajazidi Jëlldërëm në Galipoli, në vendin e arsenalit të mbetur nga Bizanti. Osmanët, që trashëguan trashëgiminë detare të bejliqeve të Anadollit Perëndimor, kështu për herë të parë u bënë një fuqi detare që ndërtonte vetë anijet e veta. Arsenali, i vendosur në pikën kyçe të Ngushticës së Dardaneleve, nga rrethimi i Stambollit deri te fushatat në Egje, për një shekull e gjysmë shërbeu si baza kryesore e flotës osmane.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Vendi i Hamidit iu bashkua Osmanëve: Isparta, Burduri, Uluborlu, Egirdiri", "e3da7de5"], "d": ["Bajazidi Jëlldërëm, që doli në fushatë pas sulmit të Karamanogllu Alaedin Beut në vendin e Hamidit dhe ankesave të popullit, mori të gjitha tokat e mbetura të Hamidogllutëve dhe administrimin ia dha të birit, Isa Çelebiut.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fundi i dinastisë muzaferide: disfata e Shah Mansurit përpara Shirazit", "5fd14eb8"], "d": ["Shah Mansuri, sundimtari i fundit i fuqishëm i muzaferidëve, që sundonin në Jazd, Fars, Isfahan dhe Kerman nga viti 1318, u bashkua me të afërmit dhe u ngrit kundër Timurit. Në betejën pranë Shirazit, kur njëri nga emirët e tij kaloi në anën tjetër, ai humbi pjesën më të madhe të forcave, u mund dhe u vra. Kur Timuri më pas urdhëroi të vriteshin edhe të gjithë anëtarët e dinastisë, sundimi muzaferid mori fund dhe Farsi me Kermanin iu bashkuan administrimit timurid.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Bashkimi i Amasjas me tokat osmane", "fe2860cf"], "d": ["Emiri i Amasjas, i rrethuar gjatë operacionit të Bajazidit Jëlldërëm në Anadollin Qendror, ua dorëzoi qytetin Osmanëve dhe Bajazidi hyri në qytet në vitin 1393. Sulltani ia la administrimin këtij vendi të birit, Mehmet Çelebiut; Amasja si sanxhak shehzadesh pas kësaj u bë një nga vatrat më të rëndësishme të edukimit të dinastisë osmane. Vendbanime të tjera që u humbën në të njëjtën datë: Ladik (Amasja), Merzifon, Osmanxhik, Çorum. Kjo zgjedhje do të ishte vendimtare në Periudhën e ardhshme të Interregnumit, kur Mehmet Çelebiu do ta zhvillonte pikërisht nga kjo bazë e Amasjas luftën për ribashkimin e shtetit.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timuri pushtoi Bagdadin — xhelairidët ikën në Anadoll", "4d5602b3"], "d": ["Timuri, pas një rrethimi të gjatë, mori Bagdadin; sundimtari i qytetit, sulltan Ahmed Xhelairi, duke ikur drejt perëndimit, u strehua fillimisht te memlukët e pastaj në sarajin osman. Kështu zgjerimi i Timurit drejt perëndimit për herë të parë ra drejtpërdrejt në kontakt me zonën e ndikimit osman. Hallka e parë e armiqësisë midis dy sundimtarëve fillon këtu.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Marrja e Varnës në bregun e Detit të Zi", "a84b2abf"], "d": ["Gjatë shtrëngimit të tokave të Caratit Bullgar midis Danubit dhe Detit të Zi, Varna, porti më i madh i bregdetit, kaloi nën administrimin osman. Marrja e portit i hapi rrugën përparimit drejt Dobruxhës dhe u siguroi Osmanëve skelën e parë të madhe në bregun perëndimor të Detit të Zi. Varna, pesëdhjetë e një vjet më vonë, do të ishte edhe skena e fitores së vitit 1444, ku do të asgjësohej ushtria kryqtare.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Viset e Nevshehirit dhe Ürgüpit kaluan nga Karamanogullët në duart osmane", "06ff59e8"], "d": ["Gjatë fushatave të Bajazitit Rrufe (Yıldırım) kundër Karamanogullëve, viset e Nevshehirit (Muşkara) dhe Ürgüpit më 800/1398 kaluan nën administrimin osman; pas Betejës së Ankarasë më 1402, Timuri ua ktheu zonën Karamanogullëve.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Rënia e Shtetit të Kadi Burhanedinit", "b13391e3"], "d": ["Kadi Burhanedini, i zënë rob nga sundimtari akkojunlu Karajylyk Osman Beu, megjithëse propozoi të lirohej në këmbim të dorëzimit të Sivasit, populli i qytetit rezistoi dhe sulltani u ekzekutua përpara mureve. Parësia e Sivasit vuri në krye të birin, Alaedin Ali Çelebiun, por, përballë presionit akkojunlu, i kërkuan ndihmë Bajazidit Jëlldërëm; forcat osmane nën komandën e Sulejman Çelebiut e mundën Karajylykun dhe u bënë zot të qytetit. Kështu Shteti i Kadi Burhanedinit hyri në histori, dhe Sivasi, Tokati, Niksari dhe Kajseria iu bashkuan tokave osmane. Vende të tjera që u bashkuan në të njëjtën datë: Kërshehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Përballja me Timurin: u refuzua dorëzimi i të arratisurve", "33790bc8"], "d": ["Me presionin e Timurit, sulltan Ahmed Xhelairi dhe udhëheqësi i karakojunlive, Kara Jusufi, u strehuan në tokat osmane; Timuri kërkoi dorëzimin e këtyre dy të arratisurve, Bajazidi Jëlldërëm refuzoi. Pas kësaj midis dy sundimtarëve filluan të shkëmbeheshin letra me fyerje të rënda reciproke. Terreni ideologjik i luftës u ndërtua me këtë korrespondencë, para se të lëvizte qoftë edhe një ushtar i vetëm.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Spitali i Jëlldërëmit në Bursë — spitali i parë osman", "5f0dc59a"], "d": ["Bajazidi Jëlldërëm, në vitet kur ndërtonte në Bursë Xhaminë e mrekullueshme Ulu, i dhuroi qytetit edhe një darushifa (spital); ishte hallka e programit të gjerë të bamirësisë, të përbërë nga imareti, medreseja, hani dhe ura, që i kushtohej mjekësisë. Ky ndërtim, spitali i parë i ngritur nga shteti, duke luajtur edhe rolin e shkollës mjekësore që përgatiste mjekë, përcaktoi modelin e institucioneve shëndetësore osmane. Vepra, e përfunduar vetëm dy vjet para katastrofës së Ankarasë, është ndër hallkat e fundit të vizionit të Jëlldërëmit për ta shndërruar Bursën në kryeqytet perandorak.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timuri e rrafshoi Sivasin", "f4d79de6"], "d": ["Timuri, që marshoi mbi Sivas me udhërrëfimin e akkojunlut Karajylyk Osman Beu dhe të emirit të Erzinxhanit, Mutahhartenit, e rrethoi qytetin tetëmbëdhjetë ditë dhe, pasi e mori me premtimin se nuk do të derdhej gjaku i askujt, bëri një masakër të madhe; mbrojtësit i hodhi në hendeqe dhe urdhëroi t'i mbulonin të gjallë. U shkatërruan veprat e rëndësishme të qytetit, në radhë të parë muret, dhe Sivasi u shemb demografikisht. Kjo është goditja e parë e madhe që Timuri u dha tokave osmane dy vjet para Betejës së Ankarasë.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bajazidi Jëlldërëm rimori Erzinxhanin dhe Kemahun", "7047ca08"], "d": ["Bajazidi Jëlldërëm, duke përfituar nga dalja e Timurit në fushatën e Sirisë, ia mori emirit të Erzinxhanit, Mutahhartenit, vartës i Timurit, Erzinxhanin dhe Kemahun. Megjithëse nuk kishte ndërhyrë në shkatërrimin e Sivasit, ky veprim ishte një sfidë e drejtpërdrejtë ndaj zonës së ndikimit të Timurit në Anadollin Lindor. Pas kësaj marrëdhëniet midis dy sundimtarëve u bënë të pariparueshme.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatumi i Timurit nga Tebrizi — katër kushte", "3e1ac50e"], "d": ["Timuri, me ambasadorin që dërgoi nga Tebrizi, njoftoi katër kushte: kthimin e Kemahut te Mutahharteni, kthimin pronarëve të tokave të marra nga bejlerët e Anadollit, dërgimin e një shehzadeje osman si peng dhe pranimin e kësulës dhe brezit si shenjë vartësie, si dhe dorëzimin e Kara Jusufit. Bajazidi nuk pranoi asnjërin prej tyre; megjithë këmbënguljen e burrështetasve dhe ndërmjetësimin e Mutahhartenit, bisedimet dështuan. Timuri ishte i vendosur ta mbyllte përfundimisht çështjen e Anadollit para se të dilte në fushatën kundër Kinës.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanogllutë u rikrijuan — Manisa doli nga Osmanët", "ac747b05"], "d": ["Tri javë pas disfatës së Ankarasë, me mbështetjen e Timurit, Orhan Beu kaloi në krye të bejlikut dhe vendi i Saruhanit u bë përsëri i pavarur. Krahina me qendër Manisën, dymbëdhjetë vjet pas aneksimit osman të vitit 1390, doli nga harta. Kjo është një nga zbatimet e para me datë të njohur saktësisht të politikës së Timurit për ringjalljen e bejliqeve.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Sulejmani iku në Rumeli me thesarin shtetëror", "0a2b7363"], "d": ["Emir Sulejmani, duke marrë me vete thesarin shtetëror në Bursë, arkivat, familjen dhe vëllezërit, nga Gemliku me anije kaloi në Güzelcehisar (Anadoluhisari), prej andej arriti në Galipoli dhe në Edrene shpalli sundimin e vet. Zhvendosja në Rumeli e arkivit dhe e thesarit shtetëror është fillimi i kalimit, për një brez, të qendrës së rëndesës osmane në Ballkan. Në hartë Rumelia që nga kjo datë vizatohet me ngjyrën e vetë Emir Sulejmanit.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timuri i rikrijoi bejliqet e Anadollit — bashkimi turk u shpërbë", "15187774"], "d": ["Timuri, pas fitores së Ankarasë, ua ktheu tokat e dikurshme bejlerëve që kishte pranë. Karamanogllu Mehmed Beut dhe Ali Beut u dha vendi i Karamanit me Kajserinë, Kërshehirin, Sivrihisarin dhe Bejshehirin; Germijanogllu Jakub Beut II iu dha Kytahja dhe vendi i Germijanit; Xhandarogllu Isfendijar Beut, përveç vijës Kastamonu-Sinop, iu dhanë Çankëri dhe Kalexhiku. Edhe vendet e Ajdënit, Mentesheut dhe Tekesë u kthyen te dinastitë e dikurshme. Bashkimi turk i Anadollit, që Bajazidi Jëlldërëm e kishte ndërtuar për dhjetë vjet, u shpërbë brenda një vere; në hartë këto bejliqe shfaqen përsëri me ngjyrat e veta. Vendbanime të tjera që ndërruan dorë në të njëjtin proces: Aksaraj, Denizli, Eregli (Konja), Ermenek, Ilgën, Karapënar, Kajseri, Konja, Kërshehir, Kytahja, Sivrihisar, Sëke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timuri ua mori Izmirin kalorësve të Shën Gjonit", "66dd1dd4"], "d": ["Timuri, që zbriti drejt perëndimit përmes Kytahjas, Denizlisë, Ajdënit, Ajasolukut dhe Tires, e rrethoi dhe e mori Izmirin bregdetar, në duart e të krishterëve që nga viti 1344. Duke e pushtuar brenda një kohe të shkurtër këtë kala që Bajazidi Jëlldërëm nuk kishte mundur ta merrte për vite, Timuri, pasi mori edhe kalatë përreth, ua la vendin e Ajdënit zotërve të dikurshëm dhe u kthye në lindje. Qyteti pas kësaj hyri nën administrimin e Ajdënogllu Xhunejd Beut.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Çelebiu mori Bursën — lindi pjesa e Anadollit", "955128c1"], "d": ["Isa Çelebiu, që pas disfatës së Ankarasë ishte tërhequr në anët e Karesit, mori Bursën ndërsa Timuri ishte në Izmir. Në kryeqytetin e dikurshëm, të plaçkitur e të djegur nga ushtarët e Timurit, shpalli sundimin e vet dhe urdhëroi të pritej monedhë në emrin e tij; në janar 1403 njihej në Anadoll me titullin 'sundimtari i turqve'. Në hartë kjo pjesë, që shtrihet përgjatë bregut aziatik të Marmarasë, duket me ngjyrën e vetë Isa Çelebiut.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Tërheqja e Timurit nga Anadolli", "93a98839"], "d": ["Timuri, që mori lajmin e vdekjes së Bajazidit Jëlldërëm në Akshehir, duke e konsideruar të përfunduar punën në Anadoll, u drejtua nga lindja. Pas tij mbetën bejliqet që i shprehën besnikëri dhe shehzadetë osmanë të përçarë; disa qytete si Sivasi iu lanë emirëve vartës të Timurit si Mezid Beu. Timuri nuk u kthye më në Anadoll, por ky rend i copëtuar që krijoi zgjati dhjetë vjet.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Sulejmani kaloi në Anadoll: Bursa i ra në dorë", "9b27aa5f"], "d": ["Emir Sulejmani, që mori vesh disfatën e Isa Çelebiut, së bashku me Çandarli Ali Pashën kaloi në Anadoll me një ushtri të fortë dhe mori Bursën; regjistrimet e marsit 1404 tregojnë se edhe Eregli i Detit të Zi ishte nën administrimin e tij. Mehmet Çelebiu nuk mundi t'i rezistonte Sulejmanit, i cili brenda pak kohe u bë zot si i Rumelisë, ashtu dhe i pjesës më të madhe të Anadollit. Vendbanime të tjera që në të njëjtin proces kaluan nga Mehmet Çelebiu te Emir Sulejmani: Akjazë, Anadolu Hisari, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, Kalaja e Ajdosit, Ajvalëk, Balëkesir, Behramkale (Assos), Bergama, Bejkoz, Biga. Në hartë që nga kjo datë deri në rimarrjen e Bursës nga Mehmet Çelebiu (1410) të dy brigjet duken me një ngjyrë, në pjesën e Emir Sulejmanit.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Beteja e fushës së Jenishehirit — Mehmet Çelebiu u tërhoq në Amasja", "f1568288"], "d": ["Mehmet Çelebiu, që humbi Bursën dhe Ankaranë, u mund nga Emir Sulejmani në fushën e Jenishehirit, humbi të gjitha fitimet në Anadollin Perëndimor dhe u tërhoq në bazën Tokat-Amasja. Pas kësaj disfate, duke shmangur përplasjen e drejtpërdrejtë, u përqendrua në forcimin e autoritetit të vet në brendësi të Anadollit. Kështu filloi faza më e gjatë e heshtur e Interregnumit.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Sulejmani ia mori Ankaranë Mehmet Çelebiut", "d6a2acd6"], "d": ["Ankaranë, që pas tërheqjes së Timurit nga Anadolli kishte mbetur në duart e Mehmet Çelebiut, e rrethoi Emir Sulejmani në vitin 1406. Komandanti i kalasë, Jakub Beu, qëndroi për ca kohë, por me një dredhi të vezirit të madh Çandarli Ali Pashës ia dorëzoi kalanë Sulejmanit. Pas kësaj Mehmet Çelebiu u mor vesh me Karamanogllu Mehmed Beun dhe veproi kundër Sulejmanit.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Mehmet Çelebiu ia rimori Sivasin timuridit Mezid Beu", "90079b0c"], "d": ["Pas pushtimit timurid, administrimi i Sivasit i ishte lënë Mezid Beut, vartës i Timurit. Mehmet Çelebiu, në Amasja, dërgoi komandantin e vet, Bajazid Pashën, për ta marrë qytetin dhe, pas një rezistence të ashpër, Sivasi për herë të dytë kaloi në duart e dinastisë osmane. Kështu pjesa e Mehmetit, gjashtë vjet pas Betejës së Ankarasë, arriti në lindje kufirin e dikurshëm.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fundi i dinastisë Artukide: dorëzimi i Mardinit te karakojunlitë", "15b06f33"], "d": ["Artukidët, dega më jetëgjatë e dinastisë që sundonte në Mardin që nga viti 1106, nuk mundën të qëndronin përballë presionit akkojunlu. Melik Ahmedi, që kuptoi se nuk mund ta mbronte qytetin, u mor vesh me sundimtarin karakojunlu, Kara Jusufin, dhe ia dorëzoi Mardinin. Kështu mori fund sundimi artukid që kishte zgjatur mbi tre shekuj; Mardini me rrethinat, deri sa kaloi te Osmanët një shekull më vonë, u bë skenë e luftës midis karakojunlive dhe akkojunlive.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Beteja e Jambollit — Musa Çelebiu hyri në Edrene", "8f978408"], "d": ["Musa Çelebiu, që përmes Vllahisë kaloi në Rumeli, me mbështetjen vllahe dhe serbe i shpartalloi në Jamboll forcat e Emir Sulejmanit dhe hyri në Edrene. Gjatë Interregnumit Rumelia doli për herë të parë nga duart e Emir Sulejmanit. Por sundimi i tij nuk qe i qëndrueshëm; katër muaj më vonë, i mundur në Kosmidion, do të tërhiqej në brendësi të Ballkanit.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Beteja e Inxhegizit — disfata e parë e Mehmet Çelebiut në Rumeli", "3c35cd43"], "d": ["Mehmet Çelebiu, që me anijet e Bizantit kaloi në Rumeli, hyri në betejë me Musa Çelebiun në Inxhegiz; Musa, me shtatë mijë jeniçerë nën urdhrat e vet, e mundi Mehmetin dhe Mehmeti u detyrua të kthehej në Anadoll. Kjo disfatë e shtyu Mehmetin, në vend të luftës së drejtpërdrejtë, drejt strategjisë së tërheqjes në anën e vet të bejlerëve kufitarë të Rumelisë dhe të despotatit serb. Terreni i fitores së Çamurlusë, nëntë muaj më vonë, u përgatit me këtë diplomaci.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Rrethimi i Konjës dhe marrëveshja me Karamanogllutë — u rimorën vendi i Hamidit, Said-ili, Bejshehiri, Sejdishehiri dhe Akshehiri", "0996257e"], "d": ["Kundër Karamanogllutëve, që gjatë Interregnumit sulmonin tokat osmane dhe rrethuan e dogjën Bursën, Mehmet Çelebiu organizoi një fushatë të madhe dhe në muharrem 818 rrethoi Konjën. Karamanogllu Mehmed Beu II u detyrua të kërkonte paqe; si rezultat i marrëveshjes, vendi i Hamidit (krahina e Ispartës) dhe Said-ili iu bashkuan përsëri tokave osmane, u kthyen edhe Bejshehiri, Sejdishehiri dhe Akshehiri; edhe Sivrihisari, që Timuri ua kishte dhënë Karamanogllutëve në vitin 1402, iu kthye Osmanëve. Kjo fushatë, me të cilën filloi të arnohej bashkimi i Anadollit i shpërbërë nga Beteja e Ankarasë, është nga arsyet konkrete pse Mehmet Çelebiu konsiderohet 'themeluesi i dytë'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Marrja e Izmirit nga Ajdënogllu Xhunejd Beu", "2377ca51"], "d": ["Izmiri, qendra e Ajdënogllu Xhunejd Beut, që gjatë Interregnumit ndërronte vazhdimisht anë midis shehzadeve, pas një rrethimi dhjetëditor u mor nga Mehmet Çelebiu; Xhunejdi u fal dhe u dërgua sanxhakbej në Nikopojë. Kështu qyteti, që Timuri në vitin 1402 ua kishte kthyer Ajdënogllutëve, pas trembëdhjetë vjetësh iu kthye Osmanëve. Xhunejdi do ta rimerrte qytetin në vitin 1422, dhe çështja do të mbyllej vetëm në vitet 1424-1426 nga Murati II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Ekzekutimi i Torllak Kemalit — Saruhani përfundimisht osman", "8a09dbf1"], "d": ["Torllak Kemali, që drejtonte krahun e Anadollit Perëndimor të lëvizjes së Shejh Bedredinit, u mund në krahinën e Manisës dhe u ekzekutua. Pas kësaj date krahina e Saruhanit hyri përfundimisht nën kontrollin osman dhe bejliku që Timuri e kishte ringjallur në vitin 1402 hyri në histori. Kështu u pastruan mbetjet e fundit politike të Interregnumit në Anadollin Perëndimor.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Pushtimi i Vlorës, Beratit dhe Kaninës", "1e1949b8"], "d": ["Osmanët në vitin 1417 vunë nën sundim Vlorën në bregun e Adriatikut, së bashku me qytetin e Beratit në brendësi të vendit dhe Kalanë e Kaninës. Një vit më vonë përpjekja e Venedikut për ta rimarrë qytetin dështoi dhe duke u krijuar këtu një organizim sanxhaku, autoriteti osman u bë i përhershëm. Marrja e Vlorës, duke i bërë Osmanët për herë të parë zotër të drejtpërdrejtë të një porti në Adriatik, u dha një trampolinë përtej detit kundrejt Italisë.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Rimarrja e Anadollit Qendror: Kajseri dhe Kërshehir", "204eacb3"], "d": ["Qytetet e Anadollit Qendror, që gjatë Interregnumit kishin rënë në duart e Karamanogllutëve, gjatë fushatave të Mehmet Çelebiut për të rimëkëmbur shtetin u kthyen nën administrimin osman. Me bashkimin e Kajserisë dhe të Kërshehirit u rimor në masë të madhe pellgu i lumit Këzëlërmak, i humbur në Betejën e Ankarasë. Ky përparim është vazhdimi i politikës së drejtimit nga lindja, që filloi katër vjet më parë me rrethimin e Konjës.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Memlukët ia dhanë Kajserinë Nasirudin Muhamedit nga Dulkadirogllutë", "aad4b00c"], "d": ["Ushtria memluke që doli në fushatë kundër Karamanogllu Mehmed Beut pushtoi Kajserinë; komandanti memluk, duke ia lënë qytetin me rrethina Nasirudin Muhamedit të Dulkadirëve, u kthye në vendin e vet.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Vdekja e Mehmetit I dhe hipja në fron e Muratit II", "98acac77"], "d": ["Mehmeti I, që i dha fund Periudhës së Interregnumit dhe e bashkoi përsëri vendin osman në një dorë, vdiq në Edrene më 25 qershor 1421 dhe i biri Murati hipi në fron në Bursë. Sipas marrëveshjes së bërë me Bizantin para vdekjes, djemtë e tij të vegjël do të dërgoheshin si pengje pranë perandorit, kurse perandori nuk do ta lironte pretendentin për fron Mustafa Çelebi që e mbante në dorë; Murati II refuzoi t'i dërgonte vëllezërit te perandori.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Likuidimi përfundimtar i Tekeogllutëve: marrja e Antalisë", "e65565b2"], "d": ["Bejliku i Tekeogllutëve, i rikrijuar pas Betejës së Ankarasë me ringjalljen nga Timuri, mori fund me rrethimin e Antalisë nga forcat osmane nën komandën e Hamza Beut; njeriu i fundit i rëndësishëm i bejlikut, Osman Çelebiu, u eliminua. Kështu vendi i Tekesë në bregun e Mesdheut, pas njëzet e një vjet ndarjeje, iu bashkua përfundimisht Osmanëve. Bejliku sundonte në Antalia që nga viti 1321 si degë e shkëputur nga Hamidogllutë.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Fushata e Turahan Beut në More dhe shembja e murit Hexamilion", "c6c2706d"], "d": ["Për shkak të mbështetjes bizantine për pretendentin rival të fronit, Mustafa Çelebiun, Murati II dërgoi Turahan Beun kundër Moresë. Turahan Beu e shembi murin Hexamilion, që mbyllte nga një skaj në tjetrin Istmin e Korintit, hyri në gadishull dhe shkaktoi shkatërrime të mëdha. Paqja u arrit me kushtin që muri të mos ndërtohej më dhe të paguhej taksë vjetore; kështu despotati i Moresë u la ushtarakisht i pambrojtur dhe terreni i pushtimit përfundimtar të vitit 1460 u përgatit tridhjetë e shtatë vjet më parë.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Hyrja e manastireve të Athosit (Aynaroz) nën mbrojtjen osmane", "562de5ea"], "d": ["Në vitet kur Selaniku ishte nën rrethim, republika monastike e Athosit, në gishtin lindor të Kalkidikisë, iu drejtua Muratit II, kërkoi mbrojtje dhe pranoi sovranitetin osman. Të drejtat e pronësisë dhe të adhurimit të murgjve u garantuan; manastiret, në këmbim të taksës, u lanë të lira në punët e brendshme. Ky rend u bë shembulli më jetëgjatë i marrëdhënies së mbrojtjes që Osmanët krijuan me institucionet ortodokse dhe zgjati pesë shekuj.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksimi i Bejlikut të Taxheddinogllutëve: Niksari", "370ffd47"], "d": ["Me presionin e bejlerbeut të Amasjas, Jorgyç Pashës, Taxheddinogllu Husamedin Hasan Beu në vitin 830 (1427) dorëzoi çelësat e vendit të tij me qendër Niksarin; atij iu dha një sanxhak në Rumeli. Kështu mori fund bejliku i themeluar në gjysmën e dytë të shekullit XIV, kufijtë e të cilit herë-herë shtriheshin deri në Kelkit, Amasja, Samsun, Ordu dhe Giresun. Po atë vit u regjistruan edhe tokat e Haxhiemirogllutëve dhe u lidhën me sanxhakun e Xhanikut; u mbyll periudha e bejliqeve në Detin e Zi Qendror.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Lënia e Beogradit Hungarisë — Traktati i Tatës", "62481183"], "d": ["Pas vdekjes së despotit serb Stefan Lazarević, sipas Traktatit të Tatës, të lidhur mes mbretit hungarez Sigismund dhe trashëgimtarit Gjergj (Georg) Brankoviq, kështjella e Beogradit iu dorëzua Hungarisë. Kështjella, në pikën ku bashkohen Danubi dhe Sava, deri atëherë ishte në duart e despotatit serb dhe për osmanët ishte kyçi i derës që hapej drejt Evropës Qendrore. Ky dorëzim e bëri Beogradin për njëqind vjet pengesën më të fortë përpara përparimit osman: rrethimet e viteve 1440 dhe 1456 do të dështonin, dhe kështjella do të binte vetëm më 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardini kaloi nga rojtari karakojunlu te akkojunlu Karajylyk Osman Beu", "d82bc97f"], "d": ["Mardinin, që Kara Jusufi e mori në vitin 1409, karakojunlitë e qeverisën me valinj; emiri Nasir, i lënë si rojtar, ia dorëzoi qytetin në vitin 835 (1432) akkojunlu Karajylyk Osman Beut. Administrimi akkojunlu vazhdoi deri në fillim të shekullit XVI.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanogllutë ua morën Kajserinë Dulkadirëve", "2b09e8e8"], "d": ["Beu i Karamanit, me fitoren që korri kundër Dulkadirëve, i shtoi vendit të vet Kajserinë, Urgypin, Karahisarin e Develisë dhe Uçhisarin.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Ngjarja e Buçuktepes — kryengritja e parë e jeniçerëve dhe rikthimi në fron i Muratit II", "6388dda1"], "d": ["Ngjarja e Buçuktepes, që shpërtheu në Edrene dhe është kryengritja e parë e jeniçerëve që njeh historia, filloi me kërkesën për rritjen e rrogave me gjysmë akçeje dhe përfundoi me rrëzimin nga froni të Mehmetit II të ri. Murati II, më 8 safer 850, u nis me ngut nga Manisa dhe nisi sundimin e dytë. Ngjarja ishte shenja e parë se korpusi kapikulu ishte bërë tashmë një forcë me zë mbi fronin dhe i dha formë kujdesit që Fatihu do ta ruante gjithë jetën ndaj jeniçerëve.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Bashkimi i bregut të Epirit: Arta dhe Preveza", "796f7ecf"], "d": ["Nëntëmbëdhjetë vjet pas dorëzimit të Janinës në vitin 1430, edhe Arta dhe Preveza, në pjesën bregdetare të Despotatit të Epirit, hynë nën administrimin osman. Kështu u vu nën kontroll gjiri i Ambrakisë që hapet në Detin Jon dhe u plotësua lidhja detare e Janinës. Preveza është pika kyçe e gjirit që nëntëdhjetë vjet më vonë do t'i jepte emrin fitores historike të Barbarosës.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Vdekja e Muratit II dhe hipja e dytë në fron e Mehmetit II", "8f8256ad"], "d": ["Murati II, që u sëmur pas dasmës së të birit, vdiq në Edrene më 1 muharrem 855 (3 shkurt 1451). Nëntëmbëdhjetëvjeçari Mehmeti II, më 16 muharrem 855 (18 shkurt 1451), hipi për herë të dytë në fronin osman — këtë herë përgjithmonë. Kthimi i sundimtarit të ri, i rrëzuar pesë vjet më parë në Buçuktepe, është fillimi i sundimit që dy vjet më vonë do të kurorëzohej me pushtimin e Stambollit dhe do ta shndërronte Bejlikun Osman në një perandori botërore.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Rrethimi i parë i Kafës nga forcat e përbashkëta osmano-krimease", "e346d163"], "d": ["Hani i Krimesë, Haxhi Giraji, i cili u mor vesh me Sulltan Mehmetin Fatih në qershor 1454, me 7000 kalorës e rrethoi Kafën nga toka; edhe një flotë osmane prej pesëdhjetë-gjashtëdhjetë galerash u vendos në det të hapur. Kafa gjenoveze e hoqi rrethimin duke paguar haraç dhe pushtimi përfundimtar mbeti njëzet e një vjet më vonë, në 1475. Ky operacion i parë i përbashkët ishte shembulli i parë i bashkëpunimit ushtarak osmano-krimeas, që do të përsëritej më pas në pushtimin përfundimtar të Kafës.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Marrja e ishujve të Egjeut Verior: Bozxhaada (Tenedos), Imbros dhe Taso", "76575895"], "d": ["Menjëherë pas pushtimit të Stambollit, Sulltan Mehmeti Fatih, për të siguruar rrugën detare të kryeqytetit të ri, u drejtua nga ishujt në grykën egjeane të Ngushticës së Dardaneleve; Bozxhaada dhe Imbrosi u morën nga Bizanti, kurse Taso nga familja Gattilusio me origjinë gjenoveze. Këta ishuj, që mbyllnin të dy anët e ngushticës, pas kësaj u bënë hallka e parë e vijës së furnizimit dhe të mbrojtjes së Stambollit. Me ndërhyrjet e flotave të papatit dhe të Venedikut sundimi për ca kohë shkoi e erdhi dhe u përfundua vetëm në vitin 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Pushtimi i Kosovës: marrja e Prishtinës dhe e Novi Pazarit", "d7ed2345"], "d": ["Ushtria osmane që marshoi mbi Despotatin Serb mori Prishtinën në fushën e Kosovës dhe Novi Pazarin, qendrën e krahinës së Rashkës; në të njëjtin operacion u mor edhe Novobërda, e njohur për minierat e argjendit. Kështu gjysma jugore e Serbisë u lidh drejtpërdrejt me administrimin osman dhe despotati në Smederevë u shkëput nga tokat qendrore. Ky pushtim ishte hapi vendimtar i rrugës që katër vjet më vonë çoi në aneksimin e plotë të Serbisë.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peja (İpek) hyri nën administrimin osman — një nga qendrat e sanxhakut të Dukagjinit", "19511588"], "d": ["Në vitin 1455, menjëherë pas fushatës së Sulltan Mehmetit Fatih në Serbi, Peja, qendra e patriarkanës serbe, kaloi nën administrimin osman; në burimet osmane nuk ka asnjë regjistrim për këtë kalim. Qyteza me kohë u bë një qytezë e vogël myslimane dhe një nga rezidencat e sanxhakbeut në sanxhakun e Dukagjinit.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Pushtimi i Enosit dhe i Samotrakisë — plotësimi i bregut të Trakës Perëndimore", "106e723b"], "d": ["Enosi, ku lumi Marica derdhet në det, u mor nga familja Gattilusio me origjinë gjenoveze, që e mbante prej tetëdhjetë vjetësh; ishulli i Samotrakisë, i lidhur me të, u mor në të njëjtin operacion. Me rënien e Enosit, brezi bregdetar i Trakës Perëndimore nga Selaniku deri në Galipoli u bë tokë osmane e pandërprerë. Në duart e familjes Gattilusio mbeti vetëm Lesbosi; edhe ai do të merrej gjashtë vjet më vonë.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Dështimi i rrethimit të Beogradit", "3d53a604"], "d": ["Sulltan Mehmeti Fatih, pas pushtimit të Stambollit, rrethoi Beogradin, i konsideruar kyçi i Evropës Qendrore; por përforcimet që Jan Huniadi solli nga Danubi dhe vullnetarët e mbledhur nga predikuesi kryqtar Kapistrano e penguan rënien e kalasë. Padishahu, megjithë trimërinë personale që tregoi gjatë rrethimit, u plagos dhe u detyrua të tërhiqej. Ky dështim do t'ia mbyllte kufirin hungarez përparimit osman për gjashtëdhjetë e pesë vjet; Beogradi mundi të merrej vetëm në vitin 1521 nga Kanuniu.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Pushtimi i Moresë Veriore: Patra (Balyabadra)", "c08a8509"], "d": ["Në të njëjtat vite me aneksimin e Serbisë, forcat e Sulltan Mehmetit Fatih, që u drejtuan kundër despotatit të Moresë, morën Patrën në veriperëndim të gadishullit. Ky port që zinte grykën e gjirit të Korintit është kyçi i hyrjes tokësore në More; marrja e tij përgatiti terrenin për pushtimin përfundimtar dy vjet më vonë. Qyteti ishte skela e fundit e madhe përmes së cilës despotët bizantinë lidheshin me botën latine.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Marrja e bregut të Detit të Zi Perëndimor: Amasra", "f43608fc"], "d": ["Amasra, kolonia e fortifikuar gjenoveze në Detin e Zi Perëndimor, nën presionin e përbashkët të flotës dhe të forcave tokësore të Sulltan Mehmetit Fatih u dorëzua pa rezistuar. Ky port në bregun Bartën-Zonguldak qëndronte si një xhep latin midis Xhandarogllutëve dhe tokave osmane; me marrjen e tij bregu u bashkua. Rënia e Amasrës është hapi i parë i fushatës së madhe të Detit të Zi, që dy vjet më vonë (1461) do të drejtohej drejt Sinopit dhe Trapezundës.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Pushtimi i ishullit të Lesbosit", "fe17aeba"], "d": ["Ushtria osmane nën komandën e Sulltan Mehmetit Fatih, në dhulhixhe 866, pas një rrethimi të shkurtër por të ashpër, ia mori Lesbosin familjes Gattilusio me origjinë gjenoveze dhe e aneksoi. Rënia e ishullit më të madh të Egjeut Verior likuidoi edhe bazën e fundit të rëndësishme gjenoveze në krahinë. Ishulli, falë afërsisë me bregun anadollak, pas kësaj do të shërbente si post i përparuar për flotën osmane dhe njëkohësisht do të hynte në historinë detare si vendi ku u rritën vëllezërit Barbarosa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Fillimi i Luftës osmano-venedikase gjashtëmbëdhjetëvjeçare", "563ddb68"], "d": ["Venedikasit, për të ndalur përparimin osman në More dhe Egje, duke lidhur aleancë me sundimtarët e Karamanit dhe të akkojunlive, nisën luftën në vitin 1463. Kjo strategji rrethimi, me Uzun Hasanin në lindje, Venedikun në perëndim dhe Karamanin në mes, e detyroi Fatihun të luftonte njëkohësisht në disa fronte. Lufta gjashtëmbëdhjetëvjeçare do të përfshinte të gjitha operacionet e mëdha të kohës, nga Otllukbeli deri te fushatat e Shqipërisë, dhe do të përfundonte vetëm me Traktatin e Stambollit të vitit 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Pushtimi i pjesës më të madhe të Hercegovinës: Trebinja dhe Mostari", "f54c0100"], "d": ["Tokat e dukës së Hercegovinës, Stjepan Vukčić-Kosača, që kishte krijuar një administrim të veçantë nga Bosnja, tri vjet pas rënies së Mbretërisë së Bosnjës kaluan në masë të madhe nën administrimin osman: në jug Trebinja u mor në vitin 1466 \"së bashku me pothuajse gjithë krahinën e Hercegovinës\". Edhe Mostari, i krijuar rreth dy kalave të vogla të urës mbi Neretvë, duhet të jetë marrë pak para pushtimit të Blagajit, qendrës së Hercegovinës, në vitet 1466-1468; në regjistrin përmbledhës të Bosnjës të viteve 1468-1469 shënohet me emrin \"Kyprylly Hisar\" (Kalaja me Urë). Me kalatë e mbetura të dukatit, pushtimi i Hercegovinës përfundoi në vitin 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Fushata e dytë e Shqipërisë — marshimi vetë i Fatihut kundër Skënderbeut", "9cdd2bfa"], "d": ["Për të thyer rezistencën e Skënderbeut që kalonte një çerek shekulli, Sulltan Mehmeti Fatih në vitet 1466-1467 organizoi fushata të mëdha që i komandoi vetë. Ushtria osmane rrethoi Krujën dhe, për të vënë krahinën nën kontroll, ndërtoi kalanë e Elbasanit. Fushata, megjithëse ia theu shpinën rezistencës shqiptare, nuk arriti ta merrte kalanë; nënshtrimi i plotë i krahinës do të zgjaste dhjetë vjet pas vdekjes së Skënderbeut.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Forcat pararojë akkojunlu ia morën kështjellën e Bingölit karakojunlunjve", "51b94cbc"], "d": ["Në javët e fundit të fushatës që Xhihan Shahu ndërmori kundër Uzun Hasanit, forcat pararojë akkojunlu shtinë në dorë kështjellën e Bingölit; me vrasjen e Xhihan Shahut më 10 nëntor 1467, sundimi karakojunlu në rajon mori fund.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Shembja e Shtetit Karakojunlu: vrasja e Xhihan Shahut", "30bc6358"], "d": ["Sundimtari karakojunlu Xhihan Shahu, që po kthehej nga fushata kundër Uzun Hasanit për shkak të ardhjes së dimrit, ra në pritë dhe u vra ndërsa ikte midis Bingëlit dhe Kigëit. Pas kësaj goditjeje shteti nuk mundi të rimëkëmbej; sundimtari i fundit, Hasan Aliu, në vitin 1469 u zu rob nga Ugurlu Mehmedi, i biri i Uzun Hasanit, dhe u vra. Kështu sundimi karakojunlu, që për afro një shekull sundonte në Anadollin Lindor, Azerbajxhan dhe Irak, u kaloi akkojunlive.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Vdekja e Skënderbeut — shuarja e rezistencës shqiptare", "9158c35f"], "d": ["Skënderbeu, i rritur në sarajin osman, i cili në vitin 1444 pas disfatës së Zlaticës u ngrit në kryengritje dhe për më shumë se një çerek shekulli rezistoi në Shqipëri, vdiq në Lezhë, ku ishte strehuar. Kjo rezistencë, që në kohën e Muratit II dhe të Fatihut i kishte vonuar shpesh ushtritë osmane, me vdekjen e tij humbi udhëheqjen qendrore. Me shembjen e frontit shqiptar të ushqyer nga papati dhe Venediku, osmanët brenda dhjetë vjetësh morën Krujën dhe Shkodrën dhe e shtuan krahinën përfundimisht në tokat e tyre.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Në Kajseri u vendos administrimi osman: Gedik Ahmet Pasha u dha fund Karamanogullëve", "33cf35fc"], "d": ["Kur Gedik Ahmet Pasha më 1474 u dha fund Karamanogullëve, Kajseria hyri nën administrimin osman; qyteti gjatë shekullit XV kishte ndërruar duar mes Dulkadirëve, Ramazanogullëve dhe Karamanogullëve. Me administrimin osman, Kajseria u bë qendër sanxhaku e bejlerbejllëkut të Karamanit.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samosi u braktis: mori fund pronësia gjenoveze (e Maonës)", "5bdc380c"], "d": ["Sipas TDV-së, ishulli u braktis pas vitit 1475; më 1479 Sulltan Mehmeti Fatih e pushtoi ishullin dhe urdhëroi ndërtimin e një kështjelle.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Disfata e Rakovës (Vaslui) në Moldavi", "a1a74bf7"], "d": ["Vojvoda i Moldavisë, Stefan cel Mare, duke i tërhequr forcat osmane nën komandën e bejlerbeut të Rumelisë, Hadëm Sulejman Pashës, në një terren moçalor, u shkaktoi një disfatë të rëndë. Kjo disfatë, një nga humbjet më të rënda tokësore të kohës së Fatihut, pati jehonë të madhe në Evropë dhe i solli Stefanit famë në botën kryqtare. Padishahu vitin pasues do të dilte vetë në fushatë për hakmarrje.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Fitorja e Valea Albës (Akdere) — fushata e Moldavisë", "45a66791"], "d": ["Sulltan Mehmeti Fatih, që doli vetë në fushatë për të marrë hakun për disfatën e Rakovës të një viti më parë, me ushtrinë osmane u shkaktoi njësive moldave një disfatë të madhe në vendin Valea Albă dhe hyri në Suçava, qendrën e principatës. Por kalatë nuk u morën; për shkak të mungesës së ushqimeve, murtajës që nisi midis jeniçerëve dhe përgatitjeve hungareze, ushtria u detyrua të tërhiqej. Varësia përfundimtare e Moldavisë mundi të arrihej vetëm në vitet pasuese dhe me marrjen e Kilias dhe të Akkermanit në vitin 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Pushtimi i Krujës (Akçahisar) dhe plotësimi i Shqipërisë", "559a79b4"], "d": ["Dhjetë vjet pas vdekjes së Skënderbeut, në vitin 1478, me marrjen e Krujës, Drishtit, Lezhës dhe Zhabjakut u plotësua në masë të madhe pushtimi i Shqipërisë. Rënia e Kalasë së Krujës, që për vite i kishte rezistuar ushtrive osmane dhe ishte simbol i rezistencës së Skënderbeut, do të thoshte fund i aleancës venedikaso-shqiptare në krahinë. Kurse Shkodra e mbetur do t'u lihej Osmanëve me Traktatin e Stambollit që do të nënshkruhej vitin pasues.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Bashkimi i gadishullit të Tamanit", "4ef917b8"], "d": ["Pas marrjes së Kafës dhe Kerçit në vitin 1475, flota që Sulltan Mehmeti Fatih dërgoi në brigjet e Kaukazit, së bashku me Anapën dhe Kopan, pushtoi Matregën gjenoveze (Tamatarhan) në gadishullin e Tamanit. Kështu u vunë nën kontroll të dy brigjet e ngushticës dhe hyrja në Detin e Azovit u bë krejtësisht e kontrollueshme. Tamani, si porta drejt Kaukazit Verior, u lidh me sanxhakun e Kafës.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Hyrja e Samosit nën administrimin osman (Fatihu)", "c877bc14"], "d": ["Sulltan Mehmeti Fatih pushtoi Samosin, urdhëroi ndërtimin e një kështjelle dhe riorganizoi regjistrimin e popullsisë; kështjellën Bajaziti II urdhëroi ta shembnin më 1483 për shkaqe politike.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Dështimi i rrethimit të Rodosit", "35a85c28"], "d": ["Me urdhër të Sulltan Mehmetit Fatih, flota prej 160 anijesh nën komandën e Mesih Pashës në pranverën e vitit 885 (1480) rrethoi Rodosin dhe ishulli mbeti tre muaj nën bllokadë. Kalorësit e Shën Gjonit, nën udhëheqjen e mjeshtrit të madh Pierre d'Aubusson, megjithë humbjet e rënda rezistuan fort; pasi u zmbraps edhe sulmi i fundit i madh i 20 xhumadelula 885, flota u tërhoq më 3 gusht. Pas këtij dështimi muret e qytetit u rinovuan nga fillimi dhe u bënë fortifikimi më i fortë i Evropës, dhe ishulli mundi të merrej vetëm në vitin 1522 nga Kanuniu.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikaria (Ikaria) hyri nën administrimin e Kalorësve të Shën Gjonit të Rodosit", "5cbc2669"], "d": ["Nikaria, mes Samosit dhe Kiosit, nga viti 1481 deri më 1521 ishte nën administrimin e Kalorësve të Shën Gjonit të Rodosit.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Beteja e Jenishehirit — disfata e Xhem Sulltanit", "c35abee2"], "d": ["Dy vëllezërit që pas vdekjes së Fatihut u vunë në lëvizje për fron u ndeshën në fushën e Jenishehirit dhe Xhem Sulltani pësoi një disfatë vendimtare. Shehzadeja, që sundoi në Bursë tetëmbëdhjetë ditë dhe urdhëroi të lexohej hytbeja në emrin e vet, pas disfatës u detyrua të strehohej fillimisht në Konja, prej andej në tokat memluke. Jenishehiri nisi krizën dinastike më të gjatë të historisë osmane: çështja e Xhemit për katërmbëdhjetë vjet do ta paralizonte politikën e jashtme osmane ndaj Evropës.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksimi i Hercegovinës", "bf247891"], "d": ["Tokat e Dukatit të Hercegovinës, që kishte mbijetuar pas pushtimit të Bosnjës në vitin 1463, kaluan hap pas hapi nën administrimin osman: Trebinja dhe Mostari u morën në vitin 1466, sanxhaku i Hercegovinës u formua në vitin 1470, kurse tokat e fundit të dukatit në bregun e Adriatikut, së bashku me Herceg Novin, u pushtuan në fillim të vitit 1482 dhe iu bashkuan sanxhakut. Kështu krahina malore prapa Adriatikut u bë tërësisht osmane dhe Bosnja me Hercegovinën u bënë një gjeografi e vetme administrative. I biri i dukës së fundit, që hyri në sarajin osman, është Hercegzade Ahmed Pasha, i cili më vonë do të ngrihej deri në postin e vezirit të madh.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Lënia e Zakintosit (Zaklise) Venedikut me haraç vjetor", "268a691a"], "d": ["Zakintosi, një nga ishujt e Jonit që në fund të kohës së Fatihut iu mor familjes Tocco, iu la Venedikut nga padishahu i ri, i cili, i zënë me çështjen e Xhem Sulltanit, kërkonte qetësi në Perëndim. Ishulli iu dorëzua një administrate venedikase që njihte sovranitetin osman dhe paguante pesëqind dukate haraç në vit. Kështu në Detin Jon administrimi i drejtpërdrejtë osman mbeti vetëm në Ajamavrë.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Strehimi i Xhem Sulltanit në Rodos", "2228d6da"], "d": ["Xhem Sulltani, të cilit i mbeti pa rezultat edhe përpjekja për të rrethuar Konjën, me rreth tridhjetë njerëz iku nga Anadolli, arriti në Rodos dhe u prit me ceremoni nga kalorësit e Shën Gjonit. Por mikpritja brenda pak kohe u shndërrua në robëri; shehzadeja iu dorëzua fillimisht Francës, pastaj papatit dhe u bë një kartë në duart e politikës evropiane. Bajazidi II u detyrua të paguante çdo vit për mbajtjen e të vëllait dhe veprimet ushtarake osmane drejt Perëndimit u pezulluan deri në vdekjen e Xhemit.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Fillimi i luftës osmano-memluke (fronti i Çukurovës)", "3fe3f0c7"], "d": ["Lufta për ndikim mbi Dulkadirogllutët dhe armiqësia që la strehimi i Xhem Sulltanit në tokat memluke, në vitin 1485 nisën midis dy fuqive të mëdha sunite një luftë që do të zgjaste gjashtë vjet. Në përleshjet në Çukurovë, rreth Adanasë dhe Tarsit, asnjëra palë nuk fitoi epërsi; ushtritë osmane pësuan disa goditje të rënda. Kjo luftë është faza e parë e çarjes në marrëdhëniet osmano-memluke dhe hapja e procesit që tridhjetë vjet më vonë do të përmbyllej me fushatat e Javuzit në Mexh Dabik dhe Ridanije.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Paqja osmano-memluke — ndërmjetësimi i Tunisit", "60dd6719"], "d": ["Në luftën osmano-memluke që filloi në vitin 1485 palët nuk mundën të korrnin një fitore vendimtare; me ndërmjetësimin e sundimtarit të Tunisit, Osman Hafsit, në vitin 1491 u arrit marrëveshja. Traktati i ktheu kufijtë në masë të madhe në gjendjen e para luftës dhe llogaria midis dy shteteve islame u shty për një brez. Lufta rraskapitëse gjashtëvjeçare është një nga arsyet kryesore të politikës së jashtme të kujdesshme të Bajazidit II dhe të përqendrimit të tij te rregullimet e brendshme në vend të drejtimit nga lindja.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Pranimi në Perandorinë Osmane i hebrenjve sefardë të dëbuar nga Spanja", "5c2b5c24"], "d": ["Pas rënies së Granadës, një pjesë e hebrenjve që iknin nga dhuna e inkuizicionit në Spanjë u strehuan në tokat osmane dhe u vendosën në qytete të ndryshme. Nën administrimin osman këto komunitete sefarde fituan një liri që nuk e kishin parë deri atëherë: të vendoseshin ku të donin, të jetonin besimin e tyre, të hapnin institucione arsimore dhe të ndërtonin sinagoga të reja. Kjo shpërngulje, që me njohuritë e shtypshkronjës, mjekësisë dhe financave që sollën me vete e transformoi jetën ekonomike të Selanikut dhe të Stambollit, u bë shembulli më i përfolur në Evropë i rendit osman të tolerancës.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Vdekja e Xhem Sulltanit — fundi i pengmarrjes katërmbëdhjetëvjeçare", "f6588b70"], "d": ["Xhem Sulltani, i dorëzuar nga papati te mbreti i Francës Karli VIII, pasi u nis nga Roma më 27 janar 1495, vdiq në vendin e quajtur Castel Capuana; burimet shënojnë se mund të jetë helmuar nga rrethet papnore. Vdekja e shehzadesë, që për katërmbëdhjetë vjet u mbajt në duart e shteteve evropiane si kartë kërcënimi kundër Osmanëve, më në fund ia liroi duart Bajazidit II. Vërtet, pas kësaj padishahu do t'i shpallte luftë Venedikut dhe do ta çonte flotën në fitoren e saj të parë të madhe.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Fitorja Detare e Sapienzës (Zonchio) — suksesi i parë i madh i flotës në Mesdhe", "9754aaef"], "d": ["Bajazidi II, që me përfundimin e çështjes së Xhemit i kishte duart e lira, në vitin 1499 i shpalli luftë Venedikut; flota osmane, duke mundur flotën venedikase në ujërat e Sapienzës (Zonchio), korri fitoren e parë të madhe detare në Mesdhe. Me këtë fitore flota shpalli se tashmë mund t'i bënte ballë Venedikut në det.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Humbja e Qefalonisë dhe Itakës", "60f0f687"], "d": ["Venediku, i tronditur nga marrja e Modonit dhe Koronit, u bashkua me Spanjën, kaloi në kundërsulm dhe rrethoi Qefaloninë, që nga viti 1479 ishte në duart osmane. Pas qëndresës dyzet e shtatë ditore kështjella ra, ishulli bashkë me Itakën kaloi te Venediku dhe për treqind vjet nuk u kthye më nën administrimin osman. Kjo humbje krijoi një ekuilibër në të cilin ajo që u fitua në More u kthye në Jon.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Shembja e Hanatit të Hordhisë së Artë dhe ngritja e Krimesë", "0d1dc515"], "d": ["Sundimtari i fundit, Shejh Ahmed Hani (1481-1502), nuk mundi ta shpëtonte vendin nga kriza ku kishte rënë dhe Hanati i Hordhisë së Artë, në vitin 1502, me goditjen e hanit të Krimesë, Mengli Girajit, hyri në histori. Si pasojë e grindjeve për fronin dhe e copëtimit, në tokat e dikurshme të Hordhisë së Artë dolën hanatet e Krimesë, Kazanit, Nogait, Astrahanit dhe Sibirit. Kjo fitore e Krimesë nën mbrojtjen osmane e bëri të padiskutueshëm ndikimin osman në veri të Detit të Zi, kurse boshllëkun që lindi në krahinë do ta mbushte në shekullin pasues Moska.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Përfundimi i luftës osmano-venedikase dhe paqja", "125b1526"], "d": ["Lufta që filloi në vitin 1499 dhe e tronditi Venedikun me Sapienzën dhe me humbjen e Lepantos, Modonit dhe Koronit, përfundoi me paqe në vitin 1502. Venediku, duke humbur bazat më të rëndësishme në More, u detyrua të pranonte epërsinë osmane në këmbim të ruajtjes së privilegjeve tregtare në Mesdheun Lindor. Sundimi i Bajazidit II, që konsiderohet i kujdesshëm, me këtë luftë i kishte ngritur Osmanët për herë të parë në pozitën e një fuqie të vërtetë detare në Mesdhe.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Kryengritja e Shahkullut — kryengritja kizilbashe nga krahina e Tekesë deri në Sivas", "3beadca7"], "d": ["Shahkulu Baba Tekeli, i cili nën ndikimin e propagandës safavide në Anadoll e shfaqi hapur kryengritjen në vitin 1510, në mars 1511 sulmoi pazarin e Antalisë dhe në prill i mundi forcat osmane në Kytahja dhe rrethina. Në përleshjen e fundit me vezirin e madh Hadëm Ali Pasha pranë Sivasit, të dyja palët pësuan humbje të rënda; si veziri i madh, si udhëheqësi i kryengritjes humbën jetën. Kjo kryengritje, që e tronditi autoritetin shtetëror në Anadoll, nxori në pah boshllëkun e pushtetit në vitet e fundit të Bajazidit II dhe u bë arsyeja më e fortë e marshimit të shehzade Selimit drejt fronit.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Heqja dorë nga froni e Bajazidit II dhe hipja e Sulltan Selimi Javuzit", "c4cfab69"], "d": ["Me presionin e shehzade Selimit, që në luftën për fron me vëllezërit kishte pas vetes mbështetjen e jeniçerëve, Bajazidi II hoqi dorë nga froni më 24 prill 1512 dhe Selimi I po atë ditë hipi në fron si sundimtari i nëntë osman. Padishahu plak, ndërsa po shkonte në Dimotikë, ku kishte lindur, vdiq rrugës në fshatin Abalar pranë Çorlusë, më 25 rebiulevel 918 (10 qershor 1512). Sundimin tridhjetë e një vjeçar, të kujdesshëm dhe të mbyllur, e zëvendësoi epoka e Javuzit, që për tetë vjet do t'i dyfishonte kufijtë e perandorisë.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Pushtimi i kështjellës së Sinjit", "83271ea5"], "d": ["Forcat akinxhi osmane në kufirin e Bosnjës ia morën Mbretërisë së Hungarisë kështjellën e Sinjit, që shtrihej në brendësi të Dalmacisë. Kjo ishte një hallkë e hershme e vijës kufitare dalmate, që nëntë vjet më vonë do të zgjerohej me pushtimin e Kninit dhe rrethinave nga Gazi Husrev Beu; kështjella do t'i humbte Venedikut më 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Beteja e Jenishehirit dhe eliminimi i shehzade Ahmedit", "e2ed15dd"], "d": ["Sulltan Selimi Javuz shpartalloi në fushën e Jenishehirit pranë Bursës të vëllanë e madh, shehzade Ahmedin, rivalin më të fortë për fronin, e zuri rob dhe e eliminoi. Kështu u mbyll grindja e vëllezërve që vazhdonte që nga viti 1511 dhe mori fund përçarja e brendshme në Anadoll. Selimi, duke siguruar shpinën, fitoi lirinë për t'u marrë me çështjen safavide.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Hyrja e Sulltan Selimit Javuz në Tebriz", "dad2e227"], "d": ["Pas fitores së Çalldiranit, ushtria osmane hyri në kryeqytetin safavid, Tebriz, dhe në qytet u lexua hytbeja në emër të padishahut. Selimi qëndroi aty një javë dhe urdhëroi të zhvendosej në Stamboll një pjesë e artizanëve dhe dijetarëve të Tebrizit; ky transferim do të ndikonte thellë në artin e sarajit osman. Megjithëse qyteti u la për shkak të afrimit të dimrit dhe pakënaqësisë së jeniçerëve, epërsia safavide në Lindje ishte thyer. Vendet që në hartë këtë ditë u kalojnë Osmanëve nuk janë të ngjitura me njëri-tjetrin dhe kjo është e saktë: Tebrizi është një pushtim nëntëditor i ushtrisë; fusha e Erzinxhanit u dorëzua pa luftë gjatë fushatës, kurse kalaja e Kemahut në mes të saj rezistoi te safavidët deri më 19 maj 1515; Siirtin ua rimori safavidëve meliku i Hasankejfit, Halil Beu, i cili u shpëtua nga burgu i Shah Ismailit në Tebriz dhe iu nënshtrua Osmanëve — kurse rrethinat e tij, Dijarbekiri deri në 1515 dhe Hasankejfi deri në 1517, mbetën safavide.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Mushi dhe Bingöli (Çapakçur) kaluan nga safavidët nën administrimin osman", "b0a53b5a"], "d": ["Me marrjen e Anadollit Lindor nga safavidët pas Çalldiranit, Mushi më 921/1515 hyri nën administrimin osman; fqinji Çapakçur (Bingöl) iu bashkua osmanëve në të njëjtin proces.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Pushtimi i Kalasë së Kemahut nga safavidët", "73fd8671"], "d": ["Sulltan Selimi Javuz, që kthimin nga Çalldirani e kaloi dimrin në Amasja, e ngarkoi Bëjëkllë Mehmed Pashën me pushtimin e Kalasë së fortifikuar të Kemahut, që zinte vendkalimin e Eufratit. Në fund të rrethimit ku mori pjesë vetë padishahu, kalaja u mor nga safavidët dhe u hap porta e Anadollit Lindor. Ky pushtim është hapi i parë konkret që e shndërroi fitoren e Çalldiranit në fitim të qëndrueshëm territorial.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Fitorja e Turnadagut — Bejliku i Dulkadirëve u bë vartës i Osmanëve", "fd879145"], "d": ["Forcat osmane mundën në vendin Ordekli, midis Goksunit dhe Andërinit, beun e Dulkadirëve, Alaudevle Bozkurt, i cili gjatë fushatës së Çalldiranit mbajti qëndrim të dyshimtë; Alaudevleja u vra në këtë betejë. Bejliku në këtë datë nuk u aneksua: pas Alaudevles, në krye të Bejlikut të Dulkadirogllutëve Sulltan Selimi Javuz vendosi Shehsuvarogllu Ali Beun dhe vendi me qendër Marash-Elbistan vazhdoi si bejlik vartës i Osmanëve. Kështu zona tampon në kufirin memluk hyri nën kontrollin osman dhe u hap rruga për fushatën e Egjiptit dy vjet më vonë; aneksimi do të bëhej pas vrasjes së Ali Beut.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Pushtimi i Amidit (Dijarbekirit) dhe krijimi i Bejlerbejllëkut të Dijarbekirit", "a6867d5b"], "d": ["Pasi Idris Bitlisiu fitoi për Osmanët bejlerët kurdë sunitë të krahinës, forcat safavide nuk mundën t'i qëndronin rrethimit të gjatë dhe çelësat e Amidit iu dorëzuan Bëjëkllë Mehmed Pashës. Qyteti u bë qendra e Bejlerbejllëkut të sapokrijuar të Dijarbekirit. Kështu bërthama administrative e Mesopotamisë së Epërme kaloi në duart osmane.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Pushtimi i Harputit — hapja e rrugës së Dijarbekirit", "564eb269"], "d": ["Bejlerbeu i Karamanit, Hysrev Pasha, që u nis për ta shpëtuar nga rrethimi safavid Dijarbekirin e marrë pas Çalldiranit, në fund të një rrethimi tre ditor mori Kalanë e Harputit, rrethinat e së cilës i kishte pushtuar më parë Çerkez Husein Beu. Kështu u sigurua rruga në lindje të Eufratit që shtrihet drejt Dijarbekirit.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Beteja e Koçhisarit (Këzëltepe) — disfata e Kara Hanit", "9ea9e843"], "d": ["Ushtria osmane nën komandën e Bëjëkllë Mehmed Pashës, pranë Koçhisarit, në vendin Koruk të fushës së Dede Garkënit, e mundi valiun safavid Kara Han në një betejë fushore që zgjati gjithë ditën; koka e prerë e Kara Hanit u dërgua në kampin e padishahut. Më pas forcat osmane hynë në qytetin e Mardinit, por qëndruan pak ditë dhe u larguan; Kalaja e Mardinit, në duart e rojtarëve safavidë, mundi të merrej vetëm një vit më vonë. Kjo fitore, duke e siguruar kufirin jugor të Javuzit, i mundësoi të drejtohej për në fushatën e Egjiptit. Vende të tjera që u bashkuan në të njëjtën datë: Palu, Çemishgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Nisja e Sulltan Selimi Javuzit nga Stambolli për fushatën e Egjiptit", "ac258b4b"], "d": ["Sulltan Selimi Javuz, në dukje me përgatitje për një fushatë të re lindore kundër safavidëve, u nis nga Stambolli dhe përmes Akshehirit u drejtua drejt jugut. Fakti që sulltani memluk Kansu Gavri lidhi kontakte me Shah Ismailin dhe kërcënoi krahun lindor osman do të çonte brenda pak kohe në ndryshimin e objektivit. Fushata është fillimi i operacionit të madh që do të zgjaste dy vjet dhe do t'i shndërronte Osmanët në një perandori të Lindjes së Mesme.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Marrja e Zebidit: hyrja e parë e detarëve osmanë në Detin e Kuq", "38740e0c"], "d": ["Detarët me origjinë osmane Husein Beu dhe Selman Reisi, të dërguar në Detin e Kuq me kërkesën e sulltanit memluk Kansu Gavri përballë presionit portugez në Oqeanin Indian, me flotën e tyre morën Zebidin. Ky operacion, i kryer ende në shërbim të memlukëve, është prania e parë de fakto e marinës osmane në vijën Deti i Kuq-India. Kur një vit më vonë Egjipti u kaloi Osmanëve, po ajo flotë do të lidhej drejtpërdrejt me Stambollin.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Shpallja zyrtare e memlukëve dhe e Halepit si objektiv i fushatës", "689e310d"], "d": ["Sulltan Selimi Javuz, pasi Kansu Gavri, duke u marrë vesh me safavidët, e shtyu ushtrinë drejt Halepit, e shpalli hapur se objektiv i fushatës ishin sulltani memluk dhe Halepi. Kështu rivaliteti i fshehtë shumëvjeçar midis dy shteteve sunite u shndërrua në luftë të hapur. Kjo shpallje nisi numërimin mbrapsht katërjavor drejt Mexh Dabikut.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Dështimi i rrethimit të Adenit: përpjekja e parë në Detin e Kuq kundër Portugalisë", "8ffd46f2"], "d": ["Selman Reisi dhe Husein Beu, për të marrë Adenin, portën e Detit të Kuq drejt Oqeanit Indian, zhvilluan një rrethim tetë ditor, por përballë fortifikimit të fortë të qytetit u detyruan të tërhiqeshin. Mosmarrja e Adenit do ta pengonte për shumë vite strategjinë jugore kundër Portugalisë. Kjo përpjekje është prova e parë e politikës oqeanike osmane.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Lidhja e Bejlikut të Ramazanogllutëve me Osmanët", "cfaa3754"], "d": ["Gjatë caktimeve të bëra pas fitores së Mexh Dabikut, Bejliku i Ramazanogllutëve me qendër Adananë iu dha Mahmud Beut dhe u mor nën sovranitetin osman. Bejliku, që doli nga vartësia memluke, në vend që të zhdukej, iu la familjes me statusin 'odxhakllëk'; Ramazanogllutë vazhduan të administronin Çukurovën në cilësinë e sanxhakbejlerëve osmanë. Ky rend i privilegjuar vazhdoi deri në vitin 1608, kur Pir Mansuri e la bejlikun. Vende të tjera që u bashkuan në të njëjtën datë: Malatja, Tarsi, Mosuli, Antepi.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Hyrja e Halepit, Rakas dhe Deir ez-Zorit nën sundimin osman", "2088eb6a"], "d": ["Katër ditë pas Mexh Dabikut, Sulltan Selimi Javuz hyri pa rezistencë në Halep dhe në xhamitë e qytetit u lexua hytbeja në emrin e tij. Rënia kaq e shpejtë e Halepit, i konsideruar kryeqyteti tregtar dhe administrativ i Sirisë, tregon se autoriteti memluk në krahinë ishte shembur. Marrja e qytetit hapi menjëherë rrugën drejt Damaskut e prej andej drejt Egjiptit. Vende të tjera që u bashkuan në të njëjtën datë: Antakia, Raka, Deir ez-Zori.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Takimi me halifin abasid Mutavakkil III në Gökmejdan të Halepit", "22979f42"], "d": ["Halifi abasid i Kajros, Mutavakkil III, i zënë rob në Mexh Dabik së bashku me ushtrinë memluke, u nxor në Halep, në Gökmejdan, përpara padishahut dhe Sulltan Selimi Javuz i tregoi respekt të madh. Halifati i Kajros, që që nga viti 1261 ishte një post simbolik nën hijen e sulltanëve memlukë, me këtë takim kaloi de fakto nën mbrojtjen osmane. Halifi më vonë do të çohej me padishahun në Stamboll.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Hyrja e Tripolit të Sirisë dhe e Hamas nën administrimin osman", "a1e19a79"], "d": ["Pas Halepit dhe Hamas, edhe Tripoli i Sirisë, në bregun sirian, kaloi pa rezistencë nën administrimin osman. Qyteti, një nga portet më të gjallë të Mesdheut Lindor, ishte porta detare e Damaskut dhe qendra e tregtisë së mëndafshit dhe të sheqerit. Me marrjen e tij, brezi bregdetar i Bilad al-Shamit ndërroi plotësisht dorë.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Hyrja e Damaskut nën sundimin osman", "2b844d91"], "d": ["Sulltan Selimi Javuz, të cilit pas Halepit iu hap rruga me dorëzimin e Hamas dhe të Homsit, më 27 shtator arriti përpara Damaskut; nuk hyri menjëherë në qytet, por ngriti çadrën jashtë, në vendin Mastaba, dhe ditën e dymbëdhjetë të ardhjes hyri me ceremoni të madhe. Duke qëndruar gjatë në Damask, vendosi rendin administrativ të Sirisë dhe urdhëroi të ndërtohej varri i Muhjiddin Ibn Arabiut. Kështu i gjithë Bilad al-Shami doli nga administrimi memluk. Vende të tjera që u bashkuan në të njëjtën datë: Bejruti.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Shpallja e Tomanbeut sulltan memluk në Kajro", "6020d90d"], "d": ["Pas Kansu Gavriut, që vdiq në Mexh Dabik, emirët memlukë hipën në fron Tomanbeun, që do të ishte sulltani i fundit i shtetit. Sulltani i ri me origjinë çerkeze mori një shtet që kishte humbur Sirinë, e kishte thesarin të shterur dhe i mungonin armët e zjarrit. Megjithatë, duke ngritur një vijë mbrojtëse përpara Kajros, do të organizonte një rezistencë të fundit ndaj përparimit osman.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Beteja e Gazës (Han Junusit): disfata e Xhanbirdi Gazaliut", "9f1eb8cb"], "d": ["Sulltan Selimi Javuz dërgoi në Gazë vezirin e madh Hadëm Sinan Pashën me një pararojë prej katër mijë vetash. Xhanbirdi Gazaliu, i emëruar nga Tomanbeu zëvendës (naib) i Damaskut, u përpoq ta ndalte pararojën osmane në vijën Gazë-Han Junus, por pësoi një disfatë të rëndë dhe iku në Egjipt. Me shpërndarjen e forcës së fundit tampon memluke në Palestinë, rruga drejt shkretëtirës së Sinait u hap plotësisht.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Lindja e Jordanit: hyrja e Amanit nën administrimin osman", "9db62667"], "d": ["Pas betejës së Gazës, ndërsa forcat osmane që përgatiteshin për fushatën e Egjiptit zbrisnin drejt jugut, edhe Amani, në lindje të Jordanit, hyri nën administrimin osman. Kurse qytetet bregdetare dhe të brendshme të Palestinës (Jafa, Nablusi, Sidoni, Akka, Jerusalemi) kishin ndërruar dorë tashmë pas Mexh Dabikut, në vjeshtën e vitit 1516. Këto qytete për katër shekuj u administruan si sanxhakë të ejaletit të Damaskut.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Ardhja e Sulltan Selimi Javuzit në Jerusalem", "66d7bfad"], "d": ["Në Jerusalem, që pas Mexh Dabikut kishte kaluar pa rezistencë nën administrimin osman, pas betejës së Gazës erdhi Sulltan Selimi Javuz me parinë e shtetit dhe me ushtrinë. Padishahu vizitoi Kubbet es-Sahran dhe Xhaminë Al-Aksa dhe konfirmoi statusin e shenjtë të qytetit. Jerusalemi që nga kjo datë deri në dhjetor 1917 do të mbetej plot katër shekuj nën administrimin osman.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Hyrja e Sulltan Selimi Javuzit në Gazë dhe drejtimi drejt shkretëtirës së Sinait", "2106bfc7"], "d": ["Pas disfatës së Xhanbirdi Gazaliut në Han Junus (21 dhjetor 1516), Gaza ishte në duart e pararojës. Padishahu më 2 janar 1517 hyri në Gazë, u takua aty me Sinan Pashën, në krye të pararojës, dhe ushtria bëri përgatitjet e fundit për kalimin në Egjipt. Nëpër shkretëtirën pa ujë të Katjas (Sinait), nga Gaza deri në Salihije, do të bëheshin tetë etapa dhe uji do të mbartej me deve. Ky kalim është faza më e rrezikshme dhe logjistikisht më e vështirë e fushatës.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Marrja e Suezit — porta drejt Detit të Kuq", "05f3324e"], "d": ["Me hyrjen e njësive osmane në Kajro pas fitores së Ridanijes, edhe Suezi, në skajin verior të Detit të Kuq, kaloi nën administrimin osman. Ky port-arsenal, prej nga memlukët dërgonin flotë në Oqeanin Indian, u bë baza e politikës jugore që do të zhvillohej kundër Portugalisë. Suezi është gryka veriore e vijës ku tre shekuj më vonë do të hapej kanali.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Hyrja e parë e njësive osmane në Kajro", "0a3f4f4d"], "d": ["Ditën pas fitores së Ridanijes ushtrive osmane iu lejua të hynin në Kajro dhe më 24 janar njësitë u vendosën në qytet. Por kjo hyrje nuk do të thoshte kontroll i plotë i qytetit; Tomanbeu ishte tërhequr në Egjiptin e Epërm dhe rezistenca memluke ende nuk ishte thyer. Pushtimi i Kajros do të përfundonte jo brenda një dite, por në një proces të përgjakshëm që do të zgjaste me javë.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Sulmi i befasishëm i Tomanbeut mbi Kajro dhe luftimet tri ditore në rrugë", "b83b6ce6"], "d": ["Tomanbeu, i tërhequr në Egjiptin e Epërm, natën e 27-28 janarit, me rreth shtatë mijë veta që kishte pranë, hyri papritur në Kajro, nisi rezistencën brenda qytetit dhe i la njësitë osmane në pozitë shumë të vështirë. Në përleshjet e ashpra tri ditore në rrugë, memlukët mbajtën përkohësisht pjesën më të madhe të qytetit. Rezistenca mundi të thyhej vetëm me hyrjen në veprim të artilerisë osmane dhe të forcave përforcuese.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Hyrja e Xhanbirdi Gazaliut në shërbimin osman", "a94ea459"], "d": ["Ish-emiri memluk Xhanbirdi Gazaliu, që pas Ridanijes u tërhoq në Salihije, iu drejtua padishahut dhe kërkoi falje (aman). Sulltan Selimi Javuz, duke menduar se do të ishte i dobishëm për vendosjen e rendit në Egjipt dhe Siri, e pranoi në shërbim. Kjo zgjedhje është shembulli i parë i madh i politikës osmane për t'i përfshirë kuadrot memluke në sistem në vend që t'i likuidonte.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Hyrja ceremoniale e Sulltan Selimi Javuzit në Kajro dhe leximi i hytbesë", "6d98080c"], "d": ["Pas shtypjes së përleshjeve në rrugë, padishahu më 15 shkurt 1517 hyri në Kajro me një ceremoni shumë madhështore dhe në xhami u lexua hytbeja në emrin e tij. Leximi i hytbesë në Kajro në emrin e sulltanit osman është shpallja se sundimi memluk, që vazhdonte që nga viti 1250, kishte marrë fund juridikisht. Kjo datë konsiderohet çasti simbolik i përfundimit të pushtimit de fakto të Egjiptit.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Kapja e sulltanit të fundit memluk, Tomanbeut, në Terruxhe", "7058e6ad"], "d": ["Tomanbeu, që pasi la Kajron u fsheh në deltën e Nilit, u denoncua nga beduinët që i kishin dhënë strehë dhe u kap në krahinën e Terruxhes. Kapja e tij e zhduku qendrën e organizuar të rezistencës memluke. Sulltani i fundit pas kësaj do të mbahej katërmbëdhjetë ditë në duart e osmanëve.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Ekzekutimi i Tomanbeut në Bab Zuvejle dhe fundi i Shtetit Memluk", "ad9820be"], "d": ["Katërmbëdhjetë ditë pas kapjes, Tomanbeu u var në portën e njohur të Kajros, Bab Zuvejle; trupi i tij më pas u varros në medresenë që kishte ndërtuar xhaxhai i tij. Kështu Shteti Memluk, që sundonte Egjiptin dhe Sirinë që nga viti 1250, hyri zyrtarisht në histori. Me thyerjen e rezistencës, edhe qytete të Egjiptit të Epërm (Said) si Asjuti dhe Asuani u lidhën me administrimin osman.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Sulmi i flotës portugeze mbi Xhidë dhe mbrojtja nga Selman Reisi", "52322cf5"], "d": ["Flota portugeze, e përbërë nga rreth tridhjetë galera dhe galeona, sulmoi Xhidën; Selman Reisi, duke drejtuar mbrojtjen e qytetit, e pengoi armikun të zbarkonte dhe fundosi disa anije portugeze. Kjo mbrojtje pengoi që porti i Mekës, e si rrjedhim edhe rruga e haxhit, të binte në duart e një shteti të krishterë. Xhida pas pak muajsh, me betimin e besnikërisë (bejat) të Hixhazit, do të përfshihej zyrtarisht në administrimin osman.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Marrja në dorëzim e Aleksandrisë me flotë — përfundimi i pushtimit të Egjiptit", "386878fe"], "d": ["Plot katër muaj pas Ridanijes dhe tridhjetë e gjashtë ditë pas ekzekutimit të Tomanbeut, me ardhjen në port të flotës osmane nën komandën e Xhafer Beut, Aleksandria kaloi nën administrimin osman; po në atë proces u lidhën edhe portet e deltës si Rashidi dhe Damieta. Fakti që ky port i madh i Egjiptit në Mesdhe u mor muaj pas rënies së Kajros dhe jo nga toka, por nga deti, tregon qartë se pushtimi nuk u përfundua me një betejë të vetme, por krahinë pas krahine. Aleksandria pas kësaj do të bëhej porti jetik që lidhte Stambollin me Kajron. Vende të tjera që u bashkuan në të njëjtën datë: Rashidi (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Bashkimi pa luftë i Hixhazit: betimi i besnikërisë i Ebu Numejjit, të birit të Sherifit të Mekës", "c13b98c7"], "d": ["Sulltan Selimi Javuz fillimisht kishte menduar të dërgonte ushtri për të marrë Mekën me rrethinat, por, kur emiri i Mekës, sherif Berekati, njoftoi nënshtrimin, hoqi dorë nga kjo. Djali dymbëdhjetëvjeçar i Berekatit, Ebu Numejji, erdhi në Kajro me dhuratat e të atit dhe me çelësat e Mekës dhe u pranua përpara padishahut. Kështu Hixhazi iu bashkua Osmanëve jo si pasojë automatike e Ridanijes, por pesë muaj e gjysmë më vonë, pa u shkrepur asnjë plumb, me paqe dhe me anë të betimit të besnikërisë. Vende të tjera që u bashkuan në të njëjtën datë: Taifi. Vendbanime të tjera që u humbën në të njëjtën datë: Hurma (lindja e Taifit), Rabigu, Bedri.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Pranimi i titullit Hadim ul-Haremejn dhe hytbeja në Medinë", "63b32b59"], "d": ["Pas pritjes së dytë të delegacionit të Mekës, Sulltan Selimi Javuz mori zyrtarisht përsipër mbrojtjen e Haremejnit dhe filloi të përdorte titullin 'hadim ul-Haremejn esh-Sherifejn' (shërbëtor i dy vendeve të shenjta). Sherif Berekati, duke veshur hil'atin që iu dërgua, urdhëroi të lexohej hytbeja në emër të padishahut; me shkuarjen në Stamboll edhe të delegacionit të Medinës, emirati i Berekatit u konfirmua me berat. Padishahu, duke u dërguar banorëve të Haremejnit dyqind mijë monedha ari dhe ushqime të bollshme, nisi traditën e surres që do të përsëritej çdo vit. Vende të tjera që u bashkuan në të njëjtën datë: Jenboja, Tabuku.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Hyrja e Selman Reisit në shërbimin osman dhe kalimi i politikës së Detit të Kuq", "771da99a"], "d": ["Selman Reisi, që mbrojti Xhidën kundër portugezëve, erdhi në Kajro dhe u paraqit përpara Sulltan Selimit Javuz; ndonëse për ca kohë u mbajt, në vitin 1519 u thirr në Stamboll dhe u zotua të përgatiste tridhjetë galera dhe disa galiota kundër kërcënimit portugez. Ky takim është fillimi i kalimit të politikës së Detit të Kuq dhe Oqeanit Indian nga trashëgimia memluke dhe i lidhjes së saj drejtpërdrejt me Stambollin. Osmanët tashmë, përveç se ishin një shtet mesdhetar, ishin edhe një fuqi që ndiqte politikë oqeanike.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Largimi i Sulltan Selimit Javuz nga Kajro dhe bejlerbejllëku i Hajër Beut", "8cd4fb23"], "d": ["Sulltan Selimi Javuz, që qëndroi afro tetë muaj në Egjipt dhe vendosi rendin administrativ, financiar dhe ushtarak, u largua nga Kajro; ish-naibi i Halepit, Hajër Beu, që në Mexh Dabik, duke tërhequr krahun e majtë, përshpejtoi disfatën memluke, si bejlerbeu i parë osman i Egjiptit filloi të qeveriste nga Kal'at ul-Xhebeli. Zgjedhja e një valiu me origjinë memluke ishte politikë e vetëdijshme tranzicioni, që siguronte që administrimi i ri të mos u dukej i huaj banorëve vendas. Padishahu, në rrugën e kthimit, mori me vete në Stamboll halifin e fundit abasid Mutavakkil III dhe artizanët e dijetarët e shquar të Egjiptit.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fundi i halifatit abasid të Kajros — rrëfimi i 'ceremonisë së dorëzimit'", "1d357640"], "d": ["Sulltan Selimi Javuz, pasi pushtoi Egjiptin, e solli me vete në Stamboll halifin e fundit Mutavakkil III-Alellah, të zënë rob në Mexh Dabik; kështu mori fund halifati abasid i Kajros, që që nga viti 1261 vazhdonte pa kompetenca nën hijen e sulltanëve memlukë. Nga ana tjetër, rrëfimi i njohur se halifati iu dorëzua Javuzit me ceremoni zyrtare në Ajasofje shfaqet për herë të parë në fund të shekullit XVIII në veprën e d'Ohssonit dhe nuk gjendet në asnjë nga burimet e periudhës së Javuzit. Enciklopedia Islame e TDV-së, meqë nuk ka burim origjinal që e dokumenton ceremoninë, e konsideron rrëfimin të trilluar; por shënon gjithashtu se për kalimin e halifatit sipas sheriatit nuk kishte nevojë për një ceremoni të tillë dorëzimi.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurumi iu bashkua administrimit osman — u thye ndikimi safavid në Anadollin Lindor", "78d1be02"], "d": ["Megjithëse pas fitores së Çalldiranit (1514) ndikimi osman në krahinë u rrit, pushtimi i plotë i Erzurumit u vonua deri në thyerjen e ndikimit iranian; qyteti iu bashkua administrimit osman vetëm pas fushatës së Egjiptit, në vitet 1518-19. Erzurumi në vitin 1502, kur Shah Ismaili i dha fund Bejlikut Akkojunlu, kishte hyrë nën sundimin safavid; kjo periudhë gjashtëmbëdhjetëvjeçare u mbyll kështu. Në vitin 1534, gjatë Fushatës së Dy Irakëve, do të krijohej Bejlerbejllëku i Erzurumit. Midis viteve 1518-1519, së bashku me krahinën e Erzurumit, edhe Ashkalja iu bashkua administrimit osman (dita e pakonfirmuar).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Fillimi i kryengritjeve xhelali: kryengritja e Shejh Xhelalit nga Bozoku", "99bd8a99"], "d": ["Në krahinën e Bozokut, një person i quajtur Shejh Xhelal, duke shpallur veten mehdi, u ngrit në kryengritje rreth Tokatit; megjithëse kryengritja u shtyp, emri i tij për një shekull u bë emërtim për të gjitha lëvizjet e banditizmit dhe të kryengritjes në Anadoll. Xhelalizmi, në fund të shekullit XVI, duke u bashkuar me shpërbërjen e rendit të timarit dhe me presionin demografik, u shndërrua në problemin më të gjatë të sigurisë së brendshme të perandorisë. Kryengritjet çuan në Anadoll në shpërngulje masive të quajtura 'arratia e madhe'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Lidhja e Algjerisë me Shtetin Osman", "b8eba4c1"], "d": ["Hajreddin Reisi, që rezistonte kundër presionit spanjoll në Afrikën Veriore, për t'u mbajtur iu drejtua Stambollit, ia ofroi Algjerinë padishahut dhe hytbeja u lexua në emër të Sulltan Selimit Javuz. Kështu Algjeria iu bashkua zyrtarisht tokave osmane dhe Hajreddinit, me titullin bejlerbej, iu dërguan ushtarë e topa. Kjo lidhje hodhi themelet e sundimit detar osman në Mesdheun Perëndimor që do të zgjaste me shekuj. Vende të tjera që u bashkuan në të njëjtën datë: Konstantina, Cherchell, Medea (Titteri), Setifi.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Vdekja e Sulltan Selimit Javuz në Çorlu", "9fe83744"], "d": ["Selimi I, që për tetë vjet e rriti territorin e shtetit më shumë se dyfish, më 18 korrik 1520 u nis nga Stambolli për një fushatë të re; për shkak të një tumori të madh që i doli në shpinë, nuk mundi të shkonte përtej Çorlusë. Megjithë ndërhyrjen e mjekëve, sëmundja u rëndua dhe, pas një mjekimi pa shpresë dymujor, vdiq aty më 8-9 sheval 926 (21-22 shtator 1520). Me Çalldiranin, Mexh Dabikun dhe Ridanijen ai kishte ndalur Iranin, kishte zhdukur Shtetin Memluk dhe u kishte sjellë Osmanëve halifatin dhe mbrojtjen e Haremejnit. Pas tij la vetëm një djalë: Sulejmanin.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Hyrja e ishullit të Nikarias (Ikarias) nën administrimin osman", "6afa972b"], "d": ["Nikaria, mes Samosit dhe Kiosit, nga viti 1481 deri më 1521 ishte nën administrimin e Kalorësve të Shën Gjonit të Rodosit; periudha e parë osmane në ishull filloi më 1522 dhe zgjati deri më 1822. Në këtë periudhë, për mbledhjen dhe pagesën e taksave përgjigjej kajmekami; si në ishujt e tjerë të Egjeut, edhe këshilli vendor i pleqve (demogerontia) vazhdoi të ekzistonte dhe herë pas here u përplas me administratën osmane.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksimi i vendit të Dulkadirëve — ejaleti i Dulkadirit me qendër në Marash", "595c3c30"], "d": ["Vendi i Dulkadirëve, që pas disfatës së Turnadagut të vitit 1515 vazhdoi si bejllëk vartës i osmanëve, pas vrasjes në Artukova të Shehsuvaroglu Ali Beut bashkë me fëmijët, iu bashkua drejtpërdrejt tokave osmane dhe u bë ejalet me qendër Marashin. Zona Bozok e bejllëkut iu lidh administrimit osman si sanxhak më vete. Kështu u mbyll periudha dulkadire gati dyshekullore e Marashit, Elbistanit, Göksunit, Gürünit, Zamantëse dhe Darendes; bejllëku tampon në kufirin mamluk u zhduk plotësisht.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Pushtimi i Kninit", "a46d3117"], "d": ["Me inkursionet e sanxhakbeut të Bosnjës, Gazi Husrev Beut, në vitet 927-928 (1521-1522), një varg kështjellash venedikase, me Kninin, Skradinin dhe Ostrovicën në krye, kaluan nën administrimin osman; kufiri u shty përtej vargut të dytë malor. Ky varg pushtimesh hodhi bazën e sanxhakut të Dalmacisë, që pesëmbëdhjetë vjet më vonë do të plotësohej me marrjen e Klisit.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Tërheqja e kalorësve: dorëzimi i Bodrumit, Kosit dhe Dymbëdhjetë Ishujve", "ea01666e"], "d": ["Sipas kushteve të dorëzimit të Rodosit, kalorësit e Shën Gjonit boshatisën jo vetëm qendrën e ishullit, por të gjitha pozicionet që kishin mbajtur për dyqind vjet. Kështu kështjella e Bodrumit (Saint Pierre) në bregun anadollak dhe ishujt Kos, Kalimnos dhe Leros kaluan pa përleshje nën administrimin osman. Me këtë dorëzim, të përfunduar dy javë pas rënies së Rodosit, prania latine në qoshen juglindore të Egjeut mori fund plotësisht.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Kryengritja e Ahmed Pashës Tradhtar në Egjipt", "b18bb805"], "d": ["Ahmed Pasha, që priste postin e vezirit të madh e u dërgua vali në Egjipt, duke e shpallur veten në Kajro 'al-Melik al-Mansur sulltan Ahmed', njoftoi pavarësinë. Kryengritja u shtyp shpejt dhe pashai u vra, por ngjarja tregoi brishtësinë e kontrollit qendror në ejaletin më të pasur të perandorisë. Pas kësaj Ibrahim Pasha shkoi në Egjipt dhe urdhëroi përgatitjen e Kanunamesë së njohur të Egjiptit, që riorganizoi administrimin e ejaletit.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksimi i Bosnjës Veriore: Jajce dhe Banja Lluka", "8ec86cfa"], "d": ["Kur pas Mohaçit u shemb vija mbrojtëse hungareze, sanxhakbeu i Bosnjës, Gazi Husrev Beu, marshoi nëpër luginën e Vrbasit dhe mori kështjellat e fundit të Bosnjës që i kishin mbetur mbretërisë hungareze. Me rënien e Jajces dhe Banja Llukës, ejaleti i Bosnjës në veri u mbështet te lumi Sava dhe lindi fronti i Kroacisë. Banja Lluka brenda pak kohe u bë qendra e dytë e ejaletit.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Marrja e Budës dhe dhënia e saj Zapolyait", "fba4f89b"], "d": ["Në rrugën e fushatës së Vjenës, ushtria osmane rrethoi dhe rimori Budën, që kishte rënë në duart e Ferdinandit, dhe ia dorëzoi qytetin mbretit hungarez János Szapolyai nën mbrojtjen osmane. Kështu për Hungarinë, në rivalitetin habsburgo-osman, u krijua modeli i një mbretërie vasale tampon. Ky rend do të zgjaste deri në vitin 1541; pas vdekjes së Zapolyait, Buda do të bëhej drejtpërdrejt ejalet osman.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Kanuniu doli në fushatën gjermane — sfidë ndaj Karlit V", "7c3d7055"], "d": ["Pasi rrethimi i Vjenës mbeti pa rezultat dhe Ferdinandi e rrethoi përsëri Budën, padishahu, këtë herë për ta tërhequr vetë perandorin Karli V në betejë fushore, u nis nga Stambolli. Ushtria në gusht do të vonohej nga rezistenca e kalasë së vogël të Güns-it dhe, meqë perandori nuk doli në luftë, fushata do të mbetej e kufizuar me sulme. Fushata përgatiti terrenin për paqen e parë me Habsburgët vitin pasues.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Fushata gjermane dhe rrethimi i Güns-it (Kőszeg)", "8aec937a"], "d": ["Kanuniu, me synim ta detyronte Karlin V në një betejë fushore, marshoi me ushtrinë mbi Austri; kalaja e vogël e Güns-it, duke rezistuar njëzet e pesë ditë, e vonoi përparimin e ushtrisë. Meqë perandori nuk doli në luftë, akënxhinjtë goditën rrethinat e Vjenës dhe, me avancimin e stinës, u kthyen. Fushata nuk solli fitime territoriale, por, duke i vënë Habsburgët në tryezë, përgatiti terrenin për paqen e vitit pasues.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Traktati i Stambollit — paqja e parë me Habsburgët", "b085767a"], "d": ["Padishahu, duke pritur ambasadorin e Ferdinandit, Kornelin, pranoi armëpushimin dhe doli në dritë teksti i parë zyrtar i paqes midis Osmanëve dhe Austrisë. Me traktatin, Ferdinandi pranoi të paguante taksë vjetore në këmbim të tokave hungareze që mbante, dhe arkiduka i Austrisë në protokoll u konsiderua i barabartë me vezirin e madh. Ky status i pabarabartë ishte shprehja e hapur e pretendimit për epërsi të diplomacisë osmane në shekullin XVI.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Marrja e Karsit dhe hapja e kufirit verilindor", "742e3101"], "d": ["Teksa kolona pararojë e Fushatës së Irakejnit drejtohej nga Erzurumi drejt lindjes, kështjella e Karsit, që ishte në duart e atabegllëkut gjeorgjian dhe e rrënuar që nga Timuri, u mor në dorëzim pa hasur rezistencë. Qyteti konsiderohej çelësi i portës veriore që hapej drejt Iranit, sepse zotëronte kalimin mes harkut të Araksit dhe Çëldërit. Ky fitim u bë hallka e parë e bejlerbejllëkut të Karsit, që do të krijohej tridhjetë vjet më vonë, dhe e vijës së Kaukazit.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Hyrja e parë në Tabriz — hapja e Fushatës së Irakejnit", "cf7ed4e3"], "d": ["Ibrahim Pasha, që si serdar ekrem lëvizte përpara, hyri pa hasur rezistencë në Tabriz, kryeqytetin safavid, pasi Shah Tahmaspi i shmangej betejës fushore dhe u tërhoq në thellësi. Edhe Sulejmani Ligjvënës arriti në qytet në shtator; por për shkak të ardhjes së dimrit dhe zgjatjes së tepërt të linjës së furnizimit, ushtria u drejtua nga Bagdadi dhe Tabrizi nuk mundi të mbahej gjatë. Qyteti, i marrë për herë të dytë pas Çalldiranit, u bë vendi ku osmanët mësuan se në lindje ishte e lehtë të shtije në dorë, por e vështirë të mbaje.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Pushtimi i Tunisit nga Barbarosa", "d8754216"], "d": ["Kapudan pashai Barbaros Hajreddin Pasha, pasi goditi me flotë brigjet e Italisë, u drejtua drejt Tunisit, e detyroi sundimtarin hafsid Mulej Hasan të ikte dhe hyri në qytet. Marrja e Tunisit, me pozitën që kontrollonte ngushticën e Siçilisë, e ktheu menjëherë ekuilibrin e forcave në Mesdheun Perëndimor në favor të Osmanëve. Por ky sundim nuk do të zgjaste shumë; Karli V vitin pasues do të përgjigjej me një flotë të madhe.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Humbja e Tunisit ndaj Karlit V", "a691f0f8"], "d": ["Karli V, me një fushatë të madhe të mbështetur nga flotat gjenoveze dhe papnore, pasi rrëzoi La Goulette-n (Halkul-Vad), mori Tunisin dhe e riktheu në fron Mulej Hasanin nën mbrojtjen spanjolle. Duke u vendosur një garnizon spanjoll në qytet, përparimi osman në Mesdheun Qendror u ndal përkohësisht. Pushtimi përfundimtar i Tunisit do të ishte i mundur vetëm dyzet vjet më vonë, në vitin 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operacioni i Gazi Husrev Beut përgjatë Savës: Bosanski Brod dhe Jasenovac", "3740ec83"], "d": ["Pas marrjes së Jajces dhe Banja Llukës më 1528, kështjellat përgjatë lumit Sava mbetën edhe për një farë kohe në kufirin kroato-sllavon të lidhur me kurorën habsburge. Gazi Husrev Beu, që më 1536 u bë për të tretën herë sanxhakbe i Bosnjës, po atë vit, ndërsa merrte Požegën dhe rrethinat, i bashkoi me administrimin osman edhe kështjellat e Brodit dhe Jasenovacit në bregun e Savës. Kështu kufiri verior i Bosnjës u mbështet te Sava; zona u plotësua dy vjet më vonë me marrjen e Dubicës.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Ekzekutimi i Makbul Ibrahim Pashës", "348aa7b8"], "d": ["Ibrahim Pasha, që shërbeu trembëdhjetë vjet si vezir i madh, miku më i ngushtë i Kanuniut dhe njeriu i dytë de fakto i shtetit, u ftua në saraj për iftar dhe, pa iu paraqitur asnjë arsye, u ekzekutua me mbytje. Sjellja e tij gjatë fushatës së Dy Irakëve, përdorimi i titullit 'serasker sulltan' dhe ekuilibrat brenda sarajit konsiderohen ndikues në vdekjen e tij. Ekzekutimi është një kthesë që tregon se në qeverisjen qendrore osmane vezirët e mëdhenj nuk kishin siguri absolute.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Pushtimi i Kalasë së Klisit dhe krijimi i sanxhakut të Dalmacisë", "6ffd4ebf"], "d": ["Qehajai i Gazi Hysrev Beut, Murad Beu, i konvertuar me origjinë kroate, ia mori Venedikut Kalanë strategjike të Klisit, menjëherë në veri të Splitit. Menjëherë pas pushtimit, Klisi u bë qendra e një sanxhaku të ri dhe e një kazaje që përfshinte rrethinat; kufijtë e këtij sanxhaku vizatuan në masë të madhe kornizën e Kroacisë osmane. Ky pushtim, pesëmbëdhjetë vjet pas Kninit, plotësoi skeletin administrativ të brendësisë së Dalmacisë.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Rrethimi i Korfuzit dhe lufta me Venedikun", "11af95bd"], "d": ["Pas fushatës së Pulias (Apulia), ushtria osmane zbarkoi ushtarë në Korfuz dhe rrethoi kalanë e fortë venedikase të ishullit. Për shkak të terrenit të thepisur të kalasë, humbjeve të rënda dhe kushteve të stinës, bllokada u hoq më 6 shtator dhe ushtria u tërhoq. Megjithëse rrethimi mbeti pa rezultat, lufta e hapur me Venedikun përfundoi me bashkimin e shumë ishujve të Egjeut dhe të Adriatikut me Osmanët dhe vitin pasues me fitoren e Prevezës.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Fushata e Barbarosit në Egje: marrja e ishujve të drejtuar drejtpërdrejt nga Venediku", "1b32ed96"], "d": ["Flota që u kthye nga rrethimi i Korfuzit, duke përfituar nga fakti që Venedikut i ishte shpallur luftë, mori në dorëzim njërin pas tjetrit në Egje ishujt që nuk vareshin nga dukati, por drejtpërdrejt nga Venediku. Egina u shtie në dorë pas një qëndrese të ashpër, Astipalia në duart e familjes Querini si dhe Karpathosi e Kasosi u dorëzuan, dhe Patmosi nën administrim manastiri e pranoi mbrojtjen osmane. Dukati i Naksosit u la në vend duke iu vënë haraç; aneksimi i tij do të priste vitin 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Fushata e Barbarosit në Egjeun Verior: marrja e Skirosit dhe Sporadeve Veriore", "20ab688e"], "d": ["Në rrugën drejt Prevezës, flota mori në dorëzim njërin pas tjetrit ishujt e Egjeut Verior që pas pushtimit të Stambollit i ishin strehuar Venedikut. Kështu Skirosi në veri të Eubesë dhe Skiathosi, Skopelosi e Alonisosi, që zotëronin grykën e gjirit të Selanikut, hynë nën administrimin osman. Me këta ishuj u mbyll boshllëku i fundit i Egjeut Verior, që, megjithëse Eubea ishte marrë më 1470, kishte mbetur edhe gjashtëdhjetë e tetë vjet në duart e Venedikut.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Marrja e Adenit dhe aneksimi i bregdetit të Jemenit", "e7d46d8f"], "d": ["Flota e nisur nga Suezi për fushatën e Indisë, ngaqë pa e siguruar Detin e Kuq nuk mund të dilej në oqean, fillimisht u drejtua nga bregu i Jemenit. Hadëm Sulejman Pasha hyri në portin e Adenit më 3 gusht 1538; sundimtari tahirid Amir b. Davud, që anonte nga portugezët, u soll te porta e kapedanit dhe u ekzekutua, dhe në qytet u la një garnizon prej 500 vetash. Gjatë së njëjtës fushatë u morën në dorëzim edhe Moka dhe ishujt Kameran e Farasan që zotëronin ngushticën, dhe u hodh themeli i bejlerbejllëkut të Jemenit. Kështu Shteti Osman për herë të parë zotëroi të gjithë bregun verior të Bab-el-Mandebit; ndërsa Sana dhe zonat e brendshme do të duhej të prisnin edhe nëntë vjet.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Fushata e Moldavisë dhe aneksimi i krahinës së Buxhakut (Benderit)", "90a88a56"], "d": ["Në fushatën kundër vojvodës së Moldavisë, Petru Rareş, që nuk përmbushte detyrimet ndaj Osmanëve, u pushtua Suçava, kurse qytetin e Jashit e plaçkiti hani i Krimesë, Sahib Giraj. Padishahu vendosi në vojvodat Stefan Lëkundësin (Stefan Lăcustă) dhe së bashku me Benderin aneksoi drejtpërdrejt në tokat osmane krahinën e Buxhakut (Besarabia Jugore). Ky aneksim u bë një nga hallkat që i shndërruan brigjet veriperëndimore të Detit të Zi në det të brendshëm osman. Moldavia ishte tashmë vojvodat vartës i Osmanëve; kjo fushatë nuk ia mori tokën një shteti të huaj, por vetëm ia hoqi vojvodës administrimin e brendshëm të Benderit dhe të Buxhakut dhe e lidhi drejtpërdrejt me padishahun; pjesa tjetër e vojvodatit e ruajti statusin vartës. E njëjta strukturë do të përsëritej në vitin 1484 në Kili dhe Akkerman dhe në vitin 1713 në Hotin: kalatë kufitare drejtpërdrejt, tokat e brendshme vartëse.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Marrja me traktat e Nauplias (Anabolu)", "104d0937"], "d": ["Lufta trevjeçare me Venedikun pas Prevezës përfundoi kur republika pranoi të lëshonte dy kështjellat e fundit në More. Nauplia dhe Monemvasia (Benefşe), që nuk mundën të merreshin me rrethim, iu dorëzuan osmanëve në tryezë, bashkë me treqind mijë dukate dëmshpërblim lufte. Kështu gadishulli i Moresë u bashkua i tëri, pa mbetur asnjë gjurmë këmbe venedikase.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Hyrja e Szegedit nën administrimin osman dhe formimi i livasë së Szegedit", "019aa000"], "d": ["Pas vendosjes së plotë të administrimit osman në Budin më 1541, paria e Szegedit e përqafoi sundimin e Ferdinandit I dhe u përgatit për mbrojtje të armatosur. Bejlerbeu i Budinit, Kyçyk Bali Pasha, në fillim të vitit 1543 i thirri pranë vetes drejtuesit e qytetit dhe i ekzekutoi me akuzën e tradhtisë, pastaj dërgoi një njësi për të shtënë në dorë qytetin. Në këtë kohë u formua livaja e Szegedit dhe sanxhakbe i parë u emërua i biri i Bali Pashës, Dervish Beu; livaja në fillim shtrihej mes Danubit dhe Tisës.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Pushtimi i Valpos, Siklósit dhe Pecsit", "2ca030a3"], "d": ["Objektivi i parë i fushatës së Hungarisë, e nisur dy vjet pas aneksimit të Budinit, ishte sigurimi i krahut jugor të ejaletit të ri mes Dravës dhe Danubit. Pasi u morën kështjellat e Valpos dhe Siklósit, u dorëzua Pecsi, qendra e Baranjës. Qyteti do të bëhej qendra më e populluar dhe më e ndërtuar e Hungarisë osmane, dhe prej tij historiani Ibrahim do të merrte emrin Peçevi.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Pushtimi i Estergomit dhe i Székesfehérvárit (İstolni Belgrad)", "efca9e05"], "d": ["Në fushatën e Hungarisë, ku doli vetë Kanuniu, pas një rrethimi dy javë e gjysmë, Estergomi, qendra fetare dhe qyteti i kryepeshkopatës i Mbretërisë së Hungarisë, hyri nën administrimin osman. Më pas u mor edhe Székesfehérvári, qyteti ku kurorëzoheshin mbretërit hungarezë, dhe u plotësua brezi mbrojtës i ejaletit të Budës. Estergomi deri në vitin 1595 do të mbetej në duart osmane si kalaja kyçe e vijës së Danubit.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Brezi mbrojtës verior dhe perëndimor i Budinit: Vác, Hatvan dhe Simontornya", "733ee5ce"], "d": ["Pasi u morën Estergomi dhe Székesfehérvári (İstolni Belgrad), bejlerbeu i Budinit u vu në veprim pa fushatë të padishahut për të plotësuar unazën e kështjellave rreth kryeqytetit. Váci në bërrylin e Danubit, Hatvani, porta e Alföldit, dhe Simontornya në vijën e Siós u morën në dorëzim njëra pas tjetrës. Fitimet e këtij viti të qetë e shndërruan Budinin nga qytet kufitar në qendër ejaleti që do të qëndronte njëqind e dyzet vjet.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksimi i Basrës dhe dalja në Gjirin e Basrës", "02f87c11"], "d": ["Gjatë pushtimit të Bagdadit (1534), sundimtari i Basrës Rashid b. Megamis i kishte njoftuar bindjen Sulejmanit Ligjvënës dhe më 1538 i kishte dërguar çelësat e qytetit. Kur pasardhësi i tij, Sheik Jahja, u kthye kundër osmanëve, bejlerbeu i Bagdadit, Ajas Pasha, marshoi nga toka, kurse sanxhakbeu i Mosulit me 120 anije nëpër Eufrat; Ajas Pasha hyri në Basrë më 26 dhjetor 1545 dhe qyteti u bë qendër bejlerbejllëku. Ky port në grykën e Shatt-el-Arabit ishte dera nga e cila osmanët dilnin në gjirin që portugezët e kontrollonin nga Hormuzi; me Traktatin e Amasjas të vitit 1555 edhe Irani e njohu këtë gjendje.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Pushtimi i Sanasë dhe i brendësisë së Jemenit", "d31ded85"], "d": ["Pas Taizit u mor edhe Sanaja dhe i gjithë vendi iu lidh bejlerbejllëkut. Megjithatë, për shkak të gjeografisë së thepisur dhe dallimit të medhhebit, ky sundim nuk ishte kurrë i qetë; Jemeni u bë për osmanët një front që vazhdimisht përpinte ushtarë.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Pushtimi i Taizit", "d4509df9"], "d": ["Në Jemen, ku nëntë vjet më parë ishin mjaftuar me rripin bregdetar, ngaqë imamët zejditë po forcoheshin gjithnjë e më shumë në zonën malore të brendshme, forcat e Ozdemir Pashës u ngjitën në rrafshnaltë dhe shtinë në dorë Taizin.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Traktati i Stambollit — paqe pesëvjeçare me Habsburgët", "41f81773"], "d": ["Midis Osmanëve dhe Habsburgëve u nënshkrua një paqe me afat pesëvjeçar; Ferdinandi pranoi të paguante 30.000 dukate në vit për tokat hungareze që mbante. Traktati e regjistroi juridikisht gjendjen de fakto të Hungarisë të ndarë në tri pjesë. Sigurimi në këtë mënyrë i frontit perëndimor i dha Kanuniut mundësinë të organizonte fushata të reja kundër Iranit.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Fushata e dytë e Iranit dhe rimarrja e Tabrizit", "e82365df"], "d": ["Në fushatën e ndërmarrë me nxitjen e Elkas Mirzës, vëllait të Shah Tahmaspit që u ngrit kundër tij dhe u strehua në Stamboll, ushtria hyri për herë të dytë në Tabriz. Meqë safavidët përsëri nuk pranuan betejë fushore dhe u tërhoqën duke djegur tokën, në qytet mundi të qëndrohej vetëm pak javë. Fushata e bëri të qartë se Tabrizi nuk mund të mbahej dhe e orientoi strategjinë osmane drejt krijimit të një vije kufitare të qëndrueshme, domethënë drejt fortifikimit të Vanit.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Pushtimi i Vanit dhe përcaktimi i qëndrueshëm i kufirit lindor", "fc8f930b"], "d": ["Kështjella e Vanit, e rrethuar gjatë kthimit nga Tabrizi, me pozitën e saj mbi një shkëmb në bregun lindor të liqenit ishte padiskutim çelësi i rajonit dhe pas një rrethimi të shkurtër u dorëzua. Qyteti u bë menjëherë qendër bejlerbejllëku; sanxhakët e Erxhishit, Adilxhevazit dhe Hakkarit iu lidhën atij. Ndryshe nga Tabrizi, Vani u mbajt dhe për katërqind vjet mbeti pozicioni i përhershëm më i përparuar osman në lindje.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksimi i Lahsës dhe Katifit — bregu arab i Gjirit", "f6701e60"], "d": ["Pas marrjes së Basrës u shtie në dorë Katifi, që në bregun perëndimor të gjirit ishte bërë postblloku i përparuar i Portugalisë, dhe bashkë me oazet e Lahsës në brendësi u krijua një bejlerbejllëk i ri. Prej këtej niseshin operacionet drejt Bahreinit dhe Hormuzit. Kështu Shteti Osman pati fjalë njëkohësisht në brigjet e Detit të Kuq dhe të Gjirit të Basrës të gadishullit arab.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Humbja e Shehrizorit — beu i Ardelanit, Suhrabi, anoi nga safavidët", "5600efc9"], "d": ["Viset e Shehrizorit, që gjatë Fushatës së Irakejnit (1535) e kishin njohur administrimin osman, drejtoheshin nga emiri i Ardelanit Bige Beu, që qëndronte në kështjellën Zalm. Pas vdekjes së Bige Beut më 1550, i vëllai Suhrabi, që shtiu në dorë kështjellën Zalm dhe u bë zot i bejllëkut, u drejtua nga safavidët dhe doli nga bindja ndaj osmanëve; kështu viset e Shehrizorit dolën nga ndikimi osman. Rajoni u rifitua vetëm gjatë fushatës së Nahiçevanit, më 1554, me rrethimin dhe marrjen e kështjellës Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Marrja e Ardahanit dhe pellgut të Çëldërit", "14c9eb76"], "d": ["Gjatë luftës që vazhdonte me safavidët, bejlerbeu i Erzurumit u drejtua nga tokat e atabegëve gjeorgjianë në harkun e Kurës dhe ia lidhi administrimit osman Ardahanin dhe rrethinat e Çëldërit. Kështu vija Kars-Ardahan u bashkua dhe u vunë nën kontroll trojet e larta që në verilindje hapeshin drejt Gjeorgjisë. Rendi përfundimtar administrativ i rajonit do të plotësohej me ejaletin e Çëldërit, që do të krijohej njëzet e shtatë vjet më vonë.", "2f8d92cc"]}
});
